import type { LifecyclePhase } from '@magic-ingredients/tiny-brain-core';
import { isMergeAvailableForPhase } from '@magic-ingredients/tiny-brain-core/get-validation';
import type { DeliveryPillView } from './delivery-pill';

/**
 * work-item-detail-service-rewrite / board-parity-retire — the card presentation
 * of the SERVER-computed `LifecyclePhase` (core `getValidation`). The board card
 * and the detail page now render the ONE shared producer, so their delivery pills
 * cannot drift: the board no longer folds its own `DeliveryPill` from board-row
 * facts for display, it renders the same `LifecyclePhase` the detail payload
 * carries.
 *
 * Only an ACTIVE delivery-side phase (running or failed on item_completion /
 * reconciliation / merge / post_merge) names a pill; every idle position — a
 * passed/not-started stage, or the TDD floor — names nothing (`null`), exactly as
 * the retired `DeliveryPill` `none` did. The label/tone/testId vocabulary is kept
 * identical to that mapping so the card reads the same at a glance. `runFailed` is
 * orthogonal and NOT handled here — the card renders the crashed-run badge from its
 * own row signal.
 */
export function describeLifecyclePhasePill(phase: LifecyclePhase | undefined): DeliveryPillView | null {
  if (phase === undefined) return null;
  const { pipeline, status } = phase;
  if (status !== 'running' && status !== 'failed') return null;
  const failed = status === 'failed';
  switch (pipeline) {
    case 'item_completion':
      return failed
        ? { label: 'validation failed', tone: 'tb-pill--red', testId: 'delivery-pill-validation-failed' }
        : { label: 'validating', tone: 'tb-pill--review', testId: 'delivery-pill-validating' };
    case 'reconciliation':
      return failed
        ? { label: 'reconcile failed', tone: 'tb-pill--red', testId: 'delivery-pill-reconcile-failed' }
        : { label: 'reconciling', tone: 'tb-pill--live', testId: 'delivery-pill-reconciling' };
    case 'merge':
      // A reconcile `conflicts` red is folded by getValidation to `merge`/failed —
      // the `/merge` hand-off, distinct from a plain reconcile failure above.
      return failed
        ? { label: 'merge failed', tone: 'tb-pill--red', testId: 'delivery-pill-merge-failed' }
        : { label: 'merging', tone: 'tb-pill--pri', testId: 'delivery-pill-merging' };
    case 'post_merge':
      return failed
        ? { label: 'post-merge failed', tone: 'tb-pill--red', testId: 'delivery-pill-post-merge-failed' }
        : { label: 'validating on main', tone: 'tb-pill--review', testId: 'delivery-pill-post-merging' };
    case 'tdd':
      // The TDD floor names no delivery pill (a running item pre-delivery).
      return null;
    case 'planning':
      // ADR-0040: a Backlog design-readiness phase names no delivery pill — it
      // never reaches this In-review-only mapping (guarded to running/failed
      // above regardless). Enumerated to keep the switch exhaustive.
      return null;
  }
}

/**
 * fix in-review-card-no-active-phase-indication — the in-review "no active phase"
 * cue. `describeLifecyclePhasePill` names a pill ONLY for a running/failed phase,
 * so every idle resting position leaves the in-review card's pill slot blank and
 * the card reads as inert (no "validating", no "ready to land", nothing). This
 * fills that gap for the NON-active positions, naming only the state the
 * `LifecyclePhase` already reports (no fabricated phase, no board-row re-fold — the
 * detail carries the same phase, so the two cannot drift):
 *
 *   - a genuine pre-land PASS (`item_completion.passed` / `reconciliation.passed`)
 *     ⇒ "ready to land" — validated, waiting on the detail's Merge cap. This reuses
 *     core's `isMergeAvailableForPhase` — the ONE "genuinely validated, ready to
 *     land" predicate the endcap's Merge gate also drives off — rather than
 *     re-deriving it, so the cue and the gate cannot drift (DRY). An in-review card
 *     is unlanded, so its `landed` arg is a constant `false`.
 *   - the pre-delivery awaiting floor — `tdd.passed` (TDD done, no delivery pass
 *     yet) or a configured-but-unrun `item_completion.not_started` — ⇒ "validation
 *     pending": completion is coming, no run yet.
 *
 * Everything else names nothing: an ACTIVE (running/failed) phase (the active pill
 * already fills the slot), an undefined phase (never fabricate), and a TERMINAL
 * landed pass (`merge.passed` / `post_merge.*`) — that is Done, not pending, so the
 * cue must not read "validation pending" there even if a stale row leaks off-lane.
 * Quiet tones (neutral / ok), distinct from the vivid active-phase hues: these are
 * a resting-state read, not a live pipeline signal.
 */
export function describeLifecyclePendingCue(
  phase: LifecyclePhase | undefined,
  reconciledAgainst?: string,
): DeliveryPillView | null {
  if (phase === undefined) return null;
  if (phase.status === 'running' || phase.status === 'failed') return null;
  // In-review is always unlanded — the constant `false` is exact, not a guess.
  if (isMergeAvailableForPhase(phase, false)) {
    // Provisional-ready (F2): name the main the item is ready AS OF — "ready to
    // land · main@<sha7>" — consuming F1's reconciled-against SHA. Fall back to the
    // plain cue when no SHA is present (older run / absent), never an empty `main@`.
    const label =
      reconciledAgainst !== undefined && reconciledAgainst.length > 0
        ? `ready to land · main@${reconciledAgainst.slice(0, 7)}`
        : 'ready to land';
    return { label, tone: 'tb-pill--ok', testId: 'delivery-cue-ready-to-land' };
  }
  const awaitingFloor =
    (phase.pipeline === 'tdd' && phase.status === 'passed') ||
    (phase.pipeline === 'item_completion' && phase.status === 'not_started');
  return awaitingFloor
    ? { label: 'validation pending', tone: 'tb-pill--kind', testId: 'delivery-cue-validation-pending' }
    : null;
}
