/**
 * Scope resolver — the single contract shared by coverage and mutation.
 *
 * One mode per pipeline step decides which files an analyser scopes against.
 * The resolver is **pure**: the git-touching inputs (the pre-push stdin, the
 * HEAD tip, a work-item's commit range) are gathered by the hooks/quality
 * runner and passed in via {@link ScopeContext}; the resolver only maps
 * mode + context to a {@link ScopeDescriptor} the analyser adapters consume.
 *
 * Every ambiguous case over-scopes to `full`: under-scoping would let
 * unanalysed changes slip through a gate, whereas over-scoping is merely slower.
 */
import { pushRanges } from './pre-push-refs.js';
/** All-zero object name (no base / a deletion). */
const ZERO_OBJECT_NAME = /^0+$/;
/**
 * A diff base that is safe to interpolate into a git command: a hex object
 * name, or the literal `HEAD` (the working-tree base). Anything else — a ref
 * expression, a path, shell metacharacters — is rejected. The descriptor's
 * bases are safe by construction (HEAD, or hex shas from git), but consumers
 * that splice the base into `execSync` validate against this as defence in
 * depth, independent of evaluation order.
 */
export const SAFE_DIFF_BASE = /^(HEAD|[0-9a-f]+)$/i;
/** The scope modes, as a const tuple — the single source feeding both the
 *  `ScopeMode` type and the config schema's `z.enum`, so they can't drift. */
export const SCOPE_MODES = ['changed', 'since-push', 'work-item', 'full'];
export function resolveScope(mode, ctx = {}) {
    switch (mode) {
        case 'changed':
            // Uncommitted/staged work, measured against HEAD — or the caller-supplied
            // base (the empty-tree object) when HEAD is unborn in a fresh repo. `||`
            // (not `??`) so an EMPTY supplied base also falls back to HEAD: threading
            // `base: ''` would fail SAFE_DIFF_BASE downstream and throw `Invalid scope
            // base` — a different crash in the same fresh-repo path.
            return { kind: 'working-tree', base: ctx.workingTreeBase || 'HEAD' };
        case 'since-push': {
            // Scope to the single pushed ref's range, base..pushed-tip — the pushed
            // local sha, NOT HEAD (which can differ when the hook fires). Anything
            // ambiguous — no stdin, deletion-only (empty ranges), a brand-new branch
            // (zero base), or more than one ref (no single base..tip covers them all)
            // — over-scopes to full rather than under-scoping.
            const ranges = ctx.pushStdin ? pushRanges(ctx.pushStdin) : [];
            if (ranges.length === 1 && !ZERO_OBJECT_NAME.test(ranges[0].remoteSha)) {
                return { kind: 'range', base: ranges[0].remoteSha, tip: ranges[0].localSha };
            }
            return { kind: 'full' };
        }
        case 'work-item': {
            // The caller resolves the contiguous Fix:/Feature: commit range. A partial
            // (missing base or tip) or absent range over-scopes to full.
            const r = ctx.workItemRange;
            return r?.base && r?.tip
                ? { kind: 'range', base: r.base, tip: r.tip }
                : { kind: 'full' };
        }
        case 'full':
            return { kind: 'full' };
        default: {
            // Exhaustiveness: a newly-added ScopeMode must be handled above, not fall
            // through to an undefined descriptor at runtime.
            const exhaustive = mode;
            return exhaustive;
        }
    }
}
