import { Fragment, useCallback, useEffect, useMemo, useRef, useState, type ReactNode } from 'react';
import { Activity } from 'lucide-react';
import { cn } from '@/lib/utils';
import { ResizablePanel, ResizablePanelGroup, ResizableHandle } from '@/components/ui/resizable';
import { usePanelSizeMemory } from '@/hooks/usePanelSizeMemory';
import { BoardCard } from './BoardCard';
import { RedMainBanner } from './RedMainBanner';
import { MainBrokenOverlay } from './MainBrokenOverlay';
import SkeletonLoader from '@/components/SkeletonLoader';
import type { BoardHealthSummary, BoardLane, BoardLanes, BoardRow, Liveness } from '@/hooks/useBoard';
import type { BoardTypeFilter } from '@/utils/resolve-work-view';
import '../board.css';

/**
 * board-surface F1/F2 — the four-lane work board, a faithful port of the mockup
 * (docs/prd/work-board/assets/work-board.html). Side-by-side lane columns over
 * the board projection, each item a {@link BoardCard}. Clicking a column header
 * isolates that lane into a master-detail split (mockup:
 * work-board-lane-focus.html) — the lane as a narrow list, the selected item's
 * detail in the main pane via {@link BoardViewProps.renderDetail}. The header is
 * the mockup's shape: an eyebrow row (All lanes · n items · n live · focus hint)
 * and the full toggle button row (type filter · attention · search). Column
 * headers are uniform and eyebrow-sized; In progress carries the
 * all/live/stalled/failed liveness quick-filter (the only lane whose rows carry
 * run liveness). There is no Canceled lane — superseded work leaves the board
 * for the Archive. Dumb UI: every bucket, count, and flag comes from the
 * projection; selection + focus are parent-owned for URL round-tripping.
 */
interface BoardViewBaseProps {
  lanes: BoardLanes;
  /** The selected row's key ({@link boardRowKey}); parent-owned for deep-linking. */
  selectedKey?: string | null;
  /** Row click selects the row (deep-linked via `?item=`). */
  onSelect?: (row: BoardRow) => void;
  /**
   * Fire the land action for an In-review row (land-dashboard task 1). Threaded
   * to the In-review lane's cards, which render the item-keyed Land button; the
   * board re-derives on the land run's SSE, moving the card In review → Done.
   * Absent ⇒ no Land button (read-only / Storybook).
   */
  onLand?: (row: BoardRow) => void;
  /**
   * Open the WorkerRun island for a row's live run (fix:
   * prd-feature-live-run-stream-unreachable task 1) — threaded to every card's
   * rail Running pill. Absent ⇒ no pill at all (read-only shells / Storybook),
   * never a dead button eating the card-select click.
   */
  onOpenRun?: (runId: string) => void;
  /**
   * The land action's live state for a row — `landing` / `error` / undefined —
   * from the container's {@link useBoardLand}. Threaded to each card so its Land
   * button reflects the in-flight / failed feedback. Absent ⇒ every card idle.
   */
  landStateFor?: (row: BoardRow) => 'landing' | 'error' | undefined;
  /** The isolated lane (task 2). When set, the board renders as that lane's list + a detail main. */
  focusedLane?: BoardLaneKey | null;
  /** Focus a lane (header click) or clear focus (back / All-lanes). Parent-owned for `?lane=`. */
  onFocusLane?: (lane: BoardLaneKey | null) => void;
  /** Renders the selected row's detail in the focused view's main pane (the existing islands). */
  renderDetail?: (row: BoardRow) => ReactNode;
  /**
   * The Done lane's total size (board-surface task 24). Done is served as a count
   * only — `lanes.done` is empty until fetched — so the collapsed Done strip
   * reads this. Falls back to `lanes.done.length` when omitted (Storybook / tests).
   */
  doneCount?: number;
  /**
   * The Done lane's cleanup-debt total (done-lane-cleanup task 3) — done items
   * whose worktree/branch/run were never reaped. Served beside `doneCount`, so
   * the collapsed strip renders it without loading rows; omitted or 0 renders
   * no row at all (never a "CLEANUP 0").
   */
  cleanupCount?: number;
  /**
   * Fetch the Done rows on demand — called when Done is expanded or focused, the
   * fetch-on-expand trigger for the count-only Done lane. Parent wires it to
   * `useBoard().loadDone`.
   */
  onExpandDone?: () => void;
  /** True while the Done rows are being fetched — the expanded lane shows a
   * loading affordance instead of an empty state (task 24). */
  doneLoading?: boolean;
  /**
   * True while the board's own data is loading (repo-switch-shows-stale-board
   * task 2). A repo switch clears the lanes at once (task 1), so an empty board
   * during the load must read as loading, not empty: each working lane renders a
   * skeleton placeholder instead of the "Nothing here." prompt.
   */
  loading?: boolean;
}

/**
 * The header kind filter is either fully controlled — both `type` (for the
 * pressed chip) and `onTypeChange` (writing `?type=`) — for URL round-tripping,
 * or fully internal (neither) for Storybook / tests. Never half-wired: passing
 * `type` without `onTypeChange` would silently drop filter changes.
 */
type BoardTypeControl =
  | { type?: undefined; onTypeChange?: undefined }
  | { type: BoardTypeFilter; onTypeChange: (type: BoardTypeFilter) => void };

/**
 * The Attention chip (attention-filter F5) toggles attention mode — the same
 * controlled-or-internal contract as the kind filter: either both `attention`
 * and `onAttentionChange` (URL round-tripping) or neither (Storybook / tests).
 */
type BoardAttentionControl =
  | { attention?: undefined; onAttentionChange?: undefined }
  | { attention: boolean; onAttentionChange: (on: boolean) => void };

export type BoardViewProps = BoardViewBaseProps & {
  /**
   * Main's validation health (split-land-from-validation F6). Drives the
   * always-on red-main banner above the lanes. Optional so Storybook and every
   * existing caller render a green board unchanged.
   */
  health?: BoardHealthSummary;
  /**
   * Revert a flagged land from the triage overlay (split-land-from-validation
   * F5). Optional, and its absence is meaningful: the overlay renders revert
   * buttons ONLY when a handler exists, so a board wired without one shows no
   * affordance rather than a button that would do nothing. Receives the picked
   * land's sha — the operator's choice of suspect is the whole point of the
   * ambiguous overlay, so it must survive to the caller.
   */
  onRevert?: (sha: string) => void;
  /**
   * Schedules a fresh main validation — the banner's Re-validate lever
   * (red-main-banner-stale-without-revalidation-path). The host owns the POST;
   * this view only threads the affordance to the banner. Returning the
   * schedule's promise lets the banner's optimistic revalidating rail restore
   * itself on refusal (revalidate-click-rail-not-instant).
   */
  onRevalidate?: () => void | Promise<unknown>;
  /**
   * The Runs board sub-mode (runs-view-rework). Runs is a work-item filter that
   * lives in this header rail (beside All/Plans/Fixes/Spikes + Attention), NOT
   * the top nav rail: when `runsActive`, the header persists and `runsBody`
   * renders in place of the kanban lanes (the environment-laned runs board). All
   * optional so every existing board caller (Archive, stories, tests) renders
   * the kanban unchanged.
   */
  runsActive?: boolean;
  /** Toggle the Runs sub-mode from the rail (sets/clears the `?runs` marker). */
  onRunsToggle?: () => void;
  /** Live-run count shown on the Runs toggle. */
  runsCount?: number;
  /** The runs board rendered as the body when `runsActive` (RunsListDetailView). */
  runsBody?: ReactNode;
} &
  BoardTypeControl &
  BoardAttentionControl;

export type BoardLaneKey = keyof BoardLanes;

interface LaneDef {
  key: BoardLaneKey;
  /** The mockup `data-lane` value — drives the lane tint. */
  attr: string;
  label: string;
  /** Lane accent — the dot + eyebrow colour, as a theme-aware design token. */
  accent: string;
}

/** The four board lanes, in order. Superseded / abandoned work leaves the board
 *  for the Archive (like archived work), so there is no Cancelled lane. */
const LANES: readonly LaneDef[] = [
  { key: 'backlog', attr: 'backlog', label: 'Backlog', accent: 'var(--color-subtle)' },
  { key: 'inProgress', attr: 'inprogress', label: 'In progress', accent: 'var(--color-blue)' },
  { key: 'inReview', attr: 'inreview', label: 'In review', accent: 'var(--color-phase-review)' },
  { key: 'done', attr: 'done', label: 'Done', accent: 'var(--color-done)' },
];

/** The header type filter — maps a chip to the projection `workRef.kind` it keeps. */
type TypeFilter = BoardTypeFilter;
// The chip `value` stays the projection wire kind (`prd`); only the visible
// label is the board's noun. A PRD is a Plan here — never "Features" (a plan's
// features are its parts, not board rows).
const TYPE_CHIPS: readonly { value: TypeFilter; label: string }[] = [
  { value: 'all', label: 'All' },
  { value: 'prd', label: 'Plans' },
  { value: 'fix', label: 'Fixes' },
  { value: 'spike', label: 'Spikes' },
];

/** Only In progress carries the FULL liveness axis (live/stalled/failed), so
 *  it is the sole lane with the liveness quick-filter. Backlog carries the
 *  live and failed arms (launched window; dead dispatch — the two backlog-
 *  card fixes) but never stalled — a partial axis whose failed rows already
 *  ride the attention chip, so backlog stays out of this list; its live rows
 *  feed the "n live" count below. */
const FILTERABLE: readonly BoardLaneKey[] = ['inProgress'];

/** Map a row's settled lane to its column key (for focus-on-card-click). The
 *  `canceled` entry is a defensive remnant: `BoardLane` still includes it (the
 *  pure projection can bucket a superseded item there) so this total Record must
 *  too, but production rows never reach it — superseded work is excluded before
 *  the board (see board.routes), so no `canceled` row exists to map. */
const LANE_KEY_OF: Record<BoardLane, BoardLaneKey> = {
  backlog: 'backlog',
  'in-progress': 'inProgress',
  'in-review': 'inReview',
  done: 'done',
  canceled: 'canceled',
};

/** Every focusable lane key — for validating a `?lane=` param before use (no
 *  blind cast). `canceled` is absent: superseded work leaves the board, so a
 *  `?lane=canceled` deep-link falls back to the grid. */
export const BOARD_LANE_KEYS: readonly BoardLaneKey[] = ['backlog', 'inProgress', 'inReview', 'done'];

/** The column key a row belongs to (its settled lane) — lets a parent focus + select atomically. */
export function boardLaneKeyForRow(row: BoardRow): BoardLaneKey {
  return LANE_KEY_OF[row.lane];
}

/** The one cleanup-row predicate (review of db15dd59e) — shared by the focused
 *  detail set, the lane filter, and the pill count so they cannot drift. */
const isCleanupRow = (row: BoardRow): boolean => row.cleanup === true;

/** A stable identity for a row across renders — for selection + deep-linking. */
export function boardRowKey(row: BoardRow): string {
  return `${row.workRef.kind}:${row.workRef.id}`;
}

/** The row's searchable text — title + id + kind — lower-cased for the header search. */
function rowText(row: BoardRow): string {
  return `${row.summary.title} ${row.workRef.id} ${row.workRef.kind}`.toLowerCase();
}

/** A row needs a decision when it carries at least one attention reason (F5). */
function isFlagged(row: BoardRow): boolean {
  return row.attention.length > 0;
}

/**
 * A lane's filed-date sort (board-lane-sort-by-filed-age task 2). Three states,
 * cycled by the header chevron: `none` keeps the projection order (opt-in — an
 * untouched lane never reorders), `desc` newest-filed-first, `asc`
 * oldest-filed-first. Per-lane and client-side.
 */
export type LaneSort = 'none' | 'desc' | 'asc';

/** The next state in the sort cycle: none → desc → asc → none. */
const nextSort = (s: LaneSort): LaneSort => (s === 'none' ? 'desc' : s === 'desc' ? 'asc' : 'none');

/**
 * Order rows by their `summary.filed` instant for the given sort. ISO-8601
 * timestamps are lexically ordered, so a plain string `<`/`>` compare is
 * chronological. A missing filed date (a fix with no `reported:`) sorts last in
 * both directions, so a fileless row never jumps to the top of either order.
 * `none` is the identity — the caller keeps projection order.
 */
function sortByFiled(rows: BoardRow[], sort: LaneSort): BoardRow[] {
  if (sort === 'none') return rows;
  const rank = (r: BoardRow): string => r.summary.filed ?? '';
  return [...rows].sort((a, b) => {
    const av = rank(a);
    const bv = rank(b);
    // Push missing dates to the bottom regardless of direction.
    if (av === '' || bv === '') return av === bv ? 0 : av === '' ? 1 : -1;
    if (av === bv) return 0;
    const older = av < bv ? -1 : 1;
    return sort === 'desc' ? -older : older;
  });
}

export function BoardView({ lanes, selectedKey, onSelect, onLand, onOpenRun, landStateFor, focusedLane, onFocusLane, renderDetail, health, doneCount, cleanupCount, onExpandDone, doneLoading, loading, type: typeProp, onTypeChange, attention: attentionProp, onAttentionChange, onRevert, onRevalidate, runsActive, onRunsToggle, runsCount, runsBody }: BoardViewProps) {
  // The triage overlay's open state (split-land-from-validation F6 Task 3).
  // Local to the board: it is a view of health the board already has, not a
  // route, so opening it needs no navigation and survives no reload.
  const [brokenOpen, setBrokenOpen] = useState(false);
  const resolvedHealth: BoardHealthSummary = health ?? { mainRed: false };
  // The overlay is scoped to ONE range. On an SSE-driven board a red can clear
  // and a different one arrive while it is open, which would otherwise leave a
  // stale triage table on screen describing lands that are no longer the
  // question — so the tip identity closes it.
  const openRange = resolvedHealth.mainRed ? resolvedHealth.tipSha : null;
  const lastRangeRef = useRef<string | null>(openRange);
  if (lastRangeRef.current !== openRange) {
    lastRangeRef.current = openRange;
    if (brokenOpen) setBrokenOpen(false);
  }

  // Independent liveness filter per filterable lane (In progress only).
  const [filters, setFilters] = useState<Partial<Record<BoardLaneKey, 'all' | Liveness>>>({});
  // Independent filed-date sort per lane (board-lane-sort-by-filed-age task 2) —
  // opt-in, so an untouched lane keeps its projection order.
  const [sorts, setSorts] = useState<Partial<Record<BoardLaneKey, LaneSort>>>({});
  // The expanded Done lane's all/cleanup filter (done-lane-cleanup task 4).
  const [doneCleanupFilter, setDoneCleanupFilter] = useState<'all' | 'cleanup'>('all');
  // The kind filter is controlled when the parent passes `type`/`onTypeChange`
  // (URL round-tripping) and internal otherwise (Storybook / tests).
  const [typeState, setTypeState] = useState<TypeFilter>('all');
  const type = typeProp ?? typeState;
  const setType = onTypeChange ?? setTypeState;
  // Attention mode — same controlled-or-internal contract as the kind filter.
  const [attentionState, setAttentionState] = useState(false);
  const attentionOn = attentionProp ?? attentionState;
  const setAttention = onAttentionChange ?? setAttentionState;
  const [search, setSearch] = useState('');
  // Remember the single-lane view's list/detail splitter offset (task 36). One
  // board-level, lane-agnostic key so the dragged offset survives lane switches
  // and reloads and applies to EVERY focused lane — the same panel-size memory
  // the workspace splitter uses.
  const focusPanels = usePanelSizeMemory('board-focus');
  // The Done lane dominates the board (most cards, rarely in play), so it
  // renders collapsed by default — a slim strip that expands in place on the
  // chevron (task 32). Grid-only: a focused Done lane shows its cards.
  const [doneCollapsed, setDoneCollapsed] = useState(true);
  // The working-lane width frozen at the moment Done expands, so the other lanes
  // do NOT reflow when Done grows — only Done changes, and the board scrolls to
  // reveal it. Null until first expand (and in jsdom, which has no layout).
  const [frozenLaneW, setFrozenLaneW] = useState<number | null>(null);

  // The kind + search scope (NOT attention) — the count of flagged rows is
  // taken over this scope so the chip composes with the other filters but is
  // independent of whether attention mode is currently on.
  const q = search.trim().toLowerCase();
  const matchesScope = useCallback(
    (r: BoardRow) =>
      (type === 'all' || r.workRef.kind === type) &&
      (q === '' || rowText(r).includes(q)),
    [type, q],
  );

  // Apply the type + search scope AND (when on) the attention filter across
  // every lane before any counts are taken, so the lane counts follow the shown set.
  const filtered = useMemo<BoardLanes>(() => {
    if (type === 'all' && q === '' && !attentionOn) return lanes;
    const keep = (rows: BoardRow[]) => rows.filter((r) => matchesScope(r) && (!attentionOn || isFlagged(r)));
    return {
      backlog: keep(lanes.backlog),
      inProgress: keep(lanes.inProgress),
      inReview: keep(lanes.inReview),
      done: keep(lanes.done),
      canceled: keep(lanes.canceled),
    };
  }, [lanes, type, q, attentionOn, matchesScope]);

  const displayLanes = filtered;

  // The focused lane, validated — an unknown `?lane=` value is ignored (the board
  // falls back to the grid), so the summaries never index the lanes with junk.
  const focusedKey: BoardLaneKey | null =
    focusedLane && BOARD_LANE_KEYS.includes(focusedLane) ? focusedLane : null;

  // A filter/search is active — the count-only Done total can't answer it, so
  // Done's rows must be fetched to count and show the matching subset.
  const filterActive = type !== 'all' || q !== '' || attentionOn;
  // Fetch the Done rows the moment they're needed — Done expanded in the grid,
  // Done focused into the single-lane view, or a filter that Done must answer
  // (task 24). While Done stays collapsed AND unfiltered its rows never load,
  // which is the payload saving. `onExpandDone` is stable (useCallback), so this
  // fires once per transition into needing Done, then the fetched rows filter
  // locally without re-fetching.
  const needDone = !doneCollapsed || focusedKey === 'done' || filterActive;
  useEffect(() => {
    if (needDone) onExpandDone?.();
  }, [needDone, onExpandDone]);

  // "Items" and "live" summarise the working lanes.
  // When a lane is FOCUSED, they narrow to that lane so the eyebrow describes
  // what's on screen ("… › In progress · n items"). Done is count-only until
  // expanded (task 24): with no filter its size is the server total `doneCount`
  // (the rows aren't loaded); under a filter its rows ARE loaded, so its size is
  // the filtered subset — the collapsed count and the expanded lane then agree.
  const doneSize = filterActive ? displayLanes.done.length : doneCount ?? displayLanes.done.length;
  const totalItems = focusedKey
    ? displayLanes[focusedKey].length
    : LANES.reduce((n, l) => n + (l.key === 'done' ? doneSize : displayLanes[l.key].length), 0);
  // Live rows across the liveness-bearing lanes: In progress, backlog's
  // launched rows (fix launched-run-invisible-on-board-backlog-card), and In
  // review's held rows (the relocated validating hold — fix validating-pill-
  // label-collides-with-validation: a completed item under running
  // validation is live machinery and must not vanish from the unfocused
  // count). Focused, it narrows to the focused lane.
  const liveCount = (
    focusedKey
      ? displayLanes[focusedKey]
      : [...displayLanes.inProgress, ...displayLanes.inReview, ...displayLanes.backlog]
  ).filter((r) => r.liveness === 'live').length;
  // "n live" shows over the filterable lane always, and over any other focused
  // lane exactly when it has live rows (a focused backlog with a launched card
  // reads "1 live"; In review / Done and an idle backlog stay suppressed).
  const showLive = !focusedKey || FILTERABLE.includes(focusedKey) || liveCount > 0;
  // Flagged rows within the current scope — the chip's live count, from the
  // server-derived per-row `attention` (single source of truth), independent of
  // the attention toggle. When a lane is FOCUSED, the count narrows to that
  // lane's flagged rows; unfocused, it sums across all lanes.
  const attnLaneKeys: BoardLaneKey[] = focusedKey ? [focusedKey] : LANES.map((l) => l.key);
  const attnCount = attnLaneKeys.reduce(
    (n, key) => n + lanes[key].filter((r) => matchesScope(r) && isFlagged(r)).length,
    0,
  );

  const focusDef = focusedKey ? LANES.find((l) => l.key === focusedKey) ?? null : null;

  const handleSelect = onSelect;

  // Two grid shapes. Collapsed, the working lanes fill the width (fractional)
  // with Done a capped ~100px trailing column, so there is no trailing gap.
  // Expanded, every column is the same width — frozen at the width the working
  // lanes had when Done was collapsed, so they do NOT reflow; Done matches that
  // full column width with its chevron rail *inside* it (cards render at column
  // width minus the rail). The board overflows and scrolls Done into view (the
  // effect below). `LANE_W` is the jsdom / first-paint fallback.
  const gridScrollRef = useRef<HTMLDivElement>(null);
  const LANE_W = '320px';
  const expandedLaneW = frozenLaneW ? `${frozenLaneW}px` : LANE_W;
  const gridCols = doneCollapsed
    ? `repeat(${LANES.length - 1}, minmax(248px, 1fr)) minmax(80px, 100px)`
    : `repeat(${LANES.length}, ${expandedLaneW})`;

  // Toggle Done. On expand, freeze the current filled working-lane width first so
  // the other lanes keep it once the grid switches to fixed tracks — only Done
  // reflows. (getBoundingClientRect is 0 under jsdom, where we keep the fallback.)
  const toggleDone = useCallback(() => {
    if (doneCollapsed) {
      const el = gridScrollRef.current?.querySelector('[data-testid="board-lane-backlog"]');
      const w = el ? Math.round((el as HTMLElement).getBoundingClientRect().width) : 0;
      setFrozenLaneW(w > 0 ? w : null);
    }
    setDoneCollapsed((c) => !c);
  }, [doneCollapsed]);

  // Keep the toggled Done lane in view: expanding scrolls to the right-most
  // edge to reveal the freshly-unfolded column; collapsing scrolls back to the
  // working lanes at the left (the board no longer overflows, so a leftover
  // scroll offset would otherwise clip Backlog). Also runs on return from the
  // focused single-lane view (focusedKey → null): the grid re-mounts scrolled to
  // 0, so an expanded Done would otherwise sit off-screen. Skips the initial
  // mount — only a genuine toggle / view change should move the scroll.
  const didMountRef = useRef(false);
  useEffect(() => {
    if (!didMountRef.current) {
      didMountRef.current = true;
      return;
    }
    // Only the grid view owns this scroll container; in the focused view it is
    // unmounted (ref null) and there is nothing to scroll.
    const el = gridScrollRef.current;
    if (el && typeof el.scrollTo === 'function') {
      el.scrollTo({ left: doneCollapsed ? 0 : el.scrollWidth, behavior: 'smooth' });
    }
  }, [doneCollapsed, focusedKey]);

  // A card click just selects the row (one callback). The parent is responsible
  // for focusing its lane atomically — emitting two separate callbacks here made
  // consumers fire two URL updates that clobbered each other (dropping `?item=`).
  // The parent has `row.lane` via {@link boardLaneKeyForRow} to do both at once.

  // The focused lane's cards, after the lane-local filter (liveness on In
  // progress, cleanup on Done) — the detail pane must resolve the selection
  // from the same set the sidebar shows, not the unfiltered rows.
  const focusShown =
    focusDef && FILTERABLE.includes(focusDef.key) && (filters[focusDef.key] ?? 'all') !== 'all'
      ? filtered[focusDef.key].filter((r) => r.liveness === filters[focusDef.key])
      : focusDef && focusDef.key === 'done' && doneCleanupFilter === 'cleanup'
        ? filtered.done.filter(isCleanupRow)
        : focusDef
          ? filtered[focusDef.key]
          : [];

  const laneFilterProps = (key: BoardLaneKey) => ({
    filterable: FILTERABLE.includes(key),
    filterValue: filters[key] ?? ('all' as const),
    onFilter: (v: 'all' | Liveness) => setFilters((f) => ({ ...f, [key]: v })),
    sortValue: sorts[key] ?? ('none' as const),
    onSort: (v: LaneSort) => setSorts((s) => ({ ...s, [key]: v })),
  });

  return (
    <div className="tb-board">
      {/* The alarm spans the top of the board, above every lane
          (split-land-from-validation F6). Renders nothing while main is green.
          Clicking it in the ambiguous case opens the triage overlay below. */}
      <RedMainBanner
        health={resolvedHealth}
        onOpenOverlay={() => setBrokenOpen(true)}
        {...(onRevalidate !== undefined ? { onRevalidate } : {})}
      />
      {brokenOpen && resolvedHealth.mainRed && (
        <MainBrokenOverlay health={resolvedHealth} onClose={() => setBrokenOpen(false)} onRevert={onRevert} />
      )}
      <div className="tb-board__header">
        <div data-testid="board-eyebrow" className="tb-board__eyebrow-row">
          <button
            type="button"
            data-testid="board-all-lanes"
            onClick={() => onFocusLane?.(null)}
            className="eyebrow inline-flex items-center gap-2"
            style={{ color: 'var(--color-muted-foreground)', background: 'transparent', border: 'none', cursor: 'pointer', padding: 0 }}
          >
            <span className="tb-lane__dot" style={{ background: 'var(--color-muted-foreground)' }} aria-hidden />
            All lanes
          </button>
          {focusDef && (
            <span className="eyebrow" style={{ color: focusDef.accent }} data-testid="board-focus-crumb">
              › {focusDef.label}
            </span>
          )}
          <span className="mono text-[11px]" style={{ color: 'var(--color-subtle)' }}>
            {totalItems} items{showLive ? ` · ${liveCount} live` : ''}
          </span>
          {!focusDef && (
            <span className="tb-rail-note ml-auto">click a column header to focus that lane</span>
          )}
        </div>

        <div className="tb-toggles" role="group" aria-label="Board filters">
          {TYPE_CHIPS.map((chip) => (
            <Fragment key={chip.value}>
              <button
                type="button"
                data-testid={`board-type-${chip.value}`}
                aria-pressed={type === chip.value}
                onClick={() => {
                  setType(chip.value);
                }}
                className={cn('tb-chip', chip.value === 'prd' && 'tb-chip--plan')}
              >
                {chip.label}
              </button>
            </Fragment>
          ))}
          <label className="tb-search">
            <span aria-hidden>⌕</span>
            <input
              data-testid="board-search"
              type="search"
              value={search}
              onChange={(e) => setSearch(e.target.value)}
              placeholder="search work…"
              aria-label="Search work"
            />
          </label>

          <div className="tb-toggles__right">
            {onRunsToggle && (
              <button
                type="button"
                data-testid="board-runs-toggle"
                className="tb-chip inline-flex items-center gap-1.5"
                aria-pressed={runsActive ?? false}
                onClick={onRunsToggle}
              >
                <Activity className="h-3.5 w-3.5" aria-hidden />
                Runs{runsCount ? <span className="mono">{runsCount}</span> : null}
              </button>
            )}
            <button
              type="button"
              data-testid="board-attention"
              className="tb-attn"
              aria-pressed={attentionOn}
              onClick={() => setAttention(!attentionOn)}
            >
              ⚠ Attention <span className="mono">{attnCount}</span>
            </button>
          </div>
        </div>
      </div>

      {runsActive && runsBody ? (
        // Runs sub-mode: the environment-laned runs board renders in place of the
        // kanban lanes, under the SAME persistent header rail (the Runs toggle
        // lives in that rail, not the top nav) — the mockup's board-tab shape.
        <div data-testid="board-runs-body" className="tb-board__scroll">
          {runsBody}
        </div>
      ) : focusDef ? (
        <div className="tb-board__scroll tb-board__scroll--focus">
          <ResizablePanelGroup direction="horizontal" className="tb-board__split" onLayout={focusPanels.onLayout}>
            <ResizablePanel defaultSize={focusPanels.defaultSize(0, 50)} minSize={20} maxSize={60} className="tb-board__focus-list">
              <Lane
                laneDef={focusDef}
                rows={filtered[focusDef.key]}
                onHeaderClick={() => onFocusLane?.(null)}
                {...laneFilterProps(focusDef.key)}
                cleanupFilter={focusDef.key === 'done' ? doneCleanupFilter : undefined}
                onCleanupFilter={focusDef.key === 'done' ? setDoneCleanupFilter : undefined}
                selectedKey={selectedKey}
                onSelect={onSelect}
                onLand={onLand}
                onOpenRun={onOpenRun}
                landStateFor={landStateFor}
              />
            </ResizablePanel>
            {/* The list/detail gap IS the handle: 16px — the board's right-hand
                gutter (.tb-board side padding) — with no track line or grip, so
                it reads as gutter and the whole width drags. The flanking panes
                carry no side margins of their own (task 41). Hover/drag get the
                sidebar's subtle wash via the library's state attribute (its own
                pointer tracking, so the wash holds while dragging). */}
            <ResizableHandle className="w-4 rounded-md bg-transparent dark:bg-transparent data-[resize-handle-state=hover]:bg-[color-mix(in_oklab,var(--ds-fg)_6%,transparent)] data-[resize-handle-state=drag]:bg-[color-mix(in_oklab,var(--ds-fg)_9%,transparent)]" />
            <ResizablePanel defaultSize={focusPanels.defaultSize(1, 50)} minSize={40}>
              <FocusDetail rows={focusShown} selectedKey={selectedKey} renderDetail={renderDetail} />
            </ResizablePanel>
          </ResizablePanelGroup>
        </div>
      ) : (
        <div className="tb-board__scroll" ref={gridScrollRef}>
          <div className="tb-board__grid" style={{ gridTemplateColumns: gridCols }}>
            {LANES.map((laneDef) => (
              <Lane
                key={laneDef.key}
                laneDef={laneDef}
                rows={displayLanes[laneDef.key]}
                onHeaderClick={() => onFocusLane?.(laneDef.key)}
                {...laneFilterProps(laneDef.key)}
                collapsible={laneDef.key === 'done'}
                collapsed={laneDef.key === 'done' && doneCollapsed}
                onToggleCollapse={toggleDone}
                // Done is count-only until expanded (task 24): show its size on
                // the collapsed strip (server total, or the filtered subset once
                // a filter has loaded the rows), not the empty local array.
                collapsedCount={laneDef.key === 'done' ? doneSize : undefined}
                cleanupCount={laneDef.key === 'done' ? cleanupCount : undefined}
                cleanupFilter={laneDef.key === 'done' ? doneCleanupFilter : undefined}
                onCleanupFilter={laneDef.key === 'done' ? setDoneCleanupFilter : undefined}
                loading={laneDef.key === 'done' ? doneLoading : loading}
                selectedKey={selectedKey}
                onSelect={handleSelect}
                onLand={onLand}
                onOpenRun={onOpenRun}
                landStateFor={landStateFor}
              />
            ))}
          </div>
        </div>
      )}
    </div>
  );
}

/** The focused view's detail main — the selected row's island, or an empty prompt. */
function FocusDetail({
  rows,
  selectedKey,
  renderDetail,
}: {
  rows: BoardRow[];
  selectedKey?: string | null;
  renderDetail?: (row: BoardRow) => ReactNode;
}) {
  const selectedRow = selectedKey ? rows.find((r) => boardRowKey(r) === selectedKey) ?? null : null;
  return (
    <section data-testid="board-detail" className="tb-board__detail" aria-label="Selected item">
      {selectedRow && renderDetail ? (
        renderDetail(selectedRow)
      ) : (
        <p className="tb-board__detail-empty">Select an item from the lane to see its detail.</p>
      )}
    </section>
  );
}

interface LaneProps {
  laneDef: LaneDef;
  rows: BoardRow[];
  /** Whether this lane carries the liveness quick-filter (In progress only). */
  filterable: boolean;
  filterValue: 'all' | Liveness;
  onFilter: (value: 'all' | Liveness) => void;
  /** This lane's filed-date sort state (task 2) — cycled by the header chevron. */
  sortValue: LaneSort;
  onSort: (value: LaneSort) => void;
  /** Header click — focuses this lane (grid) or returns to all lanes (focused). */
  onHeaderClick?: () => void;
  /** Whether this lane can collapse to a strip (Done only, task 32). */
  collapsible?: boolean;
  /** Whether it is currently collapsed — meaningful only when `collapsible`. */
  collapsed?: boolean;
  /** Toggle the collapse (the chevron click). */
  onToggleCollapse?: () => void;
  /**
   * The count shown on the COLLAPSED strip when the lane's rows aren't loaded
   * locally (Done is count-only until expanded, task 24). Falls back to
   * `rows.length` when undefined — every other lane, and the expanded header.
   */
  collapsedCount?: number;
  /** The lane's cleanup-debt count (done-lane-cleanup task 3) — Done only. The
   * collapsed strip renders a CLEANUP row beneath the count when > 0. */
  cleanupCount?: number;
  /** The expanded Done lane's all/cleanup filter (done-lane-cleanup task 4) —
   * present (with its setter) only on the Done lane; the pill row renders when
   * both are wired. */
  cleanupFilter?: 'all' | 'cleanup';
  onCleanupFilter?: (value: 'all' | 'cleanup') => void;
  /** The lane's data is loading — Done's on-demand row fetch (task 24) or, for a
   * working lane, the board's own load after a repo switch (task 2). The empty
   * body then reads as loading (skeleton cards) rather than "Nothing here." */
  loading?: boolean;
  selectedKey?: string | null;
  onSelect?: (row: BoardRow) => void;
  /** Fire the land action for an In-review row — threaded to the lane's cards (task 1). */
  onLand?: (row: BoardRow) => void;
  /** Open the WorkerRun island for a row's live run — threaded to the cards. */
  onOpenRun?: (runId: string) => void;
  /** Per-row land state for the lane's cards (task 1). */
  landStateFor?: (row: BoardRow) => 'landing' | 'error' | undefined;
}

/** Placeholder cards for a lane whose rows are still loading (task 2) — a cleared
 *  lane reads as loading, not empty. Decorative, so hidden from the a11y tree. */
function LaneSkeleton() {
  return (
    <div data-testid="board-lane-skeleton" className="tb-lane__skeleton" aria-hidden>
      {[0, 1, 2].map((i) => (
        <SkeletonLoader key={i} variant="rect" height={64} />
      ))}
    </div>
  );
}

function Lane({ laneDef, rows, filterable, filterValue, onFilter, sortValue, onSort, onHeaderClick, collapsible, collapsed, onToggleCollapse, collapsedCount, cleanupCount, cleanupFilter, onCleanupFilter, loading, selectedKey, onSelect, onLand, onOpenRun, landStateFor }: LaneProps) {
  const isInProgress = laneDef.key === 'inProgress';
  // Two lane-local filters, one active per lane role: the In-progress liveness
  // quick-filter, and the expanded Done cleanup filter (done-lane-cleanup
  // task 4) — flagged rows only when `cleanup` is selected.
  const filteredRows =
    filterable && filterValue !== 'all'
      ? rows.filter((r) => r.liveness === filterValue)
      : cleanupFilter === 'cleanup'
        ? rows.filter(isCleanupRow)
        : rows;
  // The filed-date sort (task 2) applies AFTER the filters, so it orders only the
  // rows the filter left visible (mockup: filter narrows, sort orders the rest).
  const shown = sortByFiled(filteredRows, sortValue);
  // Stamped on every section variant — collapsed Done included, so a sorted
  // Done lane keeps its accent across collapse/expand and a [data-sorted]
  // query never returns undefined on one branch (adversarial review of
  // cbed6733b).
  const isSorted = sortValue !== 'none';

  const cards =
    shown.length > 0 ? (
      shown.map((row) => (
        <BoardCard
          key={boardRowKey(row)}
          row={row}
          selected={selectedKey === boardRowKey(row)}
          onSelect={onSelect ?? (() => {})}
          onLand={onLand}
          onOpenRun={onOpenRun}
          landState={landStateFor?.(row)}
        />
      ))
    ) : loading ? (
      // Empty + loading: skeleton cards for EVERY lane — Done's on-demand row
      // fetch (task 24) included (user call, 2026-07-26: its bespoke "Loading…"
      // text made Done read differently for no reason) — so a loading lane
      // never reads "Nothing here." (which means "genuinely empty").
      <LaneSkeleton />
    ) : (
      <p className="tb-lane__empty">Nothing here.</p>
    );

  // Done is the sole collapsible lane (task 32), with two shapes:
  //  • Collapsed — a ~third-width column keeping the normal lane header (dot ·
  //    "Done" · count) with a large chevron centred down its body as the expand
  //    target. The grid fills the remaining width, so there is no trailing gap.
  //  • Expanded — a full-width column fronted by a green full-height rail down
  //    its left edge (the collapse control); the header focus-isolates the lane
  //    like every other lane.
  if (collapsible && collapsed) {
    return (
      <section
        data-testid={`board-lane-${laneDef.key}`}
        data-lane={laneDef.attr}
        data-collapsed="true"
        data-sorted={isSorted ? 'true' : 'false'}
        aria-label={laneDef.label}
        className="tb-lane"
      >
        <div className="tb-lane__head tb-lane__head--label">
          <div className="tb-lane__title">
            <span className="tb-lane__dot" style={{ background: laneDef.accent }} aria-hidden />
            <span className="eyebrow" style={{ color: laneDef.accent }}>
              {laneDef.label}
            </span>
            <span data-testid={`board-lane-count-${laneDef.key}`} className="tb-lane__count mono">
              {collapsedCount ?? rows.length}
            </span>
          </div>
          {/* Cleanup-debt row (done-lane-cleanup task 3): rendered only when debt
              exists — a "CLEANUP 0" would restate the quiet default. Display-only;
              the filter/action surfaces live on the expanded lane and item detail. */}
          {cleanupCount !== undefined && cleanupCount > 0 && (
            <div data-testid="board-done-cleanup-count" className="tb-lane__cleanup">
              <span className="eyebrow">cleanup</span>
              <span className="tb-lane__count mono">{cleanupCount}</span>
            </div>
          )}
        </div>
        <button
          type="button"
          data-testid="board-done-toggle"
          className="tb-lane__expand-hint"
          aria-expanded={false}
          aria-label={`Expand the ${laneDef.label} lane`}
          onClick={onToggleCollapse}
        >
          <span aria-hidden>›</span>
        </button>
      </section>
    );
  }
  if (collapsible) {
    return (
      <section
        data-testid={`board-lane-${laneDef.key}`}
        data-lane={laneDef.attr}
        data-collapsed="false"
        data-sorted={isSorted ? 'true' : 'false'}
        aria-label={laneDef.label}
        className={cn('tb-lane', 'tb-lane--done')}
      >
        <button
          type="button"
          data-testid="board-done-toggle"
          className="tb-lane__rail"
          aria-expanded
          aria-label={`Collapse the ${laneDef.label} lane`}
          onClick={onToggleCollapse}
        >
          <span className="tb-lane__rail-chevron" aria-hidden>›</span>
        </button>
        <div className="tb-lane__done-body">
          {/* The body header focus-isolates the lane and carries the count
              RHS-aligned, exactly like every other lane — the rail owns collapse,
              the header owns focus. */}
          <div className="tb-lane__head" onClick={onHeaderClick}>
            <LaneTitleRow
              laneDef={laneDef}
              count={shown.length}
              pulse={false}
              sortValue={sortValue}
              onSort={onSort}
              {...(onHeaderClick !== undefined ? { onHeaderClick } : {})}
            />
            {/* The expanded lane's all/cleanup pills (done-lane-cleanup task 4) —
                the liveness-filter interaction: sibling of the title, clicks
                stopped short of the head so they never focus the lane. */}
            {cleanupFilter !== undefined && onCleanupFilter !== undefined && (
              <FilterSeam>
                <CleanupFilter laneKey={laneDef.key} rows={rows} value={cleanupFilter} onChange={onCleanupFilter} />
              </FilterSeam>
            )}
          </div>
          <div className="tb-lane__cards">{cards}</div>
        </div>
      </section>
    );
  }

  return (
    <section
      data-testid={`board-lane-${laneDef.key}`}
      data-lane={laneDef.attr}
      data-collapsed="false"
      data-sorted={isSorted ? 'true' : 'false'}
      aria-label={laneDef.label}
      className="tb-lane"
    >
      {/* The whole head is the click + hover target (focus this lane). The title
          row is the semantic + keyboard button; the liveness filter is a sibling
          whose clicks stop short of the head, so its <button>s are never nested
          inside a role="button" (valid ARIA). */}
      <div
        className="tb-lane__head"
        data-testid={`board-lane-headwrap-${laneDef.key}`}
        onClick={onHeaderClick}
      >
        {/* The count inside the row follows the lane-local filter (matching the
            expanded Done column): a narrowed lane reads the narrowed size. */}
        <LaneTitleRow
          laneDef={laneDef}
          count={shown.length}
          pulse={isInProgress}
          sortValue={sortValue}
          onSort={onSort}
          {...(onHeaderClick !== undefined ? { onHeaderClick } : {})}
        />
        {filterable && (
          <FilterSeam>
            <LivenessFilter laneKey={laneDef.key} rows={rows} value={filterValue} onChange={onFilter} />
          </FilterSeam>
        )}
        {/* The Done cleanup pills survive lane isolation (user call, 2026-07-26):
            a focused Done lane renders through this plain branch, so the filter
            rides here exactly as it does on the expanded column. */}
        {cleanupFilter !== undefined && onCleanupFilter !== undefined && (
          <FilterSeam>
            <CleanupFilter laneKey={laneDef.key} rows={rows} value={cleanupFilter} onChange={onCleanupFilter} />
          </FilterSeam>
        )}
      </div>

      <div className="tb-lane__cards">{cards}</div>
    </section>
  );
}

/** The lane-filter seam: a zero-box wrapper whose ONE job is stopping filter
 *  clicks short of the head (which would focus the lane). Shared by the
 *  liveness and cleanup filters (review of db15dd59e). */
function FilterSeam({ children }: { children: ReactNode }) {
  return (
    <span style={{ display: 'contents' }} onClick={(e) => e.stopPropagation()}>
      {children}
    </span>
  );
}

/**
 * The header's first line (lane-sort-chevron-mock-parity task 1): the
 * role="button" focus title and the seam-wrapped sort chevron side by side in
 * flow, per the mockup — the chevron can never stack on the RHS-aligned count,
 * and the seam keeps the button outside the role="button" title (valid ARIA)
 * with its clicks stopped short of the head. ONE definition shared by the
 * standard and expanded-Done branches (adversarial review of cbed6733b: the
 * copy-pasted block is how the branches drift apart).
 */
function LaneTitleRow({
  laneDef,
  count,
  pulse,
  sortValue,
  onSort,
  onHeaderClick,
}: {
  laneDef: LaneDef;
  count: number;
  pulse: boolean;
  sortValue: LaneSort;
  onSort: (value: LaneSort) => void;
  onHeaderClick?: () => void;
}) {
  return (
    <div className="tb-lane__titlerow" data-testid={`board-lane-titlerow-${laneDef.key}`}>
      <div
        role="button"
        tabIndex={0}
        aria-label={`Focus the ${laneDef.label} lane`}
        data-testid={`board-lane-head-${laneDef.key}`}
        className="tb-lane__title"
        onClick={(e) => {
          // Handle the title click here so it doesn't also bubble to the head.
          e.stopPropagation();
          onHeaderClick?.();
        }}
        onKeyDown={(e) => {
          if (e.key === 'Enter' || e.key === ' ') {
            e.preventDefault();
            onHeaderClick?.();
          }
        }}
      >
        <span
          className={cn('tb-lane__dot', pulse && 'tb-pulse')}
          style={{ background: laneDef.accent }}
          aria-hidden
        />
        <span className="eyebrow" style={{ color: laneDef.accent }}>
          {laneDef.label}
        </span>
        <span data-testid={`board-lane-count-${laneDef.key}`} className="tb-lane__count mono">
          {count}
        </span>
      </div>
      <FilterSeam>
        <LaneSort laneKey={laneDef.key} value={sortValue} onChange={onSort} />
      </FilterSeam>
    </div>
  );
}

/** The Done lane's all/cleanup pill row (done-lane-cleanup task 4) — the
 *  LivenessFilter shape, two options, cleanup styled amber via its data attr. */
function CleanupFilter({
  laneKey,
  rows,
  value,
  onChange,
}: {
  laneKey: BoardLaneKey;
  rows: BoardRow[];
  value: 'all' | 'cleanup';
  onChange: (value: 'all' | 'cleanup') => void;
}) {
  return (
    <span role="group" aria-label="Cleanup filter" className="tb-lane__filter">
      {(['all', 'cleanup'] as const).map((opt) => (
        <button
          key={opt}
          type="button"
          data-testid={`board-cleanup-${laneKey}-${opt}`}
          data-cleanup-option={opt}
          aria-pressed={value === opt}
          onClick={() => onChange(opt)}
        >
          {opt} {opt === 'all' ? rows.length : rows.filter(isCleanupRow).length}
        </button>
      ))}
    </span>
  );
}

/** The chevron glyph per sort state (task 2), a faithful port of the mockup: a
 *  quiet double chevron when unsorted, a single ▾ newest-first, a single ▴
 *  oldest-first. Stroke-only paths so they inherit the button's `currentColor`. */
function SortChevron({ sort }: { sort: LaneSort }) {
  const paths =
    sort === 'desc' ? ['m6 9 6 6 6-6'] : sort === 'asc' ? ['m18 15-6-6-6 6'] : ['m7 15 5 5 5-5', 'm7 9 5-5 5 5'];
  return (
    <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" aria-hidden>
      {paths.map((d) => (
        <path key={d} d={d} />
      ))}
    </svg>
  );
}

/** A human label for the sort control's current state — the aria-label / tooltip
 *  names what the NEXT click does, so a screen-reader user knows the affordance. */
const SORT_LABEL: Record<LaneSort, string> = {
  none: 'Sort by filed date',
  desc: 'Sorted newest filed first — click for oldest first',
  asc: 'Sorted oldest filed first — click to clear the sort',
};

/**
 * The lane's filed-date sort chevron (board-lane-sort-by-filed-age task 2) — a
 * sibling control in the header seam, so its click never focus-isolates the lane
 * (the same {@link FilterSeam} rule the liveness / cleanup filters follow). One
 * button cycling none → desc → asc → none; the chevron shows the active
 * direction, and the `on` state tints it when a sort is applied.
 */
function LaneSort({ laneKey, value, onChange }: { laneKey: BoardLaneKey; value: LaneSort; onChange: (value: LaneSort) => void }) {
  return (
    <button
      type="button"
      data-testid={`board-sort-${laneKey}`}
      data-sort={value}
      className={cn('tb-lane__sort', value !== 'none' && 'on')}
      aria-pressed={value !== 'none'}
      aria-label={SORT_LABEL[value]}
      title={SORT_LABEL[value]}
      onClick={() => onChange(nextSort(value))}
    >
      <SortChevron sort={value} />
    </button>
  );
}

const LIVENESS_OPTIONS: readonly ('all' | Liveness)[] = ['all', 'live', 'stalled', 'failed'];

function LivenessFilter({
  laneKey,
  rows,
  value,
  onChange,
}: {
  laneKey: BoardLaneKey;
  rows: BoardRow[];
  value: 'all' | Liveness;
  onChange: (value: 'all' | Liveness) => void;
}) {
  const count = (opt: 'all' | Liveness): number =>
    opt === 'all' ? rows.length : rows.filter((r) => r.liveness === opt).length;

  return (
    <span role="group" aria-label="Liveness filter" className="tb-lane__filter">
      {LIVENESS_OPTIONS.map((opt) => (
        <button
          key={opt}
          type="button"
          data-testid={`board-liveness-${laneKey}-${opt}`}
          data-liveness={opt}
          aria-pressed={value === opt}
          onClick={() => onChange(opt)}
          style={opt === 'failed' && value !== opt ? { color: 'var(--color-phase-red)' } : undefined}
        >
          {opt} {count(opt)}
        </button>
      ))}
    </span>
  );
}
