/**
 * Worktree-effective task (ADR-0007 / multi-ref-projection; fix:
 * fix-status-head-only-vs-across-refs).
 *
 * `TaskRow` shows a task's status as the most-advanced ref: it overlays
 * telemetry-derived state, fills phase SHAs from the per-ref lattice, then
 * promotes the row status to a worktree branch that's strictly ahead of the
 * launch ref. The fix AGGREGATES (FixDetail's done/left bar, the FixCard
 * sidebar) historically counted the raw launch-ref `task.status`, so a task
 * completed on a worktree branch read as "not done" there even while its row
 * icon showed completed.
 *
 * `toEffectiveTask` is that exact rollup, extracted so the aggregates reuse it
 * rather than re-deriving (and drifting). Pure: returns the input untouched when
 * nothing changes, else a shallow copy with the filled SHAs / promoted status.
 */

import type { Plan, RefStatusCell, TaskRowTask } from '../types';
import { applyDerivedState } from './apply-derived-state';
import { applyWorktreePhaseShas } from './worktree-aware-shas';
import { deriveEffectiveStatus, rollUpEffectiveStatuses } from './effective-task-status';

export function toEffectiveTask(task: TaskRowTask): TaskRowTask {
  const overlayed = applyWorktreePhaseShas(applyDerivedState(task, task.derivedState));
  const { status } = deriveEffectiveStatus(overlayed);
  // Mirror TaskRow's icon (TaskRow.tsx:91-93): a started-but-uncommitted task
  // (red/green phase entered via telemetry, no commit yet) reads in_progress.
  // Without this the aggregate would lag the row in the OTHER direction — the
  // row shows in_progress while the rolled-up fix pill shows not_started.
  const hasStartedPhase = !!(overlayed.redStartedAt || overlayed.greenStartedAt);
  const effective = status === 'not_started' && hasStartedPhase ? 'in_progress' : status;
  return effective === overlayed.status ? overlayed : { ...overlayed, status: effective };
}

/**
 * Roll a feature/container up from its tasks' PULSE-AWARE effective statuses —
 * each task via `toEffectiveTask`, the same promotion the PRD card and task row
 * use (incl. a started-but-uncommitted red/green phase carried in derivedState).
 * The launch-ref-only `deriveFeatureEffectiveStatus` misses that pulse, so an
 * active-but-uncommitted feature reads not_started there; the feature header and
 * PRD partition must use THIS rollup so they flip to in_progress in step with the
 * card/row instead of staying collapsed and hidden.
 */
export function deriveTasksEffectiveStatus(tasks: readonly TaskRowTask[]): RefStatusCell['status'] {
  return rollUpEffectiveStatuses(tasks.map((t) => toEffectiveTask(t).status));
}

/**
 * The status a plan's detail header should show, derived from the same
 * pulse-aware task rollup the PRD card uses rather than raw `plan.status` (which
 * only flips once the backend overlay reaches it). Narrowed for the header's
 * 3-value pill: a terminal plan or an all-terminal rollup maps to `completed`
 * (both `completed` and `superseded` are terminal) rather than an unlabelled
 * `superseded` — this function never RETURNS `superseded`.
 *
 * Never DOWNGRADES: a backend-terminal plan (completed OR superseded) stays
 * `completed` even if a task is reopened on a worktree, matching PlanCard (which
 * gates in-progress on `!isComplete`, so a complete plan never flips back) and
 * `deriveFixEffectiveStatus`'s promote-only floor. It only PROMOTES — surfaces an
 * active pulse or an all-terminal rollup the backend `plan.status` hasn't caught
 * up with — and otherwise preserves `plan.status` (a not_started rollup).
 */
export function derivePlanEffectiveStatus(plan: {
  status: Plan['status'];
  features?: readonly { readonly tasks?: readonly TaskRowTask[] }[];
}): Plan['status'] {
  // Terminal backend status wins — promote-only, never downgrade a terminal plan.
  // Both terminal statuses narrow to `completed` (the header pill has no
  // `superseded` label), mirroring the all-terminal rollup branch below.
  if (plan.status === 'completed' || plan.status === 'superseded') return 'completed';
  const allTasks = (plan.features ?? []).flatMap((f) => f.tasks ?? []);
  if (allTasks.length === 0) return plan.status;
  const rolled = deriveTasksEffectiveStatus(allTasks);
  if (rolled === 'completed' || rolled === 'superseded') return 'completed';
  if (rolled === 'in_progress') return 'in_progress';
  return plan.status;
}

/**
 * The worktree-effective status for a fix, rolled up from its tasks' effective
 * statuses (the all-refs lattice via `toEffectiveTask`). The fix surfaces
 * (FixCard pill, FixDetail eyebrow, and the list filter `fixCategory`) all source
 * from this so they can't drift, instead of the HEAD-only flat `fix.status` that
 * leaves worktree-only work as not_started (cross-ref-status-visibility F5-T1).
 *
 * Promote-only, mirroring `derivePlanEffectiveStatus`: it surfaces a rolled
 * status that is MORE advanced than the backend `fix.status` (a worktree branch
 * ahead, or a pre-commit pulse), but never downgrades below it. In a consistent
 * projection `fix.status === deriveContainerStatus(tasks)` and `toEffectiveTask`
 * only promotes, so the rollup is always ≥ `fix.status` and this equals the raw
 * rollup; the floor only guards an inconsistent input (e.g. a `fix.status`
 * patched without its task, or no tasks loaded). A terminal backend status wins.
 */
export function deriveFixEffectiveStatus(fix: {
  status: RefStatusCell['status'];
  /**
   * Optional to match the wire truth: an SSE fix payload can arrive without a
   * tasks array (observed as an uncaught `.length` TypeError in an async
   * handler during full-suite runs). Absent reads exactly like empty — the
   * backend status stands.
   */
  tasks?: readonly TaskRowTask[];
}): RefStatusCell['status'] {
  if (fix.status === 'completed' || fix.status === 'superseded') return fix.status;
  if (fix.tasks === undefined || fix.tasks.length === 0) return fix.status;
  const rolled = deriveTasksEffectiveStatus(fix.tasks);
  return rolled === 'not_started' ? fix.status : rolled;
}

/**
 * Whether a PRD's cleanup collapses onto ONE shared worktree (done-lane-
 * cleanup task 5, reworked by fix prd-cleanup-row-keys-dead-attribution-
 * branch task 2): true when every LIVE (non-superseded, by the same
 * pulse-aware rollup the PRD partition uses) feature is landed AND there is a
 * branch every one of them finished work on, PROVEN by the git-derived
 * lattice — a live worktree cell with terminal status. Attribution stamps
 * never participate: they survive reaps and the legacy→typed rename, so a
 * stamp can point at a branch that no longer exists (the
 * spike-worktree-lifecycle 500). The caller keys the cleanup surface by the
 * WORK ITEM (`prd:<id>`) — branch resolution is the server's job.
 */
export function hasSharedLiveCleanupBranch(
  features: readonly { id: string; tasks?: readonly TaskRowTask[] }[],
  isLanded: (featureId: string) => boolean,
): boolean {
  return sharedLiveCleanupBranches(features, isLanded).length > 0;
}

/**
 * The branches the ONE shared prd-keyed Cleanup row actually covers (fix
 * mixed-branch-cleanup-prd-buries-affordance task 2): the INTERSECTION of
 * every live feature's finished live branches, sorted — non-empty exactly when
 * {@link hasSharedLiveCleanupBranch} collapses (the predicate IS this fold's
 * non-emptiness, so the two can never drift). The cap suppression keys
 * membership here: a feature that ALSO finished work on a branch outside the
 * intersection keeps its own Delete-worktree cap, because the shared row's
 * teardown will not touch that worktree.
 */
export function sharedLiveCleanupBranches(
  features: readonly { id: string; tasks?: readonly TaskRowTask[] }[],
  isLanded: (featureId: string) => boolean,
): readonly string[] {
  const live = features.filter((f) => deriveTasksEffectiveStatus(f.tasks ?? []) !== 'superseded');
  if (live.length === 0 || !live.every((f) => isLanded(f.id))) return [];
  const [first, ...rest] = live.map((f) => finishedWorktreeBranches(f.tasks ?? []));
  // `live` is non-empty here — the undefined arm is TS index-narrowing, not a
  // reachable branch (adversarial review of 9e615a030, LOW).
  if (first === undefined) return [];
  return [...first].filter((branch) => rest.every((s) => s.has(branch))).sort();
}

/**
 * Per feature: the live branches its finished work sits on — worktree cells at
 * a terminal status. The lattice only lists branches that EXIST, so this is
 * the stamp-proof judgement every cleanup fold shares (attribution stamps
 * survive reaps and the legacy→typed rename; a cell cannot). Exported for the
 * per-feature cap suppression (task 2): a row's cap folds only when EVERY
 * branch here is covered by a rendered Cleanup row — detailsBranch won't do,
 * since the tie-ranked lattice never attributes a landed task, leaving it on
 * the attribution stamp.
 */
export function finishedWorktreeBranches(tasks: readonly TaskRowTask[]): ReadonlySet<string> {
  const set = new Set<string>();
  for (const t of tasks)
    for (const c of t.statusByRef ?? [])
      if (c.isWorktree === true && c.isLaunchRef !== true && (c.status === 'completed' || c.status === 'superseded'))
        set.add(c.ref);
  return set;
}

/**
 * The per-branch cleanup fold (fix mixed-branch-cleanup-prd-buries-affordance
 * task 1): EVERY live branch carrying a LANDED live feature's terminal
 * worktree cell, deterministically sorted. Where
 * {@link hasSharedLiveCleanupBranch} asks "is there ONE branch every landed
 * feature shares?" (the single-row collapse), this asks "which branches carry
 * any landed feature's finished work?" — one Cleanup row each on a
 * mixed-branch PRD, keyed by the RAW BRANCH (findWorktreeForId resolves
 * branch-first server-side). Unlanded features contribute nothing (merge, not
 * cleanup, is their next act); superseded features contribute nothing
 * (retired scope is not cleanup work).
 */
export function deriveLiveCleanupBranches(
  features: readonly { id: string; tasks?: readonly TaskRowTask[] }[],
  isLanded: (featureId: string) => boolean,
): readonly string[] {
  const branches = new Set<string>();
  for (const f of features) {
    if (deriveTasksEffectiveStatus(f.tasks ?? []) === 'superseded') continue;
    if (!isLanded(f.id)) continue;
    for (const branch of finishedWorktreeBranches(f.tasks ?? [])) branches.add(branch);
  }
  return [...branches].sort();
}

/**
 * The attribution fold (fix prd-cleanup-rows-not-attributed-to-features
 * task 1): each SETTLED feature (rollup completed AND landed — exactly the
 * rows the Completed group renders the affordance on) → the live cleanup
 * branches it OWNS, per-feature lists sorted. Same lattice judgement as
 * {@link deriveLiveCleanupBranches} — which flattened the branch→feature
 * relationship into a bare set, the reason mixed-branch Cleanup rows stacked
 * unattributed above the feature list. The FIRST owning feature in feature
 * order wins a branch several settled features share, so no branch ever
 * mounts two teardown commands; features owning nothing get no entry.
 *
 * Two ownership guards (adversarial review of 2590d297b, HIGH; user report
 * on PRD `workers`, 2026-07-27):
 * - Only a SETTLED feature owns. Ownership must coincide with the rendered
 *   affordance (the Completed group's pill + expand-mounted command), so a
 *   landed feature still rolling up in_progress cannot claim a branch into
 *   the covered set that no rendered row would own.
 * - A branch some UNSETTLED feature still works on is PROTECTED — no owner
 *   may claim it. The reachability lattice marks a landed feature's tasks
 *   terminal on any branch its commits are visible from, so without this a
 *   landed sibling advertised a LIVE worker run's worktree as its own
 *   cleanup debt. A live workspace is never cleanup. Superseded features
 *   are neutral throughout: they neither own nor protect.
 *
 * SECOND SOURCE (fix prd-cleanup-pill-not-attributed-to-features task 2):
 * `serverAttributed` carries the board row's matched cleanup branches — the
 * git-disk fact for the landed population whose lattice cells the fact
 * gather excludes. Typed plan names (flat or run-scoped) parse to their
 * owning feature under the SAME guards as the lattice pass (settled owners
 * only; protected branches unclaimable); the exact-id `plan/<prd>` form and
 * unknown parses attribute to no one.
 *
 * CALLER CONTRACT: pass ALL of the plan's features, in stable display order
 * (the markdown feature order every surface renders). The full array is
 * required for the protection pass; the order defines shared-branch
 * ownership (adversarial review of dc9b52698, LOW).
 */
export function deriveFeatureCleanupBranches(
  features: readonly { id: string; tasks?: readonly TaskRowTask[] }[],
  isLanded: (featureId: string) => boolean,
  serverAttributed?: { prdId: string; branches: readonly string[] },
): ReadonlyMap<string, readonly string[]> {
  const claimed = new Set(protectedWorkspaceBranches(features, isLanded));
  const owned = new Map<string, readonly string[]>();
  for (const f of features) {
    if (!isSettled(f, isLanded)) continue;
    const branches = [...finishedWorktreeBranches(f.tasks ?? [])].filter((b) => !claimed.has(b)).sort();
    if (branches.length === 0) continue;
    for (const b of branches) claimed.add(b);
    owned.set(f.id, branches);
  }
  // The board row's server-attributed branches (fix prd-cleanup-pill-not-
  // attributed-to-features task 2): the git-disk fact that tripped the
  // container's cleanup pill is an ownership source of its own — the landed
  // population's lattice cells are exactly what the fact gather excludes, so
  // the fold above legitimately yields nothing for it (the dead-stamp
  // spike-worktree-lifecycle shape). A typed plan branch — flat
  // `plan/<prd>-<feature>` or run-scoped `plan/<runId>/<prd>-<feature>`
  // (ADR-0018; the worker-run population the server matcher also emits) —
  // parses to its owning feature. The prior-review guards hold here too:
  // only a SETTLED feature owns (an unsettled/superseded row renders no
  // affordance, so an entry would suppress caps with no rendered owner);
  // protected active workspaces stay unclaimable; the exact-id `plan/<prd>`
  // form and any name parsing to no feature in this plan attribute to no one
  // (the flattened join is ambiguous across prds sharing a prefix —
  // over-flagging is the board row's accepted posture, not a feature row's).
  if (serverAttributed !== undefined) {
    const prefix = `${serverAttributed.prdId}-`;
    for (const branch of serverAttributed.branches) {
      if (!branch.startsWith('plan/') || claimed.has(branch)) continue;
      // Strip the type segment, then a run-id segment when present — the id
      // is always the LAST path segment (mirrors core's parseWorktreeBranch).
      const rest = branch.slice('plan/'.length);
      const flattenedId = rest.includes('/') ? rest.slice(rest.indexOf('/') + 1) : rest;
      if (!flattenedId.startsWith(prefix)) continue;
      const featureId = flattenedId.slice(prefix.length);
      const feature = features.find((f) => f.id === featureId);
      if (feature === undefined || !isSettled(feature, isLanded)) continue;
      claimed.add(branch);
      owned.set(featureId, [...(owned.get(featureId) ?? []), branch].sort());
    }
  }
  return owned;
}

/** Settled = the rollup the Completed group buckets on AND delivered — the
 * only rows the per-feature cleanup affordance renders on. */
const isSettled = (
  f: { id: string; tasks?: readonly TaskRowTask[] },
  isLanded: (featureId: string) => boolean,
): boolean => deriveTasksEffectiveStatus(f.tasks ?? []) === 'completed' && isLanded(f.id);

/**
 * The branches some UNSETTLED feature still works on — every worktree-cell
 * ref (any status; a live feature's done tasks already carry terminal cells
 * on its branch) of a feature that is neither settled nor superseded.
 * These are ACTIVE WORKSPACES: no cleanup fold may claim one, and the cap
 * suppression set must absorb them so no endcap offers their teardown
 * (observed live on PRD `workers`, 2026-07-27: reachability cells let a
 * landed feature advertise a live worker run's fix worktree as cleanup
 * debt). Superseded features are neutral: they neither own nor protect.
 * Deterministically sorted.
 */
export function protectedWorkspaceBranches(
  features: readonly { id: string; tasks?: readonly TaskRowTask[] }[],
  isLanded: (featureId: string) => boolean,
): readonly string[] {
  const branches = new Set<string>();
  for (const f of features) {
    if (deriveTasksEffectiveStatus(f.tasks ?? []) === 'superseded' || isSettled(f, isLanded)) continue;
    for (const t of f.tasks ?? [])
      for (const c of t.statusByRef ?? [])
        if (c.isWorktree === true && c.isLaunchRef !== true) branches.add(c.ref);
  }
  return [...branches].sort();
}
