interface PipelineEditorProps {
  /** Full pipeline including hook steps and review steps */
  pipeline: PipelineStep[];
  /** All available capability types (active + inactive shown) */
  available: PipelineStep[];
  onSave: (pipeline: PipelineStep[]) => void;
  saving?: boolean;
  showFixedPhases?: boolean;
  /** Show items as parallel (no ordering, no drag) instead of sequential */
  parallel?: boolean;
  /** Hook name for this pipeline (e.g. 'pre-commit', 'post-land'). Enables the
   *  hook drop zone when set, and is the stage a hook lane stamps onto a dropped
   *  step. Typed as core's LifecycleStage — the parent union — so it accepts the
   *  completion / post-land stages beside the git hooks and cannot drift. */
  hookName?: LifecycleStage;
  /**
   * Render only one lane of the single pipeline value:
   *  - `per-commit` — the static hook steps (run every commit), static-only.
   *  - `per-task`   — the fixed Red/Green TDD phases + the review-gate steps.
   *  - `post-land`  — the async post-merge validation steps; a hook lane like
   *    `per-commit` but stamping the zone's `hookName` (`post-land`) on add.
   *  - `work-item`  — the completion-stage steps; a hook lane that stamps BOTH
   *    completion stages (`['fix-complete', 'feature-complete']`) as an array,
   *    since a completion step is nearly always wanted for a fix AND a feature.
   * The lanes keep the OTHER lane intact on save (no clobber). When unset the
   * editor renders the legacy combined Hooks + Review zones.
   */
  lane?: 'per-commit' | 'per-task' | 'post-land' | 'work-item';
}

const byLabel = (a: PipelineStep, b: PipelineStep) => (a.label ?? '').localeCompare(b.label ?? '');

