/** Narrow a raw <select> value to a ScopeMode without asserting — a change event
 *  gives a `string`, and only the SCOPE_MODES members are valid to pin. */
const SCOPE_MODE_SET: ReadonlySet<string> = new Set(SCOPE_MODES);
const isScopeMode = (value: string): value is ScopeMode => SCOPE_MODE_SET.has(value);

/** The config panel's fixed width — the single source the horizontal clamp and
 *  the rendered element share (no `w-72` class to drift against). */
export const CONFIG_PANEL_WIDTH = 288;

/**
 * Position the step-config panel relative to the clicked tile. Prefers just below
 * the tile; flips ABOVE when there isn't room below (so it never renders past the
 * fold — the whole panel stays on-screen, not just its top edge); clamps the left
 * edge into the viewport; caps height to the viewport with scroll. With no rect
 * (config opened without a click) it centres. Pure, so the arithmetic is tested.
 */
export function computePanelStyle(
  rect: Pick<DOMRect, 'top' | 'bottom' | 'left'> | null,
  viewport: { width: number; height: number },
): React.CSSProperties {
  const GAP = 8;
  const MIN_H = 180; // usable height we want below before flipping above
  if (!rect) return { top: '50%', left: '50%', transform: 'translate(-50%, -50%)' };
  const { width: vw, height: vh } = viewport;
  const left = Math.max(GAP, Math.min(rect.left, vw - CONFIG_PANEL_WIDTH - GAP));
  const base: React.CSSProperties = { left, width: CONFIG_PANEL_WIDTH, maxHeight: vh - 2 * GAP, overflowY: 'auto' };
  const roomBelow = vh - rect.bottom - GAP;
  const roomAbove = rect.top - GAP;
  // Below when it fits, or when below simply has more room than above; else flip.
  return roomBelow >= MIN_H || roomBelow >= roomAbove
    ? { ...base, top: rect.bottom + GAP }
    : { ...base, bottom: vh - rect.top + GAP };
}

/** What a runs-tests step will run on in this lane — the scope `resolveStepScope`
 *  derives from the stage. Read-only: it reports the resolved value, it does not
 *  pin `step.scope` (scope stays stage-keyed). Shown only on runs-tests tiles. */
const ScopePill: React.FC<{ id: string; scope: ScopeMode }> = ({ id, scope }) => (
  <span
    data-testid={`scope-pill-${id}`}
    className="pill pill-muted"
    title={`Runs on: ${scope}`}
  >
    {scope}
  </span>
);

/** The tile's foot tags — the tollgate threshold badge and the run-scope pill —
 *  in ONE in-flow row so they can never overlap (a step can be both a tollgate and
 *  a runs-tests tile). Renders nothing when the tile has neither. */
const TileTags: React.FC<{ id: string; isTollgate?: boolean; maxAttempts?: number; scope?: ScopeMode }> = ({ id, isTollgate, maxAttempts, scope }) => {
  if (!(isTollgate && maxAttempts != null) && !scope) return null;
  return (
    <span className="flex items-center gap-1 mt-0.5">
      {isTollgate && maxAttempts != null && <TollgateBadge maxAttempts={maxAttempts} />}
      {scope && <ScopePill id={id} scope={scope} />}
    </span>
  );
};

