import type { AssetItemKind } from '@/services/api';

/**
 * The design-assets view (surface-design-assets F4) is a MODE of the
 * currently-open item, not a standalone view: the URL already identifies the
 * item via `?view=<area>&item=<ref>`, so `?assets` is a bare marker.
 *
 * Since board-first-chrome the board is the sole work area, so the kind can no
 * longer be read off the area name (it would always be `board`, which mapped to
 * null — leaving the assets panel unreachable, fix:
 * assets-view-unreachable-from-board). Instead it rides the kind-prefixed board
 * item ref — `prd:<slug>` / `fix:<slug>` — which is authoritative regardless of
 * area. This returns both the {@link AssetItemKind} and the BARE slug (the
 * prefix stripped), since the asset API is keyed by the slug alone. Refs that
 * carry no assets (spike / unknown prefix / empty) return null.
 *
 * The `decisions` area is the one non-board exception: its item is a bare ADR
 * slug (no prefix), mapped to `adr`.
 */
export function deriveAssetsTarget(
  activeArea: string,
  itemRef: string | null | undefined,
): { kind: AssetItemKind; slug: string } | null {
  if (!itemRef) return null;

  // Board items are kind-prefixed; the prefix is the authoritative kind.
  const sep = itemRef.indexOf(':');
  if (sep > 0) {
    const slug = itemRef.slice(sep + 1);
    if (slug.length === 0) return null;
    const prefix = itemRef.slice(0, sep);
    if (prefix === 'prd') return { kind: 'prd', slug };
    if (prefix === 'fix') return { kind: 'fix', slug };
    return null; // spike / anything else carries no assets
  }

  // Decisions is a non-board area whose item is a bare ADR slug (no prefix).
  if (activeArea === 'decisions') return { kind: 'adr', slug: itemRef };
  return null;
}
