import React from 'react';
import { Bot, Cloud, GitBranch, User } from 'lucide-react';
import { cn } from '@/lib/utils';
import { dedupeByBranch, type WorktreeBranchRef } from './worktree-branches';
import { GLYPH_STROKE_WIDTH, WorktreeChip, WorktreeMergeBar, WorktreeTooltipBody } from './worktree-indicator-parts';
import { ChipShell, GLYPH_CHIP_CLASS, GlyphChip, TwoLineTip } from './glyph-chip';
import LaunchControl, { type LaunchTarget } from './LaunchControl';
import ResumeControl, { type ResumeTarget } from './ResumeControl';
import { ProviderGlyph, providerForAgent } from './icons/provider-glyphs';

export interface MiniStatusRailProps {
  /** Branch(es) this work lives on. When present (the work is on a worktree) the
   *  rail leads with the clickable merge-status pill; empty/absent ⇒ no pill. */
  branches?: readonly WorktreeBranchRef[];
  /** Merge affordance — wired to whatever opens the delivery surface. Omit for a
   *  glance-only pill (a non-button span). */
  onMerge?: () => void;
  /** Whether a worker (a live run) drove the work — robot glyph; otherwise the
   *  user glyph ("the operator did this, not a worker"). */
  isWorkerRun: boolean;
  /** Worker identity for the worker-glyph tooltip — name on top, model beneath. */
  workerName?: string;
  workerModel?: string;
  /** How the worktree indicator reads. `'merge'` (default) leads with the long
   *  "View merge status" CTA — the delivery affordance on detail headers.
   *  `'compact'` renders an icon-only branch chip (single branch) / "{n} branches"
   *  (several) for cards, task rows, and feature rows where space is tight; the
   *  full branch + worktree names stay in the tooltip. Both modes are clickable
   *  via `onMerge` and glance-only otherwise. */
  worktreeMode?: 'merge' | 'compact';
  /**
   * Layout mode. `'rail'` (default) is the full at-a-glance rail: worktree
   * first, then the runner glyph (Bot **or** User) and — for remote work —
   * the Cloud glyph (local is the unmarked default everywhere, MSR rule 5).
   * `'card'` is the terse sidebar-card variant: it shows a glyph only when it
   * carries signal — a worker Bot only when worker-driven, the Cloud only for
   * a remote worker — hiding the User default, and orders the (compact)
   * worktree chip LAST: worker · env · branch.
   * `'board'` (task 30) splits by who ran it: an interactive session shows the
   * User glyph and NO location — with the compact worktree chip leading when the
   * work carries an attribution, `[worktree] [user]` (task 35); a worker shows
   * the Bot, plus the Cloud when remote, and never the chip.
   */
  mode?: 'rail' | 'card' | 'board';
  /** Where the work ran — `remote` shows the cloud glyph beside the runner;
   *  `local` is unmarked (the disk glyph is deleted, MSR rule 5). */
  where: 'local' | 'remote';
  /** Environment identity for the environment-glyph tooltip — name on top,
   *  details beneath. */
  envName?: string;
  envDetails?: string;
  /**
   * The item-first launch target (item-launch-rail): when present AND the rail
   * is idle — no worktree, no live worker — the whole rail is the [Launch ▾]
   * control. Header (rail-mode) surfaces only: card mode never renders it
   * (cards are glance + navigate). A worktree or a live worker always wins
   * over it; the host owns the status / active-run / repo-scope gating and
   * simply omits the prop when launching makes no sense (task rows never
   * pass one).
   */
  launch?: LaunchTarget;
  /**
   * When present, a run is live on this item (task-worker-run-drilldown) — the
   * durable "a run is live here" signal (read from disk, so it survives
   * navigation). Rail/card modes lead with the blue-pulse Running… pill; board
   * mode carries it as the Bot glyph pulsing blue instead (the pill is deleted
   * from cards — fix sidebar-backlog-card-missing-launched-pill task 2). A
   * live run wins over the idle Launch control.
   */
  activeRunId?: string;
  /** Opens the WorkerRun island for the live run — the Running pill's click
   *  (rail/card modes) or the live Bot glyph's click (board mode). */
  onOpenRun?: () => void;
  /**
   * When set, a self-gating Resume control leads the rail whenever the item's
   * latest run is resumable — shown ALONGSIDE the worktree (unlike the idle-only
   * `launch` control), so a failed run that left its branch can be continued from
   * the item header (fix: item-header-hides-resume-when-worktree-exists). It
   * renders nothing when there is no resumable run.
   */
  resume?: ResumeTarget;
  /**
   * When a run on this item ended badly (run-failure-attention-surface), its
   * terminal `failed`/`stalled` status. `failed` always tints the worker Bot
   * red — a failed liveness always originates from a RUN, even when no commit
   * exists yet to attribute a producingRun (the failed-dispatch shape).
   * Board-mode `stalled` splits by provenance instead: a worker's Bot turns
   * warn, interactive work warn-tints the User glyph (MSR rule 3, fix
   * sidebar-backlog-card-missing-launched-pill task 3). Absent for live/idle
   * work.
   */
  attentionStatus?: 'failed' | 'stalled';
  /**
   * Interactive-agent provenance (interactive-agent-glyph-not-rendered): who
   * produced this work when a human drove an agent (Claude Code / Codex). When
   * present AND `linkedClientCount >= 2`, the rail shows the vendor glyph in
   * place of the User glyph. State glyphs outrank the idle vendor mark:
   * worker Bot > attention/live state > agent > user.
   */
  agent?: { agent: string; model?: string; effort?: string };
  /**
   * How many LLM clients the user has linked (from /config-health). The vendor
   * glyph is gated on ≥2 — with a single client there's nothing to disambiguate.
   */
  linkedClientCount?: number;
  /**
   * Board mode, MSR rule 2 (fix sidebar-backlog-card-missing-launched-pill
   * task 3): a live INTERACTIVE session — the row's liveness is live with no
   * producing run and no active worker run — pulses the User glyph blue. The
   * host derives it (the rail stays presentational); worker signals
   * (activeRunId, attentionStatus) always outrank it.
   */
  interactiveLive?: boolean;
  /**
   * Rail-mode variant hiding the signal-less User default, for headers whose
   * detail surface already states who/where (the fix control strip, F9 t3
   * user call). Signal-bearing glyphs (worker Bot, vendor mark, failed state,
   * the remote Cloud) still render. The env axis needs no hiding any more:
   * the idle local-disk glyph this flag used to suppress is deleted outright
   * (MSR rule 5 — local is the unmarked default everywhere).
   */
  hideIdleGlyphs?: boolean;
  /**
   * The detail-strip variant (fix control-strip-mute-during-live-run): state
   * the worker's NAME and MODEL as VISIBLE TEXT beside the glyph — a detail
   * surface names the fact instead of hiding it in the card idiom's hover
   * tooltip. Pairs with card mode: a live run (`activeRunId` + `onOpenRun`)
   * leads with the pulsing live Bot clicking through to the run stream (never
   * the Running pill), and the worktree chip rides alongside.
   */
  namedWorker?: boolean;
  /**
   * Opt-in (fix feature-card-live-glyph-and-run-watch-surface task 1): a card that
   * passes this adopts the board-mode live vocabulary — a live run pulses the
   * click-through worker glyph and the `RunningPill` is dropped. For a card whose
   * ENDCAP owns the running words (the PRD feature card), where a second Running…
   * pill on the rail is noise. Only that card opts in; every other card keeps the
   * pill and its `Launched`/worker-name semantics.
   */
  liveGlyph?: boolean;
  /** Extra layout classes. */
  className?: string;
}

/**
 * The blue-pulse Running… pill: a button (opening the WorkerRun island via
 * `onOpen`) when wired, a glance-only span otherwise. Same tint + inset-ring
 * pill weight as the worktree / launch chips, so the rail reads consistently —
 * only the hue (blue = live) and the pulsing dot set it apart.
 */
const RunningPill: React.FC<{ onOpen?: () => void }> = ({ onOpen }) => {
  const skin =
    'inline-flex flex-shrink-0 items-center gap-1.5 rounded-lg px-2 py-0.5 text-[11px] font-medium bg-[color-mix(in_oklab,#3b82f6_12%,transparent)] text-blue-600 dark:text-blue-300 shadow-[inset_0_0_0_1px_color-mix(in_oklab,#3b82f6_38%,transparent)]';
  const body = (
    <>
      <span className="h-1.5 w-1.5 flex-shrink-0 rounded-full bg-blue-500 motion-safe:animate-pulse" aria-hidden />
      Running…
    </>
  );
  return onOpen ? (
    <button
      type="button"
      data-testid="rail-running-pill"
      aria-label="Running"
      onClick={(e) => {
        // The pill owns the click — never bubble to a clickable host row.
        e.stopPropagation();
        onOpen();
      }}
      // pointer-events-auto: on the board card the body is pointer-events:none
      // (clicks fall through to the stretched select button) — the pill is a
      // real control and re-enables its own events, like the card's retired
      // Land button did. Harmless in hosts without that wash.
      className={cn(skin, 'pointer-events-auto cursor-pointer transition-colors hover:bg-[color-mix(in_oklab,#3b82f6_20%,transparent)]')}
    >
      {body}
    </button>
  ) : (
    <span data-testid="rail-running-pill" aria-label="Running" className={skin}>
      {body}
    </span>
  );
};

/**
 * The live worker Bot (board mode): a live run reads as the Bot glyph pulsing
 * the live blue — the Running pill is deleted from cards
 * (fix sidebar-backlog-card-missing-launched-pill, MSR rule 1, user call). The
 * glyph inherits the pill's click-through to the WorkerRun island when `onOpen`
 * is wired; unwired hosts get a glance-only span, so the signal survives
 * without a dead button eating the card-select click.
 *
 * Non-colour/motion signal: the aria-label and the "Running…" tooltip carry
 * the state for reduced-motion and assistive users (the pulse is
 * `motion-safe:`-gated on purpose), and the backlog launched window adds the
 * card's `launched` text pill; on in-progress rows the lane itself already
 * says work is underway — that redundancy is why the text pill could go.
 *
 * Inline `color` (not a `text-*` class) so the blue beats the chip's
 * `text-muted-foreground`, matching the failed-glyph tint pattern.
 */

/** The live-glyph skin shared by the pulsing Bot (worker run) and the pulsing
 *  User (interactive session): the live blue + the motion-safe pulse. One
 *  definition so the two live states cannot drift apart. */
const LIVE_GLYPH_CLASS = cn(GLYPH_CHIP_CLASS, 'motion-safe:animate-pulse');
const LIVE_GLYPH_STYLE: React.CSSProperties = { color: 'var(--color-blue)' };

const LiveWorkerBot: React.FC<{ workerLabel: string; onOpen?: () => void }> = ({ workerLabel, onOpen }) => (
  <ChipShell
    testId="rail-worker-live"
    // The clickable variant names the ACTION (the file's chip-label rule); the
    // glance-only span names the state.
    ariaLabel={onOpen ? 'Open live run' : 'Running'}
    onClick={onOpen}
    style={LIVE_GLYPH_STYLE}
    className={LIVE_GLYPH_CLASS}
    // pointer-events-auto: on the board card the body is pointer-events:none
    // (clicks fall through to the stretched select button) — the glyph is a
    // real control and re-enables its own events, exactly as the retired
    // Running pill did.
    buttonClassName="pointer-events-auto"
    tooltip={<TwoLineTip title={workerLabel} detail="Running…" />}
  >
    <Bot strokeWidth={GLYPH_STROKE_WIDTH} className="h-4 w-4" />
  </ChipShell>
);

/**
 * The compact worktree chip: an icon-only branch chip (single branch) or a
 * "{n} branches" chip (several) sharing the purple worktree skin. Clickable
 * (a button firing `onMerge`) when wired, a glance-only span otherwise; the
 * full branch + worktree-dir names live in the tooltip. The long, labelled
 * sibling is {@link WorktreeMergeBar} (merge mode).
 */
const CompactWorktreeChip: React.FC<{
  branches: readonly WorktreeBranchRef[];
  onMerge?: () => void;
}> = ({ branches, onMerge }) => {
  const model = dedupeByBranch(branches);
  if (model.length === 0) return null;
  const multi = model.length > 1;
  // Single branch is icon-only; several collapse to a count. The full branch +
  // worktree names always live in the tooltip, so the summary never repeats them
  // there — the heading names the axis ("Worktree(s)"), not the branch itself.
  const summary = multi ? `${model.length} branches` : model[0].branch;
  const heading = multi ? `${model.length} worktrees` : 'Worktree';
  // The clickable chip's label names the ACTION (opens the merge island), not the
  // bare branch — a screen reader should hear what the button does.
  const ariaLabel = onMerge ? `View merge status for ${summary}` : summary;
  return (
    <WorktreeChip
      data-testid="rail-merge-status"
      ariaLabel={ariaLabel}
      onClick={onMerge}
      // Single branch is icon-only — a tight square matching the runner/env glyph
      // chips; multi carries the "{n} branches" text so it keeps horizontal room.
      className={multi ? undefined : 'p-0.5'}
      tooltip={<WorktreeTooltipBody model={model} heading={heading} />}
    >
      <GitBranch data-testid="branch-indicator" strokeWidth={GLYPH_STROKE_WIDTH} className="h-3 w-3 flex-shrink-0" />
      {multi && <span className="truncate">{summary}</span>}
    </WorktreeChip>
  );
};

/**
 * A compact horizontal rail of at-a-glance status for a unit of work:
 *
 *   [branch · merge status]   — only when on a worktree; the clickable merge
 *                               affordance (same pill + multi-branch tooltip as
 *                               the detail headers, via {@link WorktreeMergeBar}).
 *   [robot | user]            — worker-driven vs operator-driven.
 *   [cloud | disk]            — remote vs local environment.
 *
 * Presentational: the merge click is delegated to `onMerge`; the rail never
 * navigates or fetches itself.
 */
const MiniStatusRail: React.FC<MiniStatusRailProps> = ({
  branches = [],
  onMerge,
  worktreeMode = 'merge',
  mode = 'rail',
  isWorkerRun,
  workerName,
  workerModel,
  where,
  envName,
  envDetails,
  agent,
  linkedClientCount = 0,
  launch,
  activeRunId,
  onOpenRun,
  attentionStatus,
  resume,
  interactiveLive = false,
  hideIdleGlyphs = false,
  namedWorker = false,
  liveGlyph = false,
  className = '',
}) => {
  // Idle: nothing staffed here yet — the launch control IS the rail. Header
  // (rail-mode) surfaces only: cards are glance + navigate, so card mode
  // never renders an action control even when a host passes the target. A
  // live run wins over launch — the Running pill replaces the launch control.
  if (
    launch !== undefined &&
    mode !== 'card' &&
    branches.length === 0 &&
    !isWorkerRun &&
    activeRunId === undefined
  ) {
    return (
      <div data-testid="mini-status-rail" className={cn('inline-flex items-center gap-1.5', className)}>
        <LaunchControl repoId={launch.repoId} item={launch.item} attention={attentionStatus} />
      </div>
    );
  }
  const isCard = mode === 'card';
  const isBoard = mode === 'board';
  const remoteWorker = isWorkerRun && where === 'remote';
  const workerLabel = workerName ?? 'Worker run';
  // Only ever rendered for remote work — the local-disk glyph is deleted
  // (MSR rule 5), so there is no local label to fall back to.
  const envLabel = envName ?? 'Remote (cloud) environment';

  // Board mode's live-run signal is the WORKER GLYPH itself — the Bot pulsing
  // the live blue — not a Running pill (deleted from cards, task 2 of fix
  // sidebar-backlog-card-missing-launched-pill). A live run is by definition
  // worker-driven, so the live Bot renders even before a first commit gives
  // the row a producingRun (the backlog launched window) — it wins over the
  // plain Bot, the vendor mark, and the User default alike.
  // The pulsing live Bot leads whenever a run is live — board mode always, the
  // card-mode named-worker variant (the fix strip), and any card that opts into
  // `liveGlyph` (the feature card, whose endcap owns the running words — fix
  // feature-card-live-glyph-and-run-watch-surface task 1) — so each speaks the
  // board's live vocabulary instead of the anonymous card icon / Running pill.
  const liveWorker = activeRunId !== undefined && (isBoard || (isCard && (namedWorker || liveGlyph)));
  // Card mode drops the worktree chip for a REMOTE worker (its work lives in the
  // cloud sandbox, the Cloud glyph says where). Board mode (task 35) shows the
  // chip only for INTERACTIVE work — `[worktree] [user]`, the chip leading via
  // the rail order below; a worker card keeps `[bot] [location]` with no chip
  // (task 30's split — the worker says where its work lives). A live run
  // counts as worker-ness even before producingRun exists.
  const showWorktree =
    branches.length > 0 && !(isCard && remoteWorker) && !(isBoard && (isWorkerRun || liveWorker));
  // Card and board modes force the compact worktree chip; rail mode honours worktreeMode.
  const worktreeChip = showWorktree ? (
    isCard || isBoard || worktreeMode === 'compact' ? (
      <CompactWorktreeChip branches={branches} onMerge={onMerge} />
    ) : (
      <WorktreeMergeBar
        data-testid="rail-merge-status"
        label="View merge status"
        text="View merge status"
        iconClassName="h-4 w-4"
        branches={branches}
        onClick={onMerge}
      />
    )
  ) : null;

  // A terminal failed/stalled run (attention surface) turns the worker glyph
  // RED — the Bot itself, so it reads as "this worker's run failed" (the "Run
  // failed" tooltip + the board's text pill carry the non-colour signal). A LIVE
  // run wins: if there's an active runId the run is running now (e.g. a retry),
  // so the live signal leads — the Running pill (rail/card) or the live Bot
  // (board, where this guard is belt-and-braces: the liveWorker ternary below
  // already outranks the failed branch) — and no failed glyph shows. High
  // signal, so — unlike the neutral Bot — it renders in card mode too and
  // regardless of isWorkerRun (an attention run is always a worker run).
  // Interactive stalled (board, MSR rule 3): stalled work with NO worker keeps
  // the stalled pill and warn-tints the USER glyph — provenance decides which
  // glyph carries the tint, the Bot never stands in for interactive work.
  // Failed stays on the Bot in every mode: a failed liveness always
  // originates from a RUN (even a failed dispatch with no producing commit).
  // No activeRunId guard here — the liveWorker branch outranks this one, so a
  // live run already wins.
  const interactiveStalled = isBoard && !isWorkerRun && attentionStatus === 'stalled';
  const showFailedGlyph =
    attentionStatus !== undefined && activeRunId === undefined && !interactiveStalled;
  // Interactive-agent provenance replaces the User glyph with the vendor mark —
  // but only when ≥2 clients are linked (with one there's nothing to tell apart).
  // The vendor glyph carries signal (which agent), so — like the worker Bot — it
  // shows in card mode too, where the signal-less User default is hidden. The
  // worker Bot and the failed glyph both still win over it.
  const showVendorGlyph = agent !== undefined && linkedClientCount >= 2;
  const workerGlyph = liveWorker ? (
    <LiveWorkerBot workerLabel={workerLabel} onOpen={onOpenRun} />
  ) : showFailedGlyph ? (
    <GlyphChip
      testId="rail-worker-failed"
      label={`Run ${attentionStatus}`}
      // The worker glyph itself (the Bot), tinted by severity: a hard FAILED run
      // is red (destructive); a STALLED run — no activity, a softer state — is
      // warn/yellow (fix: failed-run-not-surfaced-on-card-and-header). The "Run
      // <status>" tooltip + the board's text pill carry the non-colour signal.
      style={{
        color: attentionStatus === 'stalled' ? 'var(--color-warn)' : 'var(--color-destructive)',
      }}
      tooltip={<TwoLineTip title={workerLabel} detail={`Run ${attentionStatus}`} />}
    >
      <Bot strokeWidth={GLYPH_STROKE_WIDTH} className="h-4 w-4" />
    </GlyphChip>
  ) : interactiveStalled ? (
    // MSR rule 3: the stalled pill carries the words; the USER glyph carries
    // the warn tint — stalled interactive work stays visibly interactive.
    <GlyphChip
      testId="rail-user-stalled"
      label="Session stalled"
      style={{ color: 'var(--color-warn)' }}
      tooltip={<TwoLineTip title="Interactive session" detail="Stalled" />}
    >
      <User strokeWidth={GLYPH_STROKE_WIDTH} className="h-4 w-4" />
    </GlyphChip>
  ) : isWorkerRun ? (
    <GlyphChip label={workerLabel} tooltip={<TwoLineTip title={workerLabel} detail={workerModel} />}>
      <Bot strokeWidth={GLYPH_STROKE_WIDTH} className="h-4 w-4" />
    </GlyphChip>
  ) : isBoard && interactiveLive ? (
    // MSR rule 2: a live interactive session pulses the User glyph the live
    // blue — same skin as the live Bot, but the person's glyph. Glance-only
    // (a session has no run stream to open), so always a span. Sits ABOVE the
    // vendor mark like interactiveStalled does: state glyphs outrank the idle
    // provenance detail (the `agent` prop doc's ordering).
    <ChipShell
      testId="rail-user-live"
      ariaLabel="Running"
      style={LIVE_GLYPH_STYLE}
      className={LIVE_GLYPH_CLASS}
      tooltip={<TwoLineTip title="Interactive session" detail="Running…" />}
    >
      <User strokeWidth={GLYPH_STROKE_WIDTH} className="h-4 w-4" />
    </ChipShell>
  ) : showVendorGlyph ? (
    <GlyphChip label={agent.agent} tooltip={<TwoLineTip title={agent.agent} detail={agent.model ?? agent.effort} />}>
      <ProviderGlyph provider={providerForAgent(agent.agent)} className="h-4 w-4" />
    </GlyphChip>
  ) : isCard || hideIdleGlyphs ? null : (
    <GlyphChip label="User">
      <User strokeWidth={GLYPH_STROKE_WIDTH} className="h-4 w-4" />
    </GlyphChip>
  );

  // Which modes show the env (location) glyph, and when:
  // The env glyph is the Cloud, remote-only in EVERY mode (MSR rule 5, fix
  // sidebar-backlog-card-missing-launched-pill task 5): the HardDrive glyph
  // is deleted — local is the unmarked default. On cards (card/board modes)
  // the Cloud additionally requires a worker: interactive work hides
  // location entirely (task 30), and card mode's old remote-worker gate says
  // the same thing under the remote guard. Rail-mode headers show it for any
  // remote work.
  const showEnv = where === 'remote' && (isCard || isBoard ? isWorkerRun : true);
  const envGlyph = showEnv ? (
    <GlyphChip label={envLabel} tooltip={<TwoLineTip title={envLabel} detail={envDetails} />}>
      <Cloud strokeWidth={GLYPH_STROKE_WIDTH} className="h-4 w-4" />
    </GlyphChip>
  ) : null;

  // A live run leads the rail — the headline "a run is live here" signal.
  // Board mode carries it as the pulsing live Bot instead (above), never the
  // pill.
  // The named-worker variant carries liveness on the pulsing live Bot (above),
  // so it never also renders the Running pill — the fix strip's inline activity
  // panel owns liveness, and a pill there would duplicate it.
  const runningPill = activeRunId !== undefined && !isBoard && !liveWorker ? <RunningPill onOpen={onOpenRun} /> : null;
  // The named-worker variant states the worker's identity in TEXT — the fact a
  // detail surface must show, not bury in the glyph's hover tooltip.
  const workerText =
    namedWorker && (workerName !== undefined || workerModel !== undefined) ? (
      <span className="inline-flex min-w-0 flex-col leading-tight">
        {workerName !== undefined && (
          <span className="truncate text-xs font-medium text-foreground">{workerName}</span>
        )}
        {workerModel !== undefined && (
          <span className="truncate text-[11px] text-muted-foreground">{workerModel}</span>
        )}
      </span>
    ) : null;
  // A resumable run leads the rail (before the worktree) whenever a resume target
  // is passed AND no run is live — self-gating on top of that, so it shows only
  // when there is a run to continue, and sits ALONGSIDE the worktree (fix:
  // item-header-hides-resume-when-worktree-exists). The `activeRunId === undefined`
  // guard is load-bearing: a resumed run leaves its failed parent resumable, so
  // without it the control would re-offer Resume beside the live child's Running
  // pill and spawn a SECOND concurrent run on the same worktree. Header-only, like
  // launch.
  const resumeControl =
    resume !== undefined && !isCard && activeRunId === undefined ? <ResumeControl {...resume} /> : null;

  return (
    <div data-testid="mini-status-rail" className={cn('inline-flex items-center gap-1.5', className)}>
      {isCard ? (
        // Terse card order: run · worker · (worker text) · env · branch.
        // The named-worker strip variant (fix endcap-resumes-pipeline-runs
        // task 4) separates the worktree chip from the worker identity block:
        // who ran it and where it lives are two distinct facts, and at the
        // shared gap-1.5 they crowded. Gated on the identity block ACTUALLY
        // rendering (`workerText !== null`) rather than the `namedWorker` flag
        // (adversarial review of 8537b74b7): a live run with no named worker
        // sets namedWorker=true but workerText=null, and there is then nothing
        // to separate the chip from. Terse sidebar/board cards keep the tight
        // gap.
        <>
          {runningPill}
          {workerGlyph}
          {workerText}
          {envGlyph}
          {workerText !== null && worktreeChip !== null ? (
            <span data-testid="rail-worktree-sep" className="ml-2 inline-flex items-center">
              {worktreeChip}
            </span>
          ) : (
            worktreeChip
          )}
        </>
      ) : (
        // Full rail order: resume · run · branch · runner · env.
        <>
          {resumeControl}
          {runningPill}
          {worktreeChip}
          {workerGlyph}
          {envGlyph}
        </>
      )}
    </div>
  );
};

export default MiniStatusRail;
