const BRANCH_PREFIX = 'refs/heads/';
/**
 * Normalise a branch string from a hand-edited spike doc. Strips
 * surrounding whitespace and the `refs/heads/` prefix authors may
 * paste when copying from `git branch -v` output. Without this, a
 * single hand-edit typo turns into an orphan banner — and the
 * dashboard's "clear worktree" recovery action would be wrong (the
 * fix is to correct the branch, not clear the field).
 */
function normaliseBranch(branch) {
    const trimmed = branch.trim();
    return trimmed.startsWith(BRANCH_PREFIX) ? trimmed.slice(BRANCH_PREFIX.length) : trimmed;
}
export function getSpikeWorktreeStatus(spikeWorktree, allWorktrees) {
    if (!spikeWorktree) {
        return { kind: 'unconfigured' };
    }
    const branch = normaliseBranch(spikeWorktree.branch);
    // An empty branch (after normalisation) can't match any worktree
    // and is unmatchable by construction — falls into the orphaned
    // branch below where the dashboard can surface the same recovery
    // affordance as a real orphan.
    //
    // The branch match is inlined (rather than calling `findWorktreeByBranch`)
    // to keep this module free of `worktree-list.ts`'s `child_process` import,
    // so the dashboard can value-import it via the `./spike-worktree-status`
    // subpath — a node runtime dep would break the browser bundle.
    const match = branch.length > 0 ? allWorktrees.find((w) => w.branch === branch) : undefined;
    if (match) {
        return { kind: 'present', branch, path: match.path };
    }
    return { kind: 'orphaned', branch };
}
