import type { DeliveryWorktreeRow } from '../services/api';
import { Island } from './Island';
import { WorktreeMergeDetail } from '@/features/worktrees/components/WorktreeMergeDetail';

/**
 * Dispatch container for the one worktree-merge island (delivery-convergence F10
 * / worktree-keyed-merge-surface task 4), keyed by BRANCH. It is now a thin
 * overlay wrapper: the shared {@link Island} shell around the SAME
 * {@link WorktreeMergeDetail} surface the two-pane Worktrees detail pane renders
 * inline — one worktree-in component, two mounts. The branch's fresh
 * branch-correct row arrives as a prop (the Done feed already fetched it), so
 * there is no second, fix-keyed lookup a worktree branch could never match.
 */
export interface WorktreeDeliveryIslandProps {
  repoId: string;
  /** The worktree row to deliver — its branch is the delivery work-item id. */
  worktree: DeliveryWorktreeRow;
  open: boolean;
  onClose: () => void;
  /** Called after a successful action (in addition to closing) so the list can refresh. */
  onActionComplete?: () => void;
}

export function WorktreeDeliveryIsland({ repoId, worktree, open, onClose, onActionComplete }: WorktreeDeliveryIslandProps) {
  return (
    <Island open={open} onClose={onClose} ariaLabel="Worktree delivery">
      <WorktreeMergeDetail
        repoId={repoId}
        worktree={worktree}
        onClose={onClose}
        // The overlay closes on a successful land/raise/reject; the parent
        // refreshes the list so the next open reflects the new state.
        onActionComplete={() => {
          onActionComplete?.();
          onClose();
        }}
      />
    </Island>
  );
}

export default WorktreeDeliveryIsland;
