import type { PipelineStep } from '@magic-ingredients/tiny-brain-core/phase-derivation';
import type { Fix, Plan } from '../types';
import type { BoardLanes, BoardRow } from '../hooks/useBoard';
import { taskPhaseProgress } from './task-progress';
import { toEffectiveTask, deriveFixEffectiveStatus } from './effective-task';
import { derivePlanDisplayProgress } from './planMetrics';

/**
 * The ONE phase-weighted completion percentage (0–100) for a fix, derived from
 * its tasks — the worktree-effective per-task phase progress summed over the
 * task count. The detail header and the open item's board card BOTH use this, so
 * their progress bars can never drift (fix:
 * board-card-progress-not-synced-with-open-detail). Pure.
 */
export function deriveFixProgress(fix: { tasks?: Fix['tasks'] }, reviewPipeline?: PipelineStep[]): number {
  // Wire truth: a fix payload can arrive without a tasks array (same class as
  // deriveFixEffectiveStatus's guard) — absent reads exactly like empty.
  const effective = (fix.tasks ?? []).map(toEffectiveTask);
  const total = effective.length;
  if (total === 0) return 0;
  const weight = effective.reduce((sum, t) => sum + taskPhaseProgress(t, reviewPipeline), 0);
  return Math.round((weight / total) * 100);
}

/**
 * The completion percentage a fix's card / detail should DISPLAY: the pure
 * phase-weighted {@link deriveFixProgress} PLUS the settled short-circuit — a
 * worktree-effective terminal fix reads 100 regardless of per-task shape. This is
 * exactly FixCard's existing `effectiveFixStatus terminal ? 100 : mean`, extracted
 * so FixCard, FixDetail and the board open-item override share ONE rule and can't
 * drift. Keyed on {@link deriveFixEffectiveStatus} (promote-only), so it reads 100
 * for a declared-terminal fix (matching the server `summariseFix`) and for a
 * worktree-ahead fix whose launch-ref status lags. Pure.
 */
export function deriveFixDisplayProgress(
  fix: Pick<Fix, 'status' | 'tasks'>,
  reviewPipeline?: PipelineStep[],
): number {
  const status = deriveFixEffectiveStatus(fix);
  if (status === 'completed' || status === 'superseded') return 100;
  return deriveFixProgress(fix, reviewPipeline);
}

/**
 * Override the OPEN item's board-card `summary.progress` with the value its detail
 * header shows, so a single `itemDetail` change moves the card and header in
 * lockstep (fix: board-card-progress-not-synced-with-open-detail):
 * - a fix → the header's {@link deriveFixDisplayProgress} over the fresh full
 *   `fix.tasks`;
 * - a PRD → the header's {@link derivePlanDisplayProgress} over the fresh
 *   `plan.features`, with the SAME `reviewPipeline` PlanDetails uses.
 * Both are the phase-weighted mean PLUS the settled short-circuit (a worktree-
 * effective terminal item reads 100), so the open card matches its detail AND the
 * settled closed board card — every progress surface now shares one rule
 * (unify-settled-progress-short-circuit). Every other row is untouched; null open
 * item(s) return the lanes unchanged. Pure.
 */
export function applyOpenItemProgress(
  lanes: BoardLanes,
  openFix: Fix | null,
  openPlan: Plan | null = null,
  reviewPipeline?: PipelineStep[],
): BoardLanes {
  if (openFix === null && openPlan === null) return lanes;
  const fixProgress = openFix !== null ? deriveFixDisplayProgress(openFix, reviewPipeline) : null;
  const planProgress = openPlan !== null ? derivePlanDisplayProgress(openPlan, reviewPipeline) : null;

  // `<kind>Progress !== null` is exactly `open<Kind> !== null` (derive* always
  // returns a number for a non-null item), so it's both the open-item guard and
  // the type-narrow to `number` — the open row is then UNCONDITIONALLY patched
  // (an open PRD with no loaded tasks patches to 0, not skipped).
  const patchRow = (r: BoardRow): BoardRow => {
    const withProgress = (progress: number): BoardRow => ({ ...r, summary: { ...r.summary, progress } });
    if (fixProgress !== null && r.workRef.kind === 'fix' && r.workRef.id === openFix?.id) {
      return withProgress(fixProgress);
    }
    if (planProgress !== null && r.workRef.kind === 'prd' && r.workRef.id === openPlan?.id) {
      return withProgress(planProgress);
    }
    return r;
  };

  return {
    backlog: lanes.backlog.map(patchRow),
    inProgress: lanes.inProgress.map(patchRow),
    inReview: lanes.inReview.map(patchRow),
    done: lanes.done.map(patchRow),
    canceled: lanes.canceled.map(patchRow),
  };
}
