import { useEffect, useRef, useState } from 'react';
import { Check, Copy, GitMerge, RefreshCw, Terminal, TriangleAlert } from 'lucide-react';
import { cn } from '@/lib/utils';
import type { ReconcileStripState, ReconcileTerminal } from '../utils/reconcile-strip';

export interface ReconcileStripProps {
  /** The machine state ({@link deriveReconcileStrip}) — this component only renders it. */
  state: ReconcileStripState;
  /** The branch the reconcile acts on — names the conflict hand-off command. */
  branch: string;
  /** The run's streamed output — reachable in place on a failed verification. */
  output?: string;
  /** Re-run the reconcile ladder (the streamed prepare) — offered on the conflict terminal. */
  onRecheck?: () => void;
}

/** Terminal tone accents, keyed off the shared CSS tone variables. */
const TERMINAL_TONE: Record<ReconcileTerminal, string> = {
  'ready-to-land': '--color-done',
  conflict: '--color-warn',
  'verify-failed': '--color-phase-red',
  failed: '--color-phase-red',
};

const segButton =
  'inline-flex items-center gap-1.5 rounded-lg seg px-2.5 py-1.5 text-xs text-muted-foreground transition-colors hover:text-foreground';

/** How long the hand-off Copy shows its copied tick before reverting. */
const COPIED_FEEDBACK_MS = 2_000;

/** `65_000ms → "1m 5s"`, `9_000ms → "9s"` — coarse on purpose; it reads as a clock, not a stopwatch. */
function formatElapsed(ms: number): string {
  const total = Math.max(0, Math.floor(ms / 1000));
  const minutes = Math.floor(total / 60);
  return minutes > 0 ? `${minutes}m ${total % 60}s` : `${total}s`;
}

/**
 * The running strip's advancing elapsed readout, anchored to the phase frame's
 * `since` (reconcile-verify-progress-invisible): a verify routinely runs 10+
 * minutes, and a static label is indistinguishable from a hang — the tick IS
 * the liveness signal.
 */
function ElapsedSince({ since }: { since: string }) {
  const [now, setNow] = useState(() => Date.now());
  useEffect(() => {
    const id = setInterval(() => setNow(Date.now()), 1000);
    return () => clearInterval(id);
  }, []);
  const anchor = Date.parse(since);
  // An unparseable anchor renders nothing — never the literal "NaNs".
  if (Number.isNaN(anchor)) return null;
  return (
    // aria-hidden: the strip is a role="status" live region (implicit polite +
    // atomic), and a per-second tick inside it would re-announce the whole
    // strip every second for the length of a 12-minute verify. The tick is a
    // sighted-liveness affordance; the phase label carries the announcement.
    <span data-testid="reconcile-elapsed" aria-hidden="true" className="ml-auto tabular-nums text-subtle">
      {formatElapsed(now - anchor)}
    </span>
  );
}

/**
 * The landing strip's reconcile state (work-item-provenance F7 task 2) — a pure
 * render of the {@link ReconcileStripState} machine. While the run streams it
 * shows the HONEST phase label (`Verifying…` during the verify build, never a
 * stale "Rebasing onto main…"); each terminal renders its own affordance — the
 * conflict hand-off is copyable (plus Re-check to re-run the ladder), and a
 * failed verification's output is reachable in place. Idle renders nothing.
 */
export function ReconcileStrip({ state, branch, output, onRecheck }: ReconcileStripProps) {
  // Copied acknowledgement for the conflict hand-off (fix conflict-handoff-
  // copy-gives-no-feedback) — the green-tick idiom the id-copy button uses.
  const [copied, setCopied] = useState(false);
  const copiedTimer = useRef<ReturnType<typeof setTimeout> | undefined>(undefined);
  const handoff = `tiny-brain reconcile-branch ${branch}`;
  // The tick vouches for THIS command being on the clipboard: a changed
  // hand-off target drops it, and unmount clears the pending revert timer.
  useEffect(() => {
    setCopied(false);
    return () => clearTimeout(copiedTimer.current);
  }, [handoff]);

  if (state.kind === 'idle') return null;

  if (state.kind === 'running') {
    return (
      <div
        data-testid="reconcile-strip"
        data-phase={state.phase}
        role="status"
        className="panel-flat flex items-center gap-2 rounded-xl px-3 py-2 text-xs text-muted-foreground"
      >
        <RefreshCw className="h-3.5 w-3.5 shrink-0 animate-spin text-blue" aria-hidden="true" />
        <span className="font-medium text-foreground">{state.label}</span>
        {state.since !== undefined && <ElapsedSince since={state.since} />}
      </div>
    );
  }

  const tone = TERMINAL_TONE[state.terminal];
  const trimmedOutput = output?.trim();
  return (
    <div
      data-testid="reconcile-strip"
      data-terminal={state.terminal}
      className="panel-flat rounded-xl px-3 py-2 text-xs"
    >
      <p className="flex items-center gap-1.5 font-medium" style={{ color: `var(${tone})` }}>
        {state.terminal === 'ready-to-land' ? (
          <GitMerge className="h-3.5 w-3.5 shrink-0" aria-hidden="true" />
        ) : (
          <TriangleAlert className="h-3.5 w-3.5 shrink-0" aria-hidden="true" />
        )}
        {state.label}
      </p>
      {/* The persisted failure reason (fix verify-outcomes-invisible-in-ui
          task 1): a refreshed page says WHY — never idle, never a telemetry
          spelunk. Live streams carry the richer output block below instead. */}
      {state.reason !== undefined && (
        <p data-testid="reconcile-reason" className="mono mt-1 text-[11px] text-muted-foreground">
          {state.reason}
        </p>
      )}
      {state.terminal === 'conflict' && (
        <div className="mt-2 flex items-center gap-2 rounded-lg border border-border bg-background p-2 pl-3">
          <Terminal className="h-3.5 w-3.5 shrink-0 text-subtle" aria-hidden="true" />
          <code data-testid="reconcile-handoff" className="mono min-w-0 flex-1 truncate text-xs text-foreground">
            {handoff}
          </code>
          <button
            type="button"
            aria-label="Copy hand-off command"
            className={cn(segButton, 'shrink-0 px-2 py-1 text-[11px]')}
            onClick={() => {
              void (async () => {
                try {
                  // A missing clipboard (some embeds) throws here just like a
                  // rejected write in a non-secure context — both must NOT
                  // flip to the tick: a false "copied" says the paste is
                  // ready when it is not.
                  await navigator.clipboard.writeText(handoff);
                  // Re-arm, never stack: a second copy inside the window must
                  // not inherit the first click's expiry and blink out early.
                  clearTimeout(copiedTimer.current);
                  setCopied(true);
                  copiedTimer.current = setTimeout(() => setCopied(false), COPIED_FEEDBACK_MS);
                } catch {
                  /* degrade quietly */
                }
              })();
            }}
          >
            {copied ? (
              // Deliberately the shared copy-affordance green (CopyIdButton's
              // tick), NOT this file's TERMINAL_TONE `--color-done`: the tick
              // answers "did MY copy land", the same question the id-copy
              // button answers, so they share one green. Only the icon swaps —
              // the label stays, so the button keeps its width.
              <Check data-testid="reconcile-copied" className="h-3 w-3 text-green-500" aria-hidden="true" />
            ) : (
              <Copy className="h-3 w-3" />
            )}
            Copy
          </button>
        </div>
      )}
      {state.terminal === 'verify-failed' && trimmedOutput !== undefined && trimmedOutput.length > 0 && (
        <pre
          data-testid="reconcile-output"
          className="mono mt-2 max-h-48 overflow-auto whitespace-pre-wrap rounded-lg border border-border bg-background p-2 text-[11px] text-muted-foreground"
        >
          {trimmedOutput}
        </pre>
      )}
      {/* Every FAILURE terminal offers the in-place re-run (adversarial review
          of 62174c0c5, LOW): a fixed verify red or a hand-resolved conflict
          re-checks from here — only the clean ready-to-land needs no retry. */}
      {state.terminal !== 'ready-to-land' && onRecheck !== undefined && (
        <div className="mt-2">
          <button type="button" className={segButton} onClick={onRecheck}>
            <RefreshCw className="h-3.5 w-3.5" />
            Re-check merge
          </button>
        </div>
      )}
    </div>
  );
}

export default ReconcileStrip;
