import { cn } from '@/lib/utils';

/** One segment's state in the journey bar — the same four the chip strip uses,
 *  minus `indeterminate` (the board summary always resolves a card's steps). */
export type JourneySegmentState = 'passed' | 'running' | 'failed' | 'pending';

export interface JourneySegment {
  readonly state: JourneySegmentState;
}

/** The reconcile stage tint on the journey bar (reconcile-segment task 2) —
 *  `verifying` a live reconcile, `ready` a clean verdict, `conflict` a
 *  conflict / verify-failure. Absent (the group with no segment) ⇒ hollow,
 *  "not entered". */
export type JourneyReconcileState = 'verifying' | 'ready' | 'conflict';

/** The colour-coded merge boundary (reconcile-segment task 2). The journey bar
 *  renders only on in-review (pre-land) rows, so there is no `merged` state here —
 *  a landed card drops the bar entirely; its diamond fill is the legacy
 *  {@link JourneyBarModel.landFilled}. */
export type JourneyMergeState = 'pending' | 'ready' | 'blocked';

/** The shaped journey a card renders (F5 task 2 builds this from the summary). */
export interface JourneyBarModel {
  /** Work-item (completion) segments, left of the diamond — one per config step. */
  readonly workItem: readonly JourneySegment[];
  /** The main-boundary diamond is filled — validation crossed to main's tip.
   *  Legacy boolean fill; superseded by {@link land} when present. */
  readonly landFilled: boolean;
  /** Post-merge (regression) segments, right of the diamond — present only when
   *  a post-land lane is configured. */
  readonly postMerge?: readonly JourneySegment[];
  /** The reconcile stage group left of the diamond (reconcile-segment task 2).
   *  Present ⇒ render the tinted reconcile rail; `segment` absent ⇒ a hollow
   *  "not entered" segment. */
  readonly reconcile?: { readonly segment?: JourneyReconcileState };
  /** The colour-coded merge boundary (reconcile-segment task 2). When present it
   *  supersedes {@link landFilled}. Absent ⇒ the legacy boolean fill. */
  readonly land?: JourneyMergeState;
}

export interface JourneyBarProps {
  model: JourneyBarModel;
}

/**
 * A tally-based accessible name — a bar of colour-only spans is meaningless to
 * assistive tech, so the whole bar is a labelled image summarising the journey.
 */
function ariaLabel(model: JourneyBarModel): string {
  const all = [...model.workItem, ...(model.postMerge ?? [])];
  const passed = all.filter((s) => s.state === 'passed').length;
  const failed = all.filter((s) => s.state === 'failed').length;
  const running = all.filter((s) => s.state === 'running').length;
  const bits = [`${passed}/${all.length} passed`];
  if (failed > 0) bits.push(`${failed} failed`);
  if (running > 0) bits.push(`${running} running`);
  return `Validation journey — ${bits.join(', ')}`;
}

function Segment({ state }: { state: JourneySegmentState }) {
  return (
    <span
      data-testid="journey-seg"
      data-state={state}
      className={cn('tb-journey__seg', `is-${state}`)}
      aria-hidden="true"
    />
  );
}

function SegmentGroup({ testId, segments }: { testId: string; segments: readonly JourneySegment[] }) {
  return (
    // Flex-grow tracks the segment count so every segment — across both groups —
    // ends up equal width, and the diamond floats wherever the config puts it
    // (the mock's "the bar's silhouette is a readout of the repo's posture").
    <div data-testid={testId} className="tb-journey__group" style={{ flexGrow: segments.length }}>
      {segments.map((s, i) => (
        <Segment key={i} state={s.state} />
      ))}
    </div>
  );
}

/**
 * The In-review card's journey bar (validation-pipeline-visibility F5 task 1) —
 * a STAGE-QUANTIZED segmented bar: one equal-width segment per validation step
 * (green passed / review-purple pulsing current / red failed / faint pending),
 * split by the main-boundary diamond (the neutral marker where validation
 * switches from work-item scope to main's tip — deliberately NOT a merge glyph,
 * since interactive work on main crosses it without merging). Never a smooth
 * percentage: no intra-step progress exists. This renders a shaped model; F5
 * task 2 builds it from the board summary, task 3 adds the microcopy line.
 */
/** The reconcile stage segment's `--recon` tint class (reconcile-segment task
 *  2) — blue while a reconcile is in flight (`verifying`), the DONE green once it
 *  is clean/`ready` (validation-surface-misreads-ready-to-land-fix task 3: a passed
 *  reconcile reads done, matching the green merge diamond beside it, not the
 *  in-flight blue), warn for a conflict; a hollow (classless) segment reads "not
 *  entered". */
const RECON_SEG_CLASS: Record<JourneyReconcileState, string> = {
  verifying: 'is-recon-running',
  ready: 'is-recon-done',
  conflict: 'is-recon-conflict',
};

/** The colour-coded merge diamond class per readiness (reconcile-segment task 2).
 *  `pending` is the neutral hollow default (no class). */
const LAND_CLASS: Record<JourneyMergeState, string> = {
  pending: '',
  ready: 'is-ready',
  blocked: 'is-blocked',
};

/**
 * The reconcile stage group (reconcile-segment task 2) — one tinted segment in a
 * distinct rail, immediately left of the merge diamond. A hollow (segment-less)
 * group reads "not entered" (work-item not passed, or reconcile not yet run).
 */
function ReconcileGroup({ segment }: { segment?: JourneyReconcileState }) {
  return (
    <div data-testid="journey-reconcile" className="tb-journey__group is-reconcile" style={{ flexGrow: 1 }}>
      <span
        data-testid="journey-recon-seg"
        // `none` is the hollow "not entered" sentinel — a reconcile state has no
        // `pending` member, so the merge-state word is not overloaded here.
        data-recon={segment ?? 'none'}
        className={cn('tb-journey__seg', segment !== undefined && RECON_SEG_CLASS[segment])}
        aria-hidden="true"
      />
    </div>
  );
}

export function JourneyBar({ model }: JourneyBarProps) {
  const { workItem, landFilled, postMerge, reconcile, land } = model;
  // A journey with no segments at all is not a journey — a lone floating diamond
  // (and a "0/0 passed" label) is noise, not a readout. Render nothing; the card
  // shows the bar only when the summary has steps, so this is the honest empty.
  if (workItem.length === 0 && (postMerge === undefined || postMerge.length === 0)) return null;
  // The diamond's fill/colour: the colour-coded `land` state (in-review rows)
  // supersedes the legacy boolean fill; a landed card has no reconcile axis and
  // keeps the legacy is-filled.
  const landClass = land !== undefined ? LAND_CLASS[land] : landFilled ? 'is-filled' : '';
  const landFilledAttr = land === undefined && landFilled;
  return (
    <div data-testid="journey-bar" role="img" aria-label={ariaLabel(model)} className="tb-journey">
      {workItem.length > 0 && <SegmentGroup testId="journey-workitem" segments={workItem} />}
      {reconcile !== undefined && <ReconcileGroup segment={reconcile.segment} />}
      <span
        data-testid="journey-land"
        data-filled={landFilledAttr}
        {...(land !== undefined ? { 'data-merge': land } : {})}
        className={cn('tb-journey__land', landClass)}
        aria-hidden="true"
      />
      {postMerge !== undefined && <SegmentGroup testId="journey-postmerge" segments={postMerge} />}
    </div>
  );
}

export default JourneyBar;
