import React, { cloneElement, useId } from 'react';

/**
 * Field chrome for the draft panels (fix: env-edit-keys-and-table-nits
 * task 6): label + yellow mandatory asterisk + muted subtitle, wrapping
 * exactly one form control.
 *
 * The single `required` flag drives BOTH signals — the aria-hidden asterisk
 * for sighted users and the `required` attribute injected onto the child
 * control for assistive tech — so the two can never disagree. (There is no
 * <form> here; the panels gate submission via their disabled Save buttons,
 * so `required` is an accessibility semantic, not native validation.)
 *
 * The subtitle is associated via aria-describedby, NOT nested in the label:
 * helper prose belongs in the accessible description, never the accessible
 * name.
 */
export const FieldLabel: React.FC<{
  label: string;
  required?: boolean;
  subtitle?: string;
  children: React.ReactElement<Record<string, unknown>>;
}> = ({ label, required = false, subtitle, children }) => {
  const controlId = useId();
  const subtitleId = useId();
  const control = cloneElement(children, {
    id: controlId,
    ...(required ? { required: true } : {}),
    ...(subtitle !== undefined ? { 'aria-describedby': subtitleId } : {}),
  });
  return (
    <div className="text-xs">
      {/* The asterisk sits BESIDE the label element, not inside it, so the
          field's accessible name is exactly the label text. */}
      <span className="text-muted-foreground">
        <label htmlFor={controlId}>{label}</label>
        {required && (
          <span aria-hidden="true" className="ml-0.5 text-yellow-500">
            *
          </span>
        )}
      </span>
      {subtitle !== undefined && (
        <p id={subtitleId} className="mb-0.5 text-[10px] leading-snug text-subtle">
          {subtitle}
        </p>
      )}
      {control}
    </div>
  );
};
