/**
 * Map a telemetry event's task-scoped {@link TaskRef} to the CONTAINER
 * {@link WorkRef} the board and run attachment key on (kind + id), dropping the
 * feature/task narrowing. Pure. Mirrors the container grain `sameBoardItem` uses,
 * so telemetry activity attaches to the same row a worker run does — a PRD task's
 * event lands on its `prd:<id>` row.
 */
export function taskRefToWorkRef(ref) {
    switch (ref.kind) {
        case 'prd':
            return { kind: 'prd', id: ref.prd };
        case 'fix':
            return { kind: 'fix', id: ref.fix };
        case 'spike':
            return { kind: 'spike', id: ref.spike };
    }
}
export function taskRefsMatch(a, b) {
    if (a.kind !== b.kind)
        return false;
    if (a.kind === 'prd' && b.kind === 'prd') {
        return a.prd === b.prd && a.feature === b.feature && a.task === b.task;
    }
    if (a.kind === 'fix' && b.kind === 'fix') {
        return a.fix === b.fix && a.task === b.task;
    }
    if (a.kind === 'spike' && b.kind === 'spike') {
        return a.spike === b.spike && a.task === b.task;
    }
    return false;
}
