import type { RunStatus } from '@magic-ingredients/tiny-brain-core';
import type { RunListRow } from '@/hooks/useRepoRuns';

/**
 * A run row as the board consumes it. Forward-declares the `environment`
 * discriminator the band split keys on: F1 (`run-environment-contract`) adds
 * `environment: { name, provider }` to the wire `RunListRow`; until it lands the
 * board reads the field defensively and treats an absent one as the built-in
 * local environment. Keeping the widening local means F2 builds and tests in
 * isolation without editing F1's `useRepoRuns` type.
 */
export type BoardRow = RunListRow & {
  environment?: { name: string; provider: string };
};

/** One environment band: every run whose worker resolves to this provider. */
export interface EnvBand {
  /** The environment provider — the band key (`local`, `railway`, `managed`, …). */
  provider: string;
  /** A human label for the band header (the environment name, else the provider). */
  name: string;
  /** The band's runs, in the order they arrived. */
  runs: BoardRow[];
}

/** The provider a row belongs to — the local environment when none resolves. */
const providerOf = (run: BoardRow): string => run.environment?.provider ?? 'local';

/** The band label for a row — its environment name, else the local default. */
const nameOf = (run: BoardRow): string => run.environment?.name ?? 'local';

/**
 * Group runs into stacked per-environment bands keyed on `environment.provider`,
 * the local band first and remote providers after it in first-appearance order.
 * Only providers with runs produce a band — a repo with no remote work shows no
 * remote band. A run with no resolvable environment lands in the local band.
 */
export function groupRunsByEnvironment(runs: readonly BoardRow[]): EnvBand[] {
  const bands = new Map<string, EnvBand>();
  for (const run of runs) {
    const provider = providerOf(run);
    const band = bands.get(provider);
    if (band) band.runs.push(run);
    else bands.set(provider, { provider, name: nameOf(run), runs: [run] });
  }
  // Local first; remaining providers keep Map insertion order (first appearance).
  // Providers are unique Map keys, so the comparator only ever pushes 'local'
  // ahead — every other pair keeps its stable-sort insertion order.
  return [...bands.values()].sort((a, b) => {
    if (a.provider === 'local') return -1;
    if (b.provider === 'local') return 1;
    return 0;
  });
}

/** A configured environment the runs board renders a band for — the identity is
 *  its `name` (matches `run.environment.name`); `provider` drives the local/remote
 *  visual split. Mirrors the dashboard's `EnvironmentView` name/provider fields. */
export interface ConfiguredEnvironment {
  readonly name: string;
  readonly provider: string;
}

/** True when a band is the built-in local machine — keyed on `provider` alone,
 *  the same predicate the view's badge/glyph split uses, so ordering and styling
 *  never disagree (a band named `local` on a remote provider is still remote). */
const isLocalEnv = (band: { provider: string }): boolean => band.provider === 'local';

/**
 * The environment bands the runs board always shows — one band per CONFIGURED
 * environment (the Environments registry: built-in `local` first, then each
 * remote environment by name), rendered with full chrome even when idle so the
 * board reads as a standing fleet monitor rather than collapsing to an empty
 * placeholder. Runs slot into the band whose `name` matches `run.environment.name`.
 *
 * A run whose environment is NOT in the configured list (e.g. a repo-scoped
 * environment the global registry does not carry) gets a fallback band derived
 * from the run rows, appended after the configured ones, so no running work is
 * ever dropped. A `local` band is always present even if the registry is empty.
 */
export function envBandsForRuns(
  environments: readonly ConfiguredEnvironment[],
  runs: readonly BoardRow[],
): EnvBand[] {
  // Bucket runs by their environment name (order-preserving).
  const runsByName = new Map<string, BoardRow[]>();
  for (const run of runs) {
    const name = nameOf(run);
    const bucket = runsByName.get(name);
    if (bucket) bucket.push(run);
    else runsByName.set(name, [run]);
  }

  const bandByName = new Map<string, EnvBand>();
  // Configured environments first, in registry order.
  for (const env of environments) {
    if (bandByName.has(env.name)) continue;
    bandByName.set(env.name, { provider: env.provider, name: env.name, runs: runsByName.get(env.name) ?? [] });
  }
  // Fallback bands for runs whose environment the registry does not carry. Each
  // bucket is non-empty, so the provider is read straight off its first run.
  for (const [name, rows] of runsByName) {
    if (bandByName.has(name)) continue;
    bandByName.set(name, { provider: providerOf(rows[0]), name, runs: rows });
  }
  const bands = [...bandByName.values()];
  // Guarantee a local band even when the registry is empty and nothing local ran.
  if (!bands.some(isLocalEnv)) bands.unshift({ provider: 'local', name: 'local', runs: [] });

  // Local island first; the rest keep their insertion order (registry, then fallback).
  return [...bands.filter(isLocalEnv), ...bands.filter((b) => !isLocalEnv(b))];
}

/**
 * One unified run on the board/runs view — a single delivery whose spawned
 * processes are folded together. A land and its post-land regression carry a
 * parent→child link (`parentRunId`, task 1); this entry represents the delivery
 * once, with the two processes listed as {@link steps} rather than each
 * rendering as its own top-level row.
 */
export interface UnifiedRun {
  /** The unified entry's identity — the lead (originating) run's id. */
  runId: string;
  /** The lead run — the delivery's originating process (the land). */
  lead: BoardRow;
  /**
   * The delivery's spawned processes as sub-steps, the lead first and its
   * `parentRunId` children after it in arrival order. A run with no folded
   * children is a single-step entry (just its lead).
   */
  steps: BoardRow[];
}

/**
 * Fold runs into unified deliveries: a run and its `parentRunId` children
 * collapse into ONE {@link UnifiedRun} whose `steps` list the spawned processes
 * (e.g. a land lead + its post-land regression child) as sub-steps, in place of
 * rendering each as a separate top-level row.
 *
 * A run is a LEAD (root) when walking up `parentRunId` reaches a run whose parent
 * is absent or not present — so an orphan child (its parent scrolled off this
 * lens) still surfaces as its own top-level entry rather than being dropped, and
 * a multi-level chain (a retry of a child) folds into its root alongside its
 * ancestors. Children attach to their root's entry in arrival order; leads keep
 * their first-appearance order. A parent cycle terminates at the first repeat.
 */
export function foldUnifiedRuns(runs: readonly BoardRow[]): UnifiedRun[] {
  const byId = new Map(runs.map((run) => [run.runId, run]));
  // The id of a run's root lead — walk up `parentRunId` while the parent is a
  // present, not-yet-seen run. A run with no present parent is its own root.
  const rootOf = (run: BoardRow): string => {
    const seen = new Set<string>();
    let current = run;
    while (current.parentRunId !== undefined && byId.has(current.parentRunId) && !seen.has(current.runId)) {
      seen.add(current.runId);
      current = byId.get(current.parentRunId)!;
    }
    return current.runId;
  };

  const unifiedByLead = new Map<string, UnifiedRun>();
  // Leads first (a run that is its own root), in arrival order, so entries keep
  // their first-appearance order.
  for (const run of runs) {
    if (rootOf(run) === run.runId) unifiedByLead.set(run.runId, { runId: run.runId, lead: run, steps: [run] });
  }
  // Then attach every non-root run to its root's entry, in arrival order. Every
  // resolved root is its own root, so its entry exists.
  for (const run of runs) {
    const root = rootOf(run);
    if (root !== run.runId) unifiedByLead.get(root)!.steps.push(run);
  }
  return [...unifiedByLead.values()];
}

/**
 * The status lanes a band splits into, always rendered in this order:
 * - `running` — live work (running / cancelling).
 * - `attention` — work that needs a human (stalled / failed / rejected).
 * - `done` — terminal, no-action work (completed / cancelled).
 */
export type LaneGroup = 'running' | 'attention' | 'done';

/** The lanes in render order — Running first, then Attention, then Done. */
export const LANE_GROUPS: readonly LaneGroup[] = ['running', 'attention', 'done'];

/** Which lane a run status belongs to — the single status→lane mapping. */
const STATUS_LANE: Record<RunStatus, LaneGroup> = {
  running: 'running',
  cancelling: 'running',
  stalled: 'attention',
  failed: 'attention',
  rejected: 'attention',
  completed: 'done',
  cancelled: 'done',
};

/** The lane a run belongs to, from its status. */
export function laneOf(run: BoardRow): LaneGroup {
  return STATUS_LANE[run.status];
}

/** One status lane within a band: its group key and the runs routed to it. */
export interface Lane {
  /** The lane's status group. */
  group: LaneGroup;
  /** The lane's runs, in arrival order. */
  runs: BoardRow[];
}

/**
 * Split a band's runs into the three status lanes, always returned in
 * {@link LANE_GROUPS} order (Running → Attention → Done). Every lane is present
 * even when empty — the collapse-to-summary decision (F2 task 3) is the
 * component's, off `lane.runs.length`. Arrival order is preserved within a lane.
 */
export function laneRunsInBand(runs: readonly BoardRow[]): Lane[] {
  const lanes: Record<LaneGroup, Lane> = {
    running: { group: 'running', runs: [] },
    attention: { group: 'attention', runs: [] },
    done: { group: 'done', runs: [] },
  };
  for (const run of runs) lanes[laneOf(run)].runs.push(run);
  return LANE_GROUPS.map((group) => lanes[group]);
}

/** The band-meta counts a header derives from its own rows — no server field. */
export interface BandMeta {
  /** Live (non-terminal) runs — the Running-lane statuses (running / cancelling). */
  active: number;
  /** Runs whose `startedAt` lands on the same calendar day as the reference `now`. */
  today: number;
}

/** Two ISO/`Date` instants share a calendar day in the viewer's local zone. */
function isSameLocalDay(a: Date, b: Date): boolean {
  return (
    a.getFullYear() === b.getFullYear() &&
    a.getMonth() === b.getMonth() &&
    a.getDate() === b.getDate()
  );
}

/**
 * The band-meta counts, derived purely client-side from the band's own rows —
 * `active` is the live (Running-lane) run count (the same non-terminal
 * convention the header live badge uses, so a `stalled`/`failed` run is
 * attention, not active), and `today` is the count of runs that started on
 * `now`'s calendar day. No server projection — both are read off the rows the
 * board already has.
 */
export function deriveBandMeta(runs: readonly BoardRow[], now: Date = new Date()): BandMeta {
  let active = 0;
  let today = 0;
  for (const run of runs) {
    if (laneOf(run) === 'running') active += 1;
    if (isSameLocalDay(new Date(run.startedAt), now)) today += 1;
  }
  return { active, today };
}

/**
 * A run's elapsed wall-clock as a compact clock — `MM:SS` under an hour, else
 * `H:MM:SS`. One formatter for both the live tick (now − startedAt) and a
 * terminal run's fixed startedAt→endedAt duration, so the two read the same.
 * A negative (future-start) span clamps to zero.
 */
export function formatElapsed(ms: number): string {
  const total = Math.max(0, Math.floor(ms / 1000));
  const h = Math.floor(total / 3600);
  const m = Math.floor((total % 3600) / 60);
  const s = total % 60;
  const pad = (n: number) => String(n).padStart(2, '0');
  return h > 0 ? `${h}:${pad(m)}:${pad(s)}` : `${pad(m)}:${pad(s)}`;
}

/**
 * A run's elapsed milliseconds: a terminal run's fixed `startedAt`→`endedAt`
 * span, or — for a live run with no end yet — the time since `startedAt` up to
 * `now` (the ticking clock). `null` when neither is computable (a non-live run
 * that never recorded an end), so the card simply omits the elapsed.
 */
export function elapsedMsOf(run: BoardRow, now: number): number | null {
  const start = new Date(run.startedAt).getTime();
  if (run.endedAt) return new Date(run.endedAt).getTime() - start;
  if (run.live) return now - start;
  return null;
}

/**
 * Idle-minutes threshold past which a live run's silence is worth flagging
 * (runs-card-stall-notice). An early warning for a still-running run that has
 * gone quiet — well before it would be formally marked `stalled`.
 */
export const STALL_NOTICE_THRESHOLD_MINUTES = 5;

/**
 * Whole minutes a run has been silent, from its last output tick to `now`
 * (runs-card-stall-notice) — the card shows `no output for {N}m` once this
 * crosses {@link STALL_NOTICE_THRESHOLD_MINUTES}.
 *
 * `null` (no notice) unless the run is LIVE, in-flight (no `endedAt`), and has
 * emitted at least once: an ended run's idle span keeps growing forever and
 * means nothing (the run is done), and a run with no `lastActivityAt` never
 * produced output to measure from (honesty rule). A negative (future
 * last-activity) span clamps to no notice.
 */
export function idleMinutesOf(run: BoardRow, now: number): number | null {
  if (!run.live || run.endedAt || !run.lastActivityAt) return null;
  const idleMs = now - new Date(run.lastActivityAt).getTime();
  if (idleMs < 0) return null;
  return Math.floor(idleMs / 60_000);
}

/**
 * The minutes to show in the card's `no output for {N}m` stall notice, or
 * `null` for no notice — {@link idleMinutesOf} gated by
 * {@link STALL_NOTICE_THRESHOLD_MINUTES}. The whole "is this a stall" decision
 * lives here (pure), so the card only renders the number the model hands it —
 * matching the sibling `elapsedMsOf` / `deriveBandMeta` pure-derivation pattern.
 */
export function stallNoticeMinutesOf(run: BoardRow, now: number): number | null {
  const idle = idleMinutesOf(run, now);
  return idle !== null && idle >= STALL_NOTICE_THRESHOLD_MINUTES ? idle : null;
}
