import type { ReactNode } from 'react';
import { ChevronDown, ChevronRight } from 'lucide-react';
import type { LucideIcon } from 'lucide-react';

/**
 * One collapsible accordion section — the shared "eyebrow" fold affordance used
 * by the worktree provenance island (`WorktreeMergeContent`) and the Done-state
 * fix detail (`FixDetail`). The header is a button (chevron + icon + title, with
 * an optional trailing summary chip always shown); the body renders only when
 * open. The section carries an `aria-label` (= title) so it is a queryable
 * region, and the toggle's accessible name is `Toggle <title> section` to stay
 * distinct from any button inside.
 */
export function CollapsibleSection({
  title,
  icon: Icon,
  open,
  onToggle,
  summary,
  children,
}: {
  title: string;
  icon: LucideIcon;
  open: boolean;
  onToggle: () => void;
  summary?: ReactNode;
  children: ReactNode;
}) {
  return (
    <section aria-label={title} className="border-b border-border last:border-0">
      <button
        type="button"
        aria-expanded={open}
        aria-label={`Toggle ${title} section`}
        onClick={onToggle}
        className="flex w-full items-center gap-2.5 px-6 py-4 text-left transition-colors hover:bg-foreground/[0.02]"
      >
        {open ? (
          <ChevronDown className="h-4 w-4 shrink-0 text-muted-foreground" />
        ) : (
          <ChevronRight className="h-4 w-4 shrink-0 text-muted-foreground" />
        )}
        <Icon className="h-4 w-4 shrink-0 text-muted-foreground" />
        <span className="display flex-1 text-base font-bold">{title}</span>
        {summary}
      </button>
      {open && <div className="px-6 pb-6">{children}</div>}
    </section>
  );
}
