import React from 'react';
import { GitBranch, RefreshCw } from 'lucide-react';
import { Button } from '../ui/button';
import { WorkerCrudBody, useWorkerCrud } from './WorkerCrud';

/**
 * Repo Settings › Workers section (workers PRD, repo-scope-worker-crud task 3).
 *
 * ADR-0025's scope ladder makes the committed `.tiny-brain/workers.yaml`
 * the primary team channel, so its CRUD is first-class here — the same
 * table + draft panel the global /workers page renders (shared
 * `WorkerCrud` surface), pointed at the repo-scoped API. Environments stay
 * global-only in the UI (ADR-0024): the draft panel reads the same global
 * registry, so adding a repo worker is the same Environment → Agent →
 * Model gating, just persisted to the repo scope.
 *
 * Committed-file honesty (ADR-0025): the header says plainly that a CRUD
 * action writes a committed file into the working tree — the dashboard
 * never auto-commits. A worker that references an environment a teammate
 * hasn't configured is BADGED (dangling), not hidden.
 */
export const RepoWorkersSection: React.FC<{ repoId: string }> = ({ repoId }) => {
  const { body, error, loading, reload } = useWorkerCrud(`/api/repos/${repoId}/workers`);

  return (
    <div className="w-full">
      <div className="flex items-start justify-between gap-3">
        {/* Committed-file notice (ADR-0025): the write is honest and manual. */}
        <p className="flex items-start gap-2 text-sm text-muted-foreground">
          <GitBranch className="mt-0.5 h-4 w-4 shrink-0" />
          <span>
            These workers are <strong className="font-medium text-foreground">shared with your
            team</strong>: saving one writes{' '}
            <span className="font-mono text-xs text-foreground">.tiny-brain/workers.yaml</span> in
            your working tree — commit it yourself to share it. The dashboard never commits for you.
          </span>
        </p>
        <Button variant="outline" size="sm" className="shrink-0" onClick={() => void reload()}>
          <RefreshCw className="mr-1.5 h-3.5 w-3.5" />
          Reload
        </Button>
      </div>

      {error && <p className="mt-4 text-sm text-red-500">{error}</p>}
      {loading && <p className="mt-4 text-sm text-muted-foreground">Loading workers…</p>}

      <WorkerCrudBody
        {...body}
        emptyHint="No repo workers yet — add one to share it with your team via git."
      />
    </div>
  );
};
