/**
 * `deriveTaskStateFromEvents` — pure projection of a `TelemetryEvent[]`
 * into the pipeline-state field shape `derivePhase` / `TddPhasePipeline`
 * consume.
 *
 * Exists so the dashboard's pipeline icon strip can render from the
 * append-only telemetry log instead of the drift-prone `progress.json`
 * mutable fields. The structured fields on `progress.json` are missed
 * by multiple writer paths (the one-cycle-per-task reject path, the
 * working-tree vs `.git/tiny-brain/` split, concurrent hook writers,
 * fresh clones with no hooks); telemetry stays whole because it's
 * append-only and best-effort writes don't roll back.
 *
 * Contract:
 *   - Pure (no I/O), deterministic, non-mutating.
 *   - Caller pre-filters events by `taskRef`. This function does NOT
 *     re-filter — mixing tasks is a contract violation that leaks
 *     observably (caught by the cross-task test).
 *   - Output shape is a subset of `PhaseDeriveInput` from
 *     `phase-derivation.ts`, so a caller can pass the result directly
 *     into `derivePhase` or overlay it on a `TaskRowTask`.
 *
 * Event→field mapping (canonical reference):
 *   - phase.entered { phase: 'red' }       → redStartedAt (earliest wins)
 *   - commit.tracked { type: 'test' }       → testCommitSha + testCommittedAt
 *   - commit.tracked { type: 'feat' | 'fix' } → commitSha + committedAt
 *   - persist.review_written { gate }       → reviews[gate].reviewSha + verdict;
 *     also arms the gate so the next
 *     commit.tracked { type: 'refactor' }    → reviews[gate].refactorCommitSha
 *   - pipeline.decision { gate } (legacy)   → arms the same refactor attribution
 *     for the historical corpus that emitted it (agent path no longer does)
 *   - task.completed                         → completedAt
 *   - pipeline.advance.rejected              → no-op (don't roll back)
 */
// Re-export the canonical task-ref join from this browser-safe subpath so the
// dashboard's client-side overlay shares the exact rule the server projector
// uses (event-types only carries types + this pure fn — no Node deps), rather
// than maintaining a drifting copy.
export { taskRefsMatch } from './event-types.js';
export function deriveTaskStateFromEvents(events) {
    // Sort defensively so caller-side ordering can't affect the output.
    // The original array isn't mutated (`[...events]` copies before sort).
    const ordered = [...events].sort((a, b) => a.ts.localeCompare(b.ts));
    const state = {};
    // Per-gate scratchpad for the decision → next-refactor attribution.
    // Holds the gate of the most-recent `pipeline.decision` (and the reviewed sha
    // that armed it); the next `commit.tracked { type: 'refactor' }` consumes it.
    let pendingRefactorGate;
    let pendingRefactorSha;
    // Keys (gate, sha) of decisions whose refactor commit has already landed.
    // A REPLAYED decision for the same (gate, sha) (retry storm / parallel
    // advance) must NOT re-arm the window — otherwise an unrelated later refactor
    // commit is mis-attributed. A decision on a NEW sha is a genuine tollgate
    // retry and is not in this set, so it re-arms (last-write-wins). (fix:
    // pipeline-decision-suppression-drops-refactor-attribution)
    const consumedDecisions = new Set();
    // NUL-joined so a gate or sha can never collide across the boundary.
    const decisionKey = (gate, sha) => `${gate}\u0000${sha}`;
    for (const event of ordered) {
        // Any "intro-shaped" event signals the task exists, so a prior
        // removal checkpoint is cancelled. Passive checkpoint events
        // (`task.removed`, `task.shas_rolled_back`) do NOT count as intro
        // — a rollback on an already-removed task is meaningless, not a
        // re-introduction. No preserved history across the removal
        // boundary — the wipe stays; the flag clears only when real
        // activity resumes.
        if (state.removed === true && !isPassiveCheckpoint(event.kind)) {
            delete state.removed;
        }
        switch (event.kind) {
            case 'phase.entered': {
                // Earliest-wins on every started-at field — pipeline re-entry
                // after a dirty decision must not bump the original start.
                // Dispatch by phase shape: top-level for red/green, per-gate
                // for review:<gate>/refactor:<gate>.
                const phase = event.phase;
                if (phase === 'red') {
                    if (state.redStartedAt === undefined)
                        state.redStartedAt = event.ts;
                }
                else if (phase === 'green') {
                    if (state.greenStartedAt === undefined)
                        state.greenStartedAt = event.ts;
                }
                else {
                    const reviewGate = extractGate(phase, 'review:');
                    if (reviewGate !== undefined) {
                        const record = ensureReviewRecord(state, reviewGate);
                        if (record.startedAt === undefined)
                            record.startedAt = event.ts;
                    }
                    else {
                        const refactorGate = extractGate(phase, 'refactor:');
                        if (refactorGate !== undefined) {
                            const record = ensureReviewRecord(state, refactorGate);
                            if (record.refactorStartedAt === undefined)
                                record.refactorStartedAt = event.ts;
                        }
                    }
                }
                break;
            }
            case 'phase.completed': {
                // *CompletedAt mirrors the phase.entered structure but is
                // last-write-wins — the pipeline re-entering a phase after a
                // dirty decision and completing again is a real operational
                // signal, so the newest completion timestamp is the one to
                // surface.
                const phase = event.phase;
                if (phase === 'red') {
                    state.redCompletedAt = event.ts;
                }
                else if (phase === 'green') {
                    state.greenCompletedAt = event.ts;
                }
                else {
                    const reviewGate = extractGate(phase, 'review:');
                    if (reviewGate !== undefined) {
                        const record = ensureReviewRecord(state, reviewGate);
                        record.completedAt = event.ts;
                    }
                    else {
                        const refactorGate = extractGate(phase, 'refactor:');
                        if (refactorGate !== undefined) {
                            const record = ensureReviewRecord(state, refactorGate);
                            record.refactorCompletedAt = event.ts;
                        }
                    }
                }
                break;
            }
            case 'commit.tracked': {
                if (event.type === 'test') {
                    state.testCommitSha = event.sha;
                    state.testCommittedAt = event.ts;
                }
                else if (event.type === 'feat' || event.type === 'fix') {
                    state.commitSha = event.sha;
                    state.committedAt = event.ts;
                }
                else if (event.type === 'refactor' && pendingRefactorGate !== undefined) {
                    const record = ensureReviewRecord(state, pendingRefactorGate);
                    record.refactorCommitSha = event.sha;
                    record.refactorCommittedAt = event.ts;
                    // Mark this (gate, reviewed-sha) decision consumed so a later replay
                    // of the same decision cannot re-arm the window.
                    if (pendingRefactorSha !== undefined) {
                        consumedDecisions.add(decisionKey(pendingRefactorGate, pendingRefactorSha));
                    }
                    pendingRefactorGate = undefined;
                    pendingRefactorSha = undefined;
                }
                break;
            }
            case 'persist.review_written': {
                const record = ensureReviewRecord(state, event.gate);
                record.reviewSha = event.sha;
                // Fix review-phase-entered-not-emitted-on-commit-driven-transition:
                // the green→review transition never emits a phase.entered{review:<gate>}
                // on the consolidated path, so without this `startedAt` is missing and
                // autoCorrect backfills it with a read-time `new Date()` — warning on
                // every read. Source it from this event's ts instead (earliest-wins, so
                // an explicit review-start event still takes precedence).
                if (record.startedAt === undefined)
                    record.startedAt = event.ts;
                if (event.verdict !== undefined) {
                    record.verdict = event.verdict === 'clean'
                        ? 'clean'
                        : event.verdict === 'failed'
                            ? 'failed'
                            : 'needs-refactoring';
                }
                // Arm refactor-commit attribution from the persist event itself
                // (review-verdict-as-its-own-commit Task 4): a review now emits ONE
                // event, so the next commit.tracked { type: 'refactor' } attributes to
                // this gate. Under Option B both verdicts leave the gate open until its
                // refactor: commit lands (empty on clean), so we arm regardless of
                // verdict. Same consumedDecisions replay guard as pipeline.decision: a
                // replayed persist for an already-consumed (gate, sha) must not re-arm.
                // The legacy pipeline.decision case still arms too (additive) for the
                // historical corpus that emitted it.
                if (!consumedDecisions.has(decisionKey(event.gate, event.sha))) {
                    pendingRefactorGate = event.gate;
                    pendingRefactorSha = event.sha;
                }
                break;
            }
            case 'pipeline.decision': {
                // The decision was made on event.sha — the reviewed commit. Record
                // it as the gate's reviewSha so the projection carries the sha the
                // events already hold (the timeline reads raw events and shows it;
                // the TddPhasePipeline badge reads this projected field). Without
                // it the badge has no sha and renders greyed. persist.review_written
                // is the more precise source and runs first, so first-write wins.
                const record = ensureReviewRecord(state, event.gate);
                record.reviewSha ??= event.sha;
                // Same startedAt sourcing as persist.review_written (fix
                // review-phase-entered-not-emitted-on-commit-driven-transition): cover
                // the case where a decision lands without a preceding persist event, so
                // a recorded reviewSha is never left without an event-sourced startedAt.
                if (record.startedAt === undefined)
                    record.startedAt = event.ts;
                // Option B (fix: pipeline-verdict-trailer-never-appended): a clean
                // verdict no longer auto-skips the refactor. BOTH verdicts leave the
                // gate open until its refactor: commit lands — empty on the clean path,
                // a real refactor on the dirty path. That commit is the carrier of the
                // durable Pipeline: verdict trailer, so the NEXT commit.tracked
                // { type: 'refactor' } attributes to this gate in either case.
                // ('skipped' is still READ as a terminal marker for legacy tasks that
                // recorded it before this change — see phase-derivation — it is just no
                // longer WRITTEN here.)
                //
                // Idempotency: skip arming for a decision whose (gate, sha) refactor has
                // already landed — a replay (retry storm / parallel advance) must not
                // re-open the window. A NEW sha (genuine tollgate retry) is not consumed
                // and re-arms normally.
                if (!consumedDecisions.has(decisionKey(event.gate, event.sha))) {
                    pendingRefactorGate = event.gate;
                    pendingRefactorSha = event.sha;
                }
                break;
            }
            case 'task.completed': {
                state.completedAt = event.ts;
                break;
            }
            case 'task.worktree_assigned': {
                // Last-write-wins: a re-assignment IS the new attribution.
                state.worktree = { name: event.worktreeName, branch: event.branch };
                break;
            }
            case 'task.shas_rolled_back': {
                // Checkpoint, not a sticky filter — clear every event-derived
                // SHA + matching timestamp. Later events repopulate normally.
                // Mirrors the runtime scrub in rollbackOrphanSHAs
                // (planning/fix-task-updater) so the projection matches
                // progress.json after the same scrub.
                delete state.testCommitSha;
                delete state.testCommittedAt;
                delete state.commitSha;
                delete state.committedAt;
                if (state.reviews !== undefined) {
                    for (const gate of Object.keys(state.reviews)) {
                        const record = state.reviews[gate];
                        delete record.refactorCommitSha;
                        delete record.refactorCommittedAt;
                    }
                }
                // Cancel any pending refactor attribution — the decision that
                // would have parked it is now invalidated alongside the SHAs. Also
                // forget consumed decisions so a post-rollback re-decision can re-arm.
                pendingRefactorGate = undefined;
                pendingRefactorSha = undefined;
                consumedDecisions.clear();
                break;
            }
            case 'task.removed': {
                // Wipe prior state and mark removed. Subsequent events on the
                // same taskRef re-introduce the task fresh — there is no
                // preserved history across the removal boundary. Mutate the
                // existing object so the projection result identity is stable;
                // delete every field individually rather than reassigning so
                // the caller's reference (if any) sees the wipe too.
                delete state.redStartedAt;
                delete state.redCompletedAt;
                delete state.greenStartedAt;
                delete state.greenCompletedAt;
                delete state.testCommitSha;
                delete state.testCommittedAt;
                delete state.commitSha;
                delete state.committedAt;
                delete state.completedAt;
                delete state.reviews;
                delete state.worktree;
                pendingRefactorGate = undefined;
                pendingRefactorSha = undefined;
                consumedDecisions.clear();
                state.removed = true;
                break;
            }
            // pipeline.advance.rejected: observability marker, NOT a rollback.
            // Falls through with no state change.
            // phase.completed / inbox.*: not consumed by the pipeline strip.
        }
    }
    return state;
}
/**
 * Returns the gate name when `phase` starts with `prefix`, else
 * `undefined`. Empty gate ('review:' with nothing after) returns
 * `undefined` so a malformed event doesn't materialise an empty-string
 * review key on the projection.
 */
function extractGate(phase, prefix) {
    if (!phase.startsWith(prefix))
        return undefined;
    const gate = phase.slice(prefix.length);
    return gate.length > 0 ? gate : undefined;
}
function ensureReviewRecord(state, gate) {
    const reviews = (state.reviews ??= {});
    const record = (reviews[gate] ??= {});
    return record;
}
/**
 * Passive checkpoint events do not signal task existence — they're
 * either the removal itself or a scrub that operates on an already-
 * established task. Used by the top-of-loop `removed` clearer to
 * decide whether a prior removal flag should be cancelled.
 */
function isPassiveCheckpoint(kind) {
    return kind === 'task.removed' || kind === 'task.shas_rolled_back';
}
