import type { RunEvent } from '@magic-ingredients/tiny-brain-core';
import { parseSSEStream } from '../utils/sse-parser';

export const DEFAULT_RECONNECT_DELAY_MS = 1000;

/** A frame's `data` is a usable RunEvent only when it parsed to an object with a
 *  string `type` — guards against `data: null` / non-JSON `data:` lines that
 *  `parseSSEStream` surfaces as `null` / a raw string. */
export function isRunEvent(data: unknown): data is RunEvent {
  return typeof data === 'object' && data !== null && typeof (data as { type?: unknown }).type === 'string';
}

export interface RunStreamHandlers {
  /** Fresh (deduped) events from a read, in arrival order. */
  onEvents?: (events: RunEvent[]) => void;
  /** Stream open/closed transitions (true on connect, false when a read ends). */
  onConnected?: (connected: boolean) => void;
  /** Last fault, or null to clear it on a successful (re)connect. */
  onError?: (error: string | null) => void;
  /** The stream reached a NATURAL terminal — the run emitted an `exit`, or the
   *  connection failed permanently (a non-OK response). NOT called on abort. */
  onEnd?: () => void;
}

export interface RunStreamCoreOptions {
  /** Delay before reconnecting after an unexpected drop (ms). Default 1000. */
  reconnectDelayMs?: number;
}

/**
 * Open a run's activity stream (ADR-0017) and drive the handlers. The single
 * source of truth for run-stream WIRE MECHANICS — {@link useRunStream} (the
 * island's single-run watcher) and the board's multiplexed land watcher both
 * build on it, so they cannot drift on how a stream is read, deduped, or
 * reconnected. On an unexpected drop (the stream ends before the run's `exit`)
 * it reconnects; the server replays history and the shared `seen` Set dedups it.
 * A non-OK response is a permanent failure (no reconnect) → `onEnd`. Returns an
 * abort function; once aborted no further handler fires (and `onEnd` does not).
 */
export function subscribeRunStream(
  repoId: string,
  runId: string,
  handlers: RunStreamHandlers,
  options: RunStreamCoreOptions = {},
): () => void {
  const reconnectDelayMs = options.reconnectDelayMs ?? DEFAULT_RECONNECT_DELAY_MS;
  const controller = new AbortController();
  // Guards every handler call so a torn-down subscription (unmount / runId
  // change) can't write state after cancellation.
  let active = true;
  const seen = new Set<string>();
  const url = `/api/repos/${encodeURIComponent(repoId)}/runs/${encodeURIComponent(runId)}/stream`;

  void (async () => {
    while (active && !controller.signal.aborted) {
      let sawExit = false;
      try {
        const response = await fetch(url, { signal: controller.signal });
        if (!response.ok || !response.body) {
          if (active) handlers.onError?.(`run stream request failed (${response.status})`);
          break;
        }
        if (active) {
          handlers.onConnected?.(true);
          handlers.onError?.(null);
        }

        const reader = response.body.getReader();
        const decoder = new TextDecoder();
        let buffer = '';
        // eslint-disable-next-line no-constant-condition
        while (true) {
          const { done, value } = await reader.read();
          if (done) break;
          buffer += decoder.decode(value, { stream: true });
          const { events: frames, buffer: remaining } = parseSSEStream(buffer);
          buffer = remaining;

          const fresh: RunEvent[] = [];
          for (const frame of frames) {
            if (!isRunEvent(frame.data)) continue;
            const event = frame.data;
            // Dedup by the SSE `id:` the decode primitive surfaces — the
            // canonical reconnect key the route emits — not the envelope.
            if (frame.id !== undefined) {
              if (seen.has(frame.id)) continue;
              seen.add(frame.id);
            }
            if (event.type === 'exit') sawExit = true;
            fresh.push(event);
          }
          if (fresh.length > 0 && active) handlers.onEvents?.(fresh);
        }
      } catch (err) {
        // Abort on unmount/runId change is expected — stop, don't reconnect, and
        // do NOT signal a terminal (the run outlives this subscription).
        if (err instanceof Error && err.name === 'AbortError') return;
        if (active) handlers.onError?.(err instanceof Error ? err.message : 'run stream error');
      } finally {
        if (active) handlers.onConnected?.(false);
      }

      // Clean end (run exited) or torn down → stop. Otherwise the connection
      // dropped mid-run: wait, then reconnect (history replays, `seen` dedups).
      if (sawExit || !active || controller.signal.aborted) break;
      await new Promise((resolve) => setTimeout(resolve, reconnectDelayMs));
    }
    // A NATURAL terminal — the run exited, or the connection failed permanently.
    // (An abort returned early above, so it never reaches here.)
    if (active && !controller.signal.aborted) handlers.onEnd?.();
  })();

  return () => {
    active = false;
    controller.abort();
  };
}
