import React, { useEffect, useMemo, useState, useRef } from 'react';
import ReactMarkdown from 'react-markdown';
import remarkGfm from 'remark-gfm';

import type { Plan } from '../types';
import type { PipelineStep } from '@magic-ingredients/tiny-brain-core/phase-derivation';
import type { WorkItemProvenance } from '@magic-ingredients/tiny-brain-core';
import { fetchPlanReport } from '../services/api';
import { derivePlanDisplayProgress } from '../utils/planMetrics';
import ProgressBar from './ProgressBar';
import PlanDetailsDashboard from './PlanDetailsDashboard';
import PlanDetailsPRD from '@/features/plans/components/PlanDetailsPRD';
import PlanDetailHeader, { planHeaderPropsFromPlan } from './PlanDetailHeader';
import { useTheme } from '../contexts/ThemeContext';
import ErrorMessage from './ErrorMessage';

interface PlanDetailsProps {
  plan: Plan;
  viewMode: 'summary' | 'details' | 'json';
  repoId?: string;
  /** Archive/unarchive the plan — threaded to the detail header action. */
  onArchive?: () => void;
  onUnarchive?: () => void;
  /** Open the WorkerRun island for a feature's live run (rail pill click). */
  onOpenRun?: (runId: string) => void;
  /** Review gate-set for phase-weighted progress — the SAME pipeline the board's
   *  open-item override passes, so the detail and the board card agree. */
  reviewPipeline?: PipelineStep[];
  /** The board row's server-attributed cleanup branches (fix
   *  prd-cleanup-pill-not-attributed-to-features task 1) — which live typed
   *  branches tripped the container's cleanup pill. */
  cleanupBranches?: readonly string[];
  /** The board row's provenance seed (fix board-detail-provenance-not-seeded-
   *  from-summary) — the container who the detail's feature rows paint from
   *  while the per-item provenance fetch resolves. Only the PRD detail reads it. */
  provenanceSeed?: WorkItemProvenance;
  /** The server-composed delivery-worktree rows, forwarded to the PRD detail so a
   *  feature's expanded reconcile lane resolves its branch's LIVE run in parity
   *  with FixDetail (fix feature-detail-live-reconcile-parity). */
  deliveryWorktrees?: readonly { branch: string; model: { liveReconcileRunId?: string } }[];
}

const PlanDetails: React.FC<PlanDetailsProps> = ({ plan, viewMode, repoId, onArchive, onUnarchive, onOpenRun, reviewPipeline, cleanupBranches, provenanceSeed, deliveryWorktrees }) => {
  const [report, setReport] = useState<string | null>(null);
  const [loadingReport, setLoadingReport] = useState(false);
  const [reportError, setReportError] = useState<string | null>(null);
  const { resolvedTheme } = useTheme();
  
  // Track the last plan ID and view mode to prevent unnecessary refetches
  const lastPlanIdRef = useRef<string | null>(null);
  const lastViewModeRef = useRef<string | null>(null);

  // Phase-weighted overall progress via the SHARED derivePlanDisplayProgress (with
  // the SAME reviewPipeline) — the settled short-circuit plus the phase-weighted
  // mean the sidebar PlanCard and the board open-item override also use, so no
  // surface drifts (unify-settled-progress-short-circuit). Only the summary view's
  // structured Progress card reads this.
  const overallProgress = useMemo(() => derivePlanDisplayProgress(plan, reviewPipeline), [plan, reviewPipeline]);

  useEffect(() => {
    // Only fetch if plan ID or view mode actually changed
    if (lastPlanIdRef.current === plan.id && lastViewModeRef.current === viewMode) {
      return;
    }
    
    lastPlanIdRef.current = plan.id;
    lastViewModeRef.current = viewMode;
    
    if (viewMode === 'summary') {
      setLoadingReport(true);
      setReportError(null);
      fetchPlanReport(plan.id)
        .then(setReport)
        .catch((error: any) => {
          setReport(null);
          setReportError(error.message || 'Failed to load plan summary');
        })
        .finally(() => setLoadingReport(false));
    }
    // No need to fetch individual plan data - it's already in the plan prop
  }, [plan.id, viewMode]);

  if (viewMode === 'details') {
    // Details view - use PRD dashboard if plan has PRD info, otherwise legacy dashboard
    if (plan.prdDirPath || plan.prdId) {
      return (
        <PlanDetailsPRD
          plan={plan}
          repoId={repoId}
          onArchive={onArchive}
          onUnarchive={onUnarchive}
          onOpenRun={onOpenRun}
          serverCleanupBranches={cleanupBranches}
          provenanceSeed={provenanceSeed}
          deliveryWorktrees={deliveryWorktrees}
        />
      );
    }
    // Legacy (non-PRD) plans: keep the header + Archive action and scroll the
    // whole section, matching the PRD view (which owns the same shell itself).
    return (
      <div className="h-full flex flex-col">
        <div className="flex-1 overflow-y-auto px-7 py-6 space-y-4">
          <PlanDetailHeader
            {...planHeaderPropsFromPlan(plan)}
            repoId={repoId}
            onArchive={onArchive}
            onUnarchive={onUnarchive}
          />
          <PlanDetailsDashboard plan={plan} />
        </div>
      </div>
    );
  }

  if (viewMode === 'json') {
    const jsonData = plan; // Plan already contains full data
    
    return (
      <div className="p-3 flex flex-col" style={{ height: '100vh' }}>
        <div className="bg-gray-900 rounded-lg border border-gray-700 shadow-lg flex flex-col min-h-0">
          <div className="px-4 py-2 border-b border-gray-700 flex items-center justify-between shrink-0">
            <span className="text-sm text-gray-400 font-mono">plan.json</span>
            <div className="flex items-center gap-4">
              <span className="text-xs text-green-400">Full data</span>
              <span className="text-xs text-gray-500">{JSON.stringify(jsonData, null, 2).length.toLocaleString()} characters</span>
            </div>
          </div>
          <div className="p-4 flex-1 min-h-0" style={{ backgroundColor: '#1f2937' }}>
            {jsonData ? (
              <pre className="text-sm text-gray-300 overflow-auto h-full whitespace-pre-wrap font-mono">
                {JSON.stringify(jsonData, null, 2)}
              </pre>
            ) : (
              <div className="text-red-400">No data to display</div>
            )}
          </div>
        </div>
      </div>
    );
  }

  // Summary view
  if (loadingReport) {
    return (
      <div className="flex items-center justify-center h-full">
        <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-primary"></div>
      </div>
    );
  }

  if (reportError) {
    return (
      <ErrorMessage
        title="Failed to load summary"
        message={reportError}
        onRetry={() => {
          setLoadingReport(true);
          setReportError(null);
          fetchPlanReport(plan.id)
            .then(setReport)
            .catch((error: any) => {
              setReport(null);
              setReportError(error.message || 'Failed to load plan summary');
            })
            .finally(() => setLoadingReport(false));
        }}
      />
    );
  }

  if (report) {
    return (
      <div className="p-3 space-y-3">
        {/* Info Banner */}
        <div className={`rounded-lg border p-4 ${
          resolvedTheme === 'dark'
            ? 'bg-blue-900/20 border-blue-800/50 text-blue-200'
            : 'bg-blue-50 border-blue-200 text-blue-700'
        }`}>
          <div className="flex items-start gap-3">
            <svg className="w-5 h-5 mt-0.5 flex-shrink-0" fill="currentColor" viewBox="0 0 20 20">
              <path fillRule="evenodd" d="M18 10a8 8 0 11-16 0 8 8 0 0116 0zm-7-4a1 1 0 11-2 0 1 1 0 012 0zM9 9a1 1 0 000 2v3a1 1 0 001 1h1a1 1 0 100-2v-3a1 1 0 00-1-1H9z" clipRule="evenodd" />
            </svg>
            <div className="text-sm">
              <p className="font-medium mb-1">About this view</p>
              <p className="opacity-90">
                This summary is generated by the <code className="px-1 py-0.5 rounded bg-black/10 dark:bg-white/10">plan status</code> tool operation. 
                It's designed to be as compact as possible to preserve token usage while providing essential plan information.
              </p>
            </div>
          </div>
        </div>
        
        {/* Report Content */}
        <div className={`rounded-lg border p-6 prose prose-sm max-w-none ${
          resolvedTheme === 'dark' 
            ? 'bg-gray-900 border-gray-700 prose-invert' 
            : 'bg-bg-primary border-border'
        }`}>
          <ReactMarkdown remarkPlugins={[remarkGfm]}>{report}</ReactMarkdown>
        </div>
      </div>
    );
  }

  // Fallback to structured view if no report available
  return (
    <div className="p-3 space-y-3">
      {/* Overview Card */}
      <div className="bg-bg-primary rounded-lg border border-border p-6">
        <h3 className="text-lg font-semibold mb-4">Overview</h3>
        <p className="text-text-secondary mb-4">
          {plan.overview || 'No overview available'}
        </p>
        
        <div className="grid grid-cols-2 gap-4 mt-6">
          <div>
            <p className="text-sm text-text-secondary mb-1">Status</p>
            <span className={`inline-block px-2 py-1 rounded text-xs font-medium ${
              plan.status === 'in_progress' ? 'bg-blue-100 text-blue-800' :
              plan.status === 'completed' ? 'bg-green-100 text-green-800' :
              plan.status === 'not_started' ? 'bg-gray-100 text-gray-800' :
              'bg-gray-100 text-gray-800'
            }`}>
              {plan.status}
            </span>
          </div>
          <div>
            <p className="text-sm text-text-secondary mb-1">Last Updated</p>
            <p className="text-sm font-medium">
              {plan.lastUpdated ? new Date(plan.lastUpdated).toLocaleString() : 'Unknown'}
            </p>
          </div>
        </div>
      </div>

      {/* Progress Card */}
      <div className="bg-bg-primary rounded-lg border border-border p-6">
        <h3 className="text-lg font-semibold mb-4">Progress</h3>
        <div className="space-y-4">
          <div>
            <div className="flex justify-between mb-2">
              <span className="text-sm text-text-secondary">Overall Progress</span>
              <span className="text-sm font-medium">{overallProgress}%</span>
            </div>
            <ProgressBar progress={overallProgress} />
          </div>
          
          {plan.currentState && (
            <>
              <div className="grid grid-cols-2 gap-4 mt-4">
                <div>
                  <p className="text-sm text-text-secondary">Completed Features</p>
                  <p className="text-2xl font-bold">
                    {plan.currentState.overallProgress.completedFeatures} / {plan.currentState.overallProgress.totalFeatures}
                  </p>
                </div>
                <div>
                  <p className="text-sm text-text-secondary">Completed Tasks</p>
                  <p className="text-2xl font-bold">
                    {plan.currentState.overallProgress.completedTasks} / {plan.currentState.overallProgress.totalTasks}
                  </p>
                </div>
              </div>
            </>
          )}
        </div>
      </div>

      {/* Current Feature Card */}
      {plan.currentState && (
        <div className="bg-bg-primary rounded-lg border border-border p-6">
          <h3 className="text-lg font-semibold mb-4">Current Feature</h3>
          <p className="text-text-primary font-medium mb-2">
            Feature {plan.currentState.feature}: {plan.currentState.featureTitle}
          </p>
          
          {plan.currentState.nextAction && (
            <div className="mt-4 p-4 bg-bg-secondary rounded-lg">
              <p className="text-sm font-medium text-text-primary mb-1">Next Action</p>
              <p className="text-sm text-text-secondary">
                {plan.currentState.nextAction.description}
              </p>
            </div>
          )}

          {plan.currentState.blockers && plan.currentState.blockers.length > 0 && (
            <div className="mt-4">
              <p className="text-sm font-medium text-red-600 mb-2">Blockers</p>
              <ul className="space-y-2">
                {plan.currentState.blockers.map((blocker, index) => (
                  <li key={index} className="flex items-start gap-2">
                    <span className={`inline-block w-2 h-2 rounded-full mt-1.5 ${
                      blocker.severity === 'high' ? 'bg-red-500' :
                      blocker.severity === 'medium' ? 'bg-yellow-500' :
                      'bg-gray-400'
                    }`} />
                    <span className="text-sm text-text-secondary">{blocker.description}</span>
                  </li>
                ))}
              </ul>
            </div>
          )}
        </div>
      )}
    </div>
  );
};

export default PlanDetails;