// Boolean and text controls render inline on the right of their row. Enum
// controls are rendered as a full-width radio list by the row itself (one
// option per row), so they never reach this component.
const FlagControl: React.FC<{
  def: FlagDef;
  value: unknown;
  onWrite: (key: string, value: boolean | string) => void;
}> = ({ def, value, onWrite }) => {
  if (def.control.kind === 'boolean') {
    return (
      <Switch
        checked={Boolean(value)}
        onCheckedChange={(checked) => onWrite(def.key, checked)}
        aria-label={def.label}
      />
    );
  }

  if (def.control.kind === 'enum') return null;

  // Text: commit on blur so a write isn't fired on every keystroke. Keyed on
  // the incoming value so a prop change (e.g. parent re-fetch after a write)
  // remounts the input with the new canonical value — uncontrolled per-edit,
  // but still a pure render of the latest props.
  const text = value === null || value === undefined ? '' : String(value);
  return (
    <input
      key={text}
      aria-label={def.label}
      defaultValue={text}
      onBlur={(e) => onWrite(def.key, e.target.value)}
      className="text-xs font-mono px-2 py-0.5 rounded border border-border bg-background w-40"
    />
  );
};

/**
 * One group's detail pane — its heading, section helper text, and per-flag rows.
 * Renders only the rows whose keys are present in `flags`.
 */
const ConfigGroupSection: React.FC<{
  group: FlagGroup;
  flags: ConfigFlags;
  mode: 'global' | 'repo';
  onWrite: (key: string, value: boolean | string) => void;
  onClearOverride?: (key: string) => void;
}> = ({ group, flags, mode, onWrite, onClearOverride }) => {
  const defs = group.flags.filter((def) => def.key in flags);
  return (
    <section data-testid={`config-group-${group.id}`} className="space-y-1">
      <div className="mb-1">
        <h3 className="text-sm font-medium text-foreground">{group.title}</h3>
        <p className="text-xs text-subtle">{group.description}</p>
      </div>
      {defs.map((def) => {
        const entry = flags[def.key];
        const source = entry.source;
        const showClear = mode === 'repo' && source === 'repo' && Boolean(onClearOverride);
        const provenance = mode === 'repo' ? <SourceBadge flagKey={def.key} source={source} /> : null;
        const clearButton = showClear ? (
          <button
            type="button"
            aria-label={`Reset ${def.label}`}
            onClick={() => onClearOverride?.(def.key)}
            className="inline-flex items-center text-muted-foreground hover:text-foreground"
          >
            <RotateCcw className="h-3.5 w-3.5" />
          </button>
        ) : null;

        // Enum: a full-width radio list, one option per row, each with its
        // own plain-language description — clearer than a dense dropdown.
        if (def.control.kind === 'enum') {
          const current = String(entry.value ?? '');
          return (
            <div
              key={def.key}
              data-testid={`config-row-${def.key}`}
              className="py-1.5 border-b border-border last:border-b-0"
            >
              <div className="flex items-center justify-between gap-3">
                <span className="text-sm text-muted-foreground">{def.label}</span>
                <div className="flex items-center gap-2 shrink-0">
                  {provenance}
                  {clearButton}
                </div>
              </div>
              <p className="text-xs text-subtle">{def.help}</p>
              <div role="radiogroup" aria-label={def.label} className="mt-2 space-y-1.5">
                {def.control.options.map((opt) => (
                  <label key={opt.value} className="flex items-start gap-2 cursor-pointer">
                    <input
                      type="radio"
                      name={def.key}
                      value={opt.value}
                      checked={current === opt.value}
                      onChange={() => onWrite(def.key, opt.value)}
                      className="mt-1 shrink-0"
                    />
                    <span className="min-w-0">
                      <span className="text-sm text-foreground">{opt.label}</span>
                      <span className="block text-xs text-subtle">{opt.help}</span>
                    </span>
                  </label>
                ))}
              </div>
            </div>
          );
        }

        return (
          <div
            key={def.key}
            data-testid={`config-row-${def.key}`}
            className="flex items-center justify-between gap-3 py-1.5 border-b border-border last:border-b-0"
          >
            <div className="min-w-0">
              <span className="text-sm text-muted-foreground">{def.label}</span>
              <p className="text-xs text-subtle">{def.help}</p>
            </div>
            <div className="flex items-center gap-2 shrink-0">
              {provenance}
              {clearButton}
              <FlagControl def={def} value={entry.value} onWrite={onWrite} />
            </div>
          </div>
        );
      })}
    </section>
  );
};

/** The Validation pseudo-group's sidebar id — not a FLAG_GROUPS entry, so the
 *  detail routing must match it by identity, never by group-lookup failure. */
const VALIDATION_ID = 'validation';

/** Human-legible duration for the summary rows: whole minutes, else whole
 *  seconds, else raw milliseconds. */
const formatMs = (ms: number): string =>
  ms % 60_000 === 0 ? `${ms / 60_000}m` : ms % 1_000 === 0 ? `${ms / 1_000}s` : `${ms}ms`;

/**
 * The Validation detail pane — a read summary of the resolved post-land state.
 * Deliberately not an editor: the dispatch settings are configured on the
 * post-land step in the pipeline builder, which the link opens.
 */
const ValidationSummaryPane: React.FC<{ validation: ValidationSummary }> = ({ validation }) => {
  const { dispatch, onConfigureInPipeline } = validation;
  return (
    <section data-testid="config-group-validation" className="space-y-3">
      <div className="mb-1">
        <h3 className="text-sm font-medium text-foreground">Validation</h3>
        <p className="text-xs text-subtle">
          Post-merge validation runs the repo&rsquo;s full suite against main&rsquo;s tip — off the
          land click, so it can be heavier than the per-commit gate.
        </p>
      </div>
      <p className="text-sm text-muted-foreground">
        {dispatch
          ? 'On — validates main’s tip once lands settle.'
          : 'Off — lands never schedule a validation run; main carries no health verdict.'}
      </p>
      {dispatch && (
        <dl>
          {(
            [
              ['Debounce', formatMs(dispatch.debounceMs)],
              ['Seed', dispatch.seed],
              ['Timeout', formatMs(dispatch.timeoutMs)],
            ] as const
          ).map(([label, value]) => (
            <div
              key={label}
              className="flex items-center justify-between gap-3 py-1.5 border-b border-border last:border-b-0"
            >
              <dt className="text-sm text-muted-foreground">{label}</dt>
              <dd className="text-xs font-mono text-foreground">{value}</dd>
            </div>
          ))}
        </dl>
      )}
      <button
        type="button"
        onClick={onConfigureInPipeline}
        className="text-sm text-blue hover:underline"
      >
        Configure in pipeline builder <span aria-hidden="true">→</span>
      </button>
    </section>
  );
};

/** One sidebar tab selecting a config group into the detail pane. Roving
 *  tabIndex: only the active tab is in the tab order; the others are reached
 *  with the arrow keys the tablist handles. */
const ConfigNavItem: React.FC<{
  group: Pick<FlagGroup, 'id' | 'title'>;
  active: boolean;
  onSelect: () => void;
}> = ({ group, active, onSelect }) => (
  <button
    type="button"
    role="tab"
    id={`config-tab-${group.id}`}
    data-testid={`config-nav-${group.id}`}
    aria-selected={active}
    aria-controls="config-detail"
    tabIndex={active ? 0 : -1}
    onClick={onSelect}
    className={`w-full text-left px-3 py-2 text-sm rounded-lg transition-colors ${
      active ? 'bg-blue/10 text-blue font-medium' : 'text-muted-foreground hover:bg-muted'
    }`}
  >
    {group.title}
  </button>
);

/**
 * Scope-aware config editor — a master-detail render over the flattened
 * `{value, source}` flag map. A left sidebar lists every group with at least one
 * present key; the detail pane shows only the selected group's options. It
 * performs no fetch and defines no API shapes: both the global (SettingsPane)
 * and repo (Setup tab) mounts pass their own flags + callbacks.
 *
 * In `repo` mode, a key whose value comes from the repo scope gets a
 * clear-override affordance (`onClearOverride`) that drops the repo key so the
 * global/default value shows through. The `global` mount never renders it.
 *
 * The per-row provenance badge is only meaningful in `repo` mode (where it
 * distinguishes default / global / repo). In the `global` mount everything is
 * global, so the badge is suppressed as noise.
 */
export const ConfigEditor: React.FC<{
  flags: ConfigFlags;
  mode: 'global' | 'repo';
  onWrite: (key: string, value: boolean | string) => void;
  onClearOverride?: (key: string) => void;
  /** When provided, a Validation item joins the sidebar summarising this state. */
  validation?: ValidationSummary;
}> = ({ flags, mode, onWrite, onClearOverride, validation }) => {
  // Only groups with a present key get a nav item + detail pane (registry
  // order); the Validation summary joins as a pseudo-group after them.
  const presentGroups = FLAG_GROUPS.filter((group) => group.flags.some((def) => def.key in flags));
  const navItems: ReadonlyArray<Pick<FlagGroup, 'id' | 'title'>> = validation
    ? [...presentGroups, { id: VALIDATION_ID, title: 'Validation' }]
    : presentGroups;
  const [selectedId, setSelectedId] = React.useState<string | undefined>(() => navItems[0]?.id);
  // Fall back to the first item if the selection is no longer present
  // (e.g. the flag map changed under us).
  const activeId = navItems.some((item) => item.id === selectedId) ? selectedId : navItems[0]?.id;
  const activeGroup = presentGroups.find((g) => g.id === activeId);

  // Arrow keys move the roving tab selection (wrap at the ends); Home/End jump.
  const onTablistKeyDown = (e: React.KeyboardEvent) => {
    const idx = navItems.findIndex((item) => item.id === activeId);
    if (idx === -1) return;
    const nextIdx =
      e.key === 'ArrowDown' ? (idx + 1) % navItems.length
      : e.key === 'ArrowUp' ? (idx - 1 + navItems.length) % navItems.length
      : e.key === 'Home' ? 0
      : e.key === 'End' ? navItems.length - 1
      : idx;
    if (nextIdx === idx) return;
    e.preventDefault();
    const next = navItems[nextIdx];
    setSelectedId(next.id);
    document.getElementById(`config-tab-${next.id}`)?.focus();
  };

  return (
    <div
      data-testid="config-editor"
      className="grid gap-6 md:grid-cols-[13rem_minmax(0,1fr)] items-start"
    >
      <nav
        role="tablist"
        aria-label="Configuration groups"
        aria-orientation="vertical"
        onKeyDown={onTablistKeyDown}
        className="space-y-1 md:sticky md:top-3"
      >
        {navItems.map((item) => (
          <ConfigNavItem
            key={item.id}
            group={item}
            active={item.id === activeId}
            onSelect={() => setSelectedId(item.id)}
          />
        ))}
      </nav>

      {activeId !== undefined && (
        <div
          id="config-detail"
          data-testid="config-detail"
          role="tabpanel"
          tabIndex={0}
          aria-labelledby={`config-tab-${activeId}`}
          className="min-w-0"
        >
          {activeId === VALIDATION_ID && validation ? (
            <ValidationSummaryPane validation={validation} />
          ) : activeGroup ? (
            <ConfigGroupSection
              group={activeGroup}
              flags={flags}
              mode={mode}
              onWrite={onWrite}
              onClearOverride={onClearOverride}
            />
          ) : null}
        </div>
      )}
    </div>
  );
};

export default ConfigEditor;
