import type { LandAvailability } from '@magic-ingredients/tiny-brain-core';
import type { Fix } from '../types';
import type { WorktreeBranchRef } from '../components/worktree-branches';
import type { LastReconcileFeed } from './reconcile-strip';

/**
 * The branch(es) a fix's work lives on, each flagged with whether a live
 * worktree exists — the shared derivation behind both the FixCard sidebar
 * marker and the FixDetail header indicator (fix fixcard-status-ignores-worktree
 * Task 3), so the two surfaces can't drift.
 *
 * Keyed on the BRANCH (the stable identity) so the same physical worktree —
 * surfacing as both a task/source dir-name and a lattice branch ref — collapses
 * to one entry. Lattice refs are filtered to live worktrees (isWorktree) STRICTLY
 * AHEAD of the launch ref; explicit task/source worktrees surface regardless of
 * ahead-status so a fresh/undiverged worktree still shows.
 *
 * Live-run (`activeRun`) worktrees are NOT folded in here — that pre-commit badge
 * is a card-only affordance the caller layers on (FixCard) after this base.
 */
export function deriveFixWorktreeBranches(
  // `tasks` is optional here (not `Pick<Fix, 'tasks'>`) because this is called
  // eagerly for the SELECTED board item, whose on-demand record can be a lean /
  // partial fix — the type states that possibility rather than the `?? []` below
  // silently swallowing it. Callers with a full `Fix` satisfy it unchanged.
  fix: Pick<Fix, 'sourceWorktree'> & { readonly tasks?: Fix['tasks'] },
): WorktreeBranchRef[] {
  const rank: Record<string, number> = { not_started: 0, in_progress: 1, completed: 2, superseded: 2 };
  const byBranch = new Map<string, { hasWorktree: boolean; worktreeName?: string }>();
  const add = (branch: string, hasWorktree: boolean, worktreeName?: string) => {
    const prev = byBranch.get(branch);
    byBranch.set(branch, {
      hasWorktree: (prev?.hasWorktree ?? false) || hasWorktree,
      worktreeName: prev?.worktreeName ?? worktreeName,
    });
  };

  if (fix.sourceWorktree) add(fix.sourceWorktree.branch, true, fix.sourceWorktree.name);
  // `?? []` handles the optional-tasks case declared in the signature — a lean
  // selected-item record resolves to "no lattice branch" rather than crashing.
  for (const task of fix.tasks ?? []) {
    if (task.worktree) add(task.worktree.branch, true, task.worktree.name);
    const cells = task.statusByRef || [];
    const launchRank = rank[cells.find((c) => c.isLaunchRef)?.status ?? 'not_started'] ?? 0;
    for (const cell of cells) {
      if (cell.isLaunchRef || !cell.isWorktree) continue;
      if ((rank[cell.status] ?? 0) <= launchRank) continue;
      add(cell.ref, true); // lattice refs carry no dir name
    }
  }
  return [...byBranch].map(([branch, v]) => ({ branch, ...v }));
}

/**
 * The fix branch's MODELED land availability out of the delivery-worktree rows
 * (work-item-provenance F7 task 2) — the ReconcileStrip's reconstruction source
 * and the end-cap's conflicts gate. The branch identity is the board row's
 * worktree branch when the caller has one, else the fix's own first derived
 * branch (the SAME derivation FixDetail keys its strip on, so the feed and the
 * strip can't disagree). No branch, or no matching row, yields undefined — the
 * caller falls back to the client edge.
 */
export function deriveFixLandAvailability(
  fix: Pick<Fix, 'sourceWorktree' | 'tasks'>,
  boardBranch: string | undefined,
  rows: readonly { branch: string; model: { landAvailability: LandAvailability } }[],
): LandAvailability | undefined {
  const branch = boardBranch ?? deriveFixWorktreeBranches(fix)[0]?.branch;
  if (branch === undefined) return undefined;
  return rows.find((row) => row.branch === branch)?.model.landAvailability;
}

/**
 * The fix branch's persisted latest reconcile verdict + reason — the model's
 * `lastReconcile` axis, keyed on the SAME branch identity as
 * {@link deriveFixLandAvailability} so the strip's failure reconstruction and
 * its availability gate can never disagree about which branch they describe
 * (fix verify-outcomes-invisible-in-ui task 1).
 */
export function deriveFixLastReconcile(
  fix: Pick<Fix, 'sourceWorktree' | 'tasks'>,
  boardBranch: string | undefined,
  rows: readonly { branch: string; model: { lastReconcile?: LastReconcileFeed } }[],
): LastReconcileFeed | undefined {
  const branch = boardBranch ?? deriveFixWorktreeBranches(fix)[0]?.branch;
  if (branch === undefined) return undefined;
  return rows.find((row) => row.branch === branch)?.model.lastReconcile;
}

/**
 * The fix branch's LIVE machinery run id (an unended reconcile/land — e.g. a
 * CLI `tiny-brain reconcile-branch`), keyed on the SAME branch identity as its
 * two sibling feeds, so the strip subscribes to the right branch's run and
 * never a foreign one (fix verify-outcomes-invisible-in-ui task 2).
 */
export function deriveFixLiveReconcileRunId(
  fix: Pick<Fix, 'sourceWorktree' | 'tasks'>,
  boardBranch: string | undefined,
  rows: readonly { branch: string; model: { liveReconcileRunId?: string } }[],
): string | undefined {
  const branch = boardBranch ?? deriveFixWorktreeBranches(fix)[0]?.branch;
  return deriveLiveReconcileRunIdForBranch(branch, rows);
}

/**
 * The LIVE reconcile machinery run id for an already-resolved branch, looked up
 * in the server-composed delivery-worktree rows — the branch-keyed generalisation
 * of {@link deriveFixLiveReconcileRunId} for callers (PlanFeatureRow) that hold a
 * branch directly, so a feature's live reconcile lane reaches true parity with
 * FixDetail (fix feature-detail-live-reconcile-parity). One lookup, not two.
 */
export function deriveLiveReconcileRunIdForBranch(
  branch: string | undefined,
  rows: readonly { branch: string; model: { liveReconcileRunId?: string } }[],
): string | undefined {
  if (branch === undefined) return undefined;
  return rows.find((row) => row.branch === branch)?.model.liveReconcileRunId;
}
