import { useCallback, useState } from 'react';
import { Bell, ArrowUpCircle, Terminal, Copy, Check } from 'lucide-react';
import { SheetHeader, SheetTitle, SheetDescription } from '../ui/sheet';
import type { Notification, UpdateAvailableNotification } from '../../types';

/** Command box CTA — terminal glyph, the mono command, and a labelled copy
 *  button (mockup: the `.cmd` row). */
function CopyCommandButton({ command }: { command: string }) {
  const [copied, setCopied] = useState(false);
  const handleCopy = useCallback(async () => {
    await navigator.clipboard.writeText(command);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  }, [command]);

  return (
    <div className="mt-2 flex items-center gap-2 rounded-md border-[1px] bg-foreground/5 px-2 py-1.5">
      <Terminal className="h-3.5 w-3.5 shrink-0 text-muted-foreground" />
      <code className="truncate font-mono text-xs text-foreground">{command}</code>
      <button
        type="button"
        onClick={() => void handleCopy()}
        aria-label="Copy the upgrade command"
        className="ml-auto flex shrink-0 items-center gap-1 rounded px-1.5 py-0.5 text-[11px] font-medium text-blue-500 hover:bg-blue-500/10 transition-colors"
      >
        {copied ? <Check className="h-3 w-3" /> : <Copy className="h-3 w-3" />}
        {copied ? 'Copied' : 'Copy'}
      </button>
    </div>
  );
}

/** Hero "update available" row — leading glyph tile, title + unread dot, the
 *  installed→latest sentence with an "N behind" pill, the command CTA, and the
 *  provenance subline (mockup `.nrow.nrow-unread`). */
function UpdateAvailableRow({ notification }: { notification: UpdateAvailableNotification }) {
  return (
    <div className="flex gap-3 rounded-xl border-l-2 border-l-blue-500 bg-blue-500/10 p-3">
      <div className="flex h-9 w-9 flex-none items-center justify-center rounded-[10px] bg-blue-500/15">
        <ArrowUpCircle className="h-5 w-5 text-blue-500" />
      </div>
      <div className="min-w-0 flex-1">
        <div className="flex items-center gap-2">
          <p className="text-sm font-semibold">{notification.title}</p>
          <span className="h-1.5 w-1.5 rounded-full bg-blue-500" aria-hidden="true" />
        </div>
        <p className="mt-0.5 text-[13px] text-muted-foreground">
          You&rsquo;re on <span className="font-mono text-foreground/70">{notification.installedVersion}</span> —{' '}
          <span className="font-mono text-foreground">{notification.latestVersion}</span> is the latest release.{' '}
          <span className="ml-0.5 inline-flex items-center rounded bg-foreground/5 px-1.5 py-0.5 font-mono text-[10px] font-medium uppercase tracking-wide text-muted-foreground">
            {notification.behindLabel}
          </span>
        </p>
        <CopyCommandButton command={notification.command} />
        <p className="mt-1.5 text-[11px] text-muted-foreground">
          from the npm registry · <span className="font-mono">dist-tags.latest</span>
        </p>
      </div>
    </div>
  );
}

/**
 * Inner content of the notifications Sheet — header (bell · title · "N new"
 * pill), the notification rows (or empty state), and the provenance footer.
 * Presentational: rendered inside the `NotificationsBell` SheetContent, it draws
 * whatever notifications it is handed. Visual target: this fix's
 * `assets/notifications-panel.html` mockup.
 */
export function NotificationsPanel({ notifications }: { notifications: Notification[] }) {
  const count = notifications.length;
  return (
    <>
      <SheetHeader className="flex-row items-center gap-2.5 space-y-0 border-b-[1px] bg-muted/50 px-5 py-4">
        <Bell className="h-4 w-4 text-blue-500" />
        <SheetTitle className="text-base">Notifications</SheetTitle>
        {count > 0 && (
          <span className="inline-flex items-center rounded-md bg-blue-500/15 px-2 py-0.5 font-mono text-[10px] font-semibold uppercase tracking-wide text-blue-500">
            {count} new
          </span>
        )}
        <SheetDescription className="sr-only">Recent notifications from tiny-brain</SheetDescription>
      </SheetHeader>

      <div className="flex-1 space-y-1.5 overflow-y-auto p-3">
        {count === 0 ? (
          <p className="px-2 py-6 text-sm text-muted-foreground">You&rsquo;re all caught up.</p>
        ) : (
          notifications.map((n) => <UpdateAvailableRow key={n.id} notification={n} />)
        )}
      </div>
    </>
  );
}
