import clsx from 'clsx';
import { Activity, ChevronDown, ChevronRight, GitMerge } from 'lucide-react';
import type { Feature } from '../types';
import { GradientProgress } from './ui';
import type { FeatureProvenanceView } from '@magic-ingredients/tiny-brain-core';
import CopyIdButton from './CopyIdButton';
import MiniStatusRail from './MiniStatusRail';
import MsrPill from './MsrPill';
import DeliveredProvenance from './DeliveredProvenance';
import FeatureEndcap from './FeatureEndcap';
import FeatureDetail from './FeatureDetail';
import CleanupCommand from './CleanupCommand';
import ShowDetailsCap from './ShowDetailsCap';
import { formatPrdFeatureSlugPath } from '../utils/task-slug-path';
import {
  deriveEffectiveStatus,
  deriveFeatureWorktreeRef,
  deriveFeatureDetailsBranch,
  hasLiveWorktreeCell,
} from '../utils/effective-task-status';
import { deriveTasksEffectiveStatus, finishedWorktreeBranches } from '../utils/effective-task';
import { deriveLiveReconcileRunIdForBranch } from '../utils/fix-worktree-branches';

const NO_OWNED_CLEANUP: readonly string[] = [];

interface PlanFeatureRowProps {
  feature: Feature;
  repoId: string;
  prdId?: string;
  expanded: boolean;
  onToggle: () => void;
  /** Open the WorkerRun island for the feature's live run (the rail pill). */
  onOpenRun?: (runId: string) => void;
  /**
   * The feature's delivered provenance (work-item-provenance F4). When present on
   * a completed / superseded feature, its section row shows the delivered
   * where/who; absent (or on a live feature) the live rail leads instead.
   */
  provenance?: FeatureProvenanceView;
  /**
   * The host's provenance read is still on its FIRST load (fix
   * endcap-resumes-pipeline-runs task 2): threads to the end-cap's `settling`
   * gate so the row holds the inert "…" cap instead of flashing the merge
   * default derived from an absent provenance. Hosts must not raise it on
   * refetches — the provenance hook keeps the previous snapshot, so a
   * settled cap stays put.
   */
  provenanceSettling?: boolean;
  /**
   * The end-cap actions (detail-action-endcap task 2) — the host owns the
   * POSTs; the row fires ids. The cap renders only when ALL THREE are wired
   * (read-only render sites pass none and get no cap).
   */
  onLandFeature?: (method: 'ff-only' | 'merge') => void;
  /**
   * This feature's land run is IN FLIGHT (fix feature-land-has-no-live-feedback
   * task 2): the end-cap pins to the inert Merging… state — no chooser, no
   * re-dispatch — until the host's streamed run reaches its terminal.
   */
  landing?: boolean;
  /** Raise a PR for this feature instead of landing (the chooser's third action — fix merge-cap-lacks-method-and-pr-choice). Optional: the endcap drops Raise PR… when absent. */
  onRaiseFeature?: () => void;
  onTeardownFeature?: (branch: string) => void;
  onResumeRun?: (runId: string) => void;
  /** Continue this feature's parked work on its existing worktree (fix incomplete-item-with-completed-run-cannot-relaunch). */
  onContinueItem?: () => void;
  /**
   * Open the read-only provenance island for the row's branch (F6 task 3). The
   * host owns the `?island=` routing; the row renders the quiet Show-details
   * column (before the end-cap) only when this is wired AND the row is STARTED
   * with an island-addressable branch.
   */
  onShowDetails?: (branch: string) => void;
  /**
   * The branches the host's rendered Cleanup row(s) cover (done-lane-cleanup
   * task 5, generalised by fix mixed-branch-cleanup-prd-buries-affordance
   * task 2): when EVERY live branch this feature finished work on is in the
   * set, a Cleanup row above the features owns its teardown — the endcap
   * withholds its worktree fact and the teardown rung folds to the inert
   * already-merged cap. A feature that finished work on any UNCOVERED branch
   * keeps its own Delete-worktree cap: no rendered row would touch that
   * worktree, and muting the cap would orphan it.
   */
  coveredCleanupBranches?: readonly string[];
  /**
   * The live cleanup branches THIS feature owns (fix
   * prd-cleanup-rows-not-attributed-to-features task 2 —
   * deriveFeatureCleanupBranches: first owner in feature order wins a shared
   * branch). When non-empty the collapsed header wears a cleanup pill (pure
   * render, no fetch) and the expanded body mounts one branch-keyed
   * CleanupCommand per branch — the manifest fetch is deferred to intent.
   */
  cleanupBranches?: readonly string[];
  /**
   * The server-composed delivery-worktree rows, so this row can resolve its
   * feature branch's LIVE reconcile machinery run and hand FeatureDetail true
   * live parity with FixDetail (fix feature-detail-live-reconcile-parity) — the
   * distinct live-run id, never the terminal verdict run. Optional: read-only /
   * board render sites that pass none simply get no live subscription.
   */
  deliveryWorktrees?: readonly { branch: string; model: { liveReconcileRunId?: string } }[];
}

/**
 * One feature in the plans-console accordion (UI Refresh). A recessed
 * panel-flat row that lifts to a panel when open, with a number badge, title,
 * copy-id, a compact worktree rail, and a right-aligned done/total count plus gradient
 * progress (or a "Not started" pill). Expanding reveals the per-task rows and
 * their commit-pipeline timelines via FeatureDetail; the row's status and
 * counts use the worktree-aware effective status so worktree work counts here.
 */
export function PlanFeatureRow({
  feature,
  repoId,
  prdId,
  expanded,
  onToggle,
  onOpenRun,
  provenance,
  provenanceSettling,
  onLandFeature,
  landing,
  onRaiseFeature,
  onTeardownFeature,
  onResumeRun,
  onContinueItem,
  onShowDetails,
  coveredCleanupBranches,
  cleanupBranches,
  deliveryWorktrees,
}: PlanFeatureRowProps) {
  const ownedCleanupBranches = cleanupBranches ?? NO_OWNED_CLEANUP;
  const tasks = feature.tasks ?? [];
  const status = deriveTasksEffectiveStatus(tasks);
  // The per-feature validation strip is NO LONGER read off the plan payload here
  // (fix plan-detail-eagerly-builds-every-feature-validation-input task 2): it is
  // fetched lazily inside FeatureDetail when this section expands, so a collapsed
  // feature reads no run-event JSONL.
  const worktreeRef = deriveFeatureWorktreeRef(tasks);
  const slug = prdId ? formatPrdFeatureSlugPath(prdId, feature.id) : undefined;
  // The live run's id (when the feature has one) — hoisted so the rail's
  // activeRunId + onOpenRun both read one narrowed const instead of `!`.
  // Gated on the effective status like the fix surfaces: activeRun is a
  // LIVE signal, so a stale link on a done feature must not resurrect a
  // live pill or its glyphs.
  const activeRunId =
    status === 'completed' || status === 'superseded' ? undefined : feature.activeRun?.runId;
  // The run's worker/env facts ride the rail's glyphs beside the Running
  // pill (launch-dispatch-feedback task 2) — the same dispatched-state
  // language the fix card and detail header speak, gated on the live runId
  // so a factless link renders no stale glyphs.
  const railIsWorker = activeRunId !== undefined && feature.activeRun?.worker !== undefined;
  // One open-the-stream closure shared by the rail pill and the expanded
  // body's Watch-live control, so the two affordances cannot drift.
  const openActiveRun =
    activeRunId !== undefined && onOpenRun ? () => onOpenRun(activeRunId) : undefined;
  const railWhere = feature.activeRun?.target === 'cloud-remote' ? 'remote' : 'local';
  // A failed/stalled latest run lights the rail's red worker glyph (task 3 —
  // the FixDetail gate mirrored): a terminal feature's stale attention fact is
  // suppressed — there is nothing left to resume. The server's hasFailedRun
  // run-record fact is NOT terminal-suppressed (fix: failed-run-not-surfaced-
  // on-prd-detail): it is supersession-aware server-side (a resume child
  // clears it), a completed feature can still own an unresumed failed run,
  // and the board card folds it unconditionally — the detail must agree with
  // the card.
  const isTerminal = status === 'completed' || status === 'superseded';
  const attention =
    feature.hasFailedRun === true
      ? ('failed' as const)
      : isTerminal
        ? undefined
        : feature.attentionStatus;

  const total = tasks.length;
  const completed = tasks.filter((t) => deriveEffectiveStatus(t).status === 'completed').length;
  const superseded = tasks.filter((t) => deriveEffectiveStatus(t).status === 'superseded').length;
  const done = completed + superseded;
  const isDone = status === 'completed' || status === 'superseded';

  // Item-first launch (item-launch-rail task 4): the PRD's launchable unit is
  // a FEATURE (go requires --prd --feature), so this section header offers
  // [Launch ▾] while the feature is idle — still open with NO task on any
  // worktree. Note `worktreeRef` alone won't do: it only resolves for a
  // FINISHED feature, so an in-progress feature mid-worktree would read
  // launchable through it. Needs the prd id to build the prd:<id>/<feature>
  // slug.
  const hasWorktreeWork = tasks.some(
    (t) => t.worktree !== undefined || deriveEffectiveStatus(t).worktreeRef !== undefined,
  );
  const launchTarget =
    prdId !== undefined && !isDone && !hasWorktreeWork
      ? { repoId, item: `prd:${prdId}/${feature.id}` }
      : undefined;
  const percent = isDone ? 100 : total > 0 ? Math.round((done / total) * 100) : 0;
  const started = status !== 'not_started';
  // Both disclosure toggles (chevron + title) control the ONE expanded body.
  const bodyId = `feature-body-${feature.id}`;

  // The Show-details branch (F6 task 3): the feature-level worktree ref when it
  // resolves (finished features), else the first task-level worktree branch —
  // an in-progress row's work is still island-addressable by its branch.
  // Shared with the host's Cleanup collapse (done-lane-cleanup task 5).
  const detailsBranch = deriveFeatureDetailsBranch(tasks);
  // Is this row's cleanup owned by a rendered Cleanup row above the features?
  // (fix mixed-branch-cleanup-prd-buries-affordance task 2). True only when
  // the feature HAS finished live branches and every one is covered — a
  // feature with work on any uncovered branch keeps its own cap.
  const finishedBranches = finishedWorktreeBranches(tasks);
  const uncoveredFinished =
    coveredCleanupBranches === undefined
      ? []
      : [...finishedBranches].filter((branch) => !coveredCleanupBranches.includes(branch)).sort();
  const cleanupCovered =
    coveredCleanupBranches !== undefined && finishedBranches.size > 0 && uncoveredFinished.length === 0;
  // The branch a KEPT cap acts on: detailsBranch unless it names a COVERED
  // branch while an uncovered one exists — then the uncovered branch is the
  // one whose teardown no rendered row owns.
  const capWorktreeBranch =
    detailsBranch !== undefined && coveredCleanupBranches?.includes(detailsBranch) === true && uncoveredFinished.length > 0
      ? uncoveredFinished[0]
      : detailsBranch;
  // The worktree dir name for THAT branch (when a task names it), so the pill's
  // tooltip surfaces branch + worktree together. Keyed off detailsBranch — the
  // same key the pill renders — never the finished-only worktreeRef, which is
  // undefined mid-flight and would silently drop a known name (adversarial
  // review of 1471ce198, MEDIUM).
  const worktreeName = tasks.find((t) => t.worktree?.branch === detailsBranch)?.worktree?.name;

  // The number badge is tinted by status — the brand purple (bg-primary) is the
  // "current phase" accent, reserved for the in-progress feature; done features
  // read neutral, not-started faintest.
  const badgeClass =
    status === 'in_progress'
      ? 'bg-primary text-primary-foreground'
      : status === 'not_started'
        ? 'bg-muted text-subtle'
        : 'bg-muted text-muted-foreground';

  // The full-height action end-cap (detail-action-endcap task 2 — mock
  // .actcap): rendered only when the host wires all three actions. The cap
  // rounds its own right edge (rounded-r-2xl) rather than the section going
  // overflow-hidden, so the collapsed row's [Launch ▾] popover never clips.
  const endcap =
    onLandFeature !== undefined &&
    onTeardownFeature !== undefined &&
    onResumeRun !== undefined &&
    onContinueItem !== undefined &&
    prdId !== undefined ? (
      <FeatureEndcap
        repoId={repoId}
        item={`prd:${prdId}/${feature.id}`}
        // Provenance still loading ⇒ the inert "…" cap (task 2 of
        // endcap-resumes-pipeline-runs) — `landed`/`deliveredViaFix` below
        // derive from it.
        settling={provenanceSettling}
        done={status === 'completed'}
        // Retired scope is its own fact, NOT folded into `done` — widening
        // done would compute a landable availability and offer Merge → main
        // on superseded work (fix superseded-feature-endcap-and-skeleton-
        // title-nits task 1).
        superseded={status === 'superseded'}
        landed={provenance?.delivery.landed === true}
        live={activeRunId !== undefined}
        deliveredViaFix={provenance?.delivery.deliveredViaFix}
        // The MID-FLIGHT-aware branch fact (adversarial review of 62612d1dc):
        // worktreeRef resolves only for finished features, which made the
        // continue rung unreachable here — a parked in-progress feature stayed
        // wedged behind the inert cap. detailsBranch (the same fact the branch
        // pill renders) also names an in-progress row's task-level branch; the
        // teardown/merge rungs are unaffected (their done/landed gates only
        // fire where worktreeRef already resolved).
        // Withheld when the host's rendered Cleanup row(s) cover EVERY live
        // branch this feature finished work on (task 5, generalised by fix
        // mixed-branch-cleanup-prd-buries-affordance task 2) — dropping the
        // fact folds this cap to the inert already-merged rung. The key is
        // the finished LATTICE branches, never detailsBranch: a landed row's
        // tie-ranked lattice does not attribute, so detailsBranch falls back
        // to the attribution stamp and would never match a covered branch.
        // A KEPT cap must target an UNCOVERED branch (adversarial review of
        // 657495936, MEDIUM): a stamp naming a covered branch would tear
        // down what the rendered row already owns while the real orphan
        // stayed on disk — so when the stamp-derived detailsBranch is
        // covered, the cap's fact re-targets the first uncovered finished
        // branch instead.
        worktree={capWorktreeBranch !== undefined && !cleanupCovered ? { branch: capWorktreeBranch } : undefined}
        started={started}
        // The cap is the ONE launch home (F6 task 4) — the launchability fact
        // rides as the launch target; the row-inline [Launch ▾] is retired.
        launch={launchTarget}
        // Only rows that could plausibly own a run probe the resumable
        // projection — an untouched feature has nothing to continue.
        // Retired rows skip the probe outright: the fold can never render
        // Resume on a superseded scope, so the fetch's only possible effect
        // is waste (adversarial review of b0c85fed9, LOW).
        mayHaveRun={status !== 'superseded' && (status !== 'not_started' || feature.activeRun !== undefined || attention !== undefined)}
        landing={landing}
        // The feature's branch-keyed reconcile verdict, resolved onto the row by
        // the plan-detail route (board-review-done-and-main-health task 6): a
        // persisted failed reconcile reads `'conflicts'` here, gating the fold's
        // Merge → main off — the endcap reads the delivery-step outcome, not just
        // done/landed. Absent ⇒ the client edge (Merge stays enabled for done
        // work), as FixDetail's `landAvailability` wire does.
        landAvailability={feature.landAvailability}
        // The server-composed genuine-validation merge gate (props-in-ui task 3),
        // projected onto the row by the plan-detail route. When present it drives
        // the endcap's Merge rung authoritatively — a non-genuine completion
        // withholds Merge even on a done, reconcile-cleared row. Absent ⇒ the
        // endcap keeps its legacy landAvailability edge.
        mergeAvailable={feature.mergeAvailable}
        onLand={onLandFeature}
        onRaise={onRaiseFeature}
        onTeardown={onTeardownFeature}
        onResume={onResumeRun}
        onContinue={onContinueItem}
        // The live cap is the feature card's watch-live home (fix feature-card-
        // live-glyph-and-run-watch-surface task 4): clicking it opens the active
        // run stream. Undefined when there's no live run ⇒ the cap stays inert.
        onOpenRun={openActiveRun}
      />
    ) : null;

  return (
    <section
      data-testid="feature-row"
      data-open={expanded}
      // NEVER overflow-hidden on the section (fix merge-chooser-clipped-by-
      // expanded-feature-row): any cap popover (Launch, the Merge chooser)
      // drops below the header, so a section-level clip swallows it in BOTH
      // row states — the FeatureDetail body's corner rounding lives on the
      // body wrapper instead. `group` lets the caps square their bottom-right
      // corner while the row is open (data-open).
      className={clsx('group rounded-2xl', expanded ? 'panel' : 'panel-flat')}
    >
      <div className="flex items-stretch">
      {/* The restacked band (F6 task 5 — mock f40fde846): [chevron + badge]
          leads, then ONE full-width middle column — the wrapping title (ending
          in its trailing copy icon) over a pills-left / tasks-right details
          row — then Show details + the end-cap at full height. */}
      <div className="flex min-w-0 flex-1 items-center gap-3 px-4 py-3.5">
        <button
          type="button"
          aria-expanded={expanded}
          aria-controls={bodyId}
          onClick={onToggle}
          className="flex shrink-0 items-center gap-3 text-left"
        >
          {expanded ? (
            <ChevronDown className="h-4 w-4 shrink-0 text-subtle" />
          ) : (
            <ChevronRight className="h-4 w-4 shrink-0 text-subtle" />
          )}
          <span className={clsx('grid h-7 w-7 shrink-0 place-items-center rounded-lg mono text-xs font-bold', badgeClass)}>
            {feature.number}
          </span>
        </button>

        <div data-testid="feature-mid" className="flex min-w-0 flex-1 flex-col justify-center gap-1.5">
          {/* Title row — the title WRAPS (two lines max, never truncates) and
              the copy icon follows the text: the title shrinks to its content,
              so the icon is never pushed to the row's right edge. */}
          <div data-testid="feature-titlerow" className="flex items-center gap-1.5">
            {/* The title is a second toggle (same aria-expanded + aria-controls
                as the chevron button, both naming the one body) — clicking the
                text opens the row, like before the restack split them. */}
            <button
              type="button"
              aria-expanded={expanded}
              aria-controls={bodyId}
              onClick={onToggle}
              className="min-w-0 text-left"
            >
              <span className="line-clamp-2 whitespace-normal break-words font-medium leading-snug">
                {feature.title}
              </span>
            </button>
            {slug && <CopyIdButton value={slug} kind="Feature" className="shrink-0" />}
          </div>

          {/* Details row — pills then the progress readout, both left-aligned
              (justify-start), so the progress no longer floats to the right edge. */}
          <div data-testid="feature-detrow" className="flex items-center justify-start gap-3">
            <div data-testid="feature-detrow-pills" className="flex min-w-0 flex-wrap items-center gap-2">
              {/* The msr cluster (detail-provenance-restyle task 3): the
                  delivered lchip/who chips and the branch/who/where rail read
                  as ONE unit. Keyed off detailsBranch (not the finished-only
                  worktreeRef) so an in-progress row's branch pill shows too
                  (mock row 5). */}
              {(isDone && provenance) || activeRunId || detailsBranch || attention ? (
                <span data-testid="feature-msr" className="inline-flex items-center gap-2">
                  {/* A completed / superseded feature carries its DELIVERED
                      provenance (where/who) here — the live rail is empty in
                      that state. A lingering worktree folds into the strip's
                      pill (work-item-provenance F4 task 2 / task 4). */}
                  {isDone && provenance && (
                    <DeliveredProvenance
                      delivery={provenance.delivery}
                      who={provenance.who}
                      lingeringBranch={worktreeRef}
                      // A completed feature collapses its branch to the worktree
                      // glyph (fix ...task 6) — this block only renders for a done
                      // feature (isDone && provenance), so it always compacts.
                      compactBranch
                      // First-load only, COMPLETED rows only (fix prd-detail-
                      // skeletons-stabilize-layout task 1): the seeded WHO paints
                      // now; the delivered where/landed detail skeletons until
                      // the fetch lands. A superseded row's delivered slot settles
                      // empty, so reserving one there would introduce a
                      // skeleton→nothing shift instead of removing one — gate it
                      // out (mirroring the un-skeletoned cleanup row).
                      settling={provenanceSettling && status === 'completed'}
                    />
                  )}
                  {activeRunId || attention ? (
                    // A live run leads with the blue-pulse Running pill (read
                    // from disk, so it survives navigation); the worktree chip
                    // rides alongside when the work is also on a branch. Gate
                    // on the runId, not the mere presence of activeRun, so a
                    // run link with no id can't render an empty rail.
                    <MiniStatusRail
                      mode="card"
                      // The feature card's endcap owns the running words, so the
                      // rail drops its redundant Running… pill and pulses the
                      // worker glyph instead (fix feature-card-live-glyph-and-run-
                      // watch-surface task 1).
                      liveGlyph
                      worktreeMode="compact"
                      branches={
                        worktreeRef ? [{ branch: worktreeRef, hasWorktree: true, worktreeName }] : []
                      }
                      activeRunId={activeRunId}
                      onOpenRun={openActiveRun}
                      isWorkerRun={railIsWorker}
                      // Only the live glyph (this rail only mounts on activeRun /
                      // attention) renders here, and it tooltips the worker NAME +
                      // "Running…" — never the model. So workerModel would be a
                      // dead prop (adversarial review of 76839c46f); it is omitted.
                      workerName={railIsWorker ? feature.activeRun?.worker : undefined}
                      where={railWhere}
                      envName={activeRunId !== undefined ? feature.activeRun?.envName : undefined}
                      attentionStatus={attention}
                      className="shrink-0"
                    />
                  ) : !(isDone && provenance) && detailsBranch ? (
                    // Quiet worktree work (no live run, no attention) reads as
                    // the mock's msr pill — the branch by NAME while in progress,
                    // collapsed to the icon-only worktree glyph once the feature is
                    // DONE (the name is noise then — fix feature-card-live-glyph-
                    // and-run-watch-surface task 6).
                    <MsrPill branch={detailsBranch} worktreeName={worktreeName} iconOnly={isDone} className="shrink-0" />
                  ) : null}
                </span>
              ) : null}
              {/* Cleanup debt owned by THIS row (task 2) — the board card's
                  amber exception pill, restated per feature so the user can
                  see WHICH feature's worktree lingers without expanding
                  anything. Pure render: the manifest fetch waits for the
                  expand below. */}
              {ownedCleanupBranches.length > 0 && (
                <span
                  data-testid="feature-cleanup-pill"
                  className="inline-flex shrink-0 items-center rounded-full bg-amber-500/10 px-2 py-0.5 mono text-[10px] uppercase tracking-[0.04em] text-amber-600 dark:text-amber-400"
                >
                  cleanup
                </span>
              )}
              {/* The persisted reconcile-failed status (board-review-done-and-
                  main-health task 6): a branch-keyed failed/conflicts reconcile,
                  resolved onto this feature by the plan-detail route, is invisible
                  today — the same gap FixDetail's lastReconcile wire already
                  avoids. The verdict rides its exit reason as the tooltip; the
                  endcap's Merge is gated off in parallel (landAvailability). */}
              {feature.lastReconcile && (
                <span
                  data-testid="feature-reconcile-failed"
                  title={feature.lastReconcile.exitReason ?? `Reconcile ${feature.lastReconcile.verdict}`}
                  className="inline-flex shrink-0 items-center gap-1 rounded-full bg-red-500/10 px-2 py-0.5 mono text-[10px] uppercase tracking-[0.04em] text-red-600 dark:text-red-400"
                >
                  <GitMerge className="h-3 w-3" aria-hidden="true" />
                  reconcile {feature.lastReconcile.verdict}
                </span>
              )}
            </div>
            <div data-testid="feature-detrow-tasks" className="flex shrink-0 items-center gap-3">
              {/* The mock's pipeline tag leads the tasks cluster on a live row
                  (mock §01 `.tag`); terminal/idle rows carry no tag. No
                  gate-derived Validating pill (fix validating-derived-from-
                  review-gates-not-pipeline-runs): review phases are the
                  task's own work, so the row keeps this tag through them. */}
              {status === 'in_progress' ? (
                <span
                  data-testid="pipeline-tag"
                  className="inline-flex items-center gap-1 mono text-[10px] uppercase tracking-[0.04em] text-subtle"
                >
                  <Activity className="h-3 w-3" aria-hidden="true" />
                  pipeline
                </span>
              ) : null}
              <span className="mono text-xs text-muted-foreground">
                {total > 0 ? `${done}/${total} tasks` : 'No tasks'}
              </span>
              {started ? (
                <>
                  <GradientProgress value={percent} className="hidden w-20 sm:block" />
                  <span className="mono text-sm font-semibold text-blue">{percent}%</span>
                </>
              ) : launchTarget ? (
                // Launchable-but-unstarted: the launch lives on the end-cap
                // (F6 task 4), so the status row just carries the count — no
                // Not-started pill (the launch cap conveys "nothing staffed yet").
                null
              ) : (
                <span className="inline-flex items-center gap-1.5 rounded-full bg-muted px-2 py-0.5 text-[11px] font-medium text-muted-foreground">
                  <span className="h-1.5 w-1.5 rounded-full border border-border-strong" />
                  Not started
                </span>
              )}
            </div>
          </div>
        </div>
      </div>
      {/* Show details (F6 task 3, mock .ac-details) — the read-only provenance
          island's entry, STARTED rows with a branch only; a not-started row has
          nothing to inspect and keeps Launch as its only cap. Except
          delivered-and-reaped (done-lane-cleanup task 6): a LANDED row whose
          branch is gone would open an island for a dead ref — attribution
          stamps survive the reap, so only a live lattice cell keeps the cap;
          mid-flight rows keep the attribution fallback (their branch is real). */}
      {onShowDetails !== undefined &&
        started &&
        detailsBranch !== undefined &&
        !(provenance?.delivery.landed === true && !hasLiveWorktreeCell(tasks, detailsBranch)) && (
          <ShowDetailsCap onClick={() => onShowDetails(detailsBranch)} />
        )}
      {endcap}
      </div>

      {expanded && (
        <div id={bodyId} className="overflow-hidden rounded-b-2xl border-t border-border">
          {/* The owned cleanup command(s), mounted ONLY on expand so the
              manifest fetch fires on intent — never up front for every owning
              row on the PRD (task 2). Keyed by the raw branch; the server
              resolves branch-first (findWorktreeForId). */}
          {ownedCleanupBranches.length > 0 && (
            <div className="space-y-3 border-b border-border p-3">
              {ownedCleanupBranches.map((branch) => (
                <CleanupCommand key={branch} repoId={repoId} workItemId={branch} />
              ))}
            </div>
          )}
          {/* The feature's own validation strip now leads FeatureDetail's body,
              fetched lazily on this expand (fix plan-detail-eagerly-builds-every-
              feature-validation-input task 2) — a collapsed section pays nothing. */}
          <FeatureDetail
            feature={feature}
            repoId={repoId}
            planId={prdId}
            {...(() => {
              // Resolve the feature branch's LIVE reconcile run from the delivery
              // rows so FeatureDetail subscribes to an in-flight foreign reconcile,
              // matching how RepoDetailPage resolves liveReconcileRunId for FixDetail.
              const live = deriveLiveReconcileRunIdForBranch(detailsBranch, deliveryWorktrees ?? []);
              return live !== undefined ? { liveReconcileRunId: live } : {};
            })()}
          />
        </div>
      )}
    </section>
  );
}

export default PlanFeatureRow;
