import { useState, useCallback, useMemo, useRef } from 'react';
import type { SkillName, SkillInvocationContext, ToolCall } from '../types';
import type { RunEvent } from '@magic-ingredients/tiny-brain-core';
import { useRunStream } from './useRunStream';

export interface UseSkillInvocationResult {
  invoke: (skill: SkillName, prompt: string, context?: SkillInvocationContext) => Promise<void>;
  cancel: () => void;
  isRunning: boolean;
  output: string;
  toolCalls: ToolCall[];
  error: string | null;
  sessionId: string | null;
}

/** Fold a run's events into the tool-call list the panel renders. The spine's
 *  `tool_result` carries only `success`, so a completed call's `result` is
 *  `{ success }` — the result/error strings the UI never displayed are gone. */
function deriveToolCalls(events: RunEvent[]): ToolCall[] {
  const calls: ToolCall[] = [];
  for (const event of events) {
    if (event.type === 'tool_use') {
      calls.push({ tool: event.tool, input: event.input });
    } else if (event.type === 'tool_result') {
      // Back-fill the most recent result-less call (mirrors the prior hook).
      for (let i = calls.length - 1; i >= 0; i--) {
        if (!calls[i].result) {
          calls[i] = { ...calls[i], id: event.toolId, result: { success: event.success } };
          break;
        }
      }
    }
  }
  return calls;
}

/**
 * Invoke a skill and render its live activity off the unified run spine
 * (ADR-0017). `invoke` starts the run (POST /api/skills/invoke returns a
 * runId); activity then flows through {@link useRunStream} against the per-run
 * SSE bridge and is folded into the `output` / `toolCalls` / `error` /
 * `isRunning` view the panel already consumes.
 */
export function useSkillInvocation(repoId: string): UseSkillInvocationResult {
  const [runId, setRunId] = useState<string | null>(null);
  const [sessionId, setSessionId] = useState<string | null>(null);
  const [starting, setStarting] = useState(false);
  const [startError, setStartError] = useState<string | null>(null);
  // A snapshot frozen at cancel time: tearing the subscription down clears
  // useRunStream's events, so we keep the last view to render rather than
  // blanking the panel. null means "live" (derive from the stream).
  const [frozen, setFrozen] = useState<RunEvent[] | null>(null);
  const startAbortRef = useRef<AbortController | null>(null);

  const { events: liveEvents, error: streamError } = useRunStream(repoId, runId ?? '');
  const events = frozen ?? liveEvents;

  const invoke = useCallback(
    async (skill: SkillName, prompt: string, context?: SkillInvocationContext): Promise<void> => {
      startAbortRef.current?.abort();
      const abort = new AbortController();
      startAbortRef.current = abort;

      setRunId(null);
      setSessionId(null);
      setStartError(null);
      setFrozen(null);
      setStarting(true);
      try {
        const response = await fetch('/api/skills/invoke', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ skill, prompt, context, repoId }),
          signal: abort.signal,
        });
        if (!response.ok) {
          const data = (await response.json().catch(() => ({}))) as { error?: string };
          setStartError(data.error || `HTTP error ${response.status}`);
          return;
        }
        const data = (await response.json()) as { runId: string; sessionId?: string };
        setSessionId(data.sessionId ?? null);
        setRunId(data.runId);
      } catch (err) {
        // A cancel mid-start aborts the request — treat as a silent stop, not
        // an error, and don't subscribe (no runId was set).
        if (err instanceof Error && err.name === 'AbortError') return;
        setStartError(err instanceof Error ? err.message : 'Unknown error');
      } finally {
        setStarting(false);
      }
    },
    [repoId],
  );

  const cancel = useCallback(() => {
    // Stop an in-flight start so a late response can't re-subscribe.
    startAbortRef.current?.abort();
    if (sessionId) {
      void fetch(`/api/skills/${sessionId}/cancel`, { method: 'POST' }).catch(() => {});
    }
    // Freeze the current view, then tear down the subscription so the run's
    // events stop mutating in the background.
    setFrozen(events);
    setRunId(null);
    setSessionId(null);
  }, [sessionId, events]);

  const output = useMemo(() => {
    let acc = '';
    for (const event of events) {
      if (event.type === 'text') acc += event.text;
    }
    return acc;
  }, [events]);

  const toolCalls = useMemo(() => deriveToolCalls(events), [events]);

  // The LATEST exit wins (fix orphan-settle-races-live-run-record task 2): a
  // liveness-sweep false settle can inject a failed exit onto a healthy run's
  // stream ahead of its real terminal — a first-exit fold would surface the
  // sweep's guess as the outcome.
  const exitEvent = useMemo(
    () => events.filter((e): e is Extract<RunEvent, { type: 'exit' }> => e.type === 'exit').at(-1),
    [events],
  );

  // Any non-`completed` terminal state is a failure to surface (failed,
  // cancelled, stalled, rejected) — not just `failed`.
  const exitError =
    exitEvent && exitEvent.status !== 'completed'
      ? exitEvent.reason ?? `Skill run ${exitEvent.status}`
      : null;
  const error = startError ?? exitError ?? streamError;

  // Running until a terminal exit — but never alongside an error, so the panel
  // never shows the spinner and the error banner at once. `frozen` (a cancel)
  // also stops it: a frozen snapshot carries no live runId.
  const isRunning =
    error === null && frozen === null && (starting || (runId !== null && exitEvent === undefined));

  return { invoke, cancel, isRunning, output, toolCalls, error, sessionId };
}
