/**
 * The board's short-SHA rendering, shared by the red-main banner and the
 * main-is-broken overlay (split-land-from-validation F6). One definition, so
 * the range in the banner and the SHAs in the overlay's rows cannot end up
 * truncated to different widths and read as different commits.
 */
export const SHORT_SHA_LENGTH = 7;

export function shortSha(sha: string): string {
  return sha.slice(0, SHORT_SHA_LENGTH);
}

/**
 * The check-window chip the banner and overlay share
 * (red-banner-copy-speaks-jargon): plain words, never the internal
 * `X…X` range form. A baseline whose short form equals the tip's (an
 * unresolved `<tip>^1` from records predating
 * main-validation-baseline-unresolved-rev, or a genuinely single-commit
 * window) reads as one checked commit; a real window reads as where the
 * failing check started.
 */
export function checkWindowLabel(baselineSha: string, tipSha: string): string {
  // Compare/display only the leading hex — a rev suffix on an unresolved
  // baseline (`abc123^1`) must neither leak into the label nor defeat the
  // degenerate-window comparison.
  const hex = (sha: string): string => shortSha(/^[0-9a-f]*/i.exec(sha)?.[0] ?? '');
  const base = hex(baselineSha);
  const tip = hex(tipSha);
  if (tip === '') return base === '' ? 'window unknown' : `since ${base}`;
  return base === tip || base === '' ? `checked at ${tip}` : `since ${base}`;
}
