import { useEffect, useState, type ReactNode } from 'react';
import { Cloud, CornerDownRight, ExternalLink, GitBranch, HardDrive, ListChecks, Server } from 'lucide-react';
import { cn } from '@/lib/utils';
import WorkerRunIsland from '@/components/WorkerRunIsland';
import type { RunListRow } from '@/hooks/useRepoRuns';
import { formatRunUsage } from '../format-run-usage';
import { RunStatusPill } from '../run-status-meta';
import {
  deriveBandMeta,
  elapsedMsOf,
  foldUnifiedRuns,
  formatElapsed,
  envBandsForRuns,
  laneOf,
  stallNoticeMinutesOf,
  type BoardRow,
  type ConfiguredEnvironment,
  type UnifiedRun,
} from './runs-board-model';
import { RunResourceFootprint } from './RunResourceFootprint';
import { runHeadingTitle, runFeatureLabel } from '../run-title';
import { GradientProgress } from '@/components/ui/GradientProgress';

/**
 * The work-item kind pill for a run card (runs-card-uplift) — a PRD run wears the
 * bronze "plan" pill and a fix run the neutral kind pill, matching the board
 * card's tag vocabulary (`tb-pill--plan` / `tb-pill--kind`): the plan tokens are
 * the same global `--ds-plan*` the board uses, and the neutral pill is
 * `foreground` at `0.11` opacity — the exact `color-mix(… --tb-fg 11% …)` the
 * board's `tb-pill--kind` resolves to (`--tb-fg` → `--foreground`). A task-keyed
 * run (reconcile / main-validation / land) names no work item — it carries its own
 * run-type treatment, not a plan/fix pill — so it maps to nothing.
 */
const WORK_ITEM_KIND_PILL: Partial<Record<RunListRow['workRef']['kind'], { label: string; className: string }>> = {
  prd: { label: 'plan', className: 'bg-[var(--ds-plan-tint)] text-[var(--ds-plan)]' },
  fix: { label: 'fix', className: 'bg-foreground/[0.11] text-foreground' },
};

/**
 * The run-TYPE badge for a run card (runs-card-uplift) — the run's ROLE, distinct
 * from its work-item kind pill. `completion` is the item's own validation lane and
 * `main-validation` the post-merge REGRESSION on main (the user's two buckets:
 * worker-side vs regression); `reconcile` / `land` are the delivery runs. A plain
 * `worker` TDD run has no role badge — it is the default, so it reads unbadged.
 */
const RUN_KIND_BADGE: Partial<Record<NonNullable<RunListRow['kind']>, string>> = {
  completion: 'validation',
  'main-validation': 'regression',
  reconcile: 'reconcile',
  land: 'land',
};

/** A band is local when its provider is the built-in `local`; anything else is remote. */
const isLocalProvider = (provider: string): boolean => provider === 'local';

/**
 * The band's environment tile — the provider glyph (a disk for the local machine,
 * a cloud for a remote provider) seated in a rounded, tinted square, matching the
 * mockup's `env-tile`. Tagged with its provider so a test (and the eye) reads the
 * band's environment kind at a glance. Derived purely from `environment.provider`.
 */
function BandGlyph({ provider }: { provider: string }) {
  const local = isLocalProvider(provider);
  const Icon = local ? HardDrive : Cloud;
  return (
    <span
      className={cn(
        'grid h-9 w-9 flex-shrink-0 place-items-center rounded-xl ring-1 ring-inset',
        local
          ? 'bg-blue-500/15 text-blue-500 ring-blue-500/30'
          : 'bg-primary/15 text-primary ring-primary/30',
      )}
    >
      <Icon data-testid="env-glyph" className="h-[18px] w-[18px]" aria-hidden="true" />
    </span>
  );
}

/**
 * The band's provider badge — `THIS MACHINE` for the local machine, else the
 * environment's provider (`RAILWAY`, `MANAGED`, …, upper-cased by the badge's
 * own styling). The heading already names the environment; this pill names the
 * PROVIDER behind it, so a `prod` environment on Railway reads `prod` · `RAILWAY`.
 */
function BandBadge({ provider }: { provider: string }) {
  const local = isLocalProvider(provider);
  const Icon = local ? HardDrive : Cloud;
  return (
    <span
      data-testid="env-badge"
      className={cn(
        'mono inline-flex items-center gap-1 rounded-md px-1.5 py-0.5 text-[10px] font-semibold uppercase tracking-[0.04em]',
        local ? 'bg-blue-500/15 text-blue-500' : 'bg-primary/15 text-primary',
      )}
    >
      <Icon className="h-3 w-3" aria-hidden="true" />
      {local ? 'this machine' : provider}
    </span>
  );
}

/**
 * The band meta line — `N active · N today` — with the counts derived
 * client-side from the band's own rows ({@link deriveBandMeta}); no server field.
 * `active` is the live (Running-lane) run count; `today` is the runs that started
 * today. The provider rides the band's badge pill, so it is not repeated here.
 */
function BandMetaLine({ runs }: { runs: readonly BoardRow[] }) {
  const { active, today } = deriveBandMeta(runs);
  return (
    <span data-testid="env-meta" className="mono text-[11px] text-muted-foreground tabular-nums">
      {/* The provider now rides the band's badge pill, so the meta line carries
          only the counts — no redundant "provider {p}" token. */}
      {active} active · {today} today
    </span>
  );
}

/**
 * The card's phase-progress block (runs-card-phase-progress + runs-card-uplift
 * task 2) — the mockup's `green phase · 62%` bar. Board parity: the LIVE bar is
 * the SAME shared {@link GradientProgress} the board card renders, driven off the
 * item progress value (`value = progressPercent ?? 0`) — always DETERMINATE, so a
 * freshly-dispatched run reads a real 0 rather than the old indeterminate pulse.
 * The phase label reads `{phase} phase` when a phase exists; the percent shows in
 * the right slot only when one has resolved.
 *
 * A NON-live run (a settled row that lingers in the running lane) shows the
 * determinate bar only when it has a real percent, and otherwise falls back to
 * the phase label alone (or nothing) — no fabricated bar for a run not working.
 */
function RunPhaseProgress({
  phase,
  progressPercent,
  live,
}: {
  phase?: RunListRow['phase'];
  progressPercent?: number;
  live: boolean;
}) {
  const hasPercent = progressPercent !== undefined;
  // Nothing to show for a settled run with no percent: the phase label alone if
  // a phase resolved, else no block at all (no fabricated bar).
  if (!hasPercent && !live) {
    if (phase === undefined) return null;
    return (
      <div data-testid="run-phase-progress" className="mt-2.5">
        <div className="mono flex items-center justify-between text-[10px] text-muted-foreground">
          <span data-testid="run-phase-label">{phase} phase</span>
        </div>
      </div>
    );
  }
  // Name the progressbar for assistive tech — a bare bar is unnamed. Falls back
  // to a generic label when no phase has resolved yet.
  const barLabel = phase !== undefined ? `${phase} phase progress` : 'run progress';
  // Board parity: the identical determinate bar the board card renders
  // (`value={d.progress ?? 0}`). No runs-only indeterminate variant.
  return (
    <div data-testid="run-phase-progress" className="mt-2.5">
      <div className="mono flex items-center justify-between text-[10px] text-muted-foreground">
        {phase !== undefined && <span data-testid="run-phase-label">{phase} phase</span>}
        {hasPercent && (
          <span data-testid="run-progress-percent" className="ml-auto tabular-nums">
            {progressPercent}%
          </span>
        )}
      </div>
      <GradientProgress value={progressPercent ?? 0} ariaLabel={barLabel} className="mt-1" />
    </div>
  );
}

export interface RunsListDetailViewProps {
  /** Every run for the repo (all states), as `useRepoRuns` returns them. */
  runs: readonly RunListRow[];
  /**
   * The configured environments (Environments registry) the board renders a band
   * for — the built-in `local` plus each remote environment, always shown even
   * when idle. Runs slot into the band matching `run.environment.name`; a run on
   * an unregistered environment gets a fallback band. Defaults to empty (a lone
   * local band) so the component renders standalone in tests/stories.
   */
  environments?: readonly ConfiguredEnvironment[];
  /** The repo whose runs these are — passed to the WorkerRun island a row opens. */
  repoId: string;
  /** A load error to surface instead of the "no runs" empty state, if any. */
  error?: string | null;
  /**
   * Render the detail island for the selected run. Defaults to the existing
   * {@link WorkerRunIsland} (live tail for a running row, record view for a
   * terminal one); injectable so tests drive a stub without the SSE stack.
   * Ignored when {@link onSelectRun} is set — the parent owns the island then.
   */
  renderIsland?: (runId: string, onClose: () => void) => ReactNode;
  /**
   * Selecting a row. When provided the parent owns the run surface (e.g.
   * RepoDetailPage's shared, deep-linkable `?run=` island) and the component
   * opens no island of its own. When absent the component is self-contained and
   * opens the {@link renderIsland} island inline.
   */
  onSelectRun?: (runId: string) => void;
}

/**
 * The runs lens: a filtered list of every run across all states, each row a
 * status pill + vitals (worker/model, failure reason, token usage, start time,
 * a reconcile-kind badge). Selecting a row opens the {@link WorkerRunIsland}.
 * Status-filter state is local (ephemeral refinement, defaulting to all);
 * selection is local too — the island is a floating overlay, not a deep-linked
 * pane, and the parent (RepoDetailPage) owns the lens toggle, not the row.
 */
export function RunsListDetailView({ runs, environments = [], repoId, error, renderIsland, onSelectRun }: RunsListDetailViewProps) {
  const [selectedRunId, setSelectedRunId] = useState<string | null>(null);
  // Running-only: the runs lens is a live fleet monitor, so it shows just the
  // in-flight runs (running / cancelling). Terminal and attention runs are the
  // work-item surfaces' concern, not this lens.
  const runningRuns = runs.filter((run) => laneOf(run) === 'running');
  // A once-per-second clock so a live run's card elapsed ticks. Only armed when a
  // live run is on screen — a board of terminal runs sets no interval and never
  // re-renders on a timer.
  const [now, setNow] = useState(() => Date.now());
  const hasLiveRun = runningRuns.some((r) => r.live && !r.endedAt);
  useEffect(() => {
    if (!hasLiveRun) return;
    const id = setInterval(() => setNow(Date.now()), 1000);
    return () => clearInterval(id);
  }, [hasLiveRun]);

  // Parent-owned selection (the page's shared ?run= island) takes precedence;
  // otherwise fall back to opening the island inline.
  const selectRun = (runId: string) => (onSelectRun ? onSelectRun(runId) : setSelectedRunId(runId));

  const openIsland =
    renderIsland ??
    ((runId: string, onClose: () => void) => (
      <WorkerRunIsland
        repoId={repoId}
        runId={runId}
        onClose={onClose}
        onContinued={selectRun}
      />
    ));

  // The board always shows one island per configured environment (local + each
  // remote env from the registry), full chrome even when nothing is running (no
  // empty-board placeholder). Running runs slot into their environment's island;
  // an idle island renders empty.
  const bands = envBandsForRuns(environments, runningRuns);

  const renderCard = (run: BoardRow) => {
    const elapsedMs = elapsedMsOf(run, now);
    // Format once so the visible digits and the announced label are provably the
    // same string (never two independent formattings that could drift).
    const elapsedLabel = elapsedMs !== null ? formatElapsed(elapsedMs) : null;
    const live = run.live && !run.endedAt;
    // `formatRunUsage` returns an em-dash placeholder for a run with no usage;
    // on the card face we drop it rather than render a bare "—".
    const usageLabel = run.usage ? formatRunUsage(run.usage) : null;
    // The output-stall notice minutes, or null for no notice — the pure model
    // owns the "is this a stall" decision (idle minutes vs threshold) against
    // the ticking now; the card just renders whatever number it hands back.
    const stallMinutes = stallNoticeMinutesOf(run, now);
    // The card leads with the work-item title (title-over-slug), the feature
    // title on its own line for a PRD run — the SHARED rule both run surfaces
    // (this card and the run island header) apply, so neither re-derives it.
    const headingTitle = runHeadingTitle(run.workRef, run.titles, run.kind);
    const featureSubtitle = runFeatureLabel(run.workRef, run.titles);
    // Bound once (not thrice) so the compiler proves definedness inside the
    // guard — no non-null assertion.
    const kindPill = WORK_ITEM_KIND_PILL[run.workRef.kind];
    const kindBadge = run.kind !== undefined ? RUN_KIND_BADGE[run.kind] : undefined;
    return (
    // A vertical run card (mockup `.run`): the whole face is the select target.
    // The inner button carries the row testid; the optional session link sits
    // outside it so an anchor never nests in a button.
    <div
      key={run.runId}
      data-testid="env-run-card"
      className={cn(
        'group relative flex flex-col rounded-xl border bg-muted/20 p-3 text-left transition-all',
        live
          ? 'border-blue-500/45 shadow-[0_0_0_1px_theme(colors.blue.500/0.25)]'
          : 'border-border hover:border-border/80',
        selectedRunId === run.runId && 'ring-1 ring-primary/50',
      )}
    >
      <button
        type="button"
        data-testid="run-list-row"
        data-run-id={run.runId}
        aria-current={selectedRunId === run.runId ? 'true' : undefined}
        onClick={() => selectRun(run.runId)}
        // `flex-1` fills the card height (the card is flex-col) so the footer's
        // `mt-auto` has room to push against — pinning the foot to the bottom edge
        // across an equal-height grid row (runs-card-uplift).
        className="flex min-w-0 flex-1 flex-col text-left outline-none"
      >
        {/* Header: status chip (left) + elapsed (right) */}
        <div className="flex items-center gap-2">
          <RunStatusPill status={run.status} />
          {kindPill && (
            <span
              data-testid="run-kind-pill"
              className={cn(
                'mono rounded-md px-1.5 py-0.5 text-[10px] font-semibold uppercase tracking-[0.04em]',
                kindPill.className,
              )}
            >
              {kindPill.label}
            </span>
          )}
          {kindBadge !== undefined && (
            <span
              data-testid="run-kind-badge"
              className="mono rounded-md bg-primary/15 px-1.5 py-0.5 text-[10px] font-semibold uppercase tracking-[0.04em] text-primary"
            >
              {kindBadge}
            </span>
          )}
          {elapsedLabel !== null && (
            // The bare MM:SS reads like a clock time, so a VISIBLE duration
            // label names it on the card face (not just for a screen reader).
            // The wording tracks liveness — "Running for" only while the run is
            // still live, "Ran for" once it has an end — so the label never
            // claims a settled run is still running. Only the value is
            // monospace/tabular (the label is sans-serif muted, per the mockup);
            // the digits keep their format and live tick.
            <span
              data-testid="run-elapsed"
              className="ml-auto flex items-center gap-1.5 text-xs text-muted-foreground"
            >
              <span>{live ? 'Running for' : 'Ran for'}</span>
              <span className="mono font-semibold text-foreground">{elapsedLabel}</span>
            </span>
          )}
          {stallMinutes !== null && (
            <span
              data-testid="run-stall-notice"
              className="mono text-xs tabular-nums text-amber-500"
            >
              no output for {stallMinutes}m
            </span>
          )}
        </div>

        {/* Identity: the work-item title leads the card; the feature title
            rides its own line on a PRD run; worker/model/effort demote to a
            secondary meta line. */}
        <h3
          data-testid="run-card-title"
          className="mt-2.5 truncate text-[15px] font-semibold leading-tight text-foreground"
        >
          {headingTitle}
        </h3>
        {featureSubtitle !== null && (
          <p
            data-testid="run-card-feature"
            className="mt-1 flex items-center gap-1 truncate text-[13px] text-muted-foreground"
          >
            <CornerDownRight className="h-3 w-3 flex-shrink-0 opacity-70" aria-hidden="true" />
            <span className="truncate">{featureSubtitle}</span>
          </p>
        )}
        {/* Worktree glyph + demoted worker/model/effort on one row. The long
            branch string collapses to the glyph (branch exposed on hover / to
            assistive tech). Only a LANE run — a completion/reconcile/land/
            main-validation run in the shared main checkout, recorded with
            target `local` and no worktree — gets the quiet host glyph. Every
            worker run has a worktree (local `local-worktree` OR cloud
            `cloud-*`), so the host glyph never claims "no worktree" for a run
            that has one. Worker and model are each their own span so the two
            read as distinct, individually-addressable tokens. */}
        <div className="mt-2 flex items-center gap-2">
          {run.target === 'local' ? (
            <span
              data-testid="run-host-glyph"
              title={`runs on ${run.branch} — no worktree`}
              className="grid h-[22px] w-[22px] flex-none place-items-center rounded-md bg-foreground/[0.07] text-muted-foreground"
            >
              <Server className="h-3 w-3" aria-hidden="true" />
              <span className="sr-only">runs on the host — no worktree</span>
            </span>
          ) : (
            <span
              data-testid="run-worktree-glyph"
              title={run.branch}
              className="grid h-[22px] w-[22px] flex-none place-items-center rounded-md bg-blue-500/15 text-blue-500 ring-1 ring-inset ring-blue-500/30"
            >
              <GitBranch className="h-3 w-3" aria-hidden="true" />
              <span className="sr-only">worktree {run.branch}</span>
            </span>
          )}
          <p className="mono flex min-w-0 items-center gap-1.5 truncate text-[11px] text-muted-foreground">
            <span className="truncate">{run.worker}</span>
            <span className="text-muted-foreground/70">·</span>
            <span className="truncate">{run.model}</span>
            <span className="text-muted-foreground/70">· {run.effort}</span>
          </p>
        </div>

        {/* Phase progress: always-on for a live run — the board-parity determinate
            bar (value = progressPercent ?? 0), labelled `{phase} phase · {percent}%`
            when a phase/percent has resolved. */}
        <RunPhaseProgress phase={run.phase} progressPercent={run.progressPercent} live={live} />

        {/* Footer: token usage · labelled Memory / CPU resource metrics, split
            from the card body by a hairline (mockup `.foot`). Rendered only when
            a metric exists, so a bare pre-metric run shows no empty bordered
            strip; absent metrics are simply omitted. The commit count was dropped
            (redundant with the phase/progress signal — runs-card-uplift). */}
        {(usageLabel !== null || Boolean(run.resources)) && (
          <div
            data-testid="run-card-footer"
            // A distinct footer bar, not loose body text: full-bleed to the card
            // edge (negative margins cancel the card's p-3), a tinted fill, and
            // seated in the card's bottom corners. The old border-foreground/10
            // hairline was invisible on the dark card, so the border is stronger
            // and the fill carries the demarcation. mt-auto still pins it to the
            // card bottom across an equal-height grid row.
            className="mono -mx-3 -mb-3 mt-auto flex flex-wrap items-center gap-x-2 gap-y-1 rounded-b-xl border-t border-foreground/15 bg-foreground/[0.04] px-3 py-2 text-[10px] tabular-nums text-muted-foreground"
          >
            {usageLabel && <span>{usageLabel}</span>}
            <RunResourceFootprint resources={run.resources} />
          </div>
        )}
      </button>
      {run.cloudSessionUrl && (
        // A sibling of the select button (never nested — an anchor inside a
        // button is invalid), present only for a cloud run: local runs have no
        // session, so no link (honesty).
        <a
          data-testid="run-session-link"
          data-run-id={run.runId}
          href={run.cloudSessionUrl}
          target="_blank"
          rel="noreferrer"
          className="flex flex-shrink-0 items-center gap-1 rounded-lg px-2 py-1 text-xs text-blue-500 transition-colors hover:bg-muted/50 hover:text-blue-400"
        >
          <ExternalLink className="h-3 w-3" aria-hidden="true" />
          session
        </a>
      )}
    </div>
    );
  };

  // A child sub-step chip within a unified run — the spawned process (the
  // post-land regression) folded under its land lead. Compact: its status pill,
  // its run-TYPE badge (`regression`), and its title, the whole row selecting the
  // child run so its island is one click away.
  const renderSubStep = (child: BoardRow) => {
    const badge = child.kind !== undefined ? RUN_KIND_BADGE[child.kind] : undefined;
    return (
      <button
        key={child.runId}
        type="button"
        data-testid="run-substep"
        data-run-id={child.runId}
        onClick={() => selectRun(child.runId)}
        className="flex w-full items-center gap-2 rounded-lg border border-border/60 bg-muted/10 px-2.5 py-1.5 text-left transition-colors hover:border-border/80"
      >
        <CornerDownRight className="h-3 w-3 flex-shrink-0 text-muted-foreground/70" aria-hidden="true" />
        <RunStatusPill status={child.status} />
        {badge !== undefined && (
          <span
            data-testid="run-substep-badge"
            className="mono rounded-md bg-primary/15 px-1.5 py-0.5 text-[10px] font-semibold uppercase tracking-[0.04em] text-primary"
          >
            {badge}
          </span>
        )}
        <span className="mono min-w-0 truncate text-[11px] text-muted-foreground">
          {runHeadingTitle(child.workRef, child.titles, child.kind)}
        </span>
      </button>
    );
  };

  // Fold a land run and its post-land regression into ONE unified entry: the
  // lead renders as the run card, its child processes nest below as sub-steps,
  // so a single delivery reads as one thing. A run with no folded children (the
  // common case) renders exactly as before — a bare card, no wrapper.
  const renderUnified = (unified: UnifiedRun) => {
    if (unified.steps.length === 1) return renderCard(unified.lead);
    return (
      <div key={unified.runId} data-testid="unified-run" className="flex flex-col gap-1.5">
        {renderCard(unified.lead)}
        <div data-testid="unified-run-substeps" className="flex flex-col gap-1.5 pl-4">
          {unified.steps.slice(1).map(renderSubStep)}
        </div>
      </div>
    );
  };

  return (
    <div className="flex h-full flex-col gap-3 px-3 pb-3 pt-2">
      <div className="min-h-0 flex-1 space-y-4 overflow-auto">
        {error ? (
          <div
            data-testid="runs-error"
            className="flex h-full flex-col items-center justify-center gap-2 text-red-500"
          >
            <ListChecks className="h-10 w-10" aria-hidden="true" />
            <span>Failed to load runs: {error}</span>
          </div>
        ) : (
          bands.map((band) => {
            const local = isLocalProvider(band.provider);
            return (
              <section
                key={band.name}
                data-testid="env-band"
                data-env-name={band.name}
                data-provider={band.provider}
                className="panel rounded-2xl p-4"
              >
                {/* Accent bar — the band's environment cue (blue local, primary→pink remote) */}
                <div
                  aria-hidden="true"
                  className={cn(
                    'mb-3 h-[3px] rounded-full bg-gradient-to-r',
                    local ? 'from-blue-500 to-blue-500/15' : 'from-primary to-pink-500',
                  )}
                />
                <div className="mb-4 flex items-center gap-3">
                  <BandGlyph provider={band.provider} />
                  <div className="min-w-0">
                    <div className="flex items-center gap-2">
                      <h2 className="text-base font-semibold text-foreground">{band.name}</h2>
                      <BandBadge provider={band.provider} />
                    </div>
                    <BandMetaLine runs={band.runs} />
                  </div>
                </div>
                {band.runs.length === 0 ? (
                  // Idle island: keep the full chrome, mark the body quietly rather
                  // than dropping the whole board to a placeholder.
                  <div
                    data-testid="env-band-idle"
                    className="rounded-xl border border-dashed border-border/60 px-4 py-6 text-center text-xs text-muted-foreground"
                  >
                    Nothing running here
                  </div>
                ) : (
                  <div
                    data-testid="env-run-grid"
                    // `auto-fill` keeps the min track, so with a non-full band the
                    // min width IS the card width. The prior 232px track truncated
                    // even short work titles ("Preempted/killed reconcile…"); the
                    // track is doubled so a title reads on the card face.
                    className="grid grid-cols-[repeat(auto-fill,minmax(464px,1fr))] gap-2.5"
                  >
                    {foldUnifiedRuns(band.runs).map(renderUnified)}
                  </div>
                )}
              </section>
            );
          })
        )}
      </div>

      {selectedRunId && openIsland(selectedRunId, () => setSelectedRunId(null))}
    </div>
  );
}

export default RunsListDetailView;
