import { useEffect, useRef, useState, type ReactNode } from 'react';
import { Ban, Check, GitMerge, GitPullRequestArrow, Loader2, PlaneTakeoff, Play, RotateCcw, Trash2 } from 'lucide-react';
import type { LandAvailability } from '@magic-ingredients/tiny-brain-core';
import { deriveEndcapState } from '@magic-ingredients/tiny-brain-core/endcap-state';
import { cn } from '@/lib/utils';
import LaunchControl, { type LaunchTarget } from './LaunchControl';
import { fetchResumableRun } from '../services/api';

export interface FeatureEndcapProps {
  repoId: string;
  /** The resumable-projection item slug (`prd:<prd>/<feature>` / `fix:<id>`). */
  item: string;
  /** The injected model axes the host already knows (F6 shape). */
  done: boolean;
  landed: boolean;
  live: boolean;
  deliveredViaFix?: string;
  worktree?: { branch: string };
  /** The scope has started (any task beyond not_started) — drives the inert In-progress rung (F6 task 4). */
  started?: boolean;
  /**
   * A worker is assigned but nothing has landed — the projected
   * `activeRun.state === 'launched'` fact (fix launched-state-for-dispatched-
   * runs task 2). Renders the inert Launched cap instead of the live rung's
   * cap unmount, so the column survives the dispatch→first-commit window.
   * The `landing` override still preempts it, and the fold refuses the fact
   * on terminal work (done / landed / superseded / delivered).
   */
  launched?: boolean;
  /** The scope is fully superseded (retired) — drives the inert Superseded rung (fix superseded-feature-endcap-and-skeleton-title-nits task 1). */
  superseded?: boolean;
  /**
   * The idle scope's launch target (F6 task 4) — presence IS the launchability
   * fact (the host derives it: not started, no worktree work, no run). The cap
   * then hosts the existing self-gating LaunchControl popover, retiring the
   * row-inline [Launch ▾].
   */
  launch?: LaunchTarget;
  /**
   * Whether a run could exist for this item at all (started work, a run link,
   * or an attention fact). Idle rows pass false and never probe the resumable
   * projection — a PRD of N untouched features must not fire N probes.
   */
  mayHaveRun: boolean;
  /**
   * This item's land run is IN FLIGHT (fix feature-land-has-no-live-feedback
   * task 2): the cap pins to the inert blue Merging… state — the in-progress
   * cap family — overriding every fold rung until the host's streamed run
   * reaches its terminal, so a re-click cannot double-dispatch the land.
   */
  landing?: boolean;
  /**
   * The host's provenance read is STILL ON ITS FIRST LOAD (fix
   * endcap-resumes-pipeline-runs task 2): the delivery-family rungs (Merge /
   * Already merged / delivered / teardown) derive from facts that haven't
   * arrived, so the cap holds an inert dim pulsing "…" instead of flashing
   * the merge default. First-load ONLY — hosts must not raise this on
   * refetches (the provenance hook keeps the previous snapshot while
   * refreshing, so a settled cap must stay put). The cap folds its OWN
   * resumable probe into the same gate internally; host-known rungs
   * (running / launched / superseded / in-progress / launch) render
   * regardless — they owe nothing to the pending inputs.
   */
  settling?: boolean;
  /**
   * This item's VALIDATION suite is live (validation-pipeline-visibility F4
   * task 5): the pre-merge completion run that gates landing. Renders the inert
   * review-purple Validating… rung in place of the Merge chooser — the cap
   * answers "why can't I land yet" — so a land cannot be dispatched over a live
   * validation. It yields to Merge on green (the fact clears). `landing` (the
   * later post-merge stage) still outranks it.
   */
  validating?: boolean;
  /**
   * The KIND of the live run driving the inert `running` cap (fix land-surface-
   * single-strip-and-legible-phases task 3). The default renders "Running"; two
   * delivery-run kinds diverge, since "Running" would collide with a worker
   * executing tasks and misread as "the fix is still being worked":
   * - `'merge'` → "Merging" (a live land).
   * - `'reconcile'` → "Reconciling…" (the pre-merge rebase+verify — reconcile-
   *   segment task 3), so the cap explains why Merge is disabled.
   * `'worker'` and absent both render "Running". Both delivery kinds stay inert
   * (no click-to-view — that watches the worker stream, not a machinery run).
   * Only consulted in the `running` branch; the cap skin and spinner are the
   * same either way.
   */
  liveRunKind?: 'worker' | 'merge' | 'reconcile';
  /**
   * The MODELED land availability (the F6 model's reconcile-derived axis), when
   * the host knows it (F7 task 2 — this settles the F9 accepted deferral). A
   * `conflicts` verdict gates Merge → main OFF; `unknown` means "no reconcile
   * verdict yet" and falls back to the client-derived edge (done-unlanded work
   * still offers Merge — the land pipeline stays the conflict truth for
   * never-reconciled branches). Absent ⇒ the client edge alone, as before.
   */
  landAvailability?: LandAvailability;
  /**
   * The server-composed genuine-validation merge gate (props-in-ui task 3):
   * `isMergeAvailableForPhase` off the item's lifecycle phase, threaded from the
   * detail payload (`fix.detail` / the plan route's per-feature projection). When
   * provided it is AUTHORITATIVE for the Merge rung — the reconcile axis
   * (`landAvailability`) no longer drives the offer, so a non-genuine completion
   * (a scoping-fault-only pass) withholds Merge even on a done, reconcile-cleared
   * item. Absent ⇒ the legacy `landAvailability` edge, so an unwired host is
   * unchanged.
   */
  mergeAvailable?: boolean;
  /**
   * The host owns the POSTs — the cap only fires the choice (dumb-UI split).
   * The Merge cap is a chooser (fix merge-cap-lacks-method-and-pr-choice): the
   * chosen land method rides through here (`ff-only` default, `merge` for a
   * `--no-ff` merge commit); the host forwards it to the streamed land.
   */
  onLand: (method: 'ff-only' | 'merge') => void;
  /**
   * Raise a PR instead of landing — the chooser's third action. Optional: a
   * host that has not wired the raise orchestrator (task 2) omits it, and the
   * chooser drops the Raise PR… row rather than offering a dead click.
   */
  onRaise?: () => void;
  onTeardown: (branch: string) => void;
  onResume: (runId: string) => void;
  /**
   * Continue parked work (fix incomplete-item-with-completed-run-cannot-
   * relaunch): started, unfinished, worktree attached, nothing live or
   * resumable. The host posts the item's continue relaunch — the server
   * resolves the run and worktree, so the cap fires no ids.
   */
  onContinue: () => void;
  /**
   * Watch the live run (fix feature-card-live-glyph-and-run-watch-surface task 4):
   * when wired, the live `running` cap becomes a button opening the run stream,
   * with a `click to view` affordance. Omitted in read-only shells, where the cap
   * stays inert.
   */
  onOpenRun?: () => void;
}

/**
 * The rungs the settling gate may hold (task 2 of endcap-resumes-pipeline-
 * runs): exactly the delivery family — every action whose derivation reads
 * the host's provenance facts (`landed`, `deliveredViaFix`, the worktree
 * teardown ladder) or the resumable probe. Host-known rungs stay out so a
 * live run never loses its Running cap to the ellipsis.
 */
/** The running cap's word per live-run kind (reconcile-segment task 3) — a flat
 *  lookup rather than a nested ternary. `worker`/absent read "Running", a live
 *  land "Merging", a live reconcile "Reconciling…". */
const RUNNING_LABEL: Record<'worker' | 'merge' | 'reconcile', string> = {
  worker: 'Running',
  merge: 'Merging',
  reconcile: 'Reconciling…',
};

const SETTLE_GATED_ACTIONS: ReadonlySet<string> = new Set([
  'resume',
  'delivered',
  'teardown',
  'already-merged',
  'merge',
  'continue',
]);

// The mock's `.actcap`: a full-height column cap closing the row — icon over a
// two-line label, tinted per state, split from the lead by its border-left.
// While the host row is EXPANDED (group data-open) the bottom-right corner goes
// square — the body continues below the header, so only the top corner rounds.
//
// `min-h-[4.125rem]` fixes the cap to glyph (h-4) + a TWO-line label + gap-1 +
// py-2 (border-box, so padding is included), so a 1-line label or the settling
// `…` reserves the same height as "Resume / run" and the command row no longer
// judders as the cap resolves from its placeholder to real text.
const capBase =
  'flex min-h-[4.125rem] w-[6.75rem] flex-none flex-col items-center justify-center gap-1 self-stretch whitespace-nowrap rounded-r-2xl border-l px-2 py-2 text-center text-xs font-semibold leading-tight group-data-[open=true]:rounded-br-none';

// Every cap's text sits in this box, which reserves TWO lines (`min-h-[2.5em]` =
// 2 × leading-tight at text-xs) whether the label is one word or two. Pairing it
// with the always-present glyph (a spacer stands in for the settling `…`) is what
// makes every state the same height — the fix for the resolve-time judder.
const capLabel = 'flex min-h-[2.5em] flex-col items-center justify-center leading-tight';

// The blue in-progress cap family's shared skin (Merging… / Launched /
// In progress — the Continue button adds its own cursor + hover on top).
const capBlueSkin =
  'border-[color-mix(in_oklab,var(--color-blue)_26%,var(--color-border))] bg-[color-mix(in_oklab,var(--color-blue)_9%,transparent)] text-blue';

// The review-purple skin for the inert Validating… rung (F4 task 5) — the same
// review accent the ValidationPanel's validating pill wears (--color-primary),
// distinct from the blue in-progress family so validation reads as its own gate.
const capReviewSkin =
  'border-[color-mix(in_oklab,var(--color-primary)_26%,var(--color-border))] bg-[color-mix(in_oklab,var(--color-primary)_9%,transparent)] text-[var(--color-primary)]';

/**
 * The one-action end-cap (detail-action-endcap task 2, extended by F6 task 4 —
 * mock §§01–05): the core fold decides WHICH single state the row offers over
 * the FULL ladder — Resume / delivered / Delete worktree / Already merged /
 * Merge → main, plus the F6 rungs: the INERT blue In-progress cap (started,
 * not live) and the brand-tinted Launch cap hosting the self-gating
 * LaunchControl popover (idle not-started, launchability injected as the
 * `launch` target). This renders that state and fires the host's callback with
 * ids. Self-gating on the resumable-run projection (the same
 * `/launch/resumable` source ResumeControl reads) so Resume wins the cap
 * exactly when there is a run to continue — and never asks while a run is live
 * (nothing is resumable mid-run).
 *
 * The `landAvailability` edge starts as the CLIENT's honest knowledge —
 * `already-landed` when merged, `landable` for done-unlanded work, `unknown`
 * otherwise — and a host that knows the MODELED availability (the F6 model's
 * reconcile-derived axis) passes it in, settling the F9 accepted deferral
 * (adversarial review of 03ca40fa5): a modeled `conflicts` verdict now fires
 * the fold's conflicts-gate, so a conflicted branch never offers an enabled
 * Merge → main. A modeled `unknown` (no reconcile verdict yet) keeps the
 * client edge — the land pipeline stays the conflict truth for
 * never-reconciled branches. No probe happens here.
 */
export function FeatureEndcap({
  repoId,
  item,
  done,
  landed,
  live,
  deliveredViaFix,
  worktree,
  started,
  superseded,
  launched,
  launch,
  mayHaveRun,
  landing,
  settling,
  validating,
  liveRunKind,
  landAvailability,
  mergeAvailable,
  onLand,
  onRaise,
  onTeardown,
  onResume,
  onContinue,
  onOpenRun,
}: FeatureEndcapProps) {
  // Tri-state (task 2 of endcap-resumes-pipeline-runs): `undefined` = the
  // probe has not answered yet, `null` = answered "nothing to resume". The
  // old two-state conflated them, so a done+unlanded item rendered Merge in
  // the probe window and swapped to Resume when the answer arrived — the
  // fix doc's opening symptom. Rows that never probe initialise settled so
  // they never blank.
  const [resumable, setResumable] = useState<{ runId: string } | null | undefined>(() =>
    live || !mayHaveRun ? null : undefined,
  );

  useEffect(() => {
    // A live run is not resumable, and an item that never ran has nothing to
    // continue — both skip the projection entirely (adversarial review of
    // 03ca40fa5: only rows that could plausibly own a run probe).
    if (live || !mayHaveRun) {
      setResumable(null);
      return;
    }
    let cancelled = false;
    setResumable(undefined);
    void fetchResumableRun(repoId, item).then((run) => {
      if (!cancelled) setResumable(run);
    });
    return () => {
      cancelled = true;
    };
  }, [repoId, item, live, mayHaveRun]);

  // A land run in flight overrides the whole fold (after the hooks — the
  // probe effect above must run unconditionally): the model's axes are still
  // settling while the run writes them, so no rung may offer an action.
  if (landing === true) {
    return (
      <span
        data-testid="endcap-merging"
        className={cn(
          capBase,
          capBlueSkin,
        )}
      >
        <GitMerge className="h-4 w-4" aria-hidden="true" />
        <span className={capLabel}>Merging…</span>
      </span>
    );
  }

  const state = deriveEndcapState({
    model: {
      done,
      landed,
      live,
      // The modeled `conflicts` verdict (F7 task 2) is the ONE downgrade the
      // host can inject — the fold's conflicts-gate then fires. A modeled
      // `unknown` (never reconciled) keeps the client edge: done-unlanded work
      // still offers Merge, with the land pipeline as the conflict truth.
      landAvailability:
        landed ? 'already-landed' : landAvailability === 'conflicts' ? 'conflicts' : done ? 'landable' : 'unknown',
    },
    // The genuine-validation merge gate (props-in-ui task 3): when the host threads
    // it from the detail payload it is AUTHORITATIVE for the Merge rung — the
    // reconcile axis above no longer drives the offer. Absent ⇒ that legacy edge.
    ...(mergeAvailable !== undefined ? { mergeAvailable } : {}),
    // A pending probe (undefined) feeds no run — the settling gate below
    // holds the delivery rungs until it answers, so the fold never acts on it.
    latestRun:
      resumable !== null && resumable !== undefined
        ? { runId: resumable.runId, resumable: true }
        : undefined,
    worktree,
    deliveredViaFix,
    // Symmetric fact wiring (review of ed5b8a740): the fold checks `=== true`,
    // so absent and false are identical — both facts assign unconditionally.
    started: started === true,
    superseded: superseded === true,
    launched: launched === true,
    // Presence of a launch target IS the host's launchability fact (F6 task 4).
    launchable: launch !== undefined,
  });

  // The settling gate (task 2 of endcap-resumes-pipeline-runs), NARROW like
  // the Validating rung: it holds only the delivery-family rungs — the ones
  // derived from the pending inputs (host provenance first-load via
  // `settling`, the resumable probe via `resumable === undefined`) — as the
  // inert dim pulsing "…" cap. Host-known rungs (running / launched /
  // superseded / in-progress / launch) owe nothing to those inputs and render
  // straight through; `landing` already returned above. role=status carries
  // the accessible name (a bare span's aria-label is not honoured); the
  // ellipsis itself is decorative.
  if (
    (settling === true || resumable === undefined) &&
    SETTLE_GATED_ACTIONS.has(state.action)
  ) {
    return (
      <span
        data-testid="endcap-settling"
        // role=status names from AUTHOR (aria-label) — contents don't name
        // it, and a generic span's aria-label isn't honoured at all.
        role="status"
        aria-label="Loading item state"
        className={cn(capBase, 'border-border text-subtle motion-safe:animate-pulse')}
      >
        {/* A glyph-sized spacer stands in for the resolved states' icon so the
            placeholder reserves the exact glyph + two-line-label height. */}
        <span aria-hidden="true" className="h-4 w-4" />
        <span aria-hidden="true" className={capLabel}>…</span>
      </span>
    );
  }

  if (state.action === 'resume' && state.runId !== undefined) {
    const runId = state.runId;
    return (
      <button
        type="button"
        data-testid="endcap-resume"
        onClick={(e) => {
          e.stopPropagation();
          onResume(runId);
        }}
        className={cn(
          capBase,
          'cursor-pointer border-[color-mix(in_oklab,#10b981_32%,var(--color-border))] bg-[color-mix(in_oklab,#10b981_11%,transparent)] text-emerald-700 transition hover:brightness-110 dark:text-emerald-300',
        )}
      >
        <RotateCcw className="h-4 w-4" aria-hidden="true" />
        <span className={capLabel}>
          Resume
          <br />
          run
        </span>
      </button>
    );
  }
  if (state.action === 'delivered') {
    return (
      <span data-testid="endcap-delivered" className={cn(capBase, 'border-border text-subtle')}>
        <Check className="h-4 w-4" aria-hidden="true" />
        <span className={capLabel}>delivered</span>
      </span>
    );
  }
  if (state.action === 'teardown' && state.branch !== undefined) {
    const branch = state.branch;
    return (
      <button
        type="button"
        data-testid="endcap-teardown"
        onClick={(e) => {
          e.stopPropagation();
          onTeardown(branch);
        }}
        className={cn(
          capBase,
          'cursor-pointer border-[color-mix(in_oklab,var(--color-warn)_30%,var(--color-border))] bg-[color-mix(in_oklab,var(--color-warn)_9%,transparent)] text-[var(--color-warn)] transition hover:brightness-110',
        )}
      >
        <Trash2 className="h-4 w-4" aria-hidden="true" />
        <span className={capLabel}>
          Delete
          <br />
          worktree
        </span>
      </button>
    );
  }
  if (state.action === 'superseded') {
    // INERT (fix superseded-feature-endcap-and-skeleton-title-nits task 1):
    // retired work is a fact chip, not an action. The accent deliberately
    // reads the raw palette token `--color-orange-500` rather than a semantic
    // cap token: that IS the shared superseded accent every other superseded
    // marker renders (fix fix-strip-status-tag-and-superseded-accent-nits —
    // TaskRow icon, PRD Superseded group dot, dist chips all read it), and
    // the cap matching its markers outranks matching its sibling caps.
    return (
      <span
        data-testid="endcap-superseded"
        className={cn(
          capBase,
          'border-[color-mix(in_oklab,var(--color-orange-500)_26%,var(--color-border))] bg-[color-mix(in_oklab,var(--color-orange-500)_9%,transparent)] text-[var(--color-orange-500)] opacity-80',
        )}
      >
        <Ban className="h-4 w-4" aria-hidden="true" />
        <span className={capLabel}>Superseded</span>
      </span>
    );
  }
  if (state.action === 'already-merged') {
    // The layout-consistent "nothing to do" cap (user call, 2026-07-24): a
    // fully-landed row keeps its greyed end-cap column instead of collapsing.
    return (
      <span data-testid="endcap-already-merged" className={cn(capBase, 'border-border text-subtle opacity-70')}>
        <GitMerge className="h-4 w-4" aria-hidden="true" />
        <span className={capLabel}>
          Already
          <br />
          merged
        </span>
      </span>
    );
  }
  if (state.action === 'continue') {
    // The parked-work relaunch (fix incomplete-item-with-completed-run-cannot-
    // relaunch): blue like the in-progress family — the work IS mid-flight,
    // just unstaffed — but a real button, not the inert cap.
    return (
      <button
        type="button"
        data-testid="endcap-continue"
        onClick={(e) => {
          e.stopPropagation();
          onContinue();
        }}
        className={cn(
          capBase,
          capBlueSkin,
          'cursor-pointer transition hover:brightness-110',
        )}
      >
        <Play className="h-4 w-4" aria-hidden="true" />
        <span className={capLabel}>
          Continue
          <br />
          work
        </span>
      </button>
    );
  }
  if (state.action === 'running') {
    // INERT (control-strip-mute-during-live-run task 2): a run is executing NOW
    // past the launched window. No terminal action mid-run, but the blue
    // in-progress cap family's cap keeps the column MOUNTED — where the fold's
    // old `none` unmounted it and the strip went mute a commit after the
    // launched window showed its blue cap. The spinner (not a static glyph)
    // reads as live; the strip's inline activity panel carries the detail.
    //
    // The label follows the live run's KIND (fix land-surface-single-strip-and-
    // legible-phases task 3; reconcile-segment task 3): a live land reads
    // "Merging", a live reconcile "Reconciling…" — "Running" collides with a
    // worker executing tasks and misreads as "still being worked". A worker run,
    // or an unspecified kind, reads "Running". Both delivery kinds are `merge`-
    // like for the click-to-view gate below (the worker stream is the only thing
    // that affordance watches). Same inert blue cap and spinner either way.
    const isDelivery = liveRunKind === 'merge' || liveRunKind === 'reconcile';
    const label = RUNNING_LABEL[liveRunKind ?? 'worker'];
    const spinner = <Loader2 className="h-4 w-4 motion-safe:animate-spin" aria-hidden="true" />;
    // Click-to-view (fix feature-card-live-glyph-and-run-watch-surface task 4):
    // when a watch handler is wired the live cap opens the run stream — the cap's
    // watch-live home now the row pulls it off the header — with an explicit
    // `click to view` sub-label. Worker runs ONLY: a land/reconcile delivery run
    // is not the worker stream this affordance watches, so it stays inert. Inert
    // span otherwise too (read-only shells).
    if (onOpenRun !== undefined && !isDelivery) {
      return (
        <button
          type="button"
          data-testid="endcap-running"
          aria-label={`${label} — click to view the run`}
          onClick={(e) => {
            e.stopPropagation();
            onOpenRun();
          }}
          className={cn(capBase, capBlueSkin, 'cursor-pointer transition hover:brightness-110')}
        >
          {spinner}
          <span className={capLabel}>
            {label}
            <br />
            <span className="text-[10px] font-normal opacity-80">click to view</span>
          </span>
        </button>
      );
    }
    return (
      <span
        data-testid="endcap-running"
        className={cn(
          capBase,
          capBlueSkin,
        )}
      >
        {spinner}
        <span className={capLabel}>{label}</span>
      </span>
    );
  }
  if (state.action === 'launched') {
    // INERT (fix launched-state-for-dispatched-runs task 2): the dispatch→
    // first-commit window as a fact — worker assigned, nothing landed. The
    // in-progress cap family's blue, so the column reads consistently while
    // the strip's rail carries the worker/env identity.
    return (
      <span
        data-testid="endcap-launched"
        className={cn(
          capBase,
          capBlueSkin,
        )}
      >
        <PlaneTakeoff className="h-4 w-4" aria-hidden="true" />
        <span className={capLabel}>Launched</span>
      </span>
    );
  }
  if (state.action === 'in-progress') {
    // INERT (F6 task 4, mock .ac-inprog): a fact, not an action — blue wash,
    // no cursor, keeps the cap column consistent across states.
    return (
      <span
        data-testid="endcap-in-progress"
        className={cn(
          capBase,
          capBlueSkin,
        )}
      >
        <Play className="h-4 w-4" aria-hidden="true" />
        <span className={capLabel}>
          In
          <br />
          progress
        </span>
      </span>
    );
  }
  if (state.action === 'launch' && launch !== undefined) {
    // The cap hosts the existing self-gating LaunchControl popover (F6 task 4,
    // mock .ac-launch — the brand-tinted primary CTA). The cap rounds its own
    // right edge and clips nothing, so the popover drops freely.
    return (
      <div
        data-testid="endcap-launch"
        className={cn(
          capBase,
          'border-[color-mix(in_oklab,var(--ds-primary,#8b7cf6)_36%,var(--color-border))] bg-[color-mix(in_oklab,var(--ds-primary,#8b7cf6)_13%,transparent)]',
        )}
      >
        {/* No attention passthrough: a launchable scope is idle by definition
            (no run), so there is never a failed-run pill to surface here. The
            cap variant carries the whole cap form — plain cap-text trigger
            (the cap owns the tint) and the vertical dispatched/error renders
            (fix launched-state-for-dispatched-runs task 5). */}
        <LaunchControl repoId={launch.repoId} item={launch.item} variant="cap" />
      </div>
    );
  }
  if (state.action === 'merge') {
    // The validation gate (F4 task 5): while the pre-merge validation suite is
    // live, the Merge chooser is replaced by an inert Validating… rung — the
    // cap answers "why can't I land yet", and no land can be dispatched over a
    // live validation. It yields to the chooser the moment the fact clears.
    // (The later-stage `landing` already returned Merging… above.)
    if (validating === true) {
      return (
        <span data-testid="endcap-validating" className={cn(capBase, capReviewSkin)}>
          <Loader2 className="h-4 w-4 motion-safe:animate-spin" aria-hidden="true" />
          <span className={capLabel}>Validating…</span>
        </span>
      );
    }
    return <MergeChooser onLand={onLand} onRaise={onRaise} />;
  }
  return null;
}

/**
 * The Merge → main delivery chooser (fix merge-cap-lacks-method-and-pr-choice
 * task 1) — the LaunchControl popover pattern applied to the merge cap. Clicking
 * the cap opens Fast-forward (default, visually first) / Merge commit / Raise
 * PR…; the two land choices fire `onLand(method)`, Raise PR… fires `onRaise`.
 * Escape or focus leaving the cap closes the popover with nothing posted. The
 * cap only fires the choice — the host owns every POST (dumb-UI split).
 */
function MergeChooser({
  onLand,
  onRaise,
}: {
  onLand: (method: 'ff-only' | 'merge') => void;
  onRaise?: () => void;
}) {
  const [open, setOpen] = useState(false);
  const rootRef = useRef<HTMLDivElement>(null);

  // Dismiss on a click anywhere outside the cap (adversarial review of
  // 901c15d14, LOW): a plain `onBlur` only fired when focus moved to another
  // focusable element, so a click on empty page chrome left the popover open. A
  // document mousedown listener closes on ANY outside press. `instanceof Node`
  // narrows the untyped event target (no unsound cast — CLAUDE.md forbids it).
  useEffect(() => {
    if (!open) return;
    const onDocMouseDown = (e: MouseEvent) => {
      if (rootRef.current && e.target instanceof Node && !rootRef.current.contains(e.target)) {
        setOpen(false);
      }
    };
    document.addEventListener('mousedown', onDocMouseDown);
    return () => document.removeEventListener('mousedown', onDocMouseDown);
  }, [open]);

  // Every choice closes the popover before firing — the cap's own re-render
  // (the streamed land pulls the merge rung) then unmounts it entirely.
  const pick = (fire: () => void) => {
    setOpen(false);
    fire();
  };

  return (
    // The cap lives inside hosts that are themselves clickable (the PRD feature
    // row toggles on click), so every interaction stops here. Escape closes; a
    // press outside the cap closes (the effect above) — neither posts. A plain
    // disclosure (aria-expanded), NOT an ARIA menu: the review flagged that
    // menu/menuitem roles promise an arrow-key roving-focus model this popover
    // does not implement, so the honest contract is a disclosure of buttons.
    <div
      ref={rootRef}
      data-testid="endcap-merge-chooser"
      onClick={(e) => e.stopPropagation()}
      onKeyDown={(e) => {
        if (e.key === 'Escape') setOpen(false);
      }}
      className={cn(
        capBase,
        // Background-tint hover, NEVER a filter (fix merge-chooser-clipped-by-
        // expanded-feature-row task 2): hover:brightness-110 promoted this
        // popover-containing cap into a stacking context on hover, flickering
        // the open menu behind neighbouring surfaces.
        'relative cursor-pointer border-[color-mix(in_oklab,var(--color-done)_32%,var(--color-border))] bg-[color-mix(in_oklab,var(--color-done)_11%,transparent)] text-done transition hover:bg-[color-mix(in_oklab,var(--color-done)_18%,transparent)]',
      )}
    >
      <button
        type="button"
        data-testid="endcap-merge"
        aria-expanded={open}
        onClick={(e) => {
          e.stopPropagation();
          setOpen((v) => !v);
        }}
        className="flex flex-col items-center gap-1 text-done"
      >
        <GitMerge className="h-4 w-4" aria-hidden="true" />
        <span className={capLabel}>
          Merge to
          <br />
          Main
        </span>
      </button>
      {open && (
        <div
          aria-label="Deliver to main"
          data-testid="endcap-merge-menu"
          // The CONTRAST surface (opaque bg-background + strong border), the
          // same skin LaunchControl's popover uses — the cap rounds its own
          // right edge and clips nothing, so this drops freely below it.
          className="absolute right-0 top-full z-50 mt-1 w-64 rounded-xl border border-[var(--ds-border-strong)] bg-background p-1.5 text-left shadow-xl"
        >
          <ChooserAction
            testId="endcap-merge-ff"
            icon={<GitMerge className="h-4 w-4 shrink-0 text-done" />}
            title="Fast-forward"
            detail="Land as a clean fast-forward"
            onClick={() => pick(() => onLand('ff-only'))}
          />
          <ChooserAction
            testId="endcap-merge-commit"
            icon={<GitMerge className="h-4 w-4 shrink-0 text-muted-foreground" />}
            title="Merge commit"
            detail="Land with a --no-ff merge commit"
            onClick={() => pick(() => onLand('merge'))}
          />
          {onRaise !== undefined && (
            <ChooserAction
              testId="endcap-merge-raise"
              icon={<GitPullRequestArrow className="h-4 w-4 shrink-0 text-muted-foreground" />}
              title="Raise PR…"
              detail="Open a pull request instead"
              onClick={() => pick(onRaise)}
            />
          )}
        </div>
      )}
    </div>
  );
}

/** One row of the merge chooser — leading glyph, title over a muted detail line. */
function ChooserAction({
  testId,
  icon,
  title,
  detail,
  onClick,
}: {
  testId: string;
  icon: ReactNode;
  title: string;
  detail: string;
  onClick: () => void;
}) {
  return (
    <button
      type="button"
      data-testid={testId}
      onClick={(e) => {
        e.stopPropagation();
        onClick();
      }}
      className="flex w-full items-center gap-2.5 rounded-lg px-2 py-1.5 text-left transition-colors hover:bg-[color-mix(in_oklab,var(--color-done)_14%,transparent)]"
    >
      {icon}
      <span className="min-w-0 flex-1">
        <span className="block truncate text-sm font-semibold leading-tight text-foreground">{title}</span>
        <span className="block truncate text-[11px] text-muted-foreground">{detail}</span>
      </span>
    </button>
  );
}

export default FeatureEndcap;
