import { GitMerge, GitPullRequest, PlaneLanding } from 'lucide-react';
import type { LandRecord } from '@magic-ingredients/tiny-brain-core';
import { formatRelativeTime } from '@/utils/relative-time';

/**
 * The land-history surface (land-dashboard task 2; per-item since
 * work-item-provenance F4 task 4). Renders the append-only, event-sourced
 * record of what landed (item · strategy · when · link), newest-first as the
 * server projects it into the item's provenance payload. Dumb + presentational:
 * it only formats. Renders nothing when the item has no landing — every
 * consumer surfaces it inside a detail view where an empty-state block would
 * be noise.
 */
export interface LandHistoryPanelProps {
  history: readonly LandRecord[];
}

// The board's noun for a PRD is `plan` (matching BoardCard's kind pill); a land
// record attributes a landed feature to its parent PRD, so `prd` is all we show.
// `spike`/`task` are here only to keep this Record total over WorkRef's kind
// union — the read guard admits fix/prd/spike and emission produces only fix/prd
// today, so `task` is unreachable in practice (type-totality, not a real column).
const KIND_LABEL: Record<LandRecord['workRef']['kind'], string> = {
  fix: 'fix',
  prd: 'plan',
  spike: 'spike',
  task: 'task',
};

/** Only ever build an href for an http(s) URL — defence-in-depth beside the read
 *  guard (isValidLink), so even a hand-fed record can't inject a `javascript:` href. */
function isHttpUrl(value: string): boolean {
  try {
    const { protocol } = new URL(value);
    return protocol === 'http:' || protocol === 'https:';
  } catch {
    return false;
  }
}

const STRATEGY: Record<LandRecord['strategy'], { label: string; icon: typeof PlaneLanding }> = {
  ff: { label: 'fast-forward', icon: PlaneLanding },
  merge: { label: 'merge commit', icon: GitMerge },
  pr: { label: 'PR', icon: GitPullRequest },
};

/** The link cell: a short merge-commit sha, or a PR link, or nothing. */
function LandLinkCell({ record }: { record: LandRecord }) {
  const link = record.link;
  if (link?.prUrl && isHttpUrl(link.prUrl)) {
    return (
      <a
        href={link.prUrl}
        target="_blank"
        rel="noreferrer"
        className="mono text-[11px] text-blue-500 hover:underline"
      >
        PR ↗
      </a>
    );
  }
  if (link?.mergeCommit) {
    return <code className="mono text-[11px] text-muted-foreground">{link.mergeCommit.slice(0, 9)}</code>;
  }
  return null;
}

export function LandHistoryPanel({ history }: LandHistoryPanelProps) {
  if (history.length === 0) return null;
  return (
    <section data-testid="land-history" aria-label="Land history" className="flex flex-col gap-2">
      <h3 className="eyebrow" style={{ color: 'var(--color-done)' }}>
        Landed
      </h3>

      <ul className="flex flex-col gap-1">
        {history.map((record, i) => {
          const strategy = STRATEGY[record.strategy];
          const StrategyIcon = strategy.icon;
          const when = formatRelativeTime(record.ts);
          return (
            <li
              // The log has no per-entry id yet, and the append-only design
              // PRODUCES same-(kind,id,ts) rows (a same-instant revert+re-land),
              // so the (kind,id,ts) tuple alone can collide — the index makes the
              // key unique within the stable, newest-first server order. (The
              // list is replaced wholesale on refetch, so an index that shifts on
              // a prepend only costs a re-render, never a wrong-row identity.)
              key={`${record.workRef.kind}:${record.workRef.id}:${record.ts}:${i}`}
              data-testid="land-history-entry"
              className="flex items-center gap-2 rounded-lg border border-border px-2.5 py-1.5 text-xs"
            >
              <span className="tb-pill tb-pill--kind shrink-0">{KIND_LABEL[record.workRef.kind]}</span>
              <span className="min-w-0 flex-1 truncate font-medium text-foreground">{record.workRef.id}</span>
              <span className="inline-flex shrink-0 items-center gap-1 text-muted-foreground" style={{ color: 'var(--color-done)' }}>
                <StrategyIcon className="h-3.5 w-3.5" />
                {strategy.label}
              </span>
              <LandLinkCell record={record} />
              {when && <span className="shrink-0 text-muted-foreground">{when}</span>}
            </li>
          );
        })}
      </ul>
    </section>
  );
}

export default LandHistoryPanel;
