import { useEffect, useMemo, useState } from 'react';
import clsx from 'clsx';
import { Sparkles, Trash2, RotateCcw, Check, X, CheckCheck, Folder, GitBranch, Bot, ShieldCheck } from 'lucide-react';
import { useRunStream } from '@/hooks/useRunStream';

/**
 * CleanupCommand (done-lane-cleanup task 8; mock:
 * docs/prd/work-board/assets/cleanup-command.html) — the ONE control for
 * cleaning up a delivered item's leftovers. Split as container + pure view so
 * Storybook renders every state over fixtures (no fetch, no SSE):
 *
 *  1. ready   — the manifest: worktree (path + size), branch (+ unmerged
 *               note), run records; one Clean up button.
 *  2. running — the teardown run's pipeline phases as a live step list.
 *  3. error   — a failed exit: the failed step goes red, later steps read
 *               skipped, the cause renders in place with Retry. Never a force
 *               (the server's no-force gate is the refusal source).
 *  4. done    — the cleaned-up receipt.
 *
 * Copy says "cleaned up", never "reaped" (user call, 2026-07-26). Hosts swap
 * this in FOR the command row when the item is in cleanup state — delivery
 * proven, artifacts on disk — so it replaces, never stacks.
 */

export interface CleanupManifest {
  readonly branch: string;
  readonly unmergedCount?: number;
  /** WHAT is not on main (fix cleanup-unmerged-commits-need-informed-approval):
   * the judgement behind an informed discard. Mirrors the wire type. */
  readonly unmergedCommits?: readonly { readonly sha: string; readonly subject: string }[];
  readonly worktree: { readonly path: string; readonly sizeBytes?: number };
  readonly runs: readonly { readonly runId: string; readonly status: string }[];
}

/** The teardown run's part phases, in reclamation order (core teardown.ts). */
const PART_STEPS = [
  { phase: 'worktree-remove', label: 'remove worktree' },
  { phase: 'branch-delete', label: 'delete branch' },
  { phase: 'record-delete', label: 'close run records' },
] as const;

/** The view's one discriminated state — what the container derives and stories fixture. */
export type CleanupViewState =
  | { mode: 'loading' }
  | { mode: 'unavailable' }
  | { mode: 'ready'; manifest: CleanupManifest }
  | { mode: 'running'; completedPhases: readonly string[] }
  | { mode: 'error'; completedPhases: readonly string[]; reason: string }
  | { mode: 'done'; sizeBytes?: number };

const mb = (bytes: number): string => `${Math.round(bytes / 1_000_000)} MB`;

/** The last path segments after `.claude/worktrees/` — the manifest's short worktree name. */
function worktreeLeaf(path: string): string {
  const marker = '/.claude/worktrees/';
  const idx = path.lastIndexOf(marker);
  return idx >= 0 ? path.slice(idx + marker.length) : path;
}

export interface CleanupCommandProps {
  repoId: string;
  /** The delivery work-item id the manifest + teardown are keyed by (e.g. `fix:my-fix`). */
  workItemId: string;
}

/** The manifest read's own lifecycle — the frame renders through ALL of it
 * (fix cleanup-command-invisible-while-manifest-loads): the GET can take tens
 * of seconds (the server walks the worktree for its size), and the swap has
 * already removed the command row, so a null render reads as "no control". */
type ManifestRead =
  | { kind: 'loading' }
  | { kind: 'unavailable' }
  | { kind: 'ready'; manifest: CleanupManifest };

/** The data container: manifest GET → teardown POST → run stream → view state. */
export function CleanupCommand({ repoId, workItemId }: CleanupCommandProps) {
  const [read, setRead] = useState<ManifestRead>({ kind: 'loading' });
  const [readTick, setReadTick] = useState(0);
  const [runId, setRunId] = useState<string | null>(null);
  const [postError, setPostError] = useState<string | null>(null);

  useEffect(() => {
    let cancelled = false;
    setRead({ kind: 'loading' });
    void fetch(`/api/repos/${repoId}/delivery/cleanup-manifest/${encodeURIComponent(workItemId)}`)
      .then(async (res): Promise<ManifestRead> => {
        if (!res.ok) return { kind: 'unavailable' };
        return { kind: 'ready', manifest: (await res.json()) as CleanupManifest };
      })
      .catch((): ManifestRead => ({ kind: 'unavailable' }))
      .then((next) => {
        if (!cancelled) setRead(next);
      });
    return () => {
      cancelled = true;
    };
  }, [repoId, workItemId, readTick]);
  const manifest = read.kind === 'ready' ? read.manifest : null;

  const { events } = useRunStream(repoId, runId ?? '');
  const completedPhases = useMemo(
    () =>
      events
        .filter((e): e is typeof e & { phase: string } => e.type === 'pipeline' && 'phase' in e)
        .map((e) => (e as { phase: string }).phase),
    [events],
  );
  const exit = events.find((e) => e.type === 'exit') as
    | { type: 'exit'; status: 'completed' | 'failed'; reason?: string }
    | undefined;

  const cleanUp = () => {
    setPostError(null);
    void fetch(`/api/repos/${repoId}/delivery/teardown`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        workItemId,
        worktree: true,
        branch: true,
        ...(manifest !== null && manifest.runs.length > 0 ? { runIds: manifest.runs.map((r) => r.runId) } : {}),
      }),
    })
      .then(async (res) => {
        if (!res.ok) throw new Error(`teardown failed (HTTP ${res.status})`);
        const body = (await res.json()) as { runId?: string };
        if (body.runId) setRunId(body.runId);
      })
      .catch((err: unknown) => setPostError(err instanceof Error ? err.message : 'cleanup failed to start'));
  };

  const state: CleanupViewState =
    exit?.status === 'completed'
      ? { mode: 'done', ...(manifest?.worktree.sizeBytes !== undefined ? { sizeBytes: manifest.worktree.sizeBytes } : {}) }
      : exit?.status === 'failed' || postError !== null
        ? { mode: 'error', completedPhases, reason: exit?.reason ?? postError ?? 'cleanup failed' }
        : runId !== null
          ? { mode: 'running', completedPhases }
          : manifest !== null
            ? { mode: 'ready', manifest }
            : read.kind === 'unavailable'
              ? { mode: 'unavailable' }
              : { mode: 'loading' };

  return <CleanupCommandView state={state} onCleanUp={cleanUp} onRetryLoad={() => setReadTick((t) => t + 1)} />;
}

/** The pure view — every state renderable from props alone (Storybook's entry). */
export function CleanupCommandView({
  state,
  onCleanUp,
  onRetryLoad,
}: {
  state: CleanupViewState;
  onCleanUp?: () => void;
  /** Re-fire the manifest GET after an unavailable read (container-wired). */
  onRetryLoad?: () => void;
}) {
  // Informed-approval gate (fix cleanup-unmerged-commits-need-informed-
  // approval): while commits are not on main, Clean up stays inert until the
  // user explicitly acknowledges the listed commits can go.
  const [acked, setAcked] = useState(false);
  // The acknowledgement is a judgement about ONE commit set (adversarial
  // review of a1419098b, MEDIUM): any change to the ready manifest's identity
  // — branch, listed shas, or count — voids it, so a re-fetched or swapped
  // manifest can never render pre-armed for commits the user never saw.
  const ackKey =
    state.mode === 'ready'
      ? [
          state.manifest.branch,
          (state.manifest.unmergedCommits ?? []).map((c) => c.sha).join(','),
          state.manifest.unmergedCount ?? '',
        ].join('|')
      : null;
  useEffect(() => {
    setAcked(false);
  }, [ackKey]);
  switch (state.mode) {
    case 'loading':
      // The frame is present from the FIRST paint — the manifest read can take
      // tens of seconds, and this slot has already replaced the command row.
      return (
        <Frame tone="warn">
          <Head tone="warn" title="Cleanup" sub="reading what's left on disk…" />
          <ul data-testid="cleanup-loading" className="mt-3 flex flex-col gap-1.5" aria-hidden="true">
            {[0, 1, 2].map((i) => (
              <li
                key={i}
                className="h-9 animate-pulse rounded-xl border border-border/60 bg-background/40"
              />
            ))}
          </ul>
        </Frame>
      );
    case 'unavailable':
      return (
        <Frame tone="warn">
          {/* Region-named testid on the STATE, not the button (adversarial
              review of 0cf4741e8) — matching cleanup-loading / cleanup-step-*. */}
          <div data-testid="cleanup-unavailable">
            <Head
              tone="warn"
              title="Cleanup"
              sub="couldn't read what's left on disk"
              action={
                <button
                  type="button"
                  onClick={onRetryLoad}
                  className="inline-flex items-center gap-1.5 rounded-lg bg-warn/15 px-3 py-1.5 text-xs font-semibold text-warn"
                >
                  <RotateCcw className="h-3.5 w-3.5" /> Retry
                </button>
              }
            />
          </div>
        </Frame>
      );
    case 'done':
      return (
        <Frame tone="done">
          <Head
            tone="done"
            title="Cleaned up"
            sub={`worktree + branch + run records cleaned up${state.sizeBytes !== undefined ? ` · ${mb(state.sizeBytes)} reclaimed` : ''}`}
          />
        </Frame>
      );
    case 'error': {
      const failedIdx = PART_STEPS.filter((s) => state.completedPhases.includes(s.phase)).length;
      return (
        <Frame tone="red">
          <Head
            tone="warn"
            title="Cleanup stopped"
            sub="a step failed · nothing was forced"
            action={
              <button
                type="button"
                onClick={onCleanUp}
                className="inline-flex items-center gap-1.5 rounded-lg bg-warn/15 px-3 py-1.5 text-xs font-semibold text-warn"
              >
                <RotateCcw className="h-3.5 w-3.5" /> Retry
              </button>
            }
          />
          <ul className="mt-3 flex flex-col gap-1 text-xs">
            {PART_STEPS.map((s, i) => (
              <li key={s.phase} data-testid={`cleanup-step-${s.phase}`} className="flex items-center gap-2.5">
                <StepDot state={i < failedIdx ? 'done' : i === failedIdx ? 'err' : 'pending'} />
                <span className={clsx(i > failedIdx && 'text-subtle')}>{s.label}</span>
                {i > failedIdx && <span className="mono ml-auto text-[10.5px] text-subtle">skipped</span>}
              </li>
            ))}
          </ul>
          <div className="mt-3 rounded-xl border border-destructive/35 bg-destructive/10 px-3 py-2.5 text-xs">
            <b className="font-semibold text-destructive">{state.reason}</b>
            <span className="mt-1 block text-subtle">
              Cleanup never discards content it cannot prove is on main. Resolve the cause, then retry.
            </span>
          </div>
        </Frame>
      );
    }
    case 'running': {
      const liveIdx = PART_STEPS.findIndex((s) => !state.completedPhases.includes(s.phase));
      const stepNo = Math.min(liveIdx < 0 ? PART_STEPS.length : liveIdx + 1, PART_STEPS.length);
      return (
        <Frame tone="warn">
          <Head tone="warn" title="Cleaning up…" sub={`step ${stepNo} of ${PART_STEPS.length}`} />
          <ul className="mt-3 flex flex-col gap-1 text-xs">
            {PART_STEPS.map((s, i) => (
              <li key={s.phase} data-testid={`cleanup-step-${s.phase}`} className="flex items-center gap-2.5">
                <StepDot state={state.completedPhases.includes(s.phase) ? 'done' : i === liveIdx ? 'live' : 'pending'} />
                <span className={clsx(!state.completedPhases.includes(s.phase) && i !== liveIdx && 'text-subtle')}>
                  {s.label}
                </span>
              </li>
            ))}
          </ul>
        </Frame>
      );
    }
    case 'ready': {
      const { manifest } = state;
      const unmergedCommits = manifest.unmergedCommits ?? [];
      // The count and the list gate SYMMETRICALLY (review of a1419098b, LOW):
      // a degraded manifest (count without the list) and a contradictory one
      // (zero count beside a non-empty list) both take the larger signal —
      // neither absence nor contradiction is licence for an uninformed discard.
      const unmergedCount = Math.max(manifest.unmergedCount ?? 0, unmergedCommits.length);
      const needsApproval = unmergedCount > 0;
      return (
        <Frame tone="warn">
          <Head
            tone="warn"
            title="Cleanup"
            sub="work is on main · these leftovers can be cleaned up"
            action={
              <button
                type="button"
                onClick={onCleanUp}
                disabled={needsApproval && !acked}
                className="inline-flex items-center gap-1.5 rounded-lg bg-warn px-3.5 py-1.5 text-xs font-semibold text-background disabled:cursor-not-allowed disabled:opacity-45"
              >
                <Trash2 className="h-3.5 w-3.5" /> Clean up
              </button>
            }
          />
          <ul className="mt-3 flex flex-col gap-1.5">
            <ManifestItem
              icon={<Folder className="h-3.5 w-3.5" />}
              what="worktree"
              refText={worktreeLeaf(manifest.worktree.path)}
              // Reclaimable, not reclaimed (user call, 2026-07-26): the ready
              // manifest PROMISES the space — only the §04 receipt has it back.
              note={manifest.worktree.sizeBytes !== undefined ? `${mb(manifest.worktree.sizeBytes)} reclaimable` : undefined}
            />
            <ManifestItem
              icon={<GitBranch className="h-3.5 w-3.5" />}
              what="branch"
              refText={manifest.branch}
              note={manifest.unmergedCount !== undefined ? `${manifest.unmergedCount} commits not on main` : undefined}
              noteTone={manifest.unmergedCount === 0 ? 'ok' : undefined}
            />
            {manifest.runs.map((r) => (
              <ManifestItem
                key={r.runId}
                icon={<Bot className="h-3.5 w-3.5" />}
                what="run record"
                refText={r.runId}
                note={`${r.status} · closes`}
              />
            ))}
          </ul>
          {needsApproval ? (
            // The shield line would be FALSE here. In its place: the commits a
            // cleanup would discard, and the explicit acknowledgement that
            // arms the button (fix cleanup-unmerged-commits-need-informed-
            // approval task 2).
            <div
              data-testid="cleanup-unmerged-warning"
              className="mt-2.5 rounded-xl border border-warn/35 bg-warn/10 px-3 py-2.5 text-xs"
            >
              <b className="font-semibold text-warn">
                {unmergedCount} {unmergedCount === 1 ? 'commit is' : 'commits are'} not on main — cleaning up will
                discard {unmergedCount === 1 ? 'it' : 'them'}
              </b>
              {unmergedCommits.length > 0 && (
                <ul className="mt-2 flex flex-col gap-1">
                  {unmergedCommits.map((c) => (
                    <li key={c.sha} className="flex min-w-0 items-baseline gap-2">
                      <span className="mono flex-none text-[10.5px] text-subtle">{c.sha.slice(0, 7)}</span>
                      <span className="mono min-w-0 truncate text-[11px]">{c.subject}</span>
                    </li>
                  ))}
                </ul>
              )}
              <label className="mt-2.5 flex cursor-pointer items-center gap-2 text-[11.5px] text-muted-foreground">
                <input
                  type="checkbox"
                  checked={acked}
                  onChange={(e) => setAcked(e.target.checked)}
                  className="h-3.5 w-3.5 accent-[var(--color-warn)]"
                />
                these commits can be discarded
              </label>
            </div>
          ) : (
            <div className="mt-2.5 flex items-center gap-2 text-[11px] text-subtle">
              <ShieldCheck className="h-3 w-3 text-[color:var(--color-done)]" />
              content verified on main — nothing in this list holds unmerged work
            </div>
          )}
        </Frame>
      );
    }
  }
}

function Frame({ tone, children }: { tone: 'warn' | 'red' | 'done'; children: React.ReactNode }) {
  return (
    <section
      data-testid="cleanup-command"
      className={clsx(
        'rounded-2xl border p-4',
        tone === 'warn' && 'border-warn/30 bg-warn/5',
        tone === 'red' && 'border-destructive/40 bg-destructive/5',
        tone === 'done' && 'border-[color:var(--color-done)]/30 bg-[color:var(--color-done)]/5',
      )}
    >
      {children}
    </section>
  );
}

function Head({
  tone,
  title,
  sub,
  action,
}: {
  tone: 'warn' | 'done';
  title: string;
  sub: string;
  action?: React.ReactNode;
}) {
  return (
    <div className="flex items-center gap-2.5">
      <span
        className={clsx(
          'grid h-8 w-8 flex-none place-items-center rounded-xl',
          tone === 'warn' ? 'bg-warn/15 text-warn' : 'bg-[color:var(--color-done)]/15 text-[color:var(--color-done)]',
        )}
      >
        {tone === 'done' ? <CheckCheck className="h-4 w-4" /> : <Sparkles className="h-4 w-4" />}
      </span>
      <span className="flex min-w-0 flex-col">
        <b className="font-display text-[13.5px] leading-tight tracking-tight">{title}</b>
        <span className="text-[11.5px] text-subtle">{sub}</span>
      </span>
      <span className="ml-auto" />
      {action}
    </div>
  );
}

function StepDot({ state }: { state: 'done' | 'live' | 'err' | 'pending' }) {
  return (
    <span
      className={clsx(
        'grid h-4 w-4 flex-none place-items-center rounded-full border',
        state === 'done' && 'border-[color:var(--color-done)] bg-[color:var(--color-done)]/15 text-[color:var(--color-done)]',
        state === 'live' && 'border-warn text-warn',
        state === 'err' && 'border-destructive bg-destructive/15 text-destructive',
        state === 'pending' && 'border-border text-transparent',
      )}
    >
      {state === 'done' && <Check className="h-2.5 w-2.5" />}
      {state === 'err' && <X className="h-2.5 w-2.5" />}
      {state === 'live' && <span className="h-1.5 w-1.5 animate-pulse rounded-full bg-warn" />}
    </span>
  );
}

function ManifestItem({
  icon,
  what,
  refText,
  note,
  noteTone,
}: {
  icon: React.ReactNode;
  what: string;
  refText: string;
  note?: string;
  noteTone?: 'ok';
}) {
  return (
    <li className="flex items-center gap-2.5 rounded-xl border border-border/60 bg-background/40 px-3 py-2 text-xs">
      <span className="flex-none text-subtle">{icon}</span>
      <span className="w-20 flex-none text-muted-foreground">{what}</span>
      <span className="mono min-w-0 truncate text-[11.5px]">{refText}</span>
      {note !== undefined && (
        <span
          className={clsx(
            'mono ml-auto flex-none text-[10.5px]',
            noteTone === 'ok' ? 'text-[color:var(--color-done)]' : 'text-subtle',
          )}
        >
          {note}
        </span>
      )}
    </li>
  );
}

export default CleanupCommand;
