import React from 'react';
import { cn } from '@/lib/utils';
import { GradientProgress } from './ui/GradientProgress';

export interface SidebarCardProps {
  /** data-testid for the card root (e.g. `plan-card`, `fix-card`). */
  testId: string;
  /**
   * Free-form status bucket exposed as `data-status` — a test / inspection hook,
   * not a style driver (the surface tint comes from the `.plan-card-*` classes,
   * not this attribute). Left as `string` on purpose: the plan/fix/spike cards
   * speak `StatusVariant` while worktree cards speak `WorktreeListStatus`, so no
   * single union fits a genuinely shared shell.
   */
  status: string;
  /** Whether this card is the selected row — sets `data-selected` and the accent. */
  isSelected?: boolean;
  /**
   * How a selected card is surfaced. `accent` (default) is the blue inset stripe
   * the sidebar lists use; `plain` is a solid card-white background + ring, used
   * on the board where a card sits on a tinted lane and a filled surface reads as
   * "selected" better than a stripe.
   */
  selectedSurface?: 'accent' | 'plain';
  /** Dims the card (archived items). */
  isArchived?: boolean;
  /** Emphasise the title (font-semibold) — in-progress or selected items. */
  emphasized?: boolean;
  /** Select the row. Fires on click and on Enter / Space. */
  onClick?: () => void;

  /** Row 1 leading slot — a glyph before the title (e.g. a worktree's content
   *  kind), so the title spans the remaining width. */
  titleLeading?: React.ReactNode;
  /** Row 1: the card title. Capped at two rows. */
  title: React.ReactNode;
  /** Row 1 trailing slot — an archive marker beside the title. */
  titleAside?: React.ReactNode;
  /** Row 2 left: the status pill(s). */
  pills: React.ReactNode;
  /** Row 2 right: the MiniStatusRail (or any at-a-glance status). */
  rail?: React.ReactNode;
  /** Row 3: gradient progress bar. Omit / `null` ⇒ no bar. */
  progress?: number | null;
  /** Row 4 left: count + percent readout. */
  metaLeft?: React.ReactNode;
  /** Row 4 right: relative time offset. */
  metaRight?: React.ReactNode;
}

/**
 * The shared sidebar-card shell every work-item card (plan / fix / spike /
 * worktree) is laid out on, so the four never drift:
 *
 *   title                                    (titleAside)
 *   [status pill · extra pills]        ‹MiniStatusRail›
 *   ▓▓▓▓▓▓▓▓░░░░░░░░  progress bar
 *   count · % complete                        time offset
 *
 * It owns the surface skin, the clickable / keyboard a11y, and the four-row
 * grid; each card computes its own status, progress, and branches and drops the
 * nodes into the slots. Presentational — it never fetches or derives.
 */
export const SidebarCard: React.FC<SidebarCardProps> = ({
  testId,
  status,
  isSelected = false,
  selectedSurface = 'accent',
  isArchived = false,
  emphasized = false,
  onClick,
  titleLeading,
  title,
  titleAside,
  pills,
  rail,
  progress,
  metaLeft,
  metaRight,
}) => {
  const showProgress = progress !== null && progress !== undefined;
  const showMeta = metaLeft !== undefined || metaRight !== undefined;
  // Only a card wired to select something is a button — a handler-less card must
  // not be a focusable, pointer-cursored no-op (review finding).
  const interactive = onClick !== undefined;
  return (
    <div
      data-testid={testId}
      data-status={status}
      data-selected={isSelected}
      {...(interactive
        ? {
            role: 'button',
            tabIndex: 0,
            onClick,
            onKeyDown: (e: React.KeyboardEvent) => {
              if (e.key === 'Enter' || e.key === ' ') {
                e.preventDefault();
                onClick();
              }
            },
          }
        : {})}
      className={cn(
        // `.plan-card-surface` / `.plan-card-accent` are the shared LIST-CARD
        // surface classes (globals.css: "all list cards — plans, fixes, spikes"),
        // legacy-named for the plan card they were first written for. Every card
        // already wears them; this shell just centralises that.
        'plan-card-surface lift rise relative block overflow-hidden rounded-2xl p-4 pl-5 hover:bg-accent/30',
        interactive && 'cursor-pointer',
        isSelected && selectedSurface === 'accent' && 'plan-card-accent panel',
        // Board selection: a filled card-white surface + ring so a selected card
        // pops off its tinted lane instead of relying on the list's inset stripe.
        isSelected && selectedSurface === 'plain' && 'bg-card shadow-sm ring-2 ring-primary/45',
        isArchived && 'opacity-60',
      )}
    >
      <div className="flex items-start gap-2">
        {titleLeading && <div className="flex flex-shrink-0 items-center pt-0.5">{titleLeading}</div>}
        <h3
          className={cn(
            'display min-w-0 flex-1 text-[15px] leading-snug line-clamp-2',
            emphasized ? 'font-semibold' : 'font-medium',
          )}
        >
          {title}
        </h3>
        {titleAside && <div className="flex flex-shrink-0 items-center gap-1">{titleAside}</div>}
      </div>

      <div className="mt-2.5 flex flex-wrap items-center gap-2">
        {pills}
        {rail && <div className="ml-auto flex-shrink-0">{rail}</div>}
      </div>

      {showProgress && <GradientProgress value={progress} className="mt-3" />}

      {showMeta && (
        <div
          data-testid="card-meta-row"
          className="mono mt-3 flex items-center justify-between gap-2 text-[11px] text-muted-foreground"
        >
          <span>{metaLeft}</span>
          {metaRight !== undefined && <span className="font-sans">{metaRight}</span>}
        </div>
      )}
    </div>
  );
};

export default SidebarCard;
