import { FileText } from 'lucide-react';
import { cn } from '@/lib/utils';

/**
 * The quiet full-height **Show details** column (work-item-provenance F6
 * task 3; mock `.ac-details`): a muted, borderless-fill cap sat just before the
 * action end-cap on feature rows and the whole-fix control strip. It opens the
 * READ-ONLY provenance island (task 2) — "inspect | act": inspection lives
 * here, every action on the end-cap. Present in every STARTED state, live
 * included; the host gates rendering (started + a branch to inspect) and owns
 * the `?island=` routing.
 */
export function ShowDetailsCap({ onClick, className }: { onClick: () => void; className?: string }) {
  return (
    <button
      type="button"
      data-testid="endcap-details"
      aria-label="Show details"
      onClick={onClick}
      className={cn(
        // last:rounded-r-2xl — when no action cap follows (e.g. a live strip),
        // this column closes the row and rounds its own right edge. On an
        // EXPANDED host row (group data-open) the bottom-right corner squares
        // off — the body continues below the header.
        'flex w-[5.75rem] shrink-0 flex-col items-center justify-center gap-1 border-l border-border px-2 py-2 text-center text-xs font-medium leading-tight text-subtle transition-colors last:rounded-r-2xl group-data-[open=true]:last:rounded-br-none hover:bg-accent/50 hover:text-foreground',
        className,
      )}
    >
      <FileText className="h-[15px] w-[15px]" aria-hidden="true" />
      <span>
        Show
        <br />
        details
      </span>
    </button>
  );
}

export default ShowDetailsCap;
