// --- Config-health status styling ---

export const getStatusIcon = (status: 'healthy' | 'warning' | 'error') => {
  switch (status) {
    case 'healthy':
      return <CheckCircle2 className="h-5 w-5 text-green-500" />;
    case 'warning':
      return <AlertTriangle className="h-5 w-5 text-yellow-500" />;
    case 'error':
      return <XCircle className="h-5 w-5 text-red-500" />;
  }
};

export const getStatusBg = (status: 'healthy' | 'warning' | 'error') => {
  switch (status) {
    case 'healthy':
      return 'from-green-50 to-emerald-50 dark:from-green-900/20 dark:to-emerald-900/20 border-green-100 dark:border-green-800';
    case 'warning':
      return 'from-yellow-50 to-amber-50 dark:from-yellow-900/20 dark:to-amber-900/20 border-yellow-100 dark:border-yellow-800';
    case 'error':
      return 'from-red-50 to-rose-50 dark:from-red-900/20 dark:to-rose-900/20 border-red-100 dark:border-red-800';
  }
};

export const getStatusLabel = (status: 'healthy' | 'warning' | 'error') => {
  switch (status) {
    case 'healthy': return 'All Good';
    case 'warning': return 'Some Issues';
    case 'error': return 'Configuration Issues';
  }
};

