// --- Enabled inventory (read-only, grouped by kind) ---

/** The active reviewer surfaces a Running pill; matched on id or name. */
const RUNNING_AGENT_PATTERN = /adversarial/i;

const kindHead = 'mono text-[10px] uppercase tracking-[0.14em] text-muted-foreground flex items-center gap-1.5 pt-1';

const EnabledRow: React.FC<{ item: InstalledItem; running?: boolean }> = ({ item, running }) => (
  <div className="rounded-2xl border border-border bg-muted/30 flex items-center gap-3 p-3">
    <div className="min-w-0 flex-1">
      <div className="flex items-center gap-2">
        <span className="font-semibold text-sm truncate">{item.name}</span>
        {running && (
          <span className="shrink-0 text-[10px] font-medium px-1.5 py-0.5 rounded-full bg-green-100 dark:bg-green-900/30 text-green-700 dark:text-green-300">
            Running
          </span>
        )}
      </div>
      {item.description && <p className="text-xs text-muted-foreground truncate">{item.description}</p>}
    </div>
    <ProvenanceMarker provenance={deriveProvenance(item)} />
  </div>
);

const KindGroup: React.FC<{ label: string; icon: React.ReactNode; items: InstalledItem[]; running?: RegExp }> = ({
  label,
  icon,
  items,
  running,
}) => {
  if (items.length === 0) return null;
  return (
    <section className="space-y-2">
      <p className={kindHead}>
        {icon}
        <span>{label}</span>
        <span className="text-subtle">· {items.length}</span>
      </p>
      <div className="grid gap-2 xl:grid-cols-2">
        {items.map(item => (
          <EnabledRow
            key={item.id}
            item={item}
            running={running ? running.test(item.id) || running.test(item.name) : false}
          />
        ))}
      </div>
    </section>
  );
};

/**
 * The read-only "Enabled" inventory: every capability available to this repo,
 * grouped by kind (Agents, Skills, Plugins, Git hooks, Detected) with a
 * provenance marker per row and no enable/disable controls. Reviewers and
 * tech-stack agents are unified under Agents; the active reviewer shows a
 * Running pill. The Detected group is sourced from the analysis analyzers.
 */
export const EnabledInventory: React.FC<{
  installedData: InstalledData;
  analysis?: RepoAnalysisFile | null;
  /** Plugin-provided reviewer agents (🧠), shown ahead of the repo's own agents. */
  pluginAgents?: InstalledItem[];
}> = ({ installedData, analysis, pluginAgents }) => {
  // Reviewers/tech-stack agents unified: plugin reviewers (🧠) then repo agents (Repo).
  const agents = [...(pluginAgents ?? []), ...installedData.agents];
  // Plugins are global-scoped (~/.claude) unless explicitly tagged otherwise.
  const plugins = installedData.plugins.map(p => ({ ...p, provenance: p.provenance ?? ('global' as const) }));
  // Plugin-contributed hooks are genuinely from the plugin → the 🧠 mark.
  const pluginHooks = installedData.pluginHooks.map(h => ({ ...h, provenance: 'plugin' as const }));
  const detected: InstalledItem[] = (analysis?.analyzers ?? []).map(a => ({
    id: a.id,
    name: a.name,
    description: a.categories?.length ? a.categories.join(' · ') : undefined,
    provenance: 'detected' as const,
  }));
  const total =
    agents.length + installedData.skills.length + plugins.length + pluginHooks.length + detected.length;

  return (
    <section data-testid="enabled-inventory" className="space-y-4">
      <div className="flex items-center gap-2">
        <span className="text-sm font-semibold">Enabled</span>
        <span className="text-xs font-medium px-2 py-0.5 rounded-full bg-green-100 dark:bg-green-900/30 text-green-700 dark:text-green-300">
          {total}
        </span>
        <span className="text-xs text-muted-foreground">available for this repo.</span>
      </div>
      <KindGroup label="Agents" icon={<Bot className="h-4 w-4" />} items={agents} running={RUNNING_AGENT_PATTERN} />
      <KindGroup label="Skills" icon={<Sparkles className="h-4 w-4" />} items={installedData.skills} />
      <KindGroup label="Plugins" icon={<Package className="h-4 w-4" />} items={plugins} />
      <KindGroup label="Git hooks" icon={<Webhook className="h-4 w-4" />} items={pluginHooks} />
      <KindGroup label="Detected in your repo" icon={<Layers className="h-4 w-4" />} items={detected} />
      <p className="text-xs text-muted-foreground">always on — no enable step; add any to a pipeline or invoke directly.</p>
    </section>
  );
};
