import type { BoardRowValidation, ValidationStepView } from '../../../hooks/useBoard';
import type { JourneyBarModel, JourneySegment } from '../components/JourneyBar';

const segment = (step: ValidationStepView): JourneySegment => ({ state: step.state });

/**
 * Shape the server `validation` summary into the card's journey-bar model
 * (validation-pipeline-visibility F5 task 2). The card reads no config and folds
 * no events: the work-item segments come straight from `steps[]`, the
 * main-boundary diamond fills from `landed`, and the post-merge segments come
 * from the `postLand` block — present only when the repo configures a post-land
 * lane. Pure and total.
 */
export function shapeJourney(validation: BoardRowValidation): JourneyBarModel {
  return {
    workItem: validation.steps.map(segment),
    landFilled: validation.landed,
    ...(validation.postLand !== undefined ? { postMerge: validation.postLand.steps.map(segment) } : {}),
    // The reconcile axis (reconcile-segment task 2): the group is present when
    // the server threads reconcile (an in-review row on a live branch); its
    // `segment` tints the rail (absent ⇒ hollow "not entered"), and `merge`
    // colour-codes the boundary diamond.
    ...(validation.reconcile !== undefined
      ? {
          reconcile: validation.reconcile.segment !== undefined ? { segment: validation.reconcile.segment } : {},
          land: validation.reconcile.merge,
        }
      : {}),
  };
}

/** The card's microcopy line: the current step named (mock section B). */
export type JourneyMicrocopy =
  | { readonly tone: 'running'; readonly emoji: string; readonly label: string; readonly since?: string }
  | { readonly tone: 'failed'; readonly emoji: string; readonly label: string };

/**
 * The current step to name beneath the journey bar (F5 task 3) — a 5px bar alone
 * is a riddle at card size. The RUNNING step across both lanes wins (its elapsed
 * anchored to the active run's start); with none running, a FAILED step is named
 * (failures collect, the bar shows which died). All-passed / all-pending name
 * nothing — the bar has left with the pill by then, or nothing has started.
 */
export function journeyMicrocopy(validation: BoardRowValidation): JourneyMicrocopy | undefined {
  const all = [...validation.steps, ...(validation.postLand?.steps ?? [])];
  const running = all.find((s) => s.state === 'running');
  if (running !== undefined) {
    return { tone: 'running', emoji: running.emoji, label: running.label, since: validation.startedAt };
  }
  const failed = all.find((s) => s.state === 'failed');
  if (failed !== undefined) return { tone: 'failed', emoji: failed.emoji, label: failed.label };
  return undefined;
}
