import type { TddPhase } from '../types';

/**
 * A concrete task-detail tab. Red, Green and Commits are fixed; review tabs are
 * one-per-pinned-gate, keyed `review:<gate>` (e.g. `review:adversarial`,
 * `review:mutation-testing`) so a multi-gate pipeline surfaces every gate.
 */
export type TaskTab = 'red' | 'green' | 'commits' | `review:${string}`;

/** The raw `?tab=` value written from a phase — `review` is the generic that
 *  resolves to the task's first review gate (the gate-set isn't known here). */
export type RawTaskTab = 'red' | 'green' | 'review';

/**
 * Map a task's live TDD phase to the `?tab=` value the row opens on. Red and
 * Green own a tab each; every review/refactor phase — and a finished task
 * ('complete') — folds onto the generic `review`, which `resolveActiveTab`
 * pins to the first review gate once the task's gate-set is known.
 */
export function phaseToTab(phase: TddPhase): RawTaskTab {
  if (phase === 'red') return 'red';
  if (phase === 'green') return 'green';
  return 'review';
}

/**
 * Resolve the raw `?tab=` value against a task's concrete tab-set:
 * - a value that is one of the available tabs passes through;
 * - the legacy generic `review` maps to the first review gate;
 * - anything missing/unknown degrades to the first tab (Red, or Green for a
 *   spike that has no Red).
 */
export function resolveActiveTab(raw: string | null, available: readonly TaskTab[]): TaskTab {
  const fallback = available[0] ?? 'red';
  if (raw && (available as readonly string[]).includes(raw)) return raw as TaskTab;
  if (raw === 'review') return available.find((t) => t.startsWith('review:')) ?? fallback;
  return fallback;
}
