import * as React from 'react';
import { cn } from '@/lib/utils';

/**
 * The shared multi-state action button (fix launch-dispatch-feedback
 * task 1). The parent declares an ordered set of states — each with its
 * own glyph, caption, and disabled flag — and controls which is current;
 * the button re-dresses itself (glyph + caption fade in) as the parent
 * advances the state and never advances itself. In-flight states are
 * declared `disabled`, so a Merging…/Preparing… button is un-reclickable
 * by construction; the parent decides what follows the final state
 * (hide the button, surface an error, …).
 */
export interface StateChangeButtonState {
  /** Stable identity the parent selects the state by. */
  key: string;
  glyph: React.ReactNode;
  caption: React.ReactNode;
  /** Non-interactive state (an in-flight Merging…/Preparing…). */
  disabled?: boolean;
}

export type StateChangeButtonSize = 'sm' | 'md';

/** Per-size spacing + type: `sm` is the rail chip, `md` the landing-strip terminal. */
const SIZES: Record<StateChangeButtonSize, { button: string; content: string }> = {
  sm: { button: 'px-2.5 py-1 font-mono text-[11px]', content: 'gap-1' },
  md: { button: 'px-3 py-2 text-xs', content: 'gap-1.5' },
};

export interface StateChangeButtonProps
  extends Omit<React.ButtonHTMLAttributes<HTMLButtonElement>, 'disabled'> {
  states: readonly StateChangeButtonState[];
  /** Key of the active state — falls back to the first state if unknown. */
  current: string;
  /** Spacing/type scale — `sm` (rail chip, default) or `md` (landing-strip terminal). */
  size?: StateChangeButtonSize;
}

export function StateChangeButton({
  states,
  current,
  size = 'sm',
  className,
  ...rest
}: StateChangeButtonProps) {
  const state = states.find((s) => s.key === current) ?? states[0];
  if (state === undefined) return null;
  return (
    <button
      type="button"
      disabled={state.disabled === true}
      className={cn(
        'inline-flex items-center rounded-lg font-medium transition-colors disabled:opacity-60',
        SIZES[size].button,
        className,
      )}
      {...rest}
    >
      {/* Every state renders into the same grid cell — the hidden ones
          still take layout space, so the button holds the width of its
          widest state and never resizes across transitions. The fade-in
          class lands on the state as it becomes current, replaying the
          entrance animation. */}
      <span className="grid">
        {states.map((s) => {
          const isCurrent = s.key === state.key;
          return (
            <span
              key={s.key}
              aria-hidden={!isCurrent}
              // Inline visibility rather than a class: it must hold in any
              // styling environment (and jsdom) so the hidden siblings never
              // leak into the button's accessible name.
              style={isCurrent ? undefined : { visibility: 'hidden' }}
              className={cn(
                'col-start-1 row-start-1 inline-flex items-center justify-center leading-none',
                SIZES[size].content,
                isCurrent && 'animate-fade-in',
              )}
            >
              {s.glyph}
              {s.caption}
            </span>
          );
        })}
      </span>
    </button>
  );
}
