/**
 * work-item-detail-service-rewrite / props-in-ui (F2) — the thin CLIENT adapter
 * that assembles the validation panel's render state from the SERVER-computed
 * detail payload, replacing the 935-line client fold `deriveValidationPanelFromInputs`.
 *
 * The heavy derivation (folding runs, scanning event streams, reading config) is
 * gone — moved server-side into the shared core producers (`getValidation`,
 * `getValidationPanel`, `getPostMergeLane`, `getRegressionEvidence`). This adapter
 * only SHAPES those already-derived pieces into the panel's render contract:
 *  - the pill comes from the ONE lifecycle phase ({@link panelPillFromLifecycle}),
 *  - the completion lane's chips are the payload's per-step strip,
 *  - the post-merge lane's chip is the payload's post-merge strip,
 *  - the regression evidence + landed flag ride straight through,
 *  - run id / timing come off the item's runs (payload data, not a re-fold).
 *
 * The branch structure keys off the lifecycle phase — the single position value —
 * so it cannot drift from the pill or the board. The live reconcile lane + merge
 * boundary stay a CLIENT overlay (the settled reconcile-split) and are layered on
 * separately; this base adapter is the panel SANS reconcile.
 */

// Value imports come from the browser-safe subpath, NOT the root barrel: the root
// (`@magic-ingredients/tiny-brain-core`) transitively pulls Node-only modules
// (storage-path-builder → `path`) that Vite externalises, crashing the browser
// bundle. Type imports are erased, so they stay on the root barrel.
import { isValidationVisible, latestOfKind } from '@magic-ingredients/tiny-brain-core/get-validation';
import type {
  LifecyclePhase,
  ValidationStepView as CoreValidationStepView,
  PostMergeStepView,
  MainValidationEvidence,
  RunRecord,
  SettledStatus,
} from '@magic-ingredients/tiny-brain-core';
import { panelPillFromLifecycle } from './panel-pill';
import type { ValidationChip, ValidationLane, ValidationPanelState } from './validation-panel-state';

/** The detail payload pieces the panel renders — the shared core producers'
 *  outputs plus the item's runs (for run id / timing) and settled status. */
export interface ValidationPanelSource {
  /** The item's settled status — the git-terminal visibility gate's input. */
  readonly status: SettledStatus;
  /** The ONE server-computed lifecycle phase (core `getValidation`). */
  readonly validation: LifecyclePhase;
  /** The completion pipeline's per-step strip (core `getValidationPanel`). */
  readonly validationPanel: { readonly steps: readonly CoreValidationStepView[] };
  /** The post-merge lane's chip strip (core `getPostMergeLane`) — present only
   *  when a post-land pipeline is configured. */
  readonly postMergeLane?: { readonly steps: readonly PostMergeStepView[] };
  /** The regression's structured evidence (core `getRegressionEvidence`) —
   *  present only on a regression-flagged post-merge run. */
  readonly regressionEvidence?: MainValidationEvidence;
  /** The item is merged onto main. */
  readonly landed: boolean;
  /** The item's runs — the run id / timing source (payload data). */
  readonly runs: readonly RunRecord[];
}

const WORK_ITEM_LANE = { kind: 'completion' as const, title: 'Work-item suite', scope: 'changed' as const };

/** The completion strip's chips — the payload's per-step states. A `receipt` lane
 *  is an all-passed collapse, so every chip forces to `passed` (the terminal status
 *  wins, as the fold's receipt did); otherwise the per-step state passes through. */
function completionChips(steps: readonly CoreValidationStepView[], receipt: boolean): ValidationChip[] {
  return steps.map((s) => ({
    type: s.type,
    label: s.label,
    emoji: s.emoji,
    state: receipt ? 'passed' : s.state,
    // Thread the mutation step's folded outcome onto its chip (mutation-run-board
    // task 2) so tasks 3/4 can render its scope / counts / score. The receipt
    // collapse forces `state` to passed but must not drop the detail; present only
    // on the mutation step, absent elsewhere.
    ...(s.mutation !== undefined ? { mutation: s.mutation } : {}),
  }));
}

/** The post-merge lane's single chip — the payload's post-merge strip, straight through. */
function postMergeChips(steps: readonly PostMergeStepView[]): ValidationChip[] {
  return steps.map((s) => ({ type: s.type, label: s.label, emoji: s.emoji, state: s.state }));
}

/** Run id + start / (frozen) end instant off the run that anchors the strip. */
function timingOf(run: RunRecord | undefined): { runId?: string; since?: string; until?: string } {
  if (run === undefined) return {};
  return { runId: run.runId, since: run.startedAt, ...(run.endedAt !== undefined ? { until: run.endedAt } : {}) };
}

export function assembleValidationPanel(source: ValidationPanelSource): ValidationPanelState {
  const { status, validation, validationPanel, postMergeLane, regressionEvidence, landed, runs } = source;

  const completionConfigured = validationPanel.steps.length > 0;
  const postMergeConfigured = postMergeLane !== undefined;
  if (!isValidationVisible(status, { completionConfigured, postMergeConfigured })) return { kind: 'hidden' };

  // The pill is the ONE lifecycle phase, refined: a post-merge crash WITHOUT
  // regression evidence is a plain failed, not a regression (the phase-only mapping
  // collapses both to failed and cannot see the evidence — F1's documented seam).
  let pill = panelPillFromLifecycle(validation);
  if (pill === 'regression' && regressionEvidence === undefined) pill = 'failed';

  // Runs feed ONLY run id / timing — never a branch decision (that is the
  // lifecycle's job), so a `runs` list that lags `getValidation` cannot mask a
  // verdict. `streaming` likewise reads the lifecycle status, not a run's, so the
  // pill and the live-tick cannot drift.
  const completion = latestOfKind(runs, 'completion');
  const main = latestOfKind(runs, 'main-validation');

  // The laundered wrong-tree scoping-fault notice the OLD fold could thread onto the
  // all-pending lane is deliberately NOT reproduced: the detail wire never populated
  // `faulted` (assembleValidationInputs omits it), so it was dead on this surface —
  // a board-only signal. Dropping it is faithful parity, confirmed with the user.

  // ── Post-merge governs: a landed item whose lifecycle has reached the post-merge
  // pipeline with a run (any status but not_started). Keyed off the lifecycle, not a
  // client re-selection of the run — the main run only anchors timing.
  if (validation.pipeline === 'post_merge' && validation.status !== 'not_started') {
    return {
      kind: 'active',
      pill,
      ...timingOf(main),
      merged: true,
      ...(pill === 'regression' && regressionEvidence !== undefined ? { evidence: regressionEvidence } : {}),
      streaming: validation.status === 'running',
      lanes: [
        { ...WORK_ITEM_LANE, receipt: true, chips: completionChips(validationPanel.steps, true) },
        {
          kind: 'main-validation',
          title: 'Post-merge regression test',
          scope: 'full',
          // The final timeline step's mockup sub-line (validation-panel-step-
          // timeline F6 task 2), in lockstep with reconcile-overlay's pending lane.
          subtitle: 'Full suite on main after merge',
          chips: postMergeChips(postMergeLane?.steps ?? []),
        },
      ],
    };
  }

  // ── Landed, no post-merge run (post_merge not_started, or a repo with no
  // post-land pipeline): the pre-merge completion is SPENT — an all-passed receipt,
  // never a red (mirrors the board's Done). No phantom lane without steps.
  if (landed) {
    const lanes: ValidationLane[] = completionConfigured
      ? [{ ...WORK_ITEM_LANE, receipt: true, chips: completionChips(validationPanel.steps, true) }]
      : [];
    return { kind: 'active', pill: 'passed', ...timingOf(completion), streaming: false, lanes };
  }

  // ── All-pending preview: no genuine completion run governs — either none exists,
  // or the latest is non-genuine (cancelled / rejected, which `getValidation` floors
  // to a not_started phase). Both read `pending` off the lifecycle; the lane appears
  // only when a completion pipeline is configured.
  if (pill === 'pending') {
    const lanes: ValidationLane[] = completionConfigured
      ? [{ ...WORK_ITEM_LANE, chips: completionChips(validationPanel.steps, false) }]
      : [];
    return { kind: 'active', pill: 'pending', streaming: false, lanes };
  }

  // ── A settled green pass (or a reconciliation / merge phase, whose completion
  // already passed): an all-passed receipt. `passed` is a settled verdict, so this
  // is never a live tick.
  if (pill === 'passed') {
    return {
      kind: 'active',
      pill: 'passed',
      ...timingOf(completion),
      streaming: false,
      lanes: [{ ...WORK_ITEM_LANE, receipt: true, chips: completionChips(validationPanel.steps, true) }],
    };
  }

  // ── A live (validating) or failed completion run: the full work-item strip. A
  // failed pill names each red step with its reasons (an empty list is meaningful —
  // a lane crash with no step-level red).
  const failures =
    pill === 'failed'
      ? validationPanel.steps
          .filter((s) => s.state === 'failed')
          .map((s) => ({ step: s.label, reasons: [...(s.reasons ?? [])] }))
      : undefined;
  return {
    kind: 'active',
    pill,
    ...timingOf(completion),
    ...(failures !== undefined ? { failures } : {}),
    streaming: pill === 'validating',
    lanes: [{ ...WORK_ITEM_LANE, chips: completionChips(validationPanel.steps, false) }],
  };
}
