import { CircleDashed, Loader2 } from 'lucide-react';

interface PhaseEmptyStateProps {
  /** Helper text shown below the icon. */
  message: string;
  /** Render the spinning in-progress glyph instead of the static empty glyph. */
  inProgress?: boolean;
}

/**
 * The shared full-bleed empty / in-progress state for a task-detail phase tab.
 * Fills the panel (`h-full`) with a centered icon above a line of helper text —
 * a static dashed-circle glyph when the phase is genuinely empty, the spinner
 * when its work is in progress. Every phase tab (Red, Green, Review, Commits)
 * renders its no-content state through this, so they read identically.
 */
export function PhaseEmptyState({ message, inProgress = false }: PhaseEmptyStateProps) {
  return (
    <div
      data-testid="phase-empty-state"
      data-state={inProgress ? 'in-progress' : 'empty'}
      className="grid h-full place-items-center p-6 text-center"
    >
      <div className="flex flex-col items-center gap-3 text-muted-foreground">
        {inProgress ? (
          <Loader2 className="h-8 w-8 animate-spin opacity-70" aria-hidden="true" />
        ) : (
          <CircleDashed className="h-8 w-8 opacity-60" aria-hidden="true" />
        )}
        <p className="max-w-xs text-sm">{message}</p>
      </div>
    </div>
  );
}
