import type {
  WorkItemProvenance,
  FeatureProvenanceView,
  ProvenanceCounts,
  TaskWho,
} from '@magic-ingredients/tiny-brain-core';

/**
 * The who/landed facts a board summary row already carries — the run
 * attachment's producing worker and the item's landed bit (fix
 * board-detail-provenance-not-seeded-from-summary). The detail pane projects
 * these to a minimal {@link WorkItemProvenance} SEED so the who glyph and
 * delivery state paint on the first frame instead of flashing empty behind the
 * per-item provenance fetch.
 */
export interface RowProvenanceFacts {
  readonly producingRun?: { readonly worker: string; readonly model?: string; readonly where: 'local' | 'remote' };
  readonly landed?: boolean;
  /**
   * The item has been delivered/settled (its board lane is In review or Done),
   * so the detail's provenance WILL resolve a who. Only then does an item with
   * no producing run seed `interactive`: seeding it on unsettled work would show
   * an "Interactive" glyph the real (absent) who then clears — a flash of its
   * own. A worker `producingRun` seeds regardless; it is the unambiguous fact.
   */
  readonly settled: boolean;
}

/** The representative deliverer the row implies — a worker when a run produced
 *  the work, else `interactive` for settled work, else absent (see `settled`). */
function seedWho(facts: RowProvenanceFacts): TaskWho | undefined {
  if (facts.producingRun !== undefined) return { kind: 'worker', worker: facts.producingRun.worker };
  return facts.settled ? { kind: 'interactive' } : undefined;
}

/**
 * A minimal per-feature view: the seeded who, plus a NEVER-landed delivery so no
 * fabricated "merged" chip flashes onto a feature (the real per-feature landed
 * fact is genuinely detail-only — the board carries only the container bit). The
 * full fetch replaces this whole view the moment it resolves.
 */
function seedFeature(featureId: string, who: TaskWho | undefined): FeatureProvenanceView {
  return { featureId, counts: EMPTY_COUNTS, delivery: { landed: false, where: { kind: 'to-do' } }, who, tasks: [] };
}

const EMPTY_COUNTS: ProvenanceCounts = { notStarted: 0, inProgress: 0, done: 0, merged: 0, superseded: 0, total: 0 };

/**
 * Seed a FIX's provenance view from its row facts (fix board-detail-provenance-
 * not-seeded-from-summary): one synthetic feature keyed by the fix id (FixDetail
 * reads `features[0]`), its who from the producing run, its container `landed`
 * bit carried through — so the delivered chip (`merged → main`) and who glyph
 * paint immediately. Returns undefined when there is nothing to seed (no worker,
 * not settled, not landed) — the detail then loads as before.
 */
export function seedFixProvenance(id: string, facts: RowProvenanceFacts): WorkItemProvenance | undefined {
  const who = seedWho(facts);
  const landed = facts.landed === true;
  if (who === undefined && !landed) return undefined;
  const feature: FeatureProvenanceView = {
    featureId: id,
    counts: EMPTY_COUNTS,
    delivery: landed ? { landed: true, where: { kind: 'merged' } } : { landed: false, where: { kind: 'to-do' } },
    who,
    tasks: [],
  };
  return { workRef: { kind: 'fix', id }, landed, counts: EMPTY_COUNTS, features: [feature], landHistory: [] };
}

/**
 * Seed a PRD's provenance view from its row facts (fix board-detail-provenance-
 * not-seeded-from-summary): one seed feature per real feature id, each carrying
 * the container-level who the board card already displayed for the whole PRD, so
 * the feature rows show the who glyph instead of an empty flash. Per-feature
 * landed/merged is left off (detail-only, see {@link seedFeature}); the full
 * fetch corrects any per-feature divergence on resolve. Returns undefined when
 * there is no who to seed.
 */
export function seedPrdProvenance(
  id: string,
  featureIds: readonly string[],
  facts: RowProvenanceFacts,
): WorkItemProvenance | undefined {
  const who = seedWho(facts);
  if (who === undefined) return undefined;
  return {
    workRef: { kind: 'prd', id },
    landed: facts.landed === true,
    counts: EMPTY_COUNTS,
    features: featureIds.map((featureId) => seedFeature(featureId, who)),
    landHistory: [],
  };
}
