/**
 * The branch-ref model every worktree indicator shares, plus the two pure
 * helpers that operate on it. Extracted from the former `WorktreePill` (now
 * deleted) into a neutral, JSX-free home consumed by `MiniStatusRail`, the
 * shared `worktree-indicator-parts`, and the status-derivation utils — so the
 * type + helpers outlive the component that used to house them.
 */

/** A branch carrying an item's work, plus its worktree (when one exists). */
export interface WorktreeBranchRef {
  readonly branch: string;
  readonly hasWorktree: boolean;
  /** The worktree's directory name, when known (assignment-sourced refs). */
  readonly worktreeName?: string;
}

/** Collapse repeated branches; OR the worktree flag and keep any known name. */
export function dedupeByBranch(branches: readonly WorktreeBranchRef[]): WorktreeBranchRef[] {
  const merged = new Map<string, { hasWorktree: boolean; worktreeName?: string }>();
  for (const b of branches) {
    const prev = merged.get(b.branch);
    merged.set(b.branch, {
      hasWorktree: (prev?.hasWorktree ?? false) || b.hasWorktree,
      worktreeName: prev?.worktreeName ?? b.worktreeName,
    });
  }
  return [...merged].map(([branch, v]) => ({ branch, ...v }));
}

/** A branch whose worktree dir name is known and differs from the branch name. */
export function diverges(b: WorktreeBranchRef): boolean {
  return !!b.worktreeName && b.worktreeName !== b.branch;
}
