import { cn } from '@/lib/utils';

/** The PRO plan badge; its border/text tint reflects library reachability. */
export function ProBadge({ libReachable }: { libReachable: boolean }) {
  return (
    <span
      title={libReachable ? 'Library connected' : 'Library not reachable'}
      className={cn(
        'rounded-md border px-2.5 py-0.5 text-[11px] font-semibold tracking-widest transition-colors',
        libReachable ? 'border-border-strong text-blue' : 'border-border text-muted-foreground',
      )}
    >
      PRO
    </span>
  );
}
