import React, { useState, useEffect } from 'react';
import { CheckCircle2, AlertTriangle, XCircle, Loader2 } from 'lucide-react';
import type { HealthStatus } from '../types';

interface ConfigHealthBadgeProps {
  repoId: string;
  onClick?: () => void;
  size?: 'sm' | 'md';
}

/**
 * A small badge that shows the config health status for a repository.
 * Click handler navigates to the repo Setup tab (wired in Task 3); the
 * old slide-out ConfigHealthPanel it used to open has been retired.
 */
const ConfigHealthBadge: React.FC<ConfigHealthBadgeProps> = ({
  repoId,
  onClick,
  size = 'sm',
}) => {
  const [status, setStatus] = useState<HealthStatus | null>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const fetchHealth = async () => {
      setLoading(true);
      try {
        const response = await fetch(`/api/repos/${repoId}/config-health`);
        if (response.ok) {
          const data = await response.json();
          setStatus(data.health.status);
        }
      } catch {
        // Silently fail - badge just won't show status
      } finally {
        setLoading(false);
      }
    };

    fetchHealth();
  }, [repoId]);

  if (loading) {
    return (
      <span className="inline-flex items-center">
        <Loader2 className={`${size === 'sm' ? 'h-4 w-4' : 'h-5 w-5'} animate-spin text-gray-400`} />
      </span>
    );
  }

  if (!status) return null;

  const iconSize = size === 'sm' ? 'h-4 w-4' : 'h-5 w-5';
  const baseClasses = onClick ? 'cursor-pointer hover:opacity-80 transition-opacity' : '';

  const handleClick = () => {
    if (onClick) onClick();
  };

  switch (status) {
    case 'healthy':
      return (
        <span
          data-testid={`config-health-badge-${repoId}`}
          className={`inline-flex items-center gap-1 ${baseClasses}`}
          onClick={handleClick}
          title="Configuration healthy"
        >
          <CheckCircle2 className={`${iconSize} text-green-500`} />
          <span className={`text-${size === 'sm' ? 'xs' : 'sm'} text-green-600 dark:text-green-400`}>
            {size === 'md' ? 'Healthy' : 'Config'}
          </span>
        </span>
      );
    case 'warning':
      return (
        <span
          data-testid={`config-health-badge-${repoId}`}
          className={`inline-flex items-center gap-1 ${baseClasses}`}
          onClick={handleClick}
          title="Configuration warnings"
        >
          <AlertTriangle className={`${iconSize} text-yellow-500`} />
          <span className={`text-${size === 'sm' ? 'xs' : 'sm'} text-yellow-600 dark:text-yellow-400`}>
            {size === 'md' ? 'Warnings' : 'Config'}
          </span>
        </span>
      );
    case 'error':
      return (
        <span
          data-testid={`config-health-badge-${repoId}`}
          className={`inline-flex items-center gap-1 ${baseClasses}`}
          onClick={handleClick}
          title="Configuration errors - click to view"
        >
          <XCircle className={`${iconSize} text-red-500`} />
          <span className={`text-${size === 'sm' ? 'xs' : 'sm'} text-red-600 dark:text-red-400`}>
            {size === 'md' ? 'Issues' : 'Config'}
          </span>
        </span>
      );
    default:
      return null;
  }
};

export default ConfigHealthBadge;
