import { useState } from 'react';
import { AlertTriangle } from 'lucide-react';

export interface OrphanedWorktreeBannerProps {
  repoId: string;
  spikeId: string;
  branch: string;
  onCleared?: () => void;
}

type State =
  | { kind: 'idle' }
  | { kind: 'clearing' }
  | { kind: 'error'; message: string };

/**
 * Recovery affordance for the disk-disagrees-with-doc case: the spike doc
 * declares a `worktree:` but git has none on the branch. It DELETEs the worktree
 * endpoint, which now PARKS (task 5) rather than only clearing the field —
 * but this banner renders ONLY when the worktree is absent (SpikeWorktreeStatus
 * kind `orphaned`), so park always takes its `alreadyGone` path and resolves to a
 * plain field-clear (204). It can never hit the dirty-worktree 409, because there
 * is no worktree on disk to be dirty. The DELETE call is force-less by design.
 */
export function OrphanedWorktreeBanner({
  repoId,
  spikeId,
  branch,
  onCleared,
}: OrphanedWorktreeBannerProps) {
  const [state, setState] = useState<State>({ kind: 'idle' });

  const handleClear = async () => {
    setState({ kind: 'clearing' });
    try {
      const res = await fetch(
        `/api/repos/${encodeURIComponent(repoId)}/spikes/${encodeURIComponent(spikeId)}/worktree`,
        { method: 'DELETE' },
      );
      if (!res.ok) {
        setState({ kind: 'error', message: 'Failed to clear worktree field' });
        return;
      }
      onCleared?.();
      setState({ kind: 'idle' });
    } catch {
      setState({ kind: 'error', message: 'Failed to clear worktree field' });
    }
  };

  return (
    <div
      role="alert"
      className="flex items-start gap-3 p-3 rounded-md border border-amber-300 dark:border-amber-700 bg-amber-50 dark:bg-amber-900/30 text-amber-900 dark:text-amber-200"
    >
      <AlertTriangle className="h-4 w-4 flex-shrink-0 mt-0.5" aria-hidden="true" />
      <div className="flex-1 min-w-0">
        <p className="text-sm font-medium">Worktree missing</p>
        <p className="text-xs mt-1">
          The spike doc points at branch{' '}
          <code className="font-mono">{branch}</code> but git no longer has a
          worktree for it. Clear the field to recreate the worktree or proceed
          branch-only.
        </p>
        {state.kind === 'error' && (
          <p className="text-xs mt-2 text-red-700 dark:text-red-300">
            {state.message}
          </p>
        )}
      </div>
      <button
        type="button"
        onClick={handleClear}
        disabled={state.kind === 'clearing'}
        className="flex-shrink-0 px-2.5 py-1.5 text-xs font-medium rounded-md bg-amber-200 dark:bg-amber-800 text-amber-900 dark:text-amber-100 hover:bg-amber-300 dark:hover:bg-amber-700 border border-amber-400 dark:border-amber-600 transition-colors disabled:opacity-50 disabled:cursor-not-allowed"
        aria-label="Clear worktree field from spike doc"
      >
        {state.kind === 'clearing' ? 'Clearing…' : 'Clear worktree'}
      </button>
    </div>
  );
}
