import type { RunEvent } from '@magic-ingredients/tiny-brain-core';

/**
 * The runId a streamed delivery action's POST returns, or null when it
 * short-circuited (an already-landed land returns `{ landed: true }`, or `{}`).
 * Read as a runtime CONTRACT check, not a blind sniff: if the server drifts the
 * id under a different key, this yields null and the action short-circuits
 * rather than streaming a run unobserved. The START of the shared land-run
 * lifecycle whose END is {@link foldRunOutcome} — used by both the island
 * ({@link useDeliveryActions}) and the board ({@link useBoardLand}) so they
 * cannot drift on how a land run is picked up.
 */
export function runIdOf(res: unknown): string | null {
  return res && typeof res === 'object' && typeof (res as { runId?: unknown }).runId === 'string'
    ? (res as { runId: string }).runId
    : null;
}

/**
 * The terminal outcome of a run's activity stream — the pure fold extracted from
 * {@link useDeliveryActions} so the worktree island (single-run) and the board
 * (multiplexed, N cards) read a land run's failure the SAME way and cannot
 * drift. Given the events seen so far, the watched runId, and the stream's last
 * fault (from useRunStream's `error`), it answers: did the run terminate, did it
 * fail, and why.
 */
export interface RunOutcome {
  /**
   * The run's terminal exit event — the LATEST when several arrive, or undefined
   * when none has. Latest-exit-wins (fix orphan-settle-races-live-run-record
   * task 2): the liveness sweep can inject a false failed/process-died exit onto
   * a healthy run's stream, and the run's real exit lands after it; a
   * first-exit fold would read the sweep's guess as the outcome.
   */
  exit: Extract<RunEvent, { type: 'exit' }> | undefined;
  /**
   * The stream dropped before any exit (a non-OK reconnect / hung run — useRunStream
   * stops tailing and surfaces `error`). A broken stream with no exit must count as
   * a failure, not leave the caller streaming forever.
   */
  streamBroke: boolean;
  /** The run has TERMINATED — an exit arrived, OR the stream broke before one. */
  terminated: boolean;
  /** The run FAILED — its exit is `failed`, OR its stream broke before any exit. */
  failed: boolean;
  /** Why it failed: the exit's `reason`, else the stream fault, else undefined. */
  reason: string | undefined;
}

/**
 * Fold a run's stream to its {@link RunOutcome}. Pure: no React, no
 * subscription — the caller supplies the events, the runId it is watching, and
 * useRunStream's `error`. A synthetic terminal exit (the server replays one for
 * a run already terminal at subscribe time) is the same shape as a live exit, so
 * it needs no special case here.
 */
export function foldRunOutcome(
  events: readonly RunEvent[],
  runId: string | undefined,
  streamError: string | null,
): RunOutcome {
  const exit = events
    .filter((e): e is Extract<RunEvent, { type: 'exit' }> => e.type === 'exit' && e.runId === runId)
    .at(-1);
  const streamBroke = runId !== undefined && exit === undefined && streamError !== null;
  const terminated = exit !== undefined || streamBroke;
  const failed = exit?.status === 'failed' || streamBroke;
  const reason = exit?.reason ?? (streamBroke ? streamError ?? undefined : undefined);
  return { exit, streamBroke, terminated, failed, reason };
}
