import type {
  CompletionStepRecord,
  MainValidationEvidence,
  MutationStepOutcome,
  RunEvent,
  RunRecord,
} from '@magic-ingredients/tiny-brain-core';
// The shared git-terminal predicate + receipt (validation-pipeline-visibility
// `git-terminal-validation-predicate`) — presence and the all-passed / all-pending
// step states are decided ONCE here, not re-derived. These are type-only cyclic:
// validation-visibility imports our ValidationStepDef/ValidationStepView types
// (erased at runtime), so this value import forms no runtime cycle.
import { validationReceipt } from './validation-visibility';
// Value imports via the browser-safe subpaths — the core barrel pulls node
// builtins Vite crashes on. `isCompletionTerminalPhase` narrows a completion
// phase frame to the run's verdict partition (F1); the main-validation guards
// (F2) do the same for the post-merge lane's fixed vocabulary — so the fold
// treats a terminal frame as "no running step" rather than lighting a chip.
import { isCompletionTerminalPhase } from '@magic-ingredients/tiny-brain-core/completion-stream';
import {
  isMainValidationStreamPhase,
  isMainValidationTerminalPhase,
  type MainValidationRunningPhase,
} from '@magic-ingredients/tiny-brain-core/main-validation-stream';
// The F1 delivery-phase fold (delivery-lifecycle-pill-taxonomy) — the SINGLE
// producer both the board projection and this panel consume, so the two
// surfaces cannot drift. Imported via the browser-safe subpath (the module is
// pure — its `work-item-pipeline` / `board-lane` imports are type-only, erased
// at runtime — so the value import pulls no node builtins).
import {
  deriveDeliveryPhase,
  type DeliveryPill,
  type PipelineStepState,
  type ValidationStepStatus,
  type DeliveryStepStatus,
} from '@magic-ingredients/tiny-brain-core/delivery-phase';
import type { ReconcileStripState } from './reconcile-strip';

/** One configured completion step's presentation scaffold, in pipeline order. */
export interface ValidationStepDef {
  readonly type: string;
  readonly label: string;
  readonly emoji: string;
}

/** One step in a validation lane's chip strip — a {@link ValidationStepDef}
 *  carrying its resolved render state. Mirrors the server `ValidationStepView`
 *  (validation-pipeline-visibility F3); `useBoard` re-exports it for board
 *  consumers, and the shared receipt derivation returns it. Lives in the util
 *  layer (not the board hook) so pure utils can bind to it without reaching up
 *  into a React hook. */
export interface ValidationStepView extends ValidationStepDef {
  readonly state: 'passed' | 'running' | 'failed' | 'pending';
}

/**
 * A laundered wrong-tree scoping fault (fix validation-strip-silent-on-laundered-
 * scoping-fault) — the item's latest completion failed ONLY on a scope fault, so
 * the genuine grouping dropped it and no run governs. Carries just the `reason`
 * to name: the re-run remedy targets the item the surface already knows (no
 * per-run id needed), so none is threaded here (adversarial review of 48a599d81).
 */
export interface ValidationFault {
  readonly reason: string;
}

export type ValidationChipState = 'passed' | 'running' | 'failed' | 'warn' | 'pending' | 'indeterminate';

export interface ValidationChip extends ValidationStepDef {
  readonly state: ValidationChipState;
  /**
   * The folded mutation outcome (mutation-run-board F2 task 2) — scope / counts /
   * score — carried from the server `validationPanel` step onto the completion
   * chip so the strip can render a mutation chip set on the step it belongs to.
   * Present ONLY on the mutation step when its outcome carried one; absent
   * elsewhere, so a step with no outcome renders without a mutation strip.
   */
  readonly mutation?: MutationStepOutcome;
}

/**
 * The colour-coded merge boundary between the reconcile lane and the post-merge
 * lane (reconcile-segment task 1) — the same vocabulary the board journey
 * diamond uses (task 2): `pending` neutral (reconcile not settled), `ready`
 * green (a clean reconcile — Merge → main is enabled), `blocked` red (a
 * conflict / verify-failure, or a failed work-item that never reached
 * reconcile), `merged` primary (the item has landed).
 */
export type MergeBoundaryState = 'pending' | 'ready' | 'blocked' | 'merged';

export interface ValidationLane {
  readonly kind: 'completion' | 'reconcile' | 'main-validation';
  readonly title: string;
  /**
   * The test scope the lane runs at — completion `changed`, post-merge `full`.
   * Rendered as a sub-line sentence. Omitted on the reconcile lane, whose
   * {@link subtitle} ("Rebase onto main, then verify") is not a changed/full
   * scope and always overrides it.
   */
  readonly scope?: 'changed' | 'full';
  readonly chips: readonly ValidationChip[];
  /**
   * The lane collapses to a one-line receipt ("N steps · all passed") instead of
   * the full strip. Set on the completion lane in two all-passed cases: a settled
   * green pre-land run (the all-passed receipt this pane shows on a Done fix), and
   * a landed item where the work-item suite passed pre-land and the eye belongs on
   * the post-merge lane. Not merge-gated — an un-merged passed run collapses too.
   *
   * NEVER set once a reconcile lane is present (reconcile-segment task 1 decision
   * c): in that surface every lane shows its full phase-pill strip, so the fold
   * strips this flag off the work-item lane when it threads a reconcile lane.
   */
  readonly receipt?: boolean;
  /**
   * A reconcile lane whose stage is NOT started because work-item validation
   * has not passed every phase (reconcile-segment task 1). The render shows the
   * locked "not started — validation must pass first" pill instead of the
   * activity strip. Reconcile-lane only.
   */
  readonly gated?: boolean;
  /**
   * Overrides the scope sentence in the lane's sub-line with bespoke copy — the
   * reconcile lane reads "Rebase onto main, then verify" rather than a
   * changed/full scope. Absent ⇒ the scope sentence stands.
   */
  readonly subtitle?: string;
  /**
   * The lane's latest completion failed ONLY on a wrong-tree scoping fault (fix
   * validation-strip-silent-on-laundered-scoping-fault) — laundered out of the
   * genuine grouping so it never pins a red. When present the lane renders a
   * distinct "Validation couldn't run — scoping fault · re-run" notice naming the
   * {@link ValidationFault.reason}, replacing the misleading all-pending chip
   * strip. Absent ⇒ the ordinary chip strip / receipt stands.
   */
  readonly faulted?: ValidationFault;
  /**
   * The reconcile lane's FAILURE detail (land-failure-surfacing task 5): the failing
   * ladder rung, the reason, the conflicting files, and the next-step hint (the
   * `/merge` hand-off on a conflict). Rendered below the reconcile lane row so a
   * failed reconcile names what broke and how to recover, in one place. Absent ⇒ no
   * failure detail (a clean / in-flight / non-reconcile lane).
   */
  readonly reconcileFailure?: ReconcileFailure;
}

export type ValidationPill = 'validating' | 'failed' | 'passed' | 'regression' | 'pending';

/** A reconcile-lane failure detail (land-failure-surfacing task 5). */
export interface ReconcileFailure {
  /** The failing ladder rung, named — e.g. `Rebase`, `Verify`, `Reconcile`. */
  readonly rung: string;
  /** The persisted failure reason (e.g. `replay-conflict`). */
  readonly reason?: string;
  /** The unmerged paths the ladder could not resolve. */
  readonly conflictedFiles?: readonly string[];
  /**
   * The copyable recovery incantation for a conflict — `tiny-brain reconcile-branch
   * <branch>`, runnable from anywhere; `/merge` resolves a residual conflict. Absent
   * when the failing branch is unknown.
   */
  readonly recoveryCommand?: string;
  /** The recovery hint accompanying the command — the `/merge` hand-off on a conflict. */
  readonly nextStep?: string;
  /**
   * The failing branch — the id the "Retry reconcile" action posts (retry-reconcile-
   * action F4). Same branch the `recoveryCommand` names; carried structured so the
   * button emits it without parsing the command string. Absent ⇒ no retry button
   * (and no command), only the rung + hint.
   */
  readonly branch?: string;
  /**
   * A CATCH-UP conflict (persistent-catch-up-conflict F3): main advanced AFTER this
   * branch was reconciled, so a fresh catch-up rebase re-conflicted — distinguished
   * from a first-time reconcile conflict by the `catch-up-conflict` exitReason. Its
   * presence drives the "main moved after this branch was reconciled" reason copy in
   * place of the raw exitReason; `toSha` is the main SHA it moved to (surface-
   * reconciled-main-sha F1), absent when that SHA is unknown. Absent ⇒ an ordinary
   * conflict, which keeps its raw reason.
   */
  readonly mainMoved?: { readonly toSha?: string };
}

/** A failed completion step named with its failure reasons (F4 task 3). */
export interface ValidationFailure {
  /** The step's human label (e.g. `Mutation Testing`). */
  readonly step: string;
  /** Its failure detail lines (surviving mutants, failing tests). */
  readonly reasons: readonly string[];
}

/**
 * The status of a validation-panel timeline node (validation-panel-step-timeline
 * F6): green tick (`ok`), red ✗ (`fail`), blue pulse (`run`), grey (`pend`). A
 * pure ROLL-UP of a lane's existing state — never a new source of truth (AC:
 * "nodes are derived from existing lane state").
 */
export type StepNodeState = 'ok' | 'fail' | 'run' | 'pend';

/**
 * The timeline node state for a compute lane (F6 task 1): a reconcile FAILURE, a
 * failed chip, OR a `warn` chip reds it — a `warn` is the reconcile rebase's
 * conflict-halt ("needs a hand"), a blocking not-ready state, so the node must
 * agree with the red merge diamond beside it, never read a neutral grey (the
 * legacy `[rebase warn, verify pending]` conflict fold carries no
 * `reconcileFailure`). Else a running chip pulses it; else an all-passed lane
 * ticks it; else it is pending (a gated / all-pending / faulted / frameless-
 * indeterminate lane — genuinely "not a settled signal", so grey). Pure over the
 * lane the panel already derived.
 */
export function laneNodeState(lane: ValidationLane): StepNodeState {
  if (
    lane.reconcileFailure !== undefined ||
    lane.chips.some((c) => c.state === 'failed' || c.state === 'warn')
  ) {
    return 'fail';
  }
  if (lane.chips.some((c) => c.state === 'running')) return 'run';
  if (lane.chips.length > 0 && lane.chips.every((c) => c.state === 'passed')) return 'ok';
  return 'pend';
}

/**
 * The merge/land DIAMOND node state (F6 task 1) — a pure map of the merge
 * boundary the panel already carries: `ready`/`merged` → `ok` (green), `blocked`
 * → `fail` (red), `pending` → `pend` (grey). The diamond never pulses (a boundary
 * is a gate, not a running lane), so `run` is unreachable here by construction.
 */
export function mergeNodeState(merge: MergeBoundaryState): StepNodeState {
  switch (merge) {
    case 'ready':
    case 'merged':
      return 'ok';
    case 'blocked':
      return 'fail';
    case 'pending':
      return 'pend';
  }
}

export type ValidationPanelState =
  // `hidden` is the SOLE no-validation case (the git-terminal predicate returned
  // false — a repo that configures neither pipeline). Run outcome NEVER hides the
  // panel: a git-terminal item with a configured pipeline is always `active`,
  // showing an all-passed receipt / all-pending preview when no run is in flight
  // (validation-pipeline-visibility Governing invariant — replaces the old `idle`
  // machine that hid a passed / no-run / validated fix).
  | { kind: 'hidden' }
  | {
      readonly kind: 'active';
      readonly pill: ValidationPill;
      /**
       * The run this reflects — ABSENT when the panel stands on configuration
       * alone with no genuine run (an all-pending preview: an interactive land,
       * or a laundered scoping-fault / rejected run). The open-run link and the
       * elapsed readout are omitted when there is no run to anchor them.
       */
      readonly runId?: string;
      /**
       * The failed steps with their reasons — set only when the pill is
       * `failed` (F4 task 3); an empty list means the run failed with no
       * step-level red (a lane crash), a populated one names each red step.
       */
      readonly failures?: readonly ValidationFailure[];
      /**
       * The item has landed — a post-merge validation run exists (F4 task 4).
       * Drives the `merged` marker pill and the work-item lane's receipt
       * collapse. Absent (falsy) pre-land, where only the work-item lane shows.
       */
      readonly merged?: boolean;
      /**
       * The post-merge regression's structured failing evidence (F4 task 4),
       * straight off the main-validation run's `regression-flagged` verdict —
       * failing tests + seed + output tail. Set only on the `regression` pill.
       */
      readonly evidence?: MainValidationEvidence;
      /** When the run began — the elapsed/duration anchor. ABSENT alongside
       *  {@link runId} when the panel stands on configuration with no genuine
       *  run (the all-pending preview); the render omits the elapsed readout. */
      readonly since?: string;
      /**
       * When the run SETTLED (its `endedAt`) — present only on a terminal run
       * that recorded an end instant. The render freezes a terminal's duration
       * against this instead of ticking `since` forever (the settled pill must
       * not read as a live stopwatch); a live run has none.
       */
      readonly until?: string;
      readonly streaming: boolean;
      readonly lanes: readonly ValidationLane[];
      /**
       * The colour-coded merge boundary rendered between the reconcile lane and
       * the post-merge lane (reconcile-segment task 1). Present ONLY when a
       * reconcile lane is threaded — the legacy completion-only panel omits it.
       */
      readonly merge?: MergeBoundaryState;
      /**
       * The main SHA the item's latest settled reconcile rebased onto (surface-
       * reconciled-main-sha F1). The passed footer reads it as the PROVISIONAL promise
       * — "Ready to land as of main@<sha7>. Merging re-checks against main's current
       * tip first." (provisional-ready-badge-and-footer F2). Absent ⇒ the plain
       * ready-to-land footer. Absent-safe.
       */
      readonly reconciledAgainst?: string;
      /**
       * The board card's PRIMARY delivery pill (delivery-lifecycle-pill-taxonomy
       * F1), derived from the SHARED `deriveDeliveryPhase` fold so the panel names
       * the same lifecycle phase the board card does — the two cannot drift
       * (detail-panel-phase-coherence task 2). Attached by {@link
       * deriveValidationPanel} (the public entry); the internal base/reconcile
       * builders omit it. `runFailed` and the live-land `merging` phase are
       * board-only signals the panel does not observe, so it reads them absent.
       */
      readonly deliveryPill?: DeliveryPill;
    };

/** Terminal run statuses that count as a GREEN pass. */
const GREEN_TERMINALS: ReadonlySet<RunRecord['status']> = new Set(['completed']);
/** Statuses the run is still working under (no verdict yet). */
const LIVE_STATUSES: ReadonlySet<RunRecord['status']> = new Set(['running', 'cancelling']);

/**
 * The stream's LATEST non-terminal `pipeline` phase (the live current step,
 * since the completion lane emits one frame per step before running it —
 * mirrors the server's `latestPipelinePhase`) and whether a terminal has been
 * observed on the stream (a terminal `pipeline` frame or an `exit`). A terminal
 * frame is not a step and never becomes the current phase; its PRESENCE settles
 * the stream so no chip reads as running (reconcile-strip rule 1: a streamed
 * terminal wins outright over liveness). `phase` is `undefined` before any step.
 */
function scanStream(events: readonly RunEvent[]): { phase: string | undefined; settled: boolean } {
  let phase: string | undefined;
  let settled = false;
  for (const e of events) {
    if (e.type === 'exit') settled = true;
    else if (e.type === 'pipeline') {
      if (isCompletionTerminalPhase(e.phase)) settled = true;
      else phase = e.phase;
    }
  }
  return { phase, settled };
}

/**
 * One configured step's chip state, in precedence order:
 * 1. A PERSISTED outcome is authoritative — passed/failed — and outranks the
 *    live phase; the record persists `label`, so it matches there.
 * 2. Once the run has SETTLED (a terminal status or a streamed terminal frame),
 *    an un-recorded step is `pending` — it never reached a verdict, and a step
 *    cannot be in flight on a run that is over (the honesty hole this guard
 *    closes: a running chip under a settled pill).
 * 3. On a LIVE stream, the step whose `type` matches the current phase is
 *    `running`; every other unrun step is `pending`.
 * 4. On a LIVE run with NO stream, the current step is unknowable — the chip
 *    degrades to `indeterminate` rather than fabricating one (the stuck-spinner
 *    guard, the reconcile-strip stream-or-disk fallback).
 */
function chipState(
  step: ValidationStepDef,
  outcomes: readonly CompletionStepRecord[] | undefined,
  currentPhase: string | undefined,
  settled: boolean,
  streaming: boolean,
): ValidationChipState {
  const outcome = outcomes?.find((o) => o.label === step.label);
  if (outcome !== undefined) return outcome.ok ? 'passed' : 'failed';
  if (settled) return 'pending';
  if (!streaming) return 'indeterminate';
  return step.type === currentPhase ? 'running' : 'pending';
}

/**
 * The post-merge lane is ONE phase — the full regression suite (fix
 * validation-footer-landed-and-post-land-single-phase task 2). Provision and
 * build are PREREQUISITES to that suite, not co-equal regression steps, so they
 * never get their own chips: they surface as the single phase's sub-state label.
 * The three observable main-validation stages (core F2 split `queued →
 * provisioning → building → testing`, minus the pre-step `queued`) are kept here
 * ONLY to name that sub-state — the current stage while running, the failed stage
 * on a crash.
 */
const MAIN_STAGES: readonly { type: MainValidationRunningPhase; running: string; failed: string }[] = [
  { type: 'provisioning', running: 'provisioning…', failed: 'Provision failed' },
  { type: 'building', running: 'building…', failed: 'Build failed' },
  { type: 'testing', running: 'running…', failed: 'Full suite failed' },
];

/** The post-merge phase's fixed identity — one chip whose label is set by its
 *  sub-state (the current / failed stage), defaulting to the phase name. The
 *  emoji is the PHASE's identity and deliberately does not track the sub-state:
 *  provisioning… / building… still wear the suite glyph, since it is one phase. */
const MAIN_PHASE: ValidationStepDef = { type: 'testing', label: 'Full suite', emoji: '🏃' };

/**
 * The post-merge run's latest RUNNING stage (one of the three lane steps —
 * `queued` is pre-step and ignored) and whether a terminal was observed on the
 * stream. Mirrors {@link scanStream} for the fixed main-validation vocabulary.
 */
function scanMainStream(events: readonly RunEvent[]): {
  phase: MainValidationRunningPhase | undefined;
  settled: boolean;
} {
  let phase: MainValidationRunningPhase | undefined;
  let settled = false;
  for (const e of events) {
    if (e.type === 'exit') settled = true;
    else if (e.type === 'pipeline' && isMainValidationStreamPhase(e.phase)) {
      if (isMainValidationTerminalPhase(e.phase)) settled = true;
      else if (e.phase !== 'queued') phase = e.phase;
    }
  }
  return { phase, settled };
}

/**
 * The post-merge lane's chip states (F4 task 4). Unlike the completion lane
 * there are no persisted per-step outcomes — progress comes from the run's
 * typed range verdict (settled) and its live stream:
 * - `validated` ⇒ all three passed; `regression-flagged` ⇒ provision + build
 *   passed, the full suite red (the regression the suite caught).
 * - a settled run with no verdict (the lane itself crashed) reconstructs from
 *   the last streamed stage — that stage failed, priors passed, later pending —
 *   or degrades to indeterminate when it never streamed.
 * - live: the current stage runs, priors passed, later pending; a live run we
 *   are not subscribed to degrades to indeterminate (the stuck-spinner guard).
 */
function mainLaneChips(
  run: RunRecord,
  events: readonly RunEvent[],
  streaming: boolean,
): readonly ValidationChip[] {
  const verdict = run.mainValidation?.verdict;
  const live = LIVE_STATUSES.has(run.status);
  const { phase, settled: streamSettled } = scanMainStream(events);
  const settled = !live || streamSettled;
  const currentIdx = phase !== undefined ? MAIN_STAGES.findIndex((s) => s.type === phase) : -1;

  let state: ValidationChipState;
  let label = MAIN_PHASE.label;
  if (settled) {
    if (verdict === 'validated') state = 'passed';
    // The full suite caught the regression — provision/build were prerequisites
    // that passed, the suite itself is red.
    else if (verdict === 'regression-flagged') {
      state = 'failed';
      label = MAIN_STAGES[MAIN_STAGES.length - 1].failed;
    }
    // A settled run with NO verdict is a lane crash: blame the last streamed stage
    // (its prerequisite or the suite), or degrade to indeterminate when it never
    // streamed a stage.
    else if (currentIdx >= 0) {
      state = 'failed';
      label = MAIN_STAGES[currentIdx].failed;
    } else state = 'indeterminate';
  } else if (!streaming || currentIdx < 0) {
    // Live but unstreamed, or streaming before any stage frame (queued) — the
    // current stage is unknowable, so honestly indeterminate.
    state = 'indeterminate';
  } else {
    // Running: the one phase names its current prerequisite / the suite itself.
    state = 'running';
    label = MAIN_STAGES[currentIdx].running;
  }
  return [{ ...MAIN_PHASE, label, state }];
}

/** The fix-detail validation fold inputs (shared by the base fold and the
 *  reconcile-aware public wrapper). */
interface DeriveValidationPanelInput {
  completion?: RunRecord;
  steps: readonly ValidationStepDef[];
  events: readonly RunEvent[];
  streaming: boolean;
  /** The post-merge main-validation run covering this item's land (F4 task 4). */
  mainValidation?: RunRecord;
  /** The post-merge run's live phase frames. */
  mainEvents?: readonly RunEvent[];
  /** Whether the post-merge run's stream is live. */
  mainStreaming?: boolean;
  /**
   * The branch's reconcile stage machine state (reconcile-segment task 1). When
   * present, the panel gains a reconcile lane between the work-item and
   * post-merge lanes and a colour-coded merge boundary; the work-item lane shows
   * its full strip (no receipt collapse). Absent ⇒ the legacy completion-only
   * shape.
   */
  reconcile?: ReconcileStripState;
  /**
   * The repo configures a post-land (post-merge) pipeline. Gates the pending
   * post-merge lane the reconcile wrapper appends pre-land (reconcile-segment):
   * without a post-land pipeline there is no regression stage to preview, so the
   * merge boundary is the finish line. The landed panel's real main-validation
   * lane is unaffected (it comes off the run, not this flag).
   */
  postLandConfigured?: boolean;
  /**
   * The item is merged onto main (detail-panel-phase-coherence task 1). A landed
   * item's pre-merge completion is SPENT — it gated the merge and no longer holds
   * the panel — so absent a post-merge run the fold reads a settled receipt, not
   * a `failed` pill, mirroring the board fold (`buildItemValidationReader`, fix
   * merged-item-pinned-in-review-by-failed-validation). Defaults to unlanded.
   */
  landed?: boolean;
  /**
   * The laundered wrong-tree scoping-fault marker (fix validation-strip-silent-
   * on-laundered-scoping-fault) — the server stamps it on the composed detail.
   * Only honoured when no genuine completion / main-validation run governs.
   */
  faulted?: ValidationFault;
  /**
   * The main SHA the item's latest settled reconcile rebased onto (surface-reconciled-
   * main-sha F1) — threaded onto the panel state so the passed footer reads the
   * PROVISIONAL "ready as of main@<sha7>" promise (provisional-ready-badge-and-footer
   * F2). Kept in lockstep with the live `withReconcileOverlay` producer. Absent-safe.
   */
  reconciledAgainst?: string;
}

// ── Reconcile lane vocabulary (reconcile-segment task 1) ────────────────────
// The rebase-onto-main + verify stage renders as per-activity pills, one per
// reconcile activity, in the same `.chip` family as the other lanes. The resolve
// rung appears only when a conflict is auto-resolved (the `agent` phase).
// Kept in lockstep with the live defs in reconcile-overlay.ts (fix
// feature-detail-live-reconcile-parity task 2): this legacy fold feeds only the
// ValidationPanel stories, whose header claims parity with FixDetail's reconcile
// lane — so the labels/icons must match the shipped lane, not drift lowercase.
const RECONCILE_REBASE: ValidationStepDef = { type: 'rebase', label: 'Rebase', emoji: '🔀' };
const RECONCILE_AGENT: ValidationStepDef = { type: 'agent', label: 'Resolve', emoji: '🤖' };
const RECONCILE_VERIFY: ValidationStepDef = { type: 'verify', label: 'Verify', emoji: '🔎' };
const RECONCILE_SUBTITLE = 'Rebase onto main, then verify';

/**
 * The reconcile lane's activity chips folded from the strip machine, in
 * reconcile order (rebase → [resolve] → verify). A landed item shows both stages
 * green regardless — reconcile passed by the time the merge happened. The
 * `conflict` terminal warns the rebase chip (`warn`); `verify-failed` reds the
 * verify chip; running phases light the current activity. Never called for a
 * gated lane (work-item not passed) — that lane carries no activity strip.
 */
function reconcileLaneChips(strip: ReconcileStripState, landed: boolean): readonly ValidationChip[] {
  if (landed) {
    return [
      { ...RECONCILE_REBASE, state: 'passed' },
      { ...RECONCILE_VERIFY, state: 'passed' },
    ];
  }
  if (strip.kind === 'terminal') {
    switch (strip.terminal) {
      case 'ready-to-land':
        return [
          { ...RECONCILE_REBASE, state: 'passed' },
          { ...RECONCILE_VERIFY, state: 'passed' },
        ];
      case 'conflict':
        return [
          { ...RECONCILE_REBASE, state: 'warn' },
          { ...RECONCILE_VERIFY, state: 'pending' },
        ];
      case 'verify-failed':
        return [
          { ...RECONCILE_REBASE, state: 'passed' },
          { ...RECONCILE_VERIFY, state: 'failed' },
        ];
      case 'failed':
        return [
          { ...RECONCILE_REBASE, state: 'failed' },
          { ...RECONCILE_VERIFY, state: 'pending' },
        ];
    }
  }
  if (strip.kind === 'running') {
    switch (strip.phase) {
      case 'replaying':
        return [
          { ...RECONCILE_REBASE, state: 'running' },
          { ...RECONCILE_VERIFY, state: 'pending' },
        ];
      case 'agent':
        return [
          { ...RECONCILE_REBASE, state: 'passed' },
          { ...RECONCILE_AGENT, state: 'running' },
          { ...RECONCILE_VERIFY, state: 'pending' },
        ];
      case 'verifying':
        return [
          { ...RECONCILE_REBASE, state: 'passed' },
          { ...RECONCILE_VERIFY, state: 'running' },
        ];
      case 'queued':
        return [
          { ...RECONCILE_REBASE, state: 'pending' },
          { ...RECONCILE_VERIFY, state: 'pending' },
        ];
    }
  }
  // idle — reconcile not yet entered on a passed work-item (both stages pending).
  return [
    { ...RECONCILE_REBASE, state: 'pending' },
    { ...RECONCILE_VERIFY, state: 'pending' },
  ];
}

/** The merge boundary colour code folded from the reconcile strip + gates. */
function mergeBoundary(strip: ReconcileStripState, gated: boolean, landed: boolean): MergeBoundaryState {
  if (landed) return 'merged';
  if (gated) return 'blocked';
  if (strip.kind === 'terminal') return strip.terminal === 'ready-to-land' ? 'ready' : 'blocked';
  // idle / running — reconcile has not reached a verdict yet.
  return 'pending';
}

/** The post-merge lane's sub-line — the approved redesign asset's copy
 *  (validation-panel-step-timeline F6 task 2), the final timeline step's bespoke
 *  subtitle, overriding the generic full-scope sentence on both the pending
 *  preview and the landed run lane. */
const POST_MERGE_SUBTITLE = 'Full suite on main after merge';

/** The pending post-merge lane shown pre-land beside the reconcile lane, so the
 *  merge boundary always has a downstream stage (the mockup's grey regression
 *  pill). Once the item lands, the real main-validation lane replaces it. */
const PENDING_POST_MERGE_LANE: ValidationLane = {
  kind: 'main-validation',
  title: 'Post-merge regression',
  scope: 'full',
  subtitle: POST_MERGE_SUBTITLE,
  chips: [{ type: 'testing', label: 'Regression', emoji: '🧪', state: 'pending' }],
};

/**
 * Fold the reconcile strip into the base panel state (reconcile-segment task 1):
 * insert a reconcile lane after the work-item lane, strip the work-item lane's
 * receipt collapse (decision c — full strip in this surface), ensure a
 * downstream post-merge lane exists, and stamp the colour-coded merge boundary.
 * Only reached when a reconcile strip is threaded and the base state is active.
 */
function withReconcileLane(
  base: Extract<ValidationPanelState, { kind: 'active' }>,
  input: DeriveValidationPanelInput,
): ValidationPanelState {
  const strip = input.reconcile;
  if (strip === undefined) return base;
  const landed = input.mainValidation !== undefined;
  const workItemPassed = input.completion !== undefined && GREEN_TERMINALS.has(input.completion.status);
  const gated = !workItemPassed && !landed;

  // Shared identity — only `chips` and the `gated` flag differ between the two
  // reconcile-lane shapes (adversarial review of 536bc27df, LOW). No `scope`:
  // the reconcile subtitle always overrides it, so a `changed` scope would be
  // inert (same review).
  const reconcileBase = { kind: 'reconcile' as const, title: 'Reconcile', subtitle: RECONCILE_SUBTITLE };
  const reconcileLane: ValidationLane = gated
    ? { ...reconcileBase, gated: true, chips: [] }
    : { ...reconcileBase, chips: reconcileLaneChips(strip, landed) };

  // Un-collapse the work-item lane (decision c) and locate it for insertion.
  const lanes: ValidationLane[] = base.lanes.map((lane) =>
    lane.kind === 'completion' && lane.receipt === true ? { ...lane, receipt: false } : lane,
  );
  const completionIdx = lanes.findIndex((l) => l.kind === 'completion');
  if (completionIdx >= 0) lanes.splice(completionIdx + 1, 0, reconcileLane);
  else lanes.unshift(reconcileLane);
  // The pending post-merge lane previews the post-land regression — but only when
  // the repo configures one. Without it the merge boundary is the finish line
  // (the landed panel's real main-validation lane rides the run, not this flag).
  if (input.postLandConfigured === true && !lanes.some((l) => l.kind === 'main-validation')) {
    lanes.push(PENDING_POST_MERGE_LANE);
  }

  return { ...base, lanes, merge: mergeBoundary(strip, gated, landed) };
}

/**
 * The Validation panel content as a PURE fold, reconcile-aware (reconcile-segment
 * task 1): the base completion/post-merge fold, then — when a reconcile strip is
 * threaded — the reconcile lane + merge boundary spliced in.
 */
export function deriveValidationPanel(input: DeriveValidationPanelInput): ValidationPanelState {
  const base = deriveBaseValidationPanel(input);
  const state = base.kind === 'active' && input.reconcile !== undefined ? withReconcileLane(base, input) : base;
  if (state.kind !== 'active') return state;
  // Attach F1's shared delivery pill at the public boundary (task 2), so board
  // and detail name one phase model. Also thread F1's reconciled-against SHA onto
  // the state so the passed footer reads the provisional "ready as of main@<sha7>"
  // promise (F2), in lockstep with the live `withReconcileOverlay` producer.
  return {
    ...state,
    deliveryPill: derivePanelDeliveryPill(input),
    ...(input.reconciledAgainst !== undefined ? { reconciledAgainst: input.reconciledAgainst } : {}),
  };
}

/**
 * The pre-merge VALIDATION step's live status for the delivery pill — the panel's
 * counterpart to the board's `validationStepStatus ∘ deriveItemValidation`. A
 * LANDED item's completion is SPENT (its pre-land steps are resolved by
 * definition), so it always reads `passed` — which keeps a landed item's running
 * post-merge window named `post-merging`, never a fresh `validating`. An unlanded
 * item folds its completion run through: live ⇒ `running`, green ⇒ `passed`, any
 * other terminal (or no run) ⇒ `failed` (`passed` for no run — nothing red yet).
 */
function panelValidationStep(completion: RunRecord | undefined, landed: boolean): ValidationStepStatus {
  if (landed) return 'passed';
  if (completion === undefined) return 'passed';
  if (LIVE_STATUSES.has(completion.status)) return 'running';
  if (GREEN_TERMINALS.has(completion.status)) return 'passed';
  return 'failed';
}

/**
 * The reconcile (delivery) step status from the branch's strip machine — the
 * panel's counterpart to the board's `buildDeliveryStepReader`. A `conflict`
 * terminal is the `/merge` hand-off (⇒ `merging`/failed); a `verify-failed` /
 * `failed` is a plain reconcile red (⇒ `reconciling`/failed) — distinct
 * remediations F1 splits on. Idle / absent ⇒ not entered (no delivery step).
 */
function panelDeliveryStep(strip: ReconcileStripState | undefined): DeliveryStepStatus | undefined {
  if (strip === undefined || strip.kind === 'idle') return undefined;
  if (strip.kind === 'running') return 'running';
  switch (strip.terminal) {
    case 'ready-to-land':
      return 'ready';
    case 'conflict':
      return 'conflicts';
    case 'verify-failed':
    case 'failed':
      return 'build-failed';
    default: {
      // Exhaustiveness guard (adversarial review, LOW): a new reconcile terminal
      // must add its delivery-step mapping HERE — a compile error at the
      // translation boundary — rather than silently returning undefined and
      // mislabeling the phase, the drift this shared fold exists to prevent.
      const _exhaustive: never = strip.terminal;
      return _exhaustive;
    }
  }
}

/**
 * The post-merge window state — the panel's counterpart to the board's
 * `postMergeValidating ? 'running' : regression ? 'failed' : undefined`. A live
 * main-validation run is `running`; a settled `regression-flagged` verdict is
 * `failed`; any other settled outcome folds to Done (`undefined`, like `passed`).
 */
function panelPostMerge(main: RunRecord | undefined): 'running' | 'failed' | undefined {
  if (main === undefined) return undefined;
  if (LIVE_STATUSES.has(main.status)) return 'running';
  return main.mainValidation?.verdict === 'regression-flagged' ? 'failed' : undefined;
}

/**
 * Translate the panel's substrate into F1's `DeliveryPhaseInput` and derive the
 * primary delivery pill via the SHARED {@link deriveDeliveryPhase} fold
 * (detail-panel-phase-coherence task 2) — the board projection's
 * `deriveRowDeliveryPill` twin, so both surfaces route through ONE producer and
 * cannot drift. The delivery(reconcile) step is a pre-land, live-branch concept —
 * fed only for an unlanded item that has actually reconciled. The panel observes
 * neither the live-land moment nor worker-run health, so `landing` and `runFailed`
 * are board-only signals it reads as absent.
 */
export function derivePanelDeliveryPill(input: DeriveValidationPanelInput): DeliveryPill {
  // Tie the pill's landed notion to the SAME signal the body branches key off
  // (adversarial review of b43b435c0, MEDIUM): `deriveBaseValidationPanel` and
  // `withReconcileLane` both treat a present `mainValidation` run as landed (a
  // post-merge run only exists once merged). Keying the pill off `input.landed`
  // alone let the header collapse to phase `none` while the body rendered the
  // post-merge lane — an internal contradiction that also diverges from the
  // board. Fold both notions together so the header pill and the lanes agree.
  const landed = (input.landed ?? false) || input.mainValidation !== undefined;
  const steps: PipelineStepState[] = [{ kind: 'validation', status: panelValidationStep(input.completion, landed) }];
  const deliveryStep = landed ? undefined : panelDeliveryStep(input.reconcile);
  if (deliveryStep !== undefined) steps.push({ kind: 'delivery', status: deliveryStep });
  const postMerge = panelPostMerge(input.mainValidation);
  return deriveDeliveryPhase({
    steps,
    landed,
    ...(postMerge !== undefined ? { postMerge } : {}),
  });
}

/**
 * The Validation panel content as a PURE fold over the item's latest runs
 * (validation-pipeline-visibility) — the completion + post-merge lanes, BEFORE
 * the reconcile-segment wrapper. Always `active` (never `hidden`); presence is
 * the git-terminal predicate's job in {@link deriveValidationPanelFromInputs}.
 * Run outcome governs only the pill and the per-step states:
 *
 * 1. No completion / main run ⇒ `pending` — an all-pending preview (an
 *    interactive land, a laundered scoping-fault): every configured step
 *    renders pending via {@link validationReceipt}, with no run to anchor.
 * 2. A settled GREEN pass off-stream ⇒ `passed`, the work-item lane collapsed to
 *    an all-passed receipt (validationReceipt) — the boring Done receipt that the
 *    old machine wrongly hid.
 * 3. A live (running) run ⇒ `validating` (state C), the full live strip.
 * 4. Any other terminal — failed, cancelled, rejected, stalled — is `failed`
 *    (state D); it persists off-stream so a refreshed page still says it failed.
 * 5. A post-merge run present pivots to the post-merge lane; a `validated`
 *    verdict is `passed` (an all-passed receipt, not hidden), `regression-flagged`
 *    is `regression` with failing evidence.
 */
function deriveBaseValidationPanel(input: DeriveValidationPanelInput): ValidationPanelState {
  const { completion, steps, events, streaming, mainValidation } = input;

  // ── Post-land (F4 task 4): a post-merge run exists, so the item has landed.
  // The panel pivots to the post-merge lane; the work-item lane, which passed
  // pre-land, collapses to a receipt.
  if (mainValidation !== undefined) {
    const range = mainValidation.mainValidation;
    const mainLive = LIVE_STATUSES.has(mainValidation.status);
    // A fully validated post-merge suite is an all-passed receipt (the land is
    // proven) — it SHOWS, it does not hide (Governing invariant). `validated`
    // reads `passed`; `regression-flagged` reads `regression`; any other settled
    // outcome (a lane crash) reads `failed`.
    const pill: ValidationPill = mainLive
      ? 'validating'
      : range?.verdict === 'validated'
        ? 'passed'
        : range?.verdict === 'regression-flagged'
          ? 'regression'
          : 'failed';
    // The failing evidence rides the `regression-flagged` verdict (the range is
    // discriminated, so `evidence` exists exactly there).
    const evidence = !mainLive && range?.verdict === 'regression-flagged' ? range.evidence : undefined;

    // The receipt lane: the completion suite's steps, settled from its persisted
    // outcomes (it passed pre-land) — `receipt` tells the render to collapse it.
    const receiptChips: readonly ValidationChip[] = steps.map((step) => ({
      ...step,
      state: chipState(step, completion?.completion, undefined, true, false),
    }));

    return {
      kind: 'active',
      pill,
      runId: mainValidation.runId,
      since: mainValidation.startedAt,
      merged: true,
      ...(evidence !== undefined ? { evidence } : {}),
      ...(mainValidation.endedAt !== undefined ? { until: mainValidation.endedAt } : {}),
      streaming: input.mainStreaming ?? false,
      lanes: [
        { kind: 'completion', title: 'Work-item suite', scope: 'changed', receipt: true, chips: receiptChips },
        {
          kind: 'main-validation',
          title: 'Post-merge regression',
          scope: 'full',
          subtitle: POST_MERGE_SUBTITLE,
          chips: mainLaneChips(mainValidation, input.mainEvents ?? [], input.mainStreaming ?? false),
        },
      ],
    };
  }

  // ── Landed, no post-merge run (detail-panel-phase-coherence task 1): the
  // pre-merge completion is SPENT — it gated the merge and no longer holds the
  // panel (fix merged-item-pinned-in-review-by-failed-validation). Mirror the
  // board fold (buildItemValidationReader): a settled all-passed receipt, never a
  // `failed` pill, so the panel agrees with the board's Done. Every post-merge
  // case (running OR settled) was handled by the `mainValidation` branch above,
  // so reaching here with `landed` is the board's "landed, no window ⇒ passed"
  // arm — the spent completion's own status is irrelevant, exactly as the board
  // ignores it. Unlanded items fall through to the completion fold (the pre-merge
  // validating hold, where landing is the live action).
  if (input.landed === true) {
    const receiptLane: ValidationLane = {
      kind: 'completion',
      title: 'Work-item suite',
      scope: 'changed',
      receipt: true,
      chips: validationReceipt(steps, { passed: true, steps: [] }),
    };
    return {
      kind: 'active',
      pill: 'passed',
      ...(completion !== undefined ? { runId: completion.runId, since: completion.startedAt } : {}),
      ...(completion?.endedAt !== undefined ? { until: completion.endedAt } : {}),
      streaming: false,
      // No phantom work-item lane in a post-land-only repo (no completion steps),
      // matching the all-pending preview's own steps-gated lane.
      lanes: steps.length > 0 ? [receiptLane] : [],
    };
  }

  if (completion === undefined) {
    // No genuine run — the all-pending preview (an interactive land, a laundered
    // scoping-fault). The work-item lane appears only when a completion pipeline
    // is configured (steps present); a post-land-only repo shows the pending
    // header alone rather than a phantom work-item lane it never runs.
    //
    // A laundered wrong-tree scoping fault (fix validation-strip-silent-on-
    // laundered-scoping-fault) is the exception the silent all-pending preview
    // must NOT swallow: the server threads a `faulted` marker so the work-item
    // lane names the fault (its notice) instead of reading as "never validated".
    // Only meaningful with a completion pipeline configured (a scoping fault is a
    // completion-lane event) — a post-land-only repo has no work-item lane to
    // carry it, so the marker is dropped there.
    const faulted = steps.length > 0 ? input.faulted : undefined;
    const lanes: readonly ValidationLane[] =
      steps.length > 0
        ? [
            {
              kind: 'completion',
              title: 'Work-item suite',
              scope: 'changed',
              chips: validationReceipt(steps),
              ...(faulted !== undefined ? { faulted } : {}),
            },
          ]
        : [];
    return { kind: 'active', pill: 'pending', streaming: false, lanes };
  }

  const green = GREEN_TERMINALS.has(completion.status);
  // A settled green pass off-stream is the all-passed receipt — it SHOWS now
  // (the old machine hid it). Collapsed to a receipt via the shared derivation.
  // The terminal STATUS wins: a `completed` run is a green pass by definition, so
  // every configured step renders passed even if a stray persisted outcome says
  // otherwise (an inconsistent record) — the board's journey bar reads it the
  // same way, so the two surfaces cannot disagree.
  if (green && !streaming) {
    return {
      kind: 'active',
      pill: 'passed',
      runId: completion.runId,
      since: completion.startedAt,
      ...(completion.endedAt !== undefined ? { until: completion.endedAt } : {}),
      streaming: false,
      lanes: [
        {
          kind: 'completion',
          title: 'Work-item suite',
          scope: 'changed',
          receipt: true,
          chips: validationReceipt(steps, { passed: true, steps: [] }),
        },
      ],
    };
  }

  const pill: ValidationPill = green ? 'passed' : LIVE_STATUSES.has(completion.status) ? 'validating' : 'failed';

  const { phase: currentPhase, settled: terminalStreamed } = scanStream(events);
  // The run is settled for chip purposes when its status has a verdict OR a
  // terminal frame already streamed — either forecloses any running chip.
  const settled = !LIVE_STATUSES.has(completion.status) || terminalStreamed;
  const chips: readonly ValidationChip[] = steps.map((step) => ({
    ...step,
    state: chipState(step, completion.completion, currentPhase, settled, streaming),
  }));

  // The failure banner's payload (F4 task 3): each red step named with its
  // reasons — only on a failed pill, and an empty list is meaningful (the run
  // failed with no step-level red, i.e. the lane itself crashed).
  const failures: readonly ValidationFailure[] | undefined =
    pill === 'failed'
      ? (completion.completion ?? [])
          .filter((o) => !o.ok)
          .map((o) => ({ step: o.label, reasons: o.reasons ?? [] }))
      : undefined;

  return {
    kind: 'active',
    pill,
    runId: completion.runId,
    since: completion.startedAt,
    ...(failures !== undefined ? { failures } : {}),
    // A terminal that recorded an end instant freezes its duration there; a
    // live run has none to freeze on.
    ...(completion.endedAt !== undefined ? { until: completion.endedAt } : {}),
    streaming,
    lanes: [{ kind: 'completion', title: 'Work-item suite', scope: 'changed', chips }],
  };
}

