import { useState } from 'react';
import type { ReactNode } from 'react';
import { ArrowUp, Bot, ChevronDown, CircleCheck, Cloud, GitBranch, GitCommitHorizontal, HardDrive, Layers, TriangleAlert, Wrench, X } from 'lucide-react';
import type { LucideIcon } from 'lucide-react';
import { cn } from '@/lib/utils';
import { CollapsibleSection } from './ui/CollapsibleSection';
import type { AcceptanceState, BranchRunProvenance, DeliveredTask, DeliveryModel, LandAvailability, RunEnvironment, WorktreeProvenance } from '@magic-ingredients/tiny-brain-core';
// Value import via the browser-safe subpath — the core barrel pulls node:path
// (LocalStoragePathBuilder), which Vite externalises and crashes at runtime.
import type { WorktreeContents, WorktreeContentContainer } from '@magic-ingredients/tiny-brain-core/worktree-contents';
import { WorktreeStatusPill } from '@/features/worktrees/components/worktree-status-meta';
import type { WorktreeListStatus } from '@/utils/worktree-list-status';

/** The canonical kind glyph + tone, matching WorktreesInProgressTab. Only the kinds
 *  a branch's WorktreeContents can carry today (PRD, fix) live here — spikes aren't
 *  represented in WorktreeContents yet, so add a `spike` entry (FlaskConical /
 *  text-cyan-500) here when they are, rather than carry dead config now. */
const KIND_META: Record<'prd' | 'fix', { tone: string; Icon: LucideIcon }> = {
  prd: { tone: 'text-primary', Icon: Layers },
  fix: { tone: 'text-blue-500', Icon: Wrench },
};

/**
 * The branch's delivery kind for the type-aware header glyph + tone: any PRD work
 * reads as a plan, else a fix. Falls back to a neutral amber branch glyph when
 * nothing is derivable — e.g. an interactive worktree with no recognised contents.
 */
function kindMeta(contents?: WorktreeContents): { tone: string; Icon: LucideIcon } {
  if (contents?.prds.length) return KIND_META.prd;
  if (contents?.fixes.length) return KIND_META.fix;
  return { tone: 'text-amber-500', Icon: GitBranch };
}

/**
 * The READ-ONLY worktree provenance/details island (work-item-provenance F6
 * task 2; formerly the single-fix merge island). Every delivery pixel renders
 * from the ONE derived {@link DeliveryModel} — delivered count, the
 * incomplete-work signal, land availability, and liveness — so the island is
 * structurally incapable of contradicting the board lane or the end-caps:
 *  - the delivered tally is `model.deliveredItems.length` (never a contents
 *    tally, which read "0/0" on branches that delivered work);
 *  - no `RunRecord.status` text renders at all (a zombie "running" record can't
 *    surface on a settled island — activity is the model's `live` axis);
 *  - the incomplete-work note keys on `model.done` (the same truth as the item's
 *    completed status), never a second tally/lattice read;
 *  - land availability is `model.landAvailability` (the reconcile outcome) —
 *    the standalone mergeability probe cannot override it.
 *
 * It is READ-ONLY by design (user call, 2026-07-24, post-F9): every action lives
 * on the F9 end-caps. Exceptional ops relocated — Reject to the run island,
 * Raise PR + method choice to the CLI, force/discard teardown to the cap's
 * failure notice, conflicted lands to the cap notice until F7. The retired
 * action props are accepted for wiring compatibility but never rendered.
 */
export interface WorktreeMergeContentProps {
  /** Optional close affordance — the header ✕ renders only when provided (the overlay passes it; an inline pane may omit it or use it to deselect). */
  onClose?: () => void;
  /** The island header title — a fix title or a worktree branch (container-agnostic). */
  title: string;
  /** The branch's contents (PRD/feature(s)/fix(es)) — the type glyph + the delivered-task grouping labels. */
  contents?: WorktreeContents;
  /** The derived delivery-acceptance state — OPTIONAL and unread (the model's `done`/`landed` axes drive the render); accepted so existing wiring keeps compiling. */
  acceptanceState?: AcceptanceState;
  /** The shared lifecycle bucket (derived once from status + acceptance) — drives the header status pill so the detail surface reads the same as the sidebar card (task 11). */
  mergeState: WorktreeListStatus;
  /** Whether an actual worker run backs this branch — OPTIONAL and unread (Reject relocated to the run island); accepted so existing wiring keeps compiling. */
  isWorkerRun?: boolean;
  /** The ONE derived delivery model (F6) — every delivery pixel on this island renders from it. */
  model: DeliveryModel;
  /**
   * Branch provenance (ahead/behind vs base, mergeability, on-disk size) behind
   * the vitals header + branch panel (workers / worktree-merge-surface). Absent on
   * surfaces that haven't wired it yet — the vitals row degrades gracefully.
   * Inspection data only: it can no longer gate or contradict `model.landAvailability`.
   */
  provenance?: WorktreeProvenance;
  /** The worker run(s) that produced this branch, most-recent first — the Worker run + Environment vitals. */
  runs?: readonly BranchRunProvenance[];
  /** RETIRED (F6 task 2): the legacy contents tally. Accepted for wiring compatibility, never rendered — the delivered count is `model.deliveredItems.length`. */
  tasks?: { done: number; total: number };
  /** The tasks this run delivered, each with its green commit SHA — the "Work delivered" list. */
  deliveredTasks?: readonly DeliveredTask[];
  /** Commits on the branch not yet on main (`base..branch`) — inspection data in the Provenance section. */
  unlandedCommits?: readonly { readonly sha: string; readonly subject: string }[];
  /** RETIRED action callbacks — the island is read-only; actions live on the end-caps (F9/F6). Accepted for wiring compatibility, never invoked. */
  onLand?: (method: 'ff-only' | 'merge') => void;
  onRaise?: () => void;
  onReject?: (reason: string) => void;
  onTeardown?: (selection: TeardownPartSelection) => void;
}

/** Which reclaimable parts of a landed worktree the user chose to clean up.
 *  The island no longer renders the teardown checklist (read-only, F6 task 2),
 *  but the selection shape remains the teardown POST contract the end-cap
 *  actions (`useDeliveryActions.onTeardown`) send. */
export interface TeardownPartSelection {
  /** Remove the on-disk worktree. */
  worktree: boolean;
  /** Delete the branch ref. */
  branch: boolean;
  /** Delete these run records (by id). */
  runIds: string[];
}

/**
 * A single at-a-glance fact chip in the vitals row (mockup `.vital .seg`). With a
 * `sub`, it stacks into two rows (label/value on top, the sub indented beneath) —
 * used to hang the on-disk size under a local Environment chip.
 */
function Vital({
  icon: Icon,
  label,
  value,
  tone,
  sub,
  faded,
  iconTone,
}: {
  icon: LucideIcon;
  label: string;
  /** Omit for a label-only chip (e.g. a worker-less worktree's faded "Worker"). */
  value?: string;
  tone?: string;
  sub?: string;
  faded?: boolean;
  /** Glyph colour — defaults to muted; the Environment glyph takes the Provenance blue. */
  iconTone?: string;
}) {
  return (
    // The glyph is vertically centred against the (possibly two-line) content via
    // the chip's `align-items: center` — so a local Environment chip's on-disk sub
    // hangs under the value while the icon stays centred beside both lines. The
    // rail's `items-stretch` makes a single-line chip match a two-line sibling.
    <span className={cn('vital seg', faded && 'opacity-50')}>
      <Icon className={cn('h-3.5 w-3.5 shrink-0', iconTone ?? 'text-muted-foreground')} />
      <span className="flex flex-col">
        <span className="inline-flex items-center gap-[0.45rem]">
          <span className="text-xs text-muted-foreground">{label}</span>
          {value && <span className={`mono text-xs font-semibold ${tone ?? 'text-foreground'}`}>{value}</span>}
        </span>
        {sub && <span className="mono text-[11px] text-subtle">{sub}</span>}
      </span>
    </span>
  );
}

/** The environment the latest run executed in — local unless a cloud run produced the branch. */
function environmentOf(runs?: readonly BranchRunProvenance[]): 'local' | 'cloud' {
  return runs?.[0]?.where ?? 'local';
}

/** The base-cap note: whether the base has moved since the branch forked. */
function baseCapNote(provenance: WorktreeProvenance): string {
  if (provenance.behind === 0) return "branched here, hasn't moved since";
  return `${provenance.base} has moved ${provenance.behind} commit${provenance.behind === 1 ? '' : 's'} since`;
}

/** The "N ahead · M behind" branch-position phrase, shown in the vitals and branch panel. */
function aheadBehind(provenance: WorktreeProvenance): string {
  return `${provenance.ahead} ahead · ${provenance.behind} behind`;
}

/** A small uppercase-mono tone chip, self-contained (the dashboard has no `.pill-*` variants). */
function TonePill({ varName, children }: { varName: string; children: ReactNode }) {
  return (
    <span
      className="mono inline-flex items-center gap-1 rounded-md px-1.5 py-0.5 text-[10px] font-semibold uppercase tracking-wide"
      style={{ color: `var(${varName})`, background: `color-mix(in oklab, var(${varName}) 16%, transparent)` }}
    >
      {children}
    </span>
  );
}

/** "Jun 22, 11:24" — null when the run hasn't ended (still running) or the date is unparseable. */
function formatFinished(iso?: string): string | null {
  if (!iso) return null;
  const date = new Date(iso);
  if (Number.isNaN(date.getTime())) return null;
  return date.toLocaleString(undefined, { month: 'short', day: 'numeric', hour: '2-digit', minute: '2-digit' });
}

/**
 * The land-availability chip's label + tone, from the model's reconcile-derived
 * axis alone. `unknown` deliberately avoids the words "ready"/"landable"/
 * "conflict" — it is the absence of a reconcile verdict, not a state of one.
 */
function availabilityChip(availability: LandAvailability): { label: string; varName: string } {
  switch (availability) {
    case 'landable':
      return { label: 'ready to land', varName: '--color-done' };
    case 'conflicts':
      return { label: 'conflicts with main', varName: '--color-warn' };
    case 'already-landed':
      return { label: 'already landed', varName: '--color-done' };
    case 'unknown':
      return { label: 'not yet reconciled', varName: '--color-blue' };
  }
}

/** Stable per-work-item key for grouping delivered tasks (distinct from core's
 *  `containerKey` — this one carries the fix/prd slug shape the UI groups on). */
function deliveredContainerKey(c: WorktreeContentContainer): string {
  return c.kind === 'fix' ? `fix:${c.fix}` : `prd:${c.prd}/${c.feature}`;
}

/** A work item's grouped delivered tasks + its identity and n/n count. */
interface WorkItemGroupData {
  key: string;
  kind: WorktreeContentContainer['kind'];
  title: string;
  slug: string;
  done: number;
  total: number;
  tasks: DeliveredTask[];
}

/**
 * Group delivered tasks by their work-item container, in first-appearance order.
 * Identity (title/slug) comes off the container each task carries; the n/n count
 * comes from `contents` (the authoritative per-item totals), falling back to the
 * delivered count when a container isn't represented there.
 */
function groupDeliveredTasks(
  deliveredTasks: readonly DeliveredTask[],
  contents?: WorktreeContents,
): WorkItemGroupData[] {
  const totals = new Map<string, { done: number; total: number }>();
  for (const fix of contents?.fixes ?? []) {
    totals.set(`fix:${fix.fix}`, { done: fix.completedTaskCount, total: fix.totalTaskCount ?? fix.completedTaskCount });
  }
  for (const prd of contents?.prds ?? []) {
    for (const f of prd.features) {
      totals.set(`prd:${prd.prd}/${f.feature}`, { done: f.completedTaskCount, total: f.totalTaskCount ?? f.completedTaskCount });
    }
  }

  // Map iteration preserves insertion order, so grouping into it keeps
  // first-appearance order without a parallel key list.
  const byKey = new Map<string, WorkItemGroupData>();
  for (const task of deliveredTasks) {
    const c = task.container;
    const key = deliveredContainerKey(c);
    const existing = byKey.get(key);
    if (existing) {
      existing.tasks.push(task);
      continue;
    }
    const count = totals.get(key);
    byKey.set(key, {
      key,
      kind: c.kind,
      title: c.kind === 'fix' ? c.fixTitle ?? c.fix : c.featureTitle ?? c.feature,
      slug: c.kind === 'fix' ? `fix · ${c.fix}` : `prd · ${c.prd} / ${c.feature}`,
      done: count?.done ?? 0,
      total: count?.total ?? 0,
      tasks: [task],
    });
  }
  // Fall back to the delivered count when contents didn't carry a total.
  return [...byKey.values()].map((g) => (g.total > 0 ? g : { ...g, done: g.tasks.length, total: g.tasks.length }));
}

/** A "N fixes · M features" summary of the branch's work items, from contents
 *  (the authoritative list) so it shows even before any per-task commit lands. */
function workItemsSummary(contents?: WorktreeContents): string {
  if (!contents) return '';
  const fixes = contents.fixes.length;
  const features = contents.prds.reduce((n, p) => n + p.features.length, 0);
  const parts: string[] = [];
  if (fixes > 0) parts.push(`${fixes} ${fixes === 1 ? 'fix' : 'fixes'}`);
  if (features > 0) parts.push(`${features} ${features === 1 ? 'feature' : 'features'}`);
  return parts.join(' · ');
}

/** One collapsible work-item group: identity header (glyph · title · slug · n/n)
 *  over its own delivered-task rows. Collapsing keeps the identity row so a
 *  many-item branch reads as a compact index. */
function WorkItemGroup({ group, defaultOpen }: { group: WorkItemGroupData; defaultOpen: boolean }) {
  const [open, setOpen] = useState(defaultOpen);
  // Match the rail convention: the kind tone (blue fix · violet plan) while in
  // progress, green (done tone) once every task in the item has landed.
  const complete = group.total > 0 && group.done === group.total;
  const { Icon } = KIND_META[group.kind];
  const iconTone = complete ? 'text-done' : KIND_META[group.kind].tone;
  const tileBg = complete ? 'bg-done/15' : group.kind === 'prd' ? 'bg-primary/15' : 'bg-blue-500/15';
  return (
    <div data-testid="work-item-group" className="panel-flat overflow-hidden rounded-xl">
      <button
        type="button"
        onClick={() => setOpen((v) => !v)}
        className="hoverable flex w-full items-center gap-2.5 p-3 text-left"
      >
        <ChevronDown className={cn('h-4 w-4 shrink-0 text-subtle transition-transform', !open && '-rotate-90')} />
        <span className={cn('flex h-7 w-7 shrink-0 items-center justify-center rounded-lg', tileBg)}>
          <Icon className={cn('h-4 w-4', iconTone)} />
        </span>
        <div className="min-w-0 flex-1">
          <div className="truncate text-sm font-medium">{group.title}</div>
          <div className="mono truncate text-xs text-subtle">{group.slug}</div>
        </div>
        <span
          data-testid="work-item-count"
          className={cn('mono shrink-0 text-xs', complete ? 'text-done' : 'text-subtle')}
        >
          {group.done} / {group.total}
        </span>
      </button>
      {open && (
        <ul className="space-y-1.5 border-t border-border/60 p-3 text-sm">
          {group.tasks.map((t, i) => (
            <li key={t.sha ?? i} className="flex items-start gap-2">
              <CircleCheck className="mt-0.5 h-4 w-4 shrink-0 text-done" />
              <span className="min-w-0 flex-1">{t.description}</span>
              {t.sha && <span className="mono shrink-0 text-xs text-subtle">{t.sha.slice(0, 7)}</span>}
            </li>
          ))}
        </ul>
      )}
    </div>
  );
}

/**
 * The branch git-graph: the base cap, a node, the delivered-tasks list, a branch
 * panel, and the unmerged tip while the branch hasn't landed. Sourced from
 * `provenance` for the git facts and the MODEL for delivery facts (landed, the
 * delivered count, liveness); the node shows the worker `run` when one backs the
 * branch, else an interactive-worktree node — so the graph renders for ANY
 * deliverable worktree, not only worker runs. No `RunRecord.status` text renders
 * here: a stale record saying "running" cannot surface — the model's `live` axis
 * is the only activity signal.
 */
function RunSection({
  provenance,
  run,
  runEnv,
  model,
  deliveredTasks,
  contents,
}: {
  provenance: WorktreeProvenance;
  run?: BranchRunProvenance;
  runEnv: RunEnvironment;
  model: DeliveryModel;
  deliveredTasks?: readonly DeliveredTask[];
  contents?: WorktreeContents;
}) {
  const landed = model.landed;
  const finished = run ? formatFinished(run.endedAt) : null;
  const EnvIcon = runEnv === 'cloud' ? Cloud : HardDrive;
  const envLabel = runEnv === 'cloud' ? 'cloud' : 'local worktree';
  const sectionLabel = run ? 'The run' : 'The branch';
  const groups =
    deliveredTasks && deliveredTasks.length > 0 ? groupDeliveredTasks(deliveredTasks, contents) : [];
  // A single work item auto-expands; a multi-item branch collapses every group by
  // default so it reads as a compact index.
  const autoOpenGroups = groups.length === 1;
  const deliveredSummary = [workItemsSummary(contents), `${model.deliveredItems.length} delivered`]
    .filter(Boolean)
    .join(' · ');
  return (
    <section aria-label={sectionLabel}>
      <p className="eyebrow mb-3 text-[10px] text-subtle">{sectionLabel}</p>
      <div className="graph">
        <div className="gcap">
          <GitCommitHorizontal className="h-4 w-4 text-blue" />
          <span className="mono text-sm font-medium">{provenance.base}</span>
          {provenance.baseSha && (
            <span className="mono text-[11px] text-subtle">{provenance.baseSha.slice(0, 7)}</span>
          )}
          <span className="text-xs text-muted-foreground">— {baseCapNote(provenance)}</span>
        </div>

        <div className="gnode panel-flat my-3 rounded-2xl p-5">
          {/* Top row: the worktree/run identity (left) and the header-less branch
              box (right), top-aligned on the same row so the tasks below run full
              width. */}
          <div className="flex flex-wrap items-start justify-between gap-4">
            <div className="flex min-w-0 items-center gap-2.5">
              <span className="grid h-8 w-8 shrink-0 place-items-center rounded-lg bg-blue/15 text-blue">
                <EnvIcon className="h-4 w-4" />
              </span>
              <div className="min-w-0">
                {run ? (
                  <>
                    <div className="flex flex-wrap items-center gap-2">
                      <span className="mono text-sm font-semibold">{run.runId}</span>
                      <TonePill varName="--color-blue">
                        <EnvIcon className="h-3 w-3" />
                        {envLabel}
                      </TonePill>
                      {/* Liveness is the model's axis, never RunRecord.status: a
                          zombie record can't paint a settled branch as active. */}
                      {model.live && <TonePill varName="--color-blue">live</TonePill>}
                    </div>
                    <p className="text-xs text-muted-foreground">
                      worker <span className="text-foreground">{run.worker}</span>
                      {finished && <> · finished {finished}</>}
                    </p>
                  </>
                ) : (
                  // Interactive worktree: the env glyph + "Local worktree" says it
                  // all — no redundant title or "worked locally" subtext.
                  <span className="text-sm font-semibold">Local worktree</span>
                )}
              </div>
            </div>

            {/* Branch box — header-less, top-aligned beside the identity. A single
                row: the branch ref (left) and its diff size (right). */}
            <div
              data-testid="branch-box"
              className="panel-flat flex w-full shrink-0 items-center justify-between gap-3 rounded-xl p-3.5 text-sm sm:w-auto sm:min-w-[240px]"
            >
              <span className="mono min-w-0 truncate text-xs">{provenance.branch}</span>
              <span className="mono whitespace-nowrap text-xs">
                <span className="t-good">+{provenance.insertions}</span>{' '}
                <span className="t-bad">−{provenance.deletions}</span>
              </span>
            </div>
          </div>

          {/* Work delivered — one collapsible group per work item, so a branch
              carrying several fixes / features reads as a grouped index rather
              than one flat mixed list. The count is the model's ONE deliveredItems
              list. Hidden once landed: a merged worktree's delivered facts are
              unreliable (introduced-scoped ⇒ empty, or reachability-inherited),
              so the merged-to-main footer below stands in for it. */}
          {!landed && (
            <div className="mt-4">
              <p className="eyebrow mb-2 text-[10px] text-subtle">
                Work delivered{deliveredSummary ? ` · ${deliveredSummary}` : ''}
              </p>
              {groups.length > 0 ? (
                <div className="space-y-2.5">
                  {groups.map((g) => (
                    <WorkItemGroup key={g.key} group={g} defaultOpen={autoOpenGroups} />
                  ))}
                </div>
              ) : (
                <p className="text-xs text-muted-foreground">No per-task commits recorded for this run.</p>
              )}
            </div>
          )}
        </div>

        {/* The tip cap: a FILLED done node once merged (the branch is integrated),
            else the dashed amber "open" ring of an unmerged tip. Merged-ness is
            the model's landed axis — the same truth the end-caps read. */}
        <div className={landed ? 'gcap merged' : 'gcap open'}>
          <span className="mono text-sm font-medium">{provenance.base}</span>
          {landed ? (
            <TonePill varName="--color-done">merged to main</TonePill>
          ) : (
            <TonePill varName="--color-warn">not merged yet</TonePill>
          )}
        </div>
      </div>
    </section>
  );
}

/**
 * Human-readable worktree size, decimal units to match the mockup's "196 MB". Only
 * the two tiers a checkout actually spans — MB (rounded) and, for a large tree, GB
 * (one decimal). Sub-MB worktrees don't occur (node_modules alone dwarfs that), and
 * a zero size is suppressed by the caller, so no smaller tier is carried.
 */
function formatBytes(bytes: number): string {
  if (bytes >= 1e9) return `${(bytes / 1e9).toFixed(1)} GB`;
  return `${Math.round(bytes / 1e6)} MB`;
}


export function WorktreeMergeContent({
  onClose,
  title,
  contents,
  mergeState,
  model,
  provenance,
  runs,
  deliveredTasks,
  unlandedCommits,
}: WorktreeMergeContentProps) {
  // The type-aware header glyph + tone, derived from what the branch delivers.
  const { tone: kindTone, Icon: KindIcon } = kindMeta(contents);

  // Pre-land the provenance graph is the whole point of the view, so it opens;
  // a landed branch's island is a historical record, so it still opens (there is
  // nothing else on the read-only island to lead with).
  const [provOpen, setProvOpen] = useState(true);

  // The latest run backs the Environment + Worker vitals.
  const runEnv = environmentOf(runs);
  const latestRun = runs?.[0];

  const availability = availabilityChip(model.landAvailability);

  // A spike is not a delivery item — its branch never merges, so the delivered
  // tally and the incomplete-work note would only mislead ("0 delivered",
  // "incomplete work" on a finished spike). Both render for delivery kinds only.
  const deliveryItem = model.workRef.kind !== 'spike';

  return (
    <>
      {/* Header — pinned at the top of the fixed-height panel. The eyebrow row
          carries the shared lifecycle pill, the model-derived delivered tally and
          the model-derived land availability; the kind glyph leads the title row,
          with Environment + Worker on a RHS rail aligned to the title. */}
      <div data-testid="island-header" className="shrink-0 border-b border-border p-6">
        <div className="flex items-start justify-between gap-4">
          {/* Eyebrow + the shared lifecycle pill, so the detail header reads the
              same merge-state as the sidebar card for this worktree (task 11). */}
          <div className="flex min-w-0 flex-wrap items-center gap-2">
            <p className={cn('eyebrow shrink-0 text-[10px]', kindTone)}>Worktree · Provenance</p>
            <WorktreeStatusPill status={mergeState} />
            {/* The delivered tally — the ONE deliveredItems list's length. Done
                tone once the model says the item is done, warn while it isn't. */}
            {deliveryItem && (
            <span
              data-testid="merge-task-tally"
              data-partial={!model.done}
              title={model.done ? 'All tasks done' : 'Some tasks are not yet done'}
              className="mono inline-flex shrink-0 items-center gap-1 rounded-md px-1.5 py-0.5 text-[10px] font-semibold"
              style={{
                color: `var(${model.done ? '--color-done' : '--color-warn'})`,
                background: `color-mix(in oklab, var(${model.done ? '--color-done' : '--color-warn'}) 16%, transparent)`,
              }}
            >
              {model.deliveredItems.length} delivered
            </span>
            )}
            {/* Land availability — the reconcile-outcome axis, verbatim. The
                mergeability probe (inspection data below) cannot override it.
                Delivery items only — a spike branch never reconciles or lands. */}
            {deliveryItem && (
            <span
              data-testid="land-availability"
              className="mono inline-flex shrink-0 items-center gap-1 rounded-md px-1.5 py-0.5 text-[10px] font-semibold"
              style={{
                color: `var(${availability.varName})`,
                background: `color-mix(in oklab, var(${availability.varName}) 16%, transparent)`,
              }}
            >
              {availability.label}
            </span>
            )}
          </div>
          {onClose && (
            <button
              aria-label="Close"
              className="-mt-1 shrink-0 text-muted-foreground hover:text-foreground"
              onClick={onClose}
            >
              <X className="h-4 w-4" />
            </button>
          )}
        </div>
        <div className="mt-3 flex items-start justify-between gap-4">
          {/* Title block — the kind glyph beside a title + subtitle column, so the
              subtitle aligns under the title (not under the glyph). */}
          <div className="flex min-w-0 gap-4">
            <KindIcon className={cn('mt-1 h-5 w-5 shrink-0', kindTone)} />
            <div className="min-w-0">
              <h2 className="display truncate text-xl font-bold">{title}</h2>
            </div>
          </div>

          {/* RHS rail — Environment + Worker, aligned to the title row. `items-stretch`
              makes the Worker chip match the taller (two-line) Environment chip
              exactly. Degrades out when no provenance is wired. */}
          {provenance && (
            <div className="flex shrink-0 flex-wrap items-stretch justify-end gap-2" aria-label="Worktree vitals">
              {/* Environment: for a local worktree the on-disk size hangs below as
                  a second row; a cloud run has no checkout, so single row. */}
              <Vital
                icon={runEnv === 'cloud' ? Cloud : HardDrive}
                iconTone="text-blue"
                label="Environment"
                value={runEnv === 'cloud' ? 'cloud' : 'local worktree'}
                sub={
                  // Only when it rounds to ≥ 1 MB — a sub-MB worktree would read
                  // "0 MB on disk", which is noise, so drop the line entirely.
                  runEnv !== 'cloud' && provenance.sizeBytes !== undefined && provenance.sizeBytes >= 1_000_000
                    ? `${formatBytes(provenance.sizeBytes)} on disk`
                    : undefined
                }
              />
              {/* Worker: the backing run's worker NAME as the value, its MODEL on
                  the second line. An interactive `tb go` worktree (no run) shows
                  just a faded "Worker" label. Stretches to the Environment height. */}
              <Vital
                icon={Bot}
                iconTone="text-done"
                label="Worker"
                value={latestRun?.worker}
                sub={latestRun?.model}
                tone="text-done"
                faded={!latestRun}
              />
            </div>
          )}
        </div>
        {/* Incomplete-work note — keyed on the model's `done` axis (the SAME truth
            as the item's completed status), so a done item can never carry it,
            whatever any tally or lattice cell claims. Informational: the land
            actions live on the end-caps, which read the same model. Delivery
            items only — a spike has no delivery to finish. */}
        {deliveryItem && !model.done && (
          <div
            data-testid="incomplete-work-warning"
            role="alert"
            className="mt-3 flex items-start gap-2 rounded-xl border px-3 py-2 text-xs"
            style={{
              borderColor: 'color-mix(in oklab, var(--color-warn) 40%, transparent)',
              background: 'color-mix(in oklab, var(--color-warn) 8%, transparent)',
            }}
          >
            <TriangleAlert className="mt-0.5 h-4 w-4 shrink-0" style={{ color: 'var(--color-warn)' }} />
            <span className="leading-snug text-muted-foreground">
              <strong className="text-foreground">Incomplete work</strong> — not every task on this item is
              finished yet.
            </span>
          </div>
        )}
      </div>

      {/* Read-only body — the Provenance section only (F6 task 2): the branch
          graph, delivered work, and the unlanded-commit list. The Landing strip
          and Clean up sections are GONE — every action lives on the end-caps. */}
      <div className="min-h-0 flex-1 overflow-y-auto">
        {provenance && (
          <CollapsibleSection
            title="Provenance"
            icon={GitBranch}
            open={provOpen}
            onToggle={() => setProvOpen((v) => !v)}
            summary={
              <span className="inline-flex items-center gap-1.5 text-xs text-muted-foreground">
                <ArrowUp className="h-3.5 w-3.5" />
                vs main
                <span className="mono">{aheadBehind(provenance)}</span>
              </span>
            }
          >
            <RunSection
              provenance={provenance}
              run={runs?.[0]}
              runEnv={runEnv}
              model={model}
              deliveredTasks={deliveredTasks}
              contents={contents}
            />
            {/* The `ahead` commits, enumerated: what is on the branch but not yet
                on main — inspection data (the teardown that would discard them
                lives on the end-cap). */}
            {unlandedCommits && unlandedCommits.length > 0 && (
              <div className="mt-4" data-testid="unlanded-commits">
                <p className="eyebrow mb-2 text-[10px] text-subtle">Not yet on main</p>
                <ul className="space-y-1">
                  {unlandedCommits.map((c) => (
                    <li key={c.sha} className="flex items-baseline gap-2 text-xs">
                      <span className="mono text-[11px] text-muted-foreground">{c.sha.slice(0, 7)}</span>
                      <span className="min-w-0 truncate">{c.subject}</span>
                    </li>
                  ))}
                </ul>
              </div>
            )}
          </CollapsibleSection>
        )}
      </div>
    </>
  );
}

export default WorktreeMergeContent;
