import type { DeliveryModel } from '@magic-ingredients/tiny-brain-core';
import { WorktreeMergeIsland } from './WorktreeMergeIsland';

export interface SpikeCleanupIslandProps {
  /** The spike's title — shown in the island header. */
  spikeTitle: string;
  /** The spike worktree's branch — names the model's ref (the spike doc itself is kept). */
  branch: string;
  open: boolean;
  onClose: () => void;
}

/** A finished spike's placeholder delivery model: nothing is delivered/landed on
 *  the delivery axes (a spike branch never merges), and no reconcile ever runs —
 *  a static literal, not a second derivation. */
function spikeModel(branch: string): DeliveryModel {
  return {
    workRef: { kind: 'spike', id: branch },
    ref: branch,
    done: false,
    landed: false,
    live: false,
    deliveredItems: [],
    landAvailability: 'unknown',
  };
}

/**
 * The spike clean-up surface (worktree-surface-consistency-pass): the shared
 * worktree island for a finished spike. Since the island became the READ-ONLY
 * provenance view (work-item-provenance F6 task 2), this shows the spike
 * worktree's details only — the former stubbed teardown button is gone (it was
 * a no-op). The real spike teardown action lives with the spike lifecycle work
 * (spike-worktree-lifecycle PRD), where its worktree/branch removal preserves
 * the spike doc and its findings.
 */
export function SpikeCleanupIsland({ spikeTitle, branch, open, onClose }: SpikeCleanupIslandProps) {
  return (
    <WorktreeMergeIsland
      open={open}
      onClose={onClose}
      title={spikeTitle}
      // A spike reaching this island is finished — the header reads
      // ready-to-clean (non-pulsing), not a live "in progress".
      mergeState="ready-to-clean"
      model={spikeModel(branch)}
    />
  );
}

export default SpikeCleanupIsland;
