import { CircleCheckBig, CircleX, Ban, CircleSlash, Clock } from 'lucide-react';
import type { LucideIcon } from 'lucide-react';
import type { RunStatus } from '@magic-ingredients/tiny-brain-core';
import { cn } from '@/lib/utils';

/** Filter/render order: live first, then success, then the failure family. */
export const RUN_STATUSES: readonly RunStatus[] = [
  'running',
  'cancelling',
  'completed',
  'failed',
  'stalled',
  'cancelled',
  'rejected',
];

/** Default filter — every status visible. */
export const DEFAULT_RUN_STATUSES: readonly RunStatus[] = RUN_STATUSES;

export interface RunStatusMeta {
  /** The pill label shown on the row and the filter pills. */
  readonly label: string;
  /** Status text colour — always applied (row pill + filter pill, active or not). */
  readonly text: string;
  /** Status background tint — the row pill, and a filter pill only when active. */
  readonly fill: string;
  /** The pill's leading glyph, or `null` when it leads with a pulse dot. */
  readonly Icon: LucideIcon | null;
  /** Render a pulsing live dot instead of an icon — the non-terminal convention. */
  readonly pulse?: boolean;
}

/**
 * The single display source for every run status — pill label, tint and glyph.
 * The non-terminal statuses (`running`, `cancelling`) lead with a pulsing dot
 * (the live convention shared with the worktree/plan pills); the terminal
 * statuses lead with a glyph. Mirrors {@link WORKTREE_STATUS_META}'s split of
 * `text` (always on) and `fill` (tint, added on an active filter pill).
 */
export const RUN_STATUS_META: Record<RunStatus, RunStatusMeta> = {
  running: { label: 'running', text: 'text-blue-500', fill: 'bg-blue-500/15', Icon: null, pulse: true },
  cancelling: { label: 'cancelling', text: 'text-amber-500', fill: 'bg-amber-500/15', Icon: null, pulse: true },
  completed: { label: 'completed', text: 'text-emerald-500', fill: 'bg-emerald-500/15', Icon: CircleCheckBig },
  failed: { label: 'failed', text: 'text-red-500', fill: 'bg-red-500/15', Icon: CircleX },
  stalled: { label: 'stalled', text: 'text-amber-500', fill: 'bg-amber-500/15', Icon: Clock },
  cancelled: { label: 'cancelled', text: 'text-gray-500', fill: 'bg-gray-500/15', Icon: Ban },
  rejected: { label: 'rejected', text: 'text-red-500', fill: 'bg-red-500/15', Icon: CircleSlash },
};

/**
 * The shared run status pill — one rendering of a {@link RunStatus} as a tinted
 * pill (pulsing dot for the live convention, else the status glyph, then the
 * label). Matches the {@link WorktreeStatusPill} geometry so a run reads as the
 * same pill family across the dashboard.
 */
export function RunStatusPill({ status, className }: { status: RunStatus; className?: string }) {
  const meta = RUN_STATUS_META[status];
  const Icon = meta.Icon;
  return (
    <span
      data-testid="status-pill"
      className={cn(
        'inline-flex items-center gap-1.5 whitespace-nowrap rounded-lg px-2 py-0.5 text-[11px] font-medium',
        meta.fill,
        meta.text,
        className,
      )}
    >
      {meta.pulse ? (
        <span data-testid="status-pulse-dot" className="h-1.5 w-1.5 flex-shrink-0 rounded-full bg-current animate-pulse" aria-hidden="true" />
      ) : (
        Icon && <Icon className="h-3 w-3 flex-shrink-0" />
      )}
      {meta.label}
    </span>
  );
}
