import React, { useEffect, useState } from 'react';
import { RotateCcw } from 'lucide-react';
import { cn } from '@/lib/utils';

/** Where a resume acts: the repo and the item work-ref slug (e.g. `fix:my-fix`). */
export interface ResumeTarget {
  repoId: string;
  item: string;
}

/** What GET /launch/resumable projects — the run Resume would continue. */
interface ResumableRun {
  runId: string;
  status: string;
  exitReason?: string;
}

/**
 * A focused Resume control for an item whose latest run is resumable
 * (failed / stalled / cancelled). Unlike the [Launch ▾] control it is NOT
 * gated to idle items — it shows alongside a worktree so a failed run that
 * left its branch can still be continued from the item header (fix:
 * item-header-hides-resume-when-worktree-exists). Self-gating: it reads
 * `GET /launch/resumable` and renders nothing when there is nothing to resume;
 * the click POSTs the existing `/runs/:runId/resume` route (the same one
 * `LaunchControl.continueRun` uses), so Resume and Continue never diverge.
 */
const ResumeControl: React.FC<ResumeTarget> = ({ repoId, item }) => {
  const [resumable, setResumable] = useState<ResumableRun | null>(null);
  const [phase, setPhase] = useState<'idle' | 'starting' | 'dispatched'>('idle');
  const [error, setError] = useState<string | null>(null);
  const base = `/api/repos/${encodeURIComponent(repoId)}/launch`;

  // Fetch the resumable projection on mount / target change. Soft-fail: an
  // unreachable route simply means no resume affordance, never an error state.
  // Clear on entry and on every non-success branch so a reused instance never
  // keeps a PREVIOUS item's runId (which would resume the wrong item) — matching
  // LaunchControl's fail-soft.
  useEffect(() => {
    let cancelled = false;
    setResumable(null);
    void (async () => {
      try {
        const res = await fetch(`${base}/resumable?item=${encodeURIComponent(item)}`);
        if (!res.ok) {
          if (!cancelled) setResumable(null);
          return;
        }
        const data = (await res.json()) as { run?: ResumableRun | null };
        if (!cancelled) setResumable(data.run ?? null);
      } catch {
        if (!cancelled) setResumable(null);
      }
    })();
    return () => {
      cancelled = true;
    };
  }, [base, item]);

  // Nothing to continue — render nothing (self-gating).
  if (resumable === null) return null;

  const resume = async () => {
    if (phase !== 'idle') return; // double-dispatch guard
    setPhase('starting');
    setError(null);
    try {
      const res = await fetch(
        `/api/repos/${encodeURIComponent(repoId)}/runs/${encodeURIComponent(resumable.runId)}/resume`,
        { method: 'POST' },
      );
      if (!res.ok) {
        const body = (await res.json().catch(() => ({}))) as { error?: string };
        setError(body.error ?? `Resume failed (HTTP ${res.status})`);
        setPhase('idle');
        return;
      }
      const data = (await res.json()) as { runId?: string };
      if (typeof data.runId !== 'string') {
        setError('Resume failed — no run id returned');
        setPhase('idle');
        return;
      }
      // The old run is now being continued (its failed record stays failed, so
      // /resumable would still return it). Clear so this control stops offering
      // an already-resumed run; the parent's live-run gate + Running pill take
      // over once the child run registers.
      setPhase('dispatched');
      setResumable(null);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Resume failed');
      setPhase('idle');
    }
  };

  const label = phase === 'starting' ? 'Resuming…' : phase === 'dispatched' ? 'Resumed' : 'Resume run';
  // Emerald "continue" tint, same pill weight as the rail's Running / worktree
  // chips so the rail reads consistently.
  const skin =
    'inline-flex flex-shrink-0 items-center gap-1.5 rounded-lg px-2 py-0.5 text-[11px] font-medium bg-[color-mix(in_oklab,#10b981_12%,transparent)] text-emerald-700 dark:text-emerald-300 shadow-[inset_0_0_0_1px_color-mix(in_oklab,#10b981_38%,transparent)]';

  return (
    <span
      className="inline-flex flex-shrink-0 items-center gap-1.5"
      // The whole control owns its clicks — the button AND the error text — so
      // nothing bubbles to a clickable host row.
      onClick={(e) => e.stopPropagation()}
    >
      <button
        type="button"
        data-testid="rail-resume"
        aria-label={`Resume run (last run ${resumable.status})`}
        disabled={phase !== 'idle'}
        title={resumable.exitReason}
        onClick={(e) => {
          e.stopPropagation();
          void resume();
        }}
        className={cn(skin, phase === 'idle' && 'cursor-pointer transition-colors hover:bg-[color-mix(in_oklab,#10b981_20%,transparent)]')}
      >
        <RotateCcw strokeWidth={2} className="h-3 w-3 flex-shrink-0" aria-hidden />
        {label}
      </button>
      {error !== null && (
        <span data-testid="rail-resume-error" className="text-[11px] text-red-600 dark:text-red-400">
          {error}
        </span>
      )}
    </span>
  );
};

export default ResumeControl;
