import React, { useState, useRef, useEffect } from 'react';
import { Sun, Moon, Monitor } from 'lucide-react';
import { useTheme } from '../contexts/ThemeContext';
import { footerRailItemClassName, RailTooltip } from './layout/AppSidebar';

interface ThemeToggleProps {
  /** Tooltip side — `top` for the horizontal rail, `right` when collapsed. */
  tooltipSide?: 'top' | 'right' | 'bottom' | 'left';
}

const ThemeToggle: React.FC<ThemeToggleProps> = ({ tooltipSide = 'top' }) => {
  const { theme, setTheme } = useTheme();
  const [isOpen, setIsOpen] = useState(false);
  const dropdownRef = useRef<HTMLDivElement>(null);

  // Close dropdown when clicking outside
  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (dropdownRef.current && !dropdownRef.current.contains(event.target as Node)) {
        setIsOpen(false);
      }
    };

    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const getCurrentIcon = () => {
    switch (theme) {
      case 'light':
        return <Sun className="h-4 w-4" />;
      case 'dark':
        return <Moon className="h-4 w-4" />;
      default:
        return <Monitor className="h-4 w-4" />;
    }
  };

  const options = [
    { value: 'light' as const, label: 'Light', icon: <Sun className="h-4 w-4" /> },
    { value: 'dark' as const, label: 'Dark', icon: <Moon className="h-4 w-4" /> },
    { value: 'system' as const, label: 'System', icon: <Monitor className="h-4 w-4" /> },
  ];

  return (
    <div className="relative" ref={dropdownRef}>
      <RailTooltip label="Theme" side={tooltipSide}>
        <button
          onClick={() => setIsOpen(!isOpen)}
          className={footerRailItemClassName(isOpen)}
          aria-label="Toggle theme"
          aria-haspopup="menu"
          aria-expanded={isOpen}
        >
          {getCurrentIcon()}
        </button>
      </RailTooltip>

      {/* The theme control is the last item in the sidebar footer rail (bottom
          of the sidebar, right edge), so the menu opens upward and anchors to
          the right edge to stay inside the rail. */}
      {isOpen && (
        <div className="absolute bottom-full right-0 mb-1 py-1 bg-white dark:bg-gray-800 rounded-lg shadow-lg border border-gray-200 dark:border-gray-700 min-w-[120px] z-50">
          {options.map((option) => (
            <button
              key={option.value}
              onClick={() => {
                setTheme(option.value);
                setIsOpen(false);
              }}
              className={`w-full flex items-center gap-2 px-3 py-2 text-sm transition-colors ${
                theme === option.value
                  ? 'bg-blue-50 dark:bg-blue-900/30 text-blue-600 dark:text-blue-400'
                  : 'text-gray-700 dark:text-gray-300 hover:bg-gray-100 dark:hover:bg-gray-700'
              }`}
            >
              {option.icon}
              <span>{option.label}</span>
            </button>
          ))}
        </div>
      )}
    </div>
  );
};

export default ThemeToggle;
