import { useEffect, useRef, useState } from 'react';
import { cn } from '@/lib/utils';
import type { BoardHealthSummary } from '@/hooks/useBoard';
import { checkWindowLabel } from './short-sha';

/**
 * split-land-from-validation F6 Task 2 — the always-on red-main alarm, spanning
 * the top of the board above all lanes.
 *
 * A faithful port of the banner in
 * `docs/prd/split-land-from-validation/assets/land-validation-lifecycle.html`.
 * The banner is ALWAYS the alarm while main is red; attribution decides only
 * what it says and whether it is a click target. Green is quiet — this renders
 * nothing at all rather than a reassuring chip, because the board's default
 * state should not spend a row on "fine".
 */
export interface RedMainBannerProps {
  health: BoardHealthSummary;
  /**
   * Opens the "main is broken" overlay (F6 Task 3), which `BoardView` supplies.
   * Omitted ⇒ the banner renders as static text rather than a dead button, so
   * a host with no overlay to show still gets the alarm.
   */
  onOpenOverlay?: () => void;
  /**
   * Schedules a fresh main validation (red-main-banner-stale-without-
   * revalidation-path) — the user's lever when the causes behind a stale red
   * are already fixed on main. Rendered only while no check is in flight (the
   * revalidating rail owns that state); omitted ⇒ no action renders.
   *
   * May return the schedule's promise: a rejection (409 already-running, no
   * post-land step, unwired) restores the alarm rail and the lever
   * (revalidate-click-rail-not-instant) — the host's notice strip still says
   * why. A void return leaves the optimistic rail to the server's axis.
   */
  onRevalidate?: () => void | Promise<unknown>;
}

/**
 * The alarm's sentence — the USER-dictated copy (red-banner-copy-speaks-jargon):
 * lead with what is failing (the test count, or "the build failed" when the
 * check died before any test ran) on EVERY shape, then the cause in plain
 * words. The internal vocabulary — lands, attribution, ranges — never reaches
 * the surface: "could be any of N recent commits" when commits are listed,
 * "the commit responsible is not identified" when none could be, "introduced
 * by X" only when attribution is confident (a guessed culprit is the
 * accusation this model exists to prevent).
 */
function bannerSentence(health: Extract<BoardHealthSummary, { mainRed: true }>) {
  const { attribution } = health;
  const failing = health.failingTests ?? [];
  const what =
    failing.length > 0
      ? `${failing.length} failing test${failing.length === 1 ? '' : 's'}`
      : 'the build failed';
  if (attribution.kind === 'attributed') {
    return (
      <>
        {what} · introduced by{' '}
        <span className="font-mono text-xs">{attribution.culprit}</span>
      </>
    );
  }
  if (attribution.suspects.length === 0) {
    return <>{what} · the commit responsible is not identified</>;
  }
  // Count the COMMITS the overlay lists (health.lands), so the banner's number
  // always matches the rows behind the click; the deduped suspects are the
  // fallback only while a record predates land plumbing (lands empty).
  const n = health.lands.length > 0 ? health.lands.length : attribution.suspects.length;
  return (
    <>
      {what} · could be {n === 1 ? '1 recent commit' : `any of ${n} recent commits`}
    </>
  );
}

/**
 * The revalidating rail's heading — how long the fresh check has run, in whole
 * minutes, so a 10-minute validation visibly progresses across refetches. No
 * start time (the optimistic click→SSE window) or an unparseable one renders
 * the bare label, never "NaNm".
 */
function revalidatingLabel(startedAt: string | undefined): string {
  if (startedAt === undefined) return 'Re-validating main…';
  const minutes = Math.floor((Date.now() - Date.parse(startedAt)) / 60_000);
  return Number.isFinite(minutes) && minutes >= 1 ? `Re-validating main (${minutes}m in)…` : 'Re-validating main…';
}

/**
 * How long the optimistic rail may claim a check is running without the
 * server confirming one. The 202→run-record→SSE loop settles in seconds; a
 * minute of grace covers a slow spawn, while a run that never materialises
 * (dropped SSE, dead spawn) hands the rail back to the alarm instead of
 * wedging it until reload.
 */
const PENDING_CONFIRM_WINDOW_MS = 60_000;

export function RedMainBanner({ health, onOpenOverlay, onRevalidate }: RedMainBannerProps) {
  // The optimistic half of the in-flight state (revalidate-click-rail-not-
  // instant): the 202 races the detached spawn, so the server's `validating`
  // axis arrives an SSE roundtrip later at best. The click itself must flip
  // the rail — pending bridges that gap, and clears on EVERY exit from it:
  // the schedule is refused (rejection), a server-confirmed cycle ends
  // still-red, main goes green (this component stays mounted across the
  // green null-render, so stale pending would haunt the next red), or the
  // confirm window lapses with no run ever observed.
  const [pending, setPending] = useState(false);
  const serverValidating = health.mainRed && health.validating !== undefined;
  const wasServerValidating = useRef(serverValidating);
  useEffect(() => {
    if (wasServerValidating.current && !serverValidating) setPending(false);
    wasServerValidating.current = serverValidating;
  }, [serverValidating]);
  useEffect(() => {
    if (!health.mainRed) setPending(false);
  }, [health.mainRed]);
  useEffect(() => {
    if (!pending || serverValidating) return undefined;
    const timer = setTimeout(() => setPending(false), PENDING_CONFIRM_WINDOW_MS);
    return () => clearTimeout(timer);
  }, [pending, serverValidating]);

  if (!health.mainRed) return null;

  const { baselineSha, tipSha } = health;
  const revalidating = pending || health.validating !== undefined;
  // Clickable whenever main is red and a host wired the overlay.
  //
  // It previously also required a NON-EMPTY suspect list, which made the alarm
  // uninspectable in exactly the state it is in today: no lands resolved, so no
  // suspects, so no button, so the overlay could never open — while the overlay
  // carried a branch explaining that very state. Two claims that could not both
  // be true. The overlay is worth opening whenever main is red: it shows the
  // range, the evidence, and says plainly when the lands are unknown.
  const clickable = onOpenOverlay !== undefined;

  // A check in flight is its own WHOLE-RAIL state, never a chip decorating the
  // stale alarm (revalidate-click-rail-not-instant, USER-dictated) — a rail
  // that is actively re-proving the verdict does not lead with it.
  const heading = revalidating ? (
    revalidatingLabel(health.validating?.startedAt)
  ) : (
    <>Main is broken — {bannerSentence(health)}</>
  );
  const body = (
    <>
      <span className="tb-board__banner-dot" aria-hidden="true" />
      <h3 className="tb-board__banner-text">{heading}</h3>
      <span className="tb-board__banner-range">{checkWindowLabel(baselineSha, tipSha)}</span>
    </>
  );

  // Re-validate renders only while no check is in flight — the revalidating
  // rail owns that state, and a second concurrent run would prove nothing.
  // The click flips the rail BEFORE the roundtrip; a rejected schedule flips
  // it back (the host's notice strip carries the refusal's words).
  const handleRevalidate = () => {
    if (onRevalidate === undefined) return;
    setPending(true);
    const result = onRevalidate();
    if (result !== undefined) {
      void result.catch(() => setPending(false));
    }
  };
  const revalidateAction = onRevalidate !== undefined && !revalidating && (
    <button type="button" className="tb-board__banner-action" onClick={handleRevalidate}>
      Re-validate
    </button>
  );

  // The overlay target and the Re-validate action are SIBLINGS inside the
  // banner strip — never a button inside a button. Without an overlay the text
  // region degrades to static content exactly as before.
  return (
    <div
      className={cn('tb-board__banner', revalidating && 'tb-board__banner--revalidating')}
      role={clickable ? undefined : 'status'}
    >
      {clickable ? (
        <button type="button" className="tb-board__banner-open" onClick={onOpenOverlay}>
          {body}
        </button>
      ) : (
        body
      )}
      {revalidateAction}
    </div>
  );
}
