import { useCallback, useEffect, useRef, useState } from 'react';
import { sseManager } from '../services/SSEManager';
import { useRunLive } from './useRunLive';
import { useDebouncedRefetch } from './useDebouncedRefetch';
import type {
  WorkRef,
  RunStatus,
  RunKind,
  RunUsage,
  RunResources,
  ReconcileOutcome,
  Effort,
} from '@magic-ingredients/tiny-brain-core';

/**
 * The run's current TDD phase (runs-card-phase-progress), mirrored from the
 * server's `RunPhase`. Kept as a local union so the client bundle never pulls
 * the server route module; the server contract is the source of truth.
 */
export type RunPhase = 'red' | 'green' | 'refactor' | 'review';

/**
 * The run workRef's human doc titles (runs-card-rework task 1), mirrored from
 * the server's `RunWorkTitles`. The card leads with these; each key is absent
 * when the docs resolve no title for it.
 */
export interface RunWorkTitles {
  prd?: string;
  feature?: string;
  fix?: string;
}

/**
 * One run as the runs-lens collection `GET /api/repos/:repoId/runs` returns it
 * (the T1 contract): every run in any state projected to what a lens row renders
 * and acts on.
 *
 * Hand-mirrors the server's `RunListRow` (run-stream.routes.ts) rather than
 * importing it — the client bundle must not pull the server route module (hono,
 * the core barrel, node built-ins), so the run-route hooks here (e.g.
 * `RunDetailView`) mirror their wire shapes the same way. The server contract is
 * the source of truth; keep the two in step.
 */
export interface RunListRow {
  runId: string;
  kind?: RunKind;
  workRef: WorkRef;
  /**
   * The workRef's doc titles (runs-card-rework task 1). The card heading leads
   * with these; absent when the docs resolve none (spike/task refs, deleted
   * docs), where the card falls back to the worker/slug.
   */
  titles?: RunWorkTitles;
  branch: string;
  worktreePath: string | null;
  status: RunStatus;
  exitReason?: string;
  failureClass?: 'transient' | 'permanent';
  worker: string;
  model: string;
  /** The run's model reasoning effort (`RunRecord.effort`) — rendered `· {effort}` beside the model. */
  effort: Effort;
  /**
   * The run's cloud session deep-link (`RunRecord.cloudSessionUrl`) — rendered as
   * a `session` external link, present only for a cloud run (local runs have none).
   */
  cloudSessionUrl?: string;
  target: string;
  /**
   * The run's resolved execution environment (run-environment-contract).
   * `provider` is the local/remote discriminator the band split reads (`local`
   * vs `railway` / `managed`). The server always projects it — a run whose
   * worker has no resolvable environment reports the built-in
   * `{ name: 'local', provider: 'local' }` — so it is never absent here.
   */
  environment: { name: string; provider: string };
  startedAt: string;
  endedAt?: string;
  /**
   * The instant the run last produced output (runs-card-stall-notice). The card
   * derives idle minutes client-side (`now − lastActivityAt`) to show a `no
   * output for {N}m` stall notice; absent when the run never emitted output.
   */
  lastActivityAt?: string;
  usage?: RunUsage;
  /** Sampled OS-resource footprint (run-resource-sampling task 3), beside usage. */
  resources?: RunResources;
  commitCount: number;
  /**
   * The run's current TDD phase (runs-card-phase-progress), from its most
   * recent recognised commit prefix. Absent when nothing recognised — the card
   * then renders no phase block.
   */
  phase?: RunPhase;
  /**
   * The run's progress as a whole percent (0–100), from its work item's
   * task-completion ratio. Absent when the run has no resolvable work item (or
   * a zero-task item) — the card shows the phase label with no bar (no
   * fabricated 0%).
   */
  progressPercent?: number;
  parentRunId?: string;
  reconcileOutcome?: ReconcileOutcome;
  resumable: boolean;
  live: boolean;
}

/**
 * Trailing-debounce window for the run-change → refetch coalescing, matched to
 * the board's `SSE_REFRESH_DEBOUNCE_MS` (useBoard.ts) so a dispatch → commit →
 * status burst on one run folds into a single list re-read.
 */
const SSE_REFRESH_DEBOUNCE_MS = 250;

export interface UseRepoRunsResult {
  runs: RunListRow[];
  loading: boolean;
  error: string | null;
  /**
   * A failed resume POST, on its OWN channel — kept separate from `error` (the
   * list-load failure) so a resume failure doesn't blank the list with a
   * contradictory "Failed to load runs: …" message.
   */
  resumeError: string | null;
  /** Refetch — resume/cancel actions call this so the list reflects the change. */
  refresh: () => void;
  /** Resume a dead run (POST the resume route) then refetch so it reflects. */
  resume: (runId: string) => Promise<void>;
}

/**
 * The repo's runs lens: every run across all states, optionally narrowed to a
 * set of statuses. A one-shot read on mount / when the repo or filter changes
 * (and on explicit `refresh`) — the list is a browse home, not a live stream;
 * the live tail lives in the WorkerRun island a row opens.
 */
export function useRepoRuns(repoId: string | null, statuses?: readonly RunStatus[]): UseRepoRunsResult {
  const [runs, setRuns] = useState<RunListRow[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [resumeError, setResumeError] = useState<string | null>(null);

  // Tracks mount so a debounced live refetch that resolves after unmount can't
  // setState on a torn-down component. The mount-effect refetches synchronously
  // (its own cancelled guard covers it); only the SSE-driven path outlives the
  // component via a pending timer, so it reads this ref as its `isActive`.
  const mountedRef = useRef(true);
  useEffect(() => {
    mountedRef.current = true;
    return () => {
      mountedRef.current = false;
    };
  }, []);

  // Collapse the filter to a stable string so an array literal re-created each
  // render doesn't re-fire the effect; empty ⇒ no filter (all statuses).
  const statusKey = statuses && statuses.length > 0 ? statuses.join(',') : '';

  // `isActive` gates every state write so a fetch that resolves after the effect
  // is torn down (unmount, or repo/filter change) can't update stale state. The
  // effect passes `() => !cancelled`; the imperative `refresh` passes the always-
  // active default (its caller is live by construction).
  const load = useCallback(
    async (isActive: () => boolean = () => true) => {
      // No repo resolved yet — don't fire a fetch at the malformed
      // `/api/repos//…`; settle to an empty, non-loading state until one arrives.
      if (!repoId) {
        if (isActive()) {
          setRuns([]);
          setError(null);
          setLoading(false);
        }
        return;
      }
      try {
        const query = statusKey ? `?status=${encodeURIComponent(statusKey)}` : '';
        const res = await fetch(`/api/repos/${encodeURIComponent(repoId)}/runs${query}`);
        if (!res.ok) {
          if (isActive()) {
            setError(`Failed to load runs (HTTP ${res.status})`);
            setRuns([]);
          }
          return;
        }
        const data = (await res.json()) as { runs: RunListRow[] };
        if (isActive()) {
          setRuns(data.runs ?? []);
          setError(null);
        }
      } catch (err) {
        if (isActive()) {
          setError(err instanceof Error ? err.message : 'Failed to load runs');
          setRuns([]);
        }
      } finally {
        if (isActive()) setLoading(false);
      }
    },
    [repoId, statusKey],
  );

  useEffect(() => {
    let cancelled = false;
    void load(() => !cancelled);
    return () => {
      cancelled = true;
    };
  }, [load]);

  const refresh = useCallback(() => {
    void load();
  }, [load]);

  // Live-invalidate the list membership on run-change SSE, mirroring the board
  // (useBoard.ts): a dispatch creates a run record, a status transition rewrites
  // it, a prune deletes it — each broadcast as `run-change`. Without this the
  // runs surface is a one-shot read that lags reality until a manual refresh.
  // Every trigger funnels through ONE trailing debounce so a dispatch → commit →
  // status burst on one run coalesces into a single refetch. The refetch carries
  // the mount guard so a timer that fires post-unmount is a no-op.
  const liveRefetch = useCallback(() => {
    void load(() => mountedRef.current);
  }, [load]);
  const scheduleRefresh = useDebouncedRefetch(liveRefetch, SSE_REFRESH_DEBOUNCE_MS);

  // Called UNCONDITIONALLY (never behind a `repoId` guard): `repoId` legitimately
  // toggles string↔null during navigation, and a gated hook would flip the hook
  // count between renders — React's "change in the order of Hooks" throw, which
  // propagates to the app-root ErrorBoundary and blanks the whole surface.
  // `useRunLive` itself no-ops internally when `repoId` is null.
  useRunLive(repoId, scheduleRefresh);

  // Reconnect resync (mirrors useBoard.ts): SSE events emitted while the tab was
  // disconnected are lost, so a reopen may leave the runs list arbitrarily stale
  // — the exact "needs a hard refresh" class this fix targets. The manager fires
  // `reconnected` on every reopen; it carries no repo, so it is unfiltered and
  // folds through the shared debounce like every other trigger.
  useEffect(() => {
    if (!repoId) return;
    return sseManager.on('reconnected', scheduleRefresh);
  }, [repoId, scheduleRefresh]);

  const resume = useCallback(
    async (runId: string) => {
      if (!repoId) return;
      setResumeError(null);
      try {
        const res = await fetch(
          `/api/repos/${encodeURIComponent(repoId)}/runs/${encodeURIComponent(runId)}/resume`,
          { method: 'POST' },
        );
        if (!res.ok) {
          setResumeError(`Failed to resume run (HTTP ${res.status})`);
          return;
        }
      } catch (err) {
        setResumeError(err instanceof Error ? err.message : 'Failed to resume run');
        return;
      }
      // Reflect the change: the resumed run is now running, so the list refetch
      // moves it off the failed count and into the running lane.
      await load();
    },
    [repoId, load],
  );

  return { runs, loading, error, resumeError, refresh, resume };
}
