import { Bot, Cloud, GitMerge, GitPullRequestArrow, User } from 'lucide-react';
import type { FeatureDelivery, TaskWho } from '@magic-ingredients/tiny-brain-core';
import { cn } from '@/lib/utils';
import MsrPill from './MsrPill';
import { Skeleton } from './ui/skeleton';

interface DeliveredProvenanceProps {
  /** The feature/item's effective delivery — where it lives + whether it landed. */
  delivery: FeatureDelivery;
  /** The representative deliverer (worker or interactive), or ABSENT when the
   *  item has no deliverer yet — a not-started fix makes no who claim (fix
   *  control-strip-mute-during-live-run task 3). Typed to mirror the core
   *  `FeatureProvenanceView.who` it is fed from; MsrPill renders nothing for an
   *  absent who. */
  who: TaskWho | undefined;
  /** A worktree branch still lingering on a landed feature — folded into the
   *  pill when the delivery itself names no branch, so the row reads one pill. */
  lingeringBranch?: string;
  /**
   * Collapse the branch chip to the icon-only worktree glyph (fix
   * feature-card-live-glyph-and-run-watch-surface task 6): a delivered item's full
   * branch name is noise, so it moves to the glyph's title. The (done-gated)
   * feature-card caller sets it; default off keeps the branch by name for any
   * future caller that wants it inline.
   */
  compactBranch?: boolean;
  /**
   * The host's provenance is on its FIRST load (fix prd-detail-skeletons-
   * stabilize-layout task 1): the delivered where/landed detail is not known
   * yet, so its slot reserves a same-height skeleton chip while the seeded WHO
   * paints immediately. The real landed chip / branch pill swap in place when
   * the fetch lands. First-load only — a background refetch keeps the previous
   * snapshot, so a settled row never blanks back to a skeleton.
   *
   * The CALLER must pass this true only for rows whose delivered slot is known
   * to fill once loaded (a completed / landed feature) — never a superseded
   * (retired) row, whose slot settles empty: reserving one there would trade
   * the pop-in for an equal-and-opposite `skeleton → nothing` shift (the same
   * reason the cleanup row is not skeletoned).
   */
  settling?: boolean;
}

/**
 * The delivered-provenance readout (work-item-provenance F4) — a completed work
 * item's WHERE (a landed chip: `merged → main` / `via fix <slug>`) and WHO,
 * rendered on its PRD-detail section row. The deliverer no longer folds into a
 * tinted pill: WHO reads as a glyph + plain-text label (Bot + name / User +
 * "Interactive"), the SAME shape the live MiniStatusRail names a worker with
 * (fix endcap-resumes-pipeline-runs task 5), and the branch keeps its own
 * compact chip. Presentational only — the projection decides the axes; this
 * just draws them. The fix control strip composes the same pieces
 * ({@link LandedChip} / {@link WhoAttribution}) directly so it can right-align
 * the landed chip.
 */
function DeliveredProvenance({ delivery, who, lingeringBranch, compactBranch, settling }: DeliveredProvenanceProps) {
  const deliveryBranch = delivery.where.kind === 'branch' ? delivery.where.branch : undefined;
  const branch = deliveryBranch ?? lingeringBranch;
  return (
    <span data-testid="feature-provenance" className="inline-flex items-center gap-2">
      {/* While settling the where/landed axis is unknown — reserve its slot with
          a same-height skeleton chip so the resolved landed chip / branch pill
          swap in place; the seeded WHO below still paints on the first frame. */}
      {settling ? (
        <Skeleton data-testid="feature-provenance-skeleton" aria-hidden="true" className="h-5 w-24 rounded-md" />
      ) : (
        <>
          <LandedChip delivery={delivery} />
          {branch !== undefined && <MsrPill branch={branch} iconOnly={compactBranch} />}
        </>
      )}
      <WhoAttribution who={who} />
    </span>
  );
}

/**
 * The deliverer as a glyph + plain-text label (fix endcap-resumes-pipeline-runs
 * tasks 5 + 9): Bot + worker name, or User + "Interactive" — matched to the
 * live MiniStatusRail named-worker block (h-4 glyph, `text-foreground
 * font-medium` name) so a completed fix keeps the in-progress body's
 * attribution look instead of swapping to a tinted who-pill. The model line the
 * live body carries has no settled source (`TaskWho` names no model), so it is
 * dropped. The branch rides its own compact chip alongside; this names WHO, not
 * where. Renders nothing for an absent who.
 */
export function WhoAttribution({
  who,
  model,
  failed = false,
}: {
  who: TaskWho | undefined;
  model?: string;
  /** The item's run failed (fix ...regression-test-wording task 4): tint THIS
   *  glyph red rather than let the command row add a separate red glyph beside it. */
  failed?: boolean;
}) {
  if (who === undefined) return null;
  const isWorker = who.kind === 'worker';
  // The glyph goes red on a failed run — the command row's single failed-run
  // signal, replacing the standalone red glyph that used to ride alongside.
  const glyphClass = cn('h-4 w-4 shrink-0', failed ? 'text-[var(--color-phase-red)]' : 'text-foreground');
  return (
    <span
      data-testid="provenance-who"
      data-who={who.kind}
      className="inline-flex min-w-0 items-center gap-1.5"
    >
      {isWorker ? (
        <Bot data-testid="provenance-who-glyph" data-failed={failed || undefined} className={glyphClass} aria-hidden="true" />
      ) : (
        <User data-testid="provenance-who-glyph" data-failed={failed || undefined} className={glyphClass} aria-hidden="true" />
      )}
      {/* Name over model — the exact stacked shape the live MiniStatusRail
          named-worker block uses, so a completed worker fix reads identically
          (fix endcap-resumes-pipeline-runs tasks 5 + 9, user call 2026-08-10).
          Interactive work names only "Interactive"; the model line is a
          worker fact. */}
      <span className="inline-flex min-w-0 flex-col leading-tight">
        <span className="truncate text-xs font-medium text-foreground">
          {isWorker ? who.worker : 'Interactive'}
        </span>
        {isWorker && model !== undefined && (
          <span className="truncate text-[11px] text-muted-foreground">{model}</span>
        )}
      </span>
    </span>
  );
}

/**
 * The environment a REMOTE (cloud) worker ran in (user call 2026-08-10): the
 * Cloud glyph + env name over its description — the SAME glyph + stacked-text
 * shape {@link WhoAttribution} uses, so a cloud worker's where reads as a peer
 * of its who. Local work is the unmarked default (MSR rule 5) and passes no env
 * section. Renders nothing without a name.
 */
export function EnvAttribution({ name, description }: { name: string | undefined; description?: string }) {
  if (name === undefined) return null;
  return (
    <span data-testid="provenance-env" className="inline-flex min-w-0 items-center gap-1.5">
      <Cloud className="h-4 w-4 shrink-0 text-foreground" aria-hidden="true" />
      <span className="inline-flex min-w-0 flex-col leading-tight">
        <span className="truncate text-xs font-medium text-foreground">{name}</span>
        {description !== undefined && (
          <span className="truncate text-[11px] text-muted-foreground">{description}</span>
        )}
      </span>
    </span>
  );
}

/**
 * Whether {@link LandedChip} would render a chip for this delivery (vs null) —
 * so a caller placing the chip in its own slot can omit the slot entirely for a
 * branch (unmerged) delivery rather than render an empty box (adversarial
 * review of d354b3890: the fix strip's right-aligned landed slot leaked an
 * empty span on a done-unlanded fix).
 */
export function landedChipRenders(delivery: FeatureDelivery): boolean {
  return delivery.deliveredViaFix !== undefined || (delivery.landed && delivery.where.kind === 'merged');
}

/**
 * How a merged delivery reached main (fix
 * `prd-completed-feature-header-merged-pill`): the strategy-specific pill copy.
 * A merge-commit land names the commit ("merged commit to main <short-sha>"); an
 * ff land reads "ff merge to main". Everything else — a `pr` land, a merge whose
 * commit never resolved, or a land whose strategy the projection did not carry —
 * falls back to the bare "merged → main" so no landed feature renders blank.
 */
function mergedPillLabel(delivery: FeatureDelivery): string {
  if (delivery.strategy === 'merge' && delivery.mergeCommit !== undefined) {
    return `merged commit to main ${delivery.mergeCommit.slice(0, 7)}`;
  }
  if (delivery.strategy === 'ff') return 'ff merge to main';
  return 'merged → main';
}

/** The landed chip — via fix wins, then merged; a branch delivery has no chip
 *  (the branch rides inside the msr pill instead). The merged chip names HOW the
 *  work reached main (ff / merge-commit sha) per {@link mergedPillLabel}. Exported
 *  so the fix control strip can right-align it away from the LHS attribution (fix
 *  endcap-resumes-pipeline-runs task 9). */
export function LandedChip({ delivery }: { delivery: FeatureDelivery }) {
  if (delivery.deliveredViaFix !== undefined) {
    return (
      <span
        data-testid="landed-chip"
        className="inline-flex items-center gap-1 rounded-md border border-primary/40 bg-primary/10 px-1.5 py-0.5 mono text-[10px] font-semibold text-primary"
      >
        <GitPullRequestArrow className="h-3 w-3" />
        via fix {delivery.deliveredViaFix}
      </span>
    );
  }
  if (delivery.landed && delivery.where.kind === 'merged') {
    return (
      <span
        data-testid="landed-chip"
        className="inline-flex items-center gap-1 rounded-md border border-done/40 bg-done/10 px-1.5 py-0.5 mono text-[10px] font-semibold text-done"
      >
        <GitMerge className="h-3 w-3" />
        {mergedPillLabel(delivery)}
      </span>
    );
  }
  return null;
}

export default DeliveredProvenance;
