// Board-first view resolution (board-first-chrome F3/T1).
//
// The board is the sole work area. The retired kind lists (plans/fixes/spikes)
// and the absorbed In-flight view must not dead-end: each legacy `?view=` value
// resolves to the board, with the kind lists carrying their equivalent board
// `type` filter. Real non-board tabs (quality/decisions/…) pass through; an
// unknown value lands on the board and is flagged for a URL rewrite so a
// malformed deep link never blanks the workspace nor sticks as garbage.

export type WorkViewTab =
  | 'board'
  | 'quality'
  | 'decisions'
  | 'agents'
  | 'skills'
  | 'plugins'
  | 'hooks';

/** The board header type filter — 'all' plus the three work-item kinds. */
export type BoardTypeFilter = 'all' | 'fix' | 'prd' | 'spike';

/** The kind lists that fold into the board, and the board type they map to. */
const KIND_REDIRECTS: Record<string, Exclude<BoardTypeFilter, 'all'>> = {
  plans: 'prd',
  fixes: 'fix',
  spikes: 'spike',
};

/** Legacy views that fold into the board with no kind scope. */
const BOARD_REDIRECTS: readonly string[] = ['in-flight', 'setup'];

/** The real, non-board tabs that pass through unchanged. */
const PASSTHROUGH_TABS: readonly WorkViewTab[] = [
  'quality',
  'decisions',
  'agents',
  'skills',
  'plugins',
  'hooks',
];

export interface ResolvedWorkView {
  /** The effective active tab. */
  tab: WorkViewTab;
  /** The board type filter implied by a legacy kind redirect (undefined otherwise). */
  boardType?: Exclude<BoardTypeFilter, 'all'>;
  /** True when the raw `?view=` value was a legacy/unknown value the URL must be rewritten away from. */
  redirected: boolean;
}

/** Resolve one raw view string (no fallback) to a tab, or null if unrecognised. */
function classify(value: string): ResolvedWorkView | null {
  if (value === 'board') return { tab: 'board', redirected: false };
  if (value in KIND_REDIRECTS) {
    return { tab: 'board', boardType: KIND_REDIRECTS[value], redirected: true };
  }
  if (BOARD_REDIRECTS.includes(value)) return { tab: 'board', redirected: true };
  if ((PASSTHROUGH_TABS as readonly string[]).includes(value)) {
    return { tab: value as WorkViewTab, redirected: false };
  }
  return null;
}

/**
 * Resolve the effective work view from the raw `?view=` param and the stored
 * tab preference. The URL wins; the stored preference is the fallback; a bare
 * load with neither defaults to the board. A legacy kind / in-flight / setup /
 * unknown value in the URL redirects to the board (kind lists seed `?type=`); a
 * stored preference resolves to its tab but never seeds a `?type=` kind scope.
 */
export function resolveWorkView(
  viewParam: string | null,
  storedTab: string | null,
): ResolvedWorkView {
  if (viewParam) {
    // An unknown URL value is a malformed deep link — land on the board and
    // flag it so the caller rewrites the URL.
    return classify(viewParam) ?? { tab: 'board', redirected: true };
  }
  if (storedTab) {
    const resolved = classify(storedTab);
    if (!resolved) return { tab: 'board', redirected: false };
    // A stored preference is a weak "last area" signal, not an explicit deep
    // link: resolve it to its tab but never revive a `?type=` kind scope from it.
    // Seeding the type from a stored legacy kind would stick forever and could
    // not be cleared through normal use — only a URL `?view=` seeds the type.
    return { tab: resolved.tab, redirected: false };
  }
  return { tab: 'board', redirected: false };
}

/** Coerce the raw `?type=` param to a board type filter, defaulting to 'all'. */
export function coerceBoardType(typeParam: string | null): BoardTypeFilter {
  return typeParam === 'fix' || typeParam === 'prd' || typeParam === 'spike' || typeParam === 'all'
    ? typeParam
    : 'all';
}
