import React, { useState, useEffect } from 'react';
import { Label } from '../ui/label';
import { Input } from '../ui/input';
import { Key, Monitor } from 'lucide-react';
import { getStoredCredentials } from '../../services/api';

export const TinyBrainApiSection: React.FC = () => {
  const [clientId, setClientId] = useState('');
  const [clientSecret, setClientSecret] = useState('');
  const [hasStoredCredentials, setHasStoredCredentials] = useState(false);

  const checkStoredCredentials = async () => {
    try {
      const data = await getStoredCredentials();
      if (data.clientId && data.clientSecret === '[STORED]') {
        setClientId(data.clientId);
        setClientSecret('[STORED]');
        setHasStoredCredentials(true);
        return true;
      }
    } catch (err) {
      console.error('Failed to check stored credentials:', err);
    }
    return false;
  };

  useEffect(() => {
    const loadCredentials = async () => {
      const hasStored = await checkStoredCredentials();
      if (!hasStored) {
        const savedClientId = localStorage.getItem('tbl-client-id');
        const savedClientSecret = localStorage.getItem('tbl-client-secret');
        if (savedClientId) setClientId(savedClientId);
        if (savedClientSecret) setClientSecret(savedClientSecret);
      }
    };
    loadCredentials();
  }, []);

  return (
    <div className="space-y-6">
      {/* Getting Started Section - Only show if no credentials */}
      {!hasStoredCredentials && (
        <section className="rounded-2xl panel p-5 md:p-6">
          <div className="flex items-center gap-2">
            <Monitor className="h-5 w-5 text-blue" />
            <h2 className="display text-base font-semibold">Getting Started</h2>
          </div>
          <p className="mt-1 text-sm text-muted-foreground">How to obtain your Tiny Brain credentials</p>
          <ol className="mt-4 space-y-2 text-sm text-muted-foreground">
            <li>1. Visit <a href="https://tiny-brain.com" target="_blank" rel="noopener noreferrer" className="text-blue hover:underline">tiny-brain.com</a></li>
            <li>2. Sign in to your account</li>
            <li>3. Navigate to Settings → API Keys</li>
            <li>4. Generate new credentials</li>
            <li>5. Copy your Client ID and Client Secret</li>
            <li>6. Set credentials using the CLI commands below</li>
          </ol>
        </section>
      )}

      {/* Library Authentication Section */}
      <section className="rounded-2xl panel p-5 md:p-6">
        <div className="flex items-center gap-2">
          <Key className="h-5 w-5 text-done" />
          <h2 className="display text-base font-semibold">Library Authentication</h2>
        </div>
        <p className="mt-1 text-sm text-muted-foreground">
          {hasStoredCredentials
            ? 'Your credentials are securely stored in the system keychain'
            : 'Your API keys for connecting to the Tiny Brain Library'}
        </p>
        <div className="mt-4 space-y-4">
          <div className="space-y-2">
            <Label htmlFor="client-id">Client ID</Label>
            <Input
              id="client-id"
              value={clientId}
              readOnly
              placeholder="No credentials configured"
              className="font-mono bg-muted"
            />
          </div>

          <div className="space-y-2">
            <Label htmlFor="client-secret">Client Secret</Label>
            <Input
              id="client-secret"
              type="text"
              value={clientSecret}
              readOnly
              placeholder={hasStoredCredentials ? 'Secret is stored securely' : 'No secret configured'}
              className="font-mono bg-muted"
            />
          </div>

          {/* CLI instructions — design-system code block */}
          <div className="rounded-lg border border-border panel-flat p-4 font-mono text-sm">
            <p className="text-subtle"># Set credentials</p>
            <p className="text-foreground">$ tiny-brain config set clientId YOUR_ID</p>
            <p className="text-foreground">$ tiny-brain config set clientSecret YOUR_SECRET</p>
            <p className="mt-3 text-subtle"># Clear credentials</p>
            <p className="text-foreground">$ tiny-brain config clear</p>
          </div>
        </div>
      </section>
    </div>
  );
};

export default TinyBrainApiSection;
