import { useState } from 'react';
import { Bell } from 'lucide-react';
import { Sheet, SheetContent, SheetTrigger } from '../ui/sheet';
import { footerRailItemClassName } from './AppSidebar';
import { NotificationsPanel } from './NotificationsPanel';
import type { Notification } from '../../types';

interface NotificationsBellProps {
  notifications: Notification[];
}

/**
 * The sidebar-rail notifications bell. Owns the open state, shows a blue unread
 * count badge when there are notifications, and opens the notifications panel as
 * a Sheet sliding in from the left over the sidebar. Dumb with respect to data —
 * the notifications are supplied by `Layout` (from the system-notifications feed).
 */
export function NotificationsBell({ notifications }: NotificationsBellProps) {
  const [open, setOpen] = useState(false);
  const count = notifications.length;

  return (
    <Sheet open={open} onOpenChange={setOpen}>
      <SheetTrigger asChild>
        <button
          type="button"
          aria-label="Notifications"
          className={`${footerRailItemClassName(open)} relative`}
        >
          <Bell className="h-4 w-4" />
          {count > 0 && (
            <span
              data-testid="notifications-unread-indicator"
              className="absolute -top-1 -right-1 flex h-4 min-w-4 items-center justify-center rounded-full bg-blue-500 px-1 font-mono text-[10px] font-semibold text-white ring-2 ring-background"
            >
              {count > 9 ? '9+' : count}
            </span>
          )}
        </button>
      </SheetTrigger>
      <SheetContent
        side="left"
        // Stop just above the sidebar footer rail (p-3 + h-9 item ≈ 3.75rem) so
        // the collapse · notifications · settings · theme controls stay visible.
        style={{ top: 0, bottom: '3.75rem', height: 'auto' }}
        className="flex w-[440px] max-w-full flex-col gap-0 rounded-br-xl p-0"
      >
        <NotificationsPanel notifications={notifications} />
      </SheetContent>
    </Sheet>
  );
}
