/**
 * Server-Sent Events Manager
 *
 * Centralized SSE handling with automatic reconnection and type-safe event dispatch
 */

import type { Plan, Fix, RepoAnalysisFile } from '../types';
// SSE event types from core — imported for local use and re-exported for consumers
import type {
  PRDEventType,
  EventDelta,
  EventFeatureInfo,
  EventTaskInfo,
  FixEventType,
  QualityEventType,
  AnalysisEventType,
  AnalysisProgressEventType,
  SSEEventType,
  BaseSSEEvent,
  CloneScopedSSEEvent,
  ConnectedEvent,
  ReconnectedEvent,
  ErrorEvent as CoreErrorEvent,
  AnalysisProgressSSEEvent,
  RecommendationsUpdatedEvent,
  QualityChangeEvent,
  TelemetryChangeEvent,
  SpikeDocChangeEvent,
  PrdDocChangeEvent,
  FixDocChangeEvent,
} from '@magic-ingredients/tiny-brain-core';
export type {
  PRDEventType,
  EventDelta,
  EventFeatureInfo,
  EventTaskInfo,
  FixEventType,
  QualityEventType,
  AnalysisEventType,
  AnalysisProgressEventType,
  SSEEventType,
  BaseSSEEvent,
  CloneScopedSSEEvent,
  ConnectedEvent,
  ReconnectedEvent,
  AnalysisProgressSSEEvent,
  RecommendationsUpdatedEvent,
  QualityChangeEvent,
  TelemetryChangeEvent,
  SpikeDocChangeEvent,
  PrdDocChangeEvent,
  FixDocChangeEvent,
};

/**
 * Persona Change Event — uses dashboard Plan (has UI-specific fields)
 */
export interface PersonaChangeEvent extends BaseSSEEvent {
  type: 'personaChange' | 'persona-changed';
  personaId: string;
  plans?: Plan[];
  activePlanId?: string | null;
}

/**
 * Plan Change Event — uses dashboard Plan
 */
export interface PlanChangeEvent extends BaseSSEEvent {
  type: 'planChange';
  eventType?: PRDEventType;
  repoId?: string;
  prdId?: string;
  prdPath?: string;
  feature?: EventFeatureInfo;
  task?: EventTaskInfo;
  tasks?: EventTaskInfo[];
  delta?: EventDelta;
  plan?: Plan;
}

/**
 * Fix Change Event — uses dashboard Fix type (has testPlan, sourceWorktree)
 * which differs from core FixProgress (has qip). Intentional: the dashboard
 * Fix type is the canonical shape for UI rendering.
 */
export interface FixChangeEvent extends BaseSSEEvent {
  type: 'fixChange';
  eventType?: FixEventType;
  repoId?: string;
  fixId?: string;
  fix?: Fix;
  task?: Fix['tasks'][number];
  delta?: EventDelta;
}

/**
 * Analysis Change Event — uses dashboard RepoAnalysisFile
 */
export interface AnalysisChangeEvent extends BaseSSEEvent {
  type: 'analysisChange';
  eventType: AnalysisEventType;
  repoId: string;
  analysis?: RepoAnalysisFile;
  error?: string;
}

/**
 * Invalidate Event — uses dashboard Plan and Fix (typed, not any)
 */
export interface InvalidateEvent extends BaseSSEEvent {
  type: 'invalidate';
  resource: 'plan' | 'plans' | 'fix' | 'fixes';
  repoId: string;
  entities: Array<Plan | Fix>;
  worktree?: { name: string; branch: string };
}

/**
 * Status Change Event — the granular per-entity status push
 * (live-frontier-projection F3-T1). The server broadcasts `status-change`
 * when a git-ref move or a status-affecting telemetry event re-projects an
 * entity; it carries ONLY the changed fix(es)/plan(s), so the client patches
 * those by id instead of refetching. `invalidate` is reserved for content.
 */
export interface StatusChangeEvent extends BaseSSEEvent, CloneScopedSSEEvent {
  type: 'statusChange';
  resource: 'plan' | 'fix';
  repoId: string;
  entities: Array<Plan | Fix>;
}

// `SpikeDocChangeEvent` lives in core (PRD F4/T5) — re-exported above
// so the dashboard's existing single-file import shape still works.

/**
 * Review Change Event — the server broadcasts `review-change` when
 * `reviews/pending.json` or a `reviews/decided/<gate>/<sha>.json` file changes
 * (fix `dashboard-drops-filewatcher-sse-events`, Task 3). The reviews surface
 * listens via `useReviewLive` and refetches. `gate`/`sha` are present only for
 * the `decided` kind.
 */
export interface ReviewChangeEvent extends BaseSSEEvent, CloneScopedSSEEvent {
  type: 'reviewChange';
  repoId: string;
  kind: 'pending' | 'decided';
  changeType?: string;
  gate?: string;
  sha?: string;
}

/**
 * Run Change Event — the server broadcasts `run-change` when a run record
 * under <git-common-dir>/tiny-brain/runs/ is written: a dispatch creates it,
 * a status transition rewrites it, a prune deletes it (fix
 * `run-dispatch-stale-dashboard`). The in-flight board and the plans list
 * listen via `useRunLive` and refetch so a dispatched run appears (and the
 * feature rail swaps Launch for the Running pill) without a reload.
 */
export interface RunChangeEvent extends BaseSSEEvent, CloneScopedSSEEvent {
  type: 'runChange';
  repoId: string;
  runId: string;
  changeType?: string;
}

/**
 * Validation Change Event — the server broadcasts a SCOPED `validation-change`
 * (work-item-detail-service-rewrite / live-run-overlay task 1) when an item's
 * server-recomputed validation phase actually MOVES on a run-record change. It
 * carries ONLY the item's identity — no derived validation — so the open detail
 * pane re-pulls the finished server payload (`useBoardItemDetail`) rather than
 * re-deriving the phase client-side. `resource` mirrors `statusChange`'s
 * discriminant (`fix` <-> `fix`, PRD <-> `plan`); `feature` is present for a
 * PRD-feature scope.
 */
export interface ValidationChangeEvent extends BaseSSEEvent, CloneScopedSSEEvent {
  type: 'validationChange';
  repoId: string;
  resource: 'plan' | 'fix';
  id: string;
  feature?: string;
}

/**
 * Pipeline Change Event — the server broadcasts a repo-scoped `pipeline-change`
 * when `.tiny-brain/config.json` is edited (work-item-detail-service-rewrite /
 * props-in-ui). The repo-constant validation pipeline row defs the board ships
 * (`pipelines`) are a pure function of that config, so a board must refetch to
 * rebuild its validation-control skeleton. Repo-scoped only — the defs are
 * identical for every item, so there is no per-item identity to carry.
 */
export interface PipelineChangeEvent extends BaseSSEEvent, CloneScopedSSEEvent {
  type: 'pipelineChange';
  repoId: string;
}

/**
 * Repo Registered Event — the server broadcasts `repo-registered` when a new
 * repository is registered (fix `dashboard-drops-filewatcher-sse-events`,
 * Task 4). The repos list listens via `useRepoRegisteredLive` and refetches so
 * the new repo appears without a manual reload.
 */
export interface RepoRegisteredEvent extends BaseSSEEvent {
  type: 'repoRegistered';
  repoId: string;
  repoName?: string;
  repoPath?: string;
}

export type SSEEvent = PersonaChangeEvent | PlanChangeEvent | FixChangeEvent | InvalidateEvent | StatusChangeEvent | QualityChangeEvent | AnalysisChangeEvent | AnalysisProgressSSEEvent | RecommendationsUpdatedEvent | TelemetryChangeEvent | SpikeDocChangeEvent | PrdDocChangeEvent | FixDocChangeEvent | ReviewChangeEvent | RunChangeEvent | ValidationChangeEvent | PipelineChangeEvent | RepoRegisteredEvent | ConnectedEvent | ReconnectedEvent | CoreErrorEvent;

class SSEManager {
  private eventSource: EventSource | null = null;
  private listeners: Map<SSEEventType, Set<(_event: SSEEvent) => void>> = new Map();
  private reconnectAttempts = 0;
  private reconnectDelay = 1000;
  private isConnected = false;
  private url: string;
  private isConnecting = false;
  /** The pending backoff timer, cancelled when a wake event reconnects early. */
  private reconnectTimer: ReturnType<typeof setTimeout> | null = null;
  /** True once any connection has dropped — the next open dispatches `reconnected`. */
  private everDropped = false;
  /** The reload hook for a stale-bundle hello (see constructor doc). */
  private readonly reloadStalePage: () => void;
  /** The build id from this page's FIRST hello — later hellos must match. */
  private knownBuildId: string | undefined;
  /** Reload at most once per page lifetime: the reload is async, and a server
   *  minting per-connection ids (a server-side bug) must degrade to one
   *  reload, never a loop. */
  private staleReloadFired = false;
  /** Bound wake handler, held so disconnect() can unregister it. */
  private readonly wake = () => {
    if (this.isConnected || this.isConnecting) return;
    if (typeof document !== 'undefined' && document.visibilityState === 'hidden') return;
    if (this.reconnectTimer !== null) {
      clearTimeout(this.reconnectTimer);
      this.reconnectTimer = null;
    }
    // A wake is a fresh start: reset the attempt counter with the delay so the
    // logged attempt number cannot drift out of step with the backoff.
    this.reconnectAttempts = 0;
    this.reconnectDelay = 1000;
    this.connect();
  };

  constructor(url = '/events', options?: {
    /**
     * Invoked when a reconnect hello carries a DIFFERENT build id than the
     * one this page booted with — the page's code is stale and must reload
     * (fix stale-bundle-tabs-survive-server-restart). Injectable for tests;
     * defaults to a full page reload.
     */
    reloadStalePage?: () => void;
  }) {
    this.url = url;
    this.reloadStalePage = options?.reloadStalePage ?? (() => {
      if (typeof window !== 'undefined') window.location.reload();
    });
    // Wake moments (fix sse-client-gives-up-and-never-resyncs task 1): a tab
    // coming back to visibility or a network returning are exactly when a
    // slept laptop / recovered link should reconnect NOW, not after whatever
    // backoff window is pending. A live connection is left alone.
    if (typeof document !== 'undefined') document.addEventListener('visibilitychange', this.wake);
    if (typeof window !== 'undefined') window.addEventListener('online', this.wake);
    this.connect();
  }

  getCurrentState() {
    return {
      isConnected: this.isConnected,
      libraryConnected: null as number | null
    };
  }

  private connect() {
    // Prevent multiple simultaneous connections
    if (this.isConnecting || this.isConnected) {
      console.log('[SSE] Already connected or connecting, skipping...');
      return;
    }
    
    if (this.eventSource) {
      this.eventSource.close();
    }

    this.isConnecting = true;
    console.log('[SSE] 🔌 Connecting to', this.url);
    this.eventSource = new EventSource(this.url);

    this.eventSource.onopen = () => {
      console.log('[SSE] ✅ Connected successfully');
      this.isConnected = true;
      this.isConnecting = false;
      this.reconnectAttempts = 0;
      this.reconnectDelay = 1000;
      // Resync signal (fix sse-client-gives-up-and-never-resyncs task 2): SSE
      // has no replay, so an open that follows ANY drop means events may have
      // been missed — tell consumers to refetch. Never fired on a clean first
      // connect (nothing existed to miss).
      if (this.everDropped) {
        this.dispatch({ type: 'reconnected', timestamp: new Date().toISOString() });
      }
    };

    // Listen for the 'connected' event specifically
    this.eventSource.addEventListener('connected', (event: MessageEvent) => {
      try {
        const data = JSON.parse(event.data);
        // Stale-bundle detection (fix stale-bundle-tabs-survive-server-
        // restart): the FIRST hello's build id is this page's identity; a
        // later hello disagreeing means the server was rebuilt and this tab
        // is executing old code — data resync cannot fix that, only a
        // reload can. A hello with no id (older server) never reloads.
        const buildId = typeof data.buildId === 'string' && data.buildId !== '' ? data.buildId : undefined;
        if (buildId !== undefined) {
          if (this.knownBuildId === undefined) {
            this.knownBuildId = buildId;
          } else if (this.knownBuildId !== buildId) {
            if (!this.staleReloadFired) {
              this.staleReloadFired = true;
              console.log(`[SSE] 🔁 Server bundle changed (${this.knownBuildId} → ${buildId}) — reloading stale page`);
              this.reloadStalePage();
            }
            // DELIBERATE: no connected dispatch on the stale path. The page
            // is about to reload — telling consumers "connected" would kick
            // off refetches whose results the reload throws away.
            return;
          }
        }
        const connectedEvent: ConnectedEvent = {
          type: 'connected',
          timestamp: new Date().toISOString(),
          libraryConnected: data.libraryConnected ?? 401
        };

        console.log('[SSE] 🔗 Connected to server');
        console.log(`[SSE]    Library status: ${connectedEvent.libraryConnected}`);

        this.dispatch(connectedEvent);
      } catch (error) {
        console.error('[SSE] ❌ Failed to parse connected event:', error, event.data);
      }
    });

    // Listen for 'persona-changed' events
    this.eventSource.addEventListener('persona-changed', (event: MessageEvent) => {
      try {
        const data = JSON.parse(event.data);
        const personaEvent: PersonaChangeEvent = {
          type: 'persona-changed',
          timestamp: data.timestamp || new Date().toISOString(),
          personaId: data.personaId,
          plans: data.plans,
          activePlanId: data.activePlanId
        };

        console.log(`[SSE] 👤 Persona changed to '${personaEvent.personaId}'`);

        this.dispatch(personaEvent);
      } catch (error) {
        console.error('[SSE] ❌ Failed to parse persona-changed event:', error, event.data);
      }
    });

    // Listen for 'persona-switched' events — the API persona-switch route's
    // event name (the MCP relay uses 'persona-changed'). Normalize to a
    // persona-changed dispatch so the same subscribers fire in standalone mode
    // (fix dashboard-drops-filewatcher-sse-events T5).
    this.eventSource.addEventListener('persona-switched', (event: MessageEvent) => {
      try {
        const data = JSON.parse(event.data);
        const personaEvent: PersonaChangeEvent = {
          type: 'persona-changed',
          timestamp: data.timestamp || new Date().toISOString(),
          personaId: data.personaId,
          plans: data.plans,
          activePlanId: data.activePlanId,
        };
        this.dispatch(personaEvent);
      } catch (error) {
        console.error('[SSE] ❌ Failed to parse persona-switched event:', error, event.data);
      }
    });

    // Listen for 'repo-starred-changed' events — bridge the server broadcast to
    // the in-tab `repo-starred-changed` window CustomEvent so every connected
    // tab refetches its star state (cross-tab sync; fix
    // dashboard-drops-filewatcher-sse-events T5). The existing window-event
    // consumers (ReposPage, StarredReposSection) already refetch on this event.
    // The originating tab also receives the broadcast and harmlessly refetches
    // once more (no loop — the consumers only fetch, they don't re-broadcast).
    this.eventSource.addEventListener('repo-starred-changed', (event: MessageEvent) => {
      try {
        const data = JSON.parse(event.data);
        window.dispatchEvent(new CustomEvent('repo-starred-changed', { detail: data }));
      } catch (error) {
        console.error('[SSE] ❌ Failed to parse repo-starred-changed event:', error, event.data);
      }
    });

    // Listen for 'plan-change' events
    this.eventSource.addEventListener('plan-change', (event: MessageEvent) => {
      try {
        const data = JSON.parse(event.data);
        const planEvent: PlanChangeEvent = {
          type: 'planChange',
          timestamp: data.timestamp || new Date().toISOString(),
          eventType: data.eventType,
          repoId: data.repoId,
          prdId: data.prdId,
          prdPath: data.prdPath,
          feature: data.feature,
          task: data.task,
          tasks: data.tasks,
          delta: data.delta,
          plan: data.plan
        };

        // Enhanced logging for granular events
        if (planEvent.eventType) {
          const eventTypeLabel = {
            'prd:created': '🆕 PRD Created',
            'prd:feature:added': '➕ Feature Added',
            'prd:feature:updated': '🔄 Feature Updated',
            'prd:feature:tasks:added': '📝 Tasks Added',
            'prd:feature:task:completed': '✅ Task Completed',
            'prd:feature:task:updated': '🔧 Task Updated'
          }[planEvent.eventType] || '📋 Plan Change';

          console.log(`[SSE] ${eventTypeLabel}: ${planEvent.prdId}`);
        } else {
          console.log(`[SSE] 📋 Plan Change`);
        }
        if (planEvent.feature) {
          console.log(`[SSE]    Feature: ${planEvent.feature.title} (${planEvent.feature.status})`);
        }
        if (planEvent.task) {
          console.log(`[SSE]    Task: ${planEvent.task.description}`);
        }
        if (planEvent.tasks && planEvent.tasks.length > 0) {
          console.log(`[SSE]    Tasks added: ${planEvent.tasks.length}`);
        }
        if (planEvent.delta) {
          if (planEvent.delta.tasksAdded) console.log(`[SSE]    +${planEvent.delta.tasksAdded} tasks`);
          if (planEvent.delta.tasksCompleted) console.log(`[SSE]    ✓${planEvent.delta.tasksCompleted} tasks`);
        }

        this.dispatch(planEvent);
      } catch (error) {
        console.error('[SSE] ❌ Failed to parse plan-change event:', error, event.data);
      }
    });

    // Listen for 'prd-doc-change' events (file watcher — PRD/feature
    // markdown edits). Two consumers: the per-repo detail view refetches
    // on the dispatched `prdDocChange`; the granular `useSSE` plan
    // reducers update in place via a normalized `planChange` event for
    // the feature:created/updated sub-types (which carry the tasks).
    this.eventSource.addEventListener('prd-doc-change', (event: MessageEvent) => {
      try {
        const data = JSON.parse(event.data);
        const docEvent: PrdDocChangeEvent = {
          type: 'prdDocChange',
          timestamp: data.timestamp || new Date().toISOString(),
          eventType: data.eventType,
          repoId: data.repoId,
          ...(data.prdId ? { prdId: data.prdId } : {}),
        };

        console.log(`[SSE] 📄 PRD Doc Change: ${docEvent.eventType} (${docEvent.prdId ?? '?'})`);
        this.dispatch(docEvent);

        // Normalize the feature sub-types onto the granular plan-change
        // channel so the existing useSSE reducers apply them, carrying
        // the payload tasks (the wire eventType differs from the client
        // switch names: feature:created → prd:feature:added, etc.).
        const normalized: Record<string, PRDEventType> = {
          'feature:created': 'prd:feature:added',
          'feature:updated': 'prd:feature:updated',
        };
        const planEventType = normalized[data.eventType];
        if (planEventType && data.prdId) {
          const planEvent: PlanChangeEvent = {
            type: 'planChange',
            timestamp: docEvent.timestamp,
            eventType: planEventType,
            repoId: data.repoId,
            prdId: data.prdId,
            feature: data.feature,
            tasks: data.tasks,
          };
          this.dispatch(planEvent);
        }
      } catch (error) {
        console.error('[SSE] ❌ Failed to parse prd-doc-change event:', error, event.data);
      }
    });

    // Listen for 'fix-doc-change' events (file watcher — fix markdown
    // edits). The per-repo detail view refetches its fixes on the
    // dispatched `fixDocChange`. (Replaces the dead `fix-change`
    // listener the server never broadcast.)
    this.eventSource.addEventListener('fix-doc-change', (event: MessageEvent) => {
      try {
        const data = JSON.parse(event.data);
        const docEvent: FixDocChangeEvent = {
          type: 'fixDocChange',
          timestamp: data.timestamp || new Date().toISOString(),
          eventType: data.eventType,
          repoId: data.repoId,
          ...(data.fixId ? { fixId: data.fixId } : {}),
        };

        console.log(`[SSE] 🐛 Fix Doc Change: ${docEvent.eventType} (${docEvent.fixId ?? '?'})`);
        this.dispatch(docEvent);
      } catch (error) {
        console.error('[SSE] ❌ Failed to parse fix-doc-change event:', error, event.data);
      }
    });

    // Listen for 'status-change' events — the granular per-entity status push
    // from the file watcher (live-frontier-projection F3-T1). Carries only the
    // changed fix(es)/plan(s); the client patches them by id.
    this.eventSource.addEventListener('status-change', (event: MessageEvent) => {
      try {
        const data = JSON.parse(event.data);
        const statusEvent: StatusChangeEvent = {
          type: 'statusChange',
          timestamp: data.timestamp || new Date().toISOString(),
          resource: data.resource,
          repoId: data.repoId,
          repoIds: data.repoIds,
          entities: data.entities || [],
        };

        console.log(`[SSE] 🔄 Status change: ${statusEvent.resource} (${statusEvent.entities.length} entities) for repo ${statusEvent.repoId}`);
        this.dispatch(statusEvent);
      } catch (error) {
        console.error('[SSE] ❌ Failed to parse status-change event:', error, event.data);
      }
    });

    // Listen for 'analysis-progress' events (streaming progress during analysis)
    this.eventSource.addEventListener('analysis-progress', (event: MessageEvent) => {
      try {
        const data = JSON.parse(event.data);
        const progressEvent: AnalysisProgressSSEEvent = {
          type: 'analysisProgress',
          timestamp: data.timestamp || new Date().toISOString(),
          eventType: data.eventType,
          repoId: data.repoId,
          message: data.message,
          data: data.data
        };

        // Enhanced logging for progress events
        const stepLabels: Record<string, string> = {
          'analysis:started': '🚀 Started',
          'analysis:tech-detection': '🔍 Detecting tech stack',
          'analysis:writing-file': '📝 Writing analysis.json',
          'analysis:fetching-contexts': '📥 Fetching tech contexts',
          'analysis:syncing-agents': '🔄 Syncing agents',
          'analysis:detecting-analyzers': '🔬 Detecting analyzers',
          'analysis:complete': '✅ Complete',
          'analysis:failed': '❌ Failed'
        };
        const label = stepLabels[progressEvent.eventType] || progressEvent.eventType;
        console.log(`[SSE] Analysis Progress: ${label}`);

        this.dispatch(progressEvent);
      } catch (error) {
        console.error('[SSE] ❌ Failed to parse analysis-progress event:', error, event.data);
      }
    });

    // Listen for 'analysis-change' events (final completion/failure)
    this.eventSource.addEventListener('analysis-change', (event: MessageEvent) => {
      try {
        const data = JSON.parse(event.data);
        const analysisEvent: AnalysisChangeEvent = {
          type: 'analysisChange',
          timestamp: data.timestamp || new Date().toISOString(),
          eventType: data.eventType,
          repoId: data.repoId,
          analysis: data.analysis,
          error: data.error
        };

        // Enhanced logging for analysis events
        const eventTypeLabel = analysisEvent.eventType === 'analysis:complete'
          ? '✅ Analysis Complete'
          : '❌ Analysis Failed';

        console.log(`[SSE] ${eventTypeLabel}: ${analysisEvent.repoId}`);
        if (analysisEvent.error) {
          console.log(`[SSE]    Error: ${analysisEvent.error}`);
        }

        this.dispatch(analysisEvent);
      } catch (error) {
        console.error('[SSE] ❌ Failed to parse analysis-change event:', error, event.data);
      }
    });

    // Listen for 'quality-change' events
    this.eventSource.addEventListener('quality-change', (event: MessageEvent) => {
      try {
        const data = JSON.parse(event.data);
        const qualityEvent: QualityChangeEvent = {
          type: 'qualityChange',
          timestamp: data.timestamp || new Date().toISOString(),
          eventType: data.eventType,
          repoId: data.repoId,
          repoIds: data.repoIds,
          runId: data.runId,
          run: data.run
        };

        const eventLabels: Record<string, string> = {
          'quality:created': '🆕 Quality Run Created',
          'quality:updated': '🔄 Quality Run Updated',
          'quality:deleted': '🗑️ Quality Run Deleted'
        };
        const label = qualityEvent.eventType ? (eventLabels[qualityEvent.eventType] || '📊 Quality Change') : '📊 Quality Change';
        console.log(`[SSE] ${label}: ${qualityEvent.runId}`);

        this.dispatch(qualityEvent);
      } catch (error) {
        console.error('[SSE] ❌ Failed to parse quality-change event:', error, event.data);
      }
    });

    // Listen for 'recommendations-updated' events
    this.eventSource.addEventListener('recommendations-updated', (event: MessageEvent) => {
      try {
        const data = JSON.parse(event.data);
        const recsEvent: RecommendationsUpdatedEvent = {
          type: 'recommendationsUpdated',
          timestamp: data.timestamp || new Date().toISOString(),
          repoId: data.repoId,
          added: data.added,
          updated: data.updated,
        };

        console.log(`[SSE] 📦 Recommendations Updated: ${recsEvent.repoId} (+${recsEvent.added} new, ${recsEvent.updated} updated)`);

        this.dispatch(recsEvent);
      } catch (error) {
        console.error('[SSE] ❌ Failed to parse recommendations-updated event:', error, event.data);
      }
    });

    // Listen for 'spike-doc-change' events (PRD F4/T5 — spike md
    // signals the detail page to refetch the projection).
    this.eventSource.addEventListener('spike-doc-change', (event: MessageEvent) => {
      try {
        const data = JSON.parse(event.data);
        const sde: SpikeDocChangeEvent = {
          type: 'spikeDocChange',
          timestamp: data.timestamp || new Date().toISOString(),
          eventType: data.eventType,
          repoId: data.repoId,
          spikeId: data.spikeId,
          ...(data.worktree ? { worktree: data.worktree } : {}),
          ...(data.filePath ? { filePath: data.filePath } : {}),
        };
        this.dispatch(sde);
      } catch (error) {
        console.error('[SSE] ❌ Failed to parse spike-doc-change event:', error, event.data);
      }
    });

    // Listen for 'review-change' events (fix dashboard-drops-filewatcher-sse-events
    // T3 — reviews/ changes signal the reviews surface to refetch).
    this.eventSource.addEventListener('review-change', (event: MessageEvent) => {
      try {
        const data = JSON.parse(event.data);
        const reviewEvent: ReviewChangeEvent = {
          type: 'reviewChange',
          timestamp: data.timestamp || new Date().toISOString(),
          repoId: data.repoId,
          repoIds: data.repoIds,
          kind: data.kind,
          ...(data.changeType ? { changeType: data.changeType } : {}),
          ...(data.gate ? { gate: data.gate } : {}),
          ...(data.sha ? { sha: data.sha } : {}),
        };
        this.dispatch(reviewEvent);
      } catch (error) {
        console.error('[SSE] ❌ Failed to parse review-change event:', error, event.data);
      }
    });

    // Listen for 'run-change' events (fix run-dispatch-stale-dashboard —
    // a run record write signals the in-flight board and the plans list
    // to refetch, so a dispatch / status transition shows without a reload).
    this.eventSource.addEventListener('run-change', (event: MessageEvent) => {
      try {
        const data = JSON.parse(event.data);
        const runEvent: RunChangeEvent = {
          type: 'runChange',
          timestamp: data.timestamp || new Date().toISOString(),
          repoId: data.repoId,
          repoIds: data.repoIds,
          runId: data.runId,
          ...(data.changeType ? { changeType: data.changeType } : {}),
        };
        this.dispatch(runEvent);
      } catch (error) {
        console.error('[SSE] ❌ Failed to parse run-change event:', error, event.data);
      }
    });

    // Listen for 'validation-change' events (live-run-overlay task 1 — a scoped,
    // gated invalidation when the named item's recomputed validation phase moved;
    // the open detail pane re-pulls the finished server payload).
    this.eventSource.addEventListener('validation-change', (event: MessageEvent) => {
      try {
        const data = JSON.parse(event.data);
        const validationEvent: ValidationChangeEvent = {
          type: 'validationChange',
          timestamp: data.timestamp || new Date().toISOString(),
          repoId: data.repoId,
          repoIds: data.repoIds,
          resource: data.resource,
          id: data.id,
          ...(data.feature ? { feature: data.feature } : {}),
        };
        this.dispatch(validationEvent);
      } catch (error) {
        console.error('[SSE] ❌ Failed to parse validation-change event:', error, event.data);
      }
    });

    this.eventSource.addEventListener('pipeline-change', (event: MessageEvent) => {
      try {
        const data = JSON.parse(event.data);
        const pipelineEvent: PipelineChangeEvent = {
          type: 'pipelineChange',
          timestamp: data.timestamp || new Date().toISOString(),
          repoId: data.repoId,
          repoIds: data.repoIds,
        };
        this.dispatch(pipelineEvent);
      } catch (error) {
        console.error('[SSE] ❌ Failed to parse pipeline-change event:', error, event.data);
      }
    });

    // Listen for 'repo-registered' events (fix dashboard-drops-filewatcher-sse-events
    // T4 — a new repo registration signals the repos list to refetch).
    this.eventSource.addEventListener('repo-registered', (event: MessageEvent) => {
      try {
        const data = JSON.parse(event.data);
        const repoEvent: RepoRegisteredEvent = {
          type: 'repoRegistered',
          timestamp: data.timestamp || new Date().toISOString(),
          repoId: data.repoId,
          ...(data.repoName ? { repoName: data.repoName } : {}),
          ...(data.repoPath ? { repoPath: data.repoPath } : {}),
        };
        this.dispatch(repoEvent);
      } catch (error) {
        console.error('[SSE] ❌ Failed to parse repo-registered event:', error, event.data);
      }
    });

    // Listen for 'telemetry-change' events
    this.eventSource.addEventListener('telemetry-change', (event: MessageEvent) => {
      try {
        const data = JSON.parse(event.data);
        const telEvent: TelemetryChangeEvent = {
          type: 'telemetryChange',
          timestamp: data.timestamp || new Date().toISOString(),
          repoId: data.repoId,
          repoIds: data.repoIds,
          event: data.event,
        };

        this.dispatch(telEvent);
      } catch (error) {
        console.error('[SSE] ❌ Failed to parse telemetry-change event:', error, event.data);
      }
    });

    this.eventSource.onmessage = (event) => {
      try {
        const data: SSEEvent = JSON.parse(event.data);
        console.log('[SSE] Received event:', data.type);
        this.dispatch(data);
      } catch (error) {
        console.error('[SSE] ❌ Failed to parse event:', error, event.data);
      }
    };

    this.eventSource.onerror = (error) => {
      console.error('[SSE] ❌ Connection error - Is the plan watcher running?');
      console.error('[SSE]    Error details:', error);
      this.isConnected = false;
      this.everDropped = true;
      // An error can arrive MID-CONNECT (server down: the source errors without
      // ever opening). Leaving isConnecting set made every scheduled retry a
      // silent no-op — the loop died on the first failed reconnect (fix
      // sse-client-gives-up-and-never-resyncs task 1).
      this.isConnecting = false;
      this.eventSource?.close();

      // Dispatch error event
      this.dispatch({
        type: 'error',
        timestamp: new Date().toISOString(),
        error: 'Connection lost - Plan watcher may not be running'
      });

      // Reconnect FOREVER with capped backoff: connection loss is routine for
      // a long-lived tab (server restarts, deploys, laptop sleep) — an attempt
      // cap turns every one of those into a permanently dead dashboard. The
      // wake listeners (visibility/online) reconnect early when the moment
      // arrives; this timer is the patient fallback.
      const delay = this.reconnectDelay;
      console.log(`[SSE] Reconnecting in ${delay}ms (attempt ${this.reconnectAttempts + 1})`);
      if (this.reconnectTimer !== null) clearTimeout(this.reconnectTimer);
      this.reconnectTimer = setTimeout(() => {
        this.reconnectTimer = null;
        this.reconnectAttempts++;
        this.reconnectDelay = Math.min(this.reconnectDelay * 2, 30000);
        this.connect();
      }, delay);
    };
  }

  private dispatch(event: SSEEvent) {
    const listeners = this.listeners.get(event.type);
    if (listeners) {
      listeners.forEach(listener => {
        try {
          listener(event);
        } catch (error) {
          console.error('[SSE] Listener error:', error);
        }
      });
    }
    
    // Also dispatch to wildcard listeners
    const wildcardListeners = this.listeners.get('*' as SSEEventType);
    if (wildcardListeners) {
      wildcardListeners.forEach(listener => {
        try {
          listener(event);
        } catch (error) {
          console.error('[SSE] Wildcard listener error:', error);
        }
      });
    }
  }

  /**
   * Subscribe to SSE events
   * @param eventType The type of event to listen for (or '*' for all events)
   * @param listener The callback function
   * @returns Unsubscribe function
   */
  on(eventType: SSEEventType | '*', listener: (_event: SSEEvent) => void): () => void {
    const key = eventType as SSEEventType;
    if (!this.listeners.has(key)) {
      this.listeners.set(key, new Set());
    }
    this.listeners.get(key)!.add(listener);
    
    // Return unsubscribe function
    return () => {
      this.listeners.get(key)?.delete(listener);
    };
  }

  /**
   * Close the SSE connection
   */
  disconnect() {
    // A deliberate disconnect also cancels any pending retry AND the wake
    // listeners — otherwise the backoff timer or a later visibility/online
    // event would resurrect the connection the caller just closed.
    if (this.reconnectTimer !== null) {
      clearTimeout(this.reconnectTimer);
      this.reconnectTimer = null;
    }
    if (typeof document !== 'undefined') document.removeEventListener('visibilitychange', this.wake);
    if (typeof window !== 'undefined') window.removeEventListener('online', this.wake);
    if (this.eventSource) {
      console.log('[SSE] Disconnecting');
      this.eventSource.close();
      this.eventSource = null;
      this.isConnected = false;
      this.isConnecting = false;
    }
  }

  /**
   * Manually reconnect
   */
  reconnect() {
    this.reconnectAttempts = 0;
    this.connect();
  }

  /**
   * Check if connected
   */
  getIsConnected(): boolean {
    return this.isConnected;
  }
}

