import { useState } from 'react';
import { Check, Copy } from 'lucide-react';
import {
  Tooltip,
  TooltipContent,
  TooltipTrigger,
} from './ui/tooltip';

export interface SpikeLaunchSnippetProps {
  path: string;
  spikeId: string;
}

const COPIED_FEEDBACK_MS = 2000;
const ACCESSIBLE_DESCRIPTION =
  'Copy launch command to clipboard — opens Claude in the spike worktree and resumes the spike doc';

function buildLaunchCommand(path: string, spikeId: string): string {
  // Single-quote the path to neutralise spaces and shell metacharacters.
  // A literal single quote inside a single-quoted string has to be closed,
  // escaped, and reopened — `'\''` — otherwise a path containing `'`
  // would terminate the quoting early and turn into command injection
  // the moment a user pastes the snippet into a shell.
  const quotedPath = `'${path.replace(/'/g, "'\\''")}'`;
  return `cd ${quotedPath} && claude "Continue the spike at docs/prd/${spikeId}/spike.md"`;
}

/**
 * Copy-only affordance for the spike worktree launch command. The full
 * command itself is intentionally hidden — it's noise on the detail
 * pane, and the user's intent at this point is "give me a runnable
 * snippet" not "let me read it character by character." The tooltip
 * spells out what gets copied for users who need that confirmation.
 */
export function SpikeLaunchSnippet({ path, spikeId }: SpikeLaunchSnippetProps) {
  const [copied, setCopied] = useState(false);
  const command = buildLaunchCommand(path, spikeId);

  const handleCopy = async () => {
    try {
      await navigator.clipboard.writeText(command);
      setCopied(true);
      setTimeout(() => setCopied(false), COPIED_FEEDBACK_MS);
    } catch {
      // Clipboard rejects in non-secure contexts and some sandboxed
      // iframes. Degrade quietly — must not flip into "Copied", which
      // would mislead the user into thinking the paste is ready.
    }
  };

  return (
    <Tooltip>
      <TooltipTrigger asChild>
        <button
          type="button"
          onClick={handleCopy}
          aria-label={ACCESSIBLE_DESCRIPTION}
          className="inline-flex items-center gap-1.5 px-3 py-1.5 text-xs font-medium rounded-md bg-blue-100 dark:bg-blue-800 text-blue-700 dark:text-blue-200 hover:bg-blue-200 dark:hover:bg-blue-700 border border-blue-300 dark:border-blue-600 transition-colors"
        >
          {copied ? (
            <>
              <Check className="h-3.5 w-3.5" />
              Copied
            </>
          ) : (
            <>
              <Copy className="h-3.5 w-3.5" />
              Copy launch command
            </>
          )}
        </button>
      </TooltipTrigger>
      <TooltipContent>{ACCESSIBLE_DESCRIPTION}</TooltipContent>
    </Tooltip>
  );
}
