import type { ReactNode } from 'react';
import { ChevronRight } from 'lucide-react';
import { cn } from '@/lib/utils';

/**
 * A collapsible section wearing the PRD feature-division "eyebrow" header
 * (PlanDetailsPRD's `FeatureStatusGroup`): a mono-uppercase `eyebrow` label with
 * a rotating chevron, a 7px round accent dot, an optional `· count`, and a rule
 * line filling the row — NOT the bold-title + icon accordion of the shared
 * `CollapsibleSection` (which the worktree island keeps). The Done-state
 * FixDetail groups Resolution / Validation / Work with this so its divisions read
 * exactly like a PRD's.
 *
 * The section is a labelled `region` (the outer `<section aria-label>`) and the
 * toggle is a button named `Toggle <label> section` carrying `aria-expanded`, so
 * it is queryable and accessible; the body renders only when open.
 */
export function EyebrowSection({
  label,
  accent,
  count,
  open,
  onToggle,
  children,
}: {
  label: string;
  /** The eyebrow's dot + label colour — a CSS colour/var expression. */
  accent: string;
  /** Optional trailing `· {count}` in the muted tone, as the PRD groups show. */
  count?: number;
  open: boolean;
  onToggle: () => void;
  children: ReactNode;
}) {
  return (
    <section aria-label={label} className="space-y-3">
      <button
        type="button"
        aria-expanded={open}
        aria-label={`Toggle ${label} section`}
        onClick={onToggle}
        className="eyebrow flex w-full items-center gap-2 text-[10px] text-subtle transition-colors hover:text-foreground"
      >
        <ChevronRight
          className={cn('h-3.5 w-3.5 shrink-0 text-border-strong transition-transform', open && 'rotate-90')}
          aria-hidden="true"
        />
        <span
          aria-hidden="true"
          className="h-[7px] w-[7px] shrink-0 rounded-full"
          style={{ background: accent }}
        />
        <span className="shrink-0" style={{ color: accent }}>
          {label}
          {count !== undefined && <span className="text-muted-foreground"> · {count}</span>}
        </span>
        <span aria-hidden="true" className="ml-1 flex-1 border-t border-border" />
      </button>
      {open && <div>{children}</div>}
    </section>
  );
}
