import React, { useState } from 'react';
import { Cloud, HardDrive, Plus, Trash2, RefreshCw, Terminal } from 'lucide-react';
import { Button } from '../components/ui/button';
import { FieldLabel } from '../components/ui/field-label';
import { ProviderGlyph } from '../components/icons/provider-glyphs';
import { HeaderActions } from '../components/layout/header-actions';
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from '../components/ui/alert-dialog';
import { sharedReferencePreview } from '../utils/key-reference-preview';
import {
  useEnvironments,
  type CreateEnvironmentInput,
  type EnvironmentView,
  type SandboxProviderView,
} from '../hooks/useEnvironments';
import { useEnvironmentSmokeTest } from '../hooks/useEnvironmentSmokeTest';

/**
 * Execution › Environments — the global surface over /api/environments
 * (workers PRD, environments-registry task 5; layout unified with the
 * Workers page by fix worker-env-pages-table-and-click-to-edit).
 *
 * An environment is where workers run: configure a provider once — connect
 * the account, reference the keys — then attach it to any worker. It is
 * repo-agnostic and work-agnostic; only a run binds a work item in a repo
 * to a worker on an environment. The page mirrors the Workers shape: a
 * table beside an ALWAYS-VISIBLE draft panel serving create and edit —
 * clicking a row loads it into the panel (no edit glyph). A connect-needed
 * row keeps the terminal handoff (copyable command + Re-check) beneath it.
 * The UI stays dumb: it POSTs/PUTs raw fields for the server to validate.
 */

const statusPill: Record<EnvironmentView['connection']['status'], { label: string; cls: string }> = {
  ready: {
    label: 'Ready',
    cls: 'bg-[color-mix(in_oklab,var(--ds-done)_16%,transparent)] text-[var(--ds-done)]',
  },
  'connect-needed': {
    label: 'Setup needed',
    cls: 'bg-[color-mix(in_oklab,var(--ds-warn,orange)_16%,transparent)] text-[var(--ds-warn,orange)]',
  },
  unavailable: {
    label: 'Not available',
    cls: 'bg-[color-mix(in_oklab,var(--ds-fg)_8%,transparent)] text-muted-foreground',
  },
};

const ConnectionPill: React.FC<{ connection: EnvironmentView['connection'] }> = ({ connection }) => {
  const pill = statusPill[connection.status];
  return (
    <span className={`eyebrow rounded-md px-2 py-0.5 text-[10px] ${pill.cls}`}>{pill.label}</span>
  );
};

/**
 * The BYOK connect handoff: `railway login` is interactive and
 * terminal-bound, so the honest move is a copyable command plus a manual
 * Re-check — the dashboard reads the session, it never signs in for you.
 */
const ConnectNeeded: React.FC<{ instruction: string; onRecheck: () => void }> = ({
  instruction,
  onRecheck,
}) => (
  <div className="mb-3 rounded-xl border border-[var(--ds-border)] p-3">
    <p className="text-xs text-muted-foreground">
      Not signed in. Run this in your terminal — it opens your browser to authorise; the
      dashboard can't sign in for you.
    </p>
    <div className="mt-2 flex items-center gap-2">
      <Terminal className="h-3.5 w-3.5 shrink-0 text-muted-foreground" />
      <code className="flex-1 rounded-md bg-[color-mix(in_oklab,var(--ds-fg)_6%,transparent)] px-2 py-1 font-mono text-xs">
        {instruction}
      </code>
      <Button
        variant="outline"
        size="sm"
        onClick={() => void navigator.clipboard?.writeText(instruction)}
      >
        Copy
      </Button>
    </div>
    <Button variant="outline" size="sm" className="mt-2" onClick={onRecheck}>
      <RefreshCw className="mr-1.5 h-3.5 w-3.5" />
      I've logged in — Re-check
    </Button>
  </div>
);

const rowGrid =
  'grid grid-cols-[minmax(0,1.4fr)_minmax(0,0.8fr)_minmax(0,1.4fr)_minmax(0,1fr)_minmax(0,8.5rem)] items-center gap-3';

/**
 * One table row per environment. The whole row is the edit affordance —
 * click it to load the environment into the draft panel; there is no edit
 * glyph. The built-in local environment is not editable (the store refuses
 * BuiltInEnvironmentError), so its row is inert. Delete stops propagation
 * so it never doubles as an edit click. The connect-needed handoff and an
 * unavailable reason render full-width beneath the row.
 */
const EnvironmentRow: React.FC<{
  environment: EnvironmentView;
  onRecheck: () => void;
  onEdit: (environment: EnvironmentView) => void;
}> = ({ environment, onRecheck, onEdit }) => {
  const isBuiltIn = environment.name === 'local' && environment.provider === 'local';
  const { connection } = environment;
  const editProps = isBuiltIn
    ? { role: 'group', 'aria-label': environment.name }
    : {
        role: 'button',
        tabIndex: 0,
        'aria-label': `Edit ${environment.name}`,
        onClick: () => onEdit(environment),
        onKeyDown: (e: React.KeyboardEvent) => {
          // Only keys pressed ON the row edit — keydowns bubbling from the
          // nested Delete button must not double as an edit.
          if (e.target !== e.currentTarget) return;
          if (e.key === 'Enter' || e.key === ' ') {
            e.preventDefault();
            onEdit(environment);
          }
        },
      };
  return (
    <div className="border-b border-[var(--ds-border)] last:border-b-0">
      <div
        {...editProps}
        className={`${rowGrid} py-3 ${
          isBuiltIn
            ? // Slightly dimmed so it's obvious the built-in row is not a
              // click target — it has no edit affordance.
              'opacity-60'
            : 'cursor-pointer rounded-lg hover:bg-[color-mix(in_oklab,var(--ds-fg)_4%,transparent)]'
        }`}
      >
        <div className="flex min-w-0 items-center gap-2.5">
          {/* Remote environments read as cloud; the built-in local as this machine. */}
          {isBuiltIn ? (
            <HardDrive className="h-4 w-4 shrink-0 text-muted-foreground" />
          ) : (
            <Cloud className="h-4 w-4 shrink-0 text-muted-foreground" />
          )}
          <span className="truncate font-mono text-sm font-semibold">{environment.name}</span>
        </div>
        {isBuiltIn ? (
          <span className="eyebrow justify-self-start rounded-md bg-[color-mix(in_oklab,var(--ds-blue)_15%,transparent)] px-2 py-0.5 text-[10px] text-blue">
            Built-in
          </span>
        ) : (
          <span className="truncate font-mono text-xs text-muted-foreground">
            {environment.provider}
          </span>
        )}
        <span className="truncate font-mono text-xs text-muted-foreground">{environment.account ?? '—'}</span>
        <span className="flex min-w-0 flex-wrap gap-1.5 text-xs">
          {environment.keyedProviders.length === 0
            ? '—'
            : environment.keyedProviders.map((provider) => (
                <span
                  key={provider}
                  className="inline-flex items-center gap-1 rounded-md bg-[color-mix(in_oklab,var(--ds-fg)_6%,transparent)] px-1.5 py-0.5 font-mono"
                >
                  <ProviderGlyph provider={provider} />
                  {provider}
                </span>
              ))}
        </span>
        <div className="flex w-full min-w-0 items-center justify-end gap-2">
          <ConnectionPill connection={connection} />
        </div>
      </div>
      {/* Detail lines indent to the name text (icon + gap), not the icon. */}
      {isBuiltIn && (
        <p className="pb-3 pl-[26px] text-xs text-muted-foreground">
          Runs on this machine — no setup required.
        </p>
      )}
      {/* The probe's logged-in readback is provenance, not configuration — it
          renders as the detail line, mirroring the built-in row (task 10).
          Guarded off the built-in row, which owns its own blurb. */}
      {!isBuiltIn && connection.status === 'ready' && connection.account !== undefined && (
        <p className="pb-3 pl-[26px] text-xs text-muted-foreground">{connection.account}</p>
      )}
      {connection.status === 'connect-needed' && (
        <div className="pl-[26px]">
          <ConnectNeeded instruction={connection.instruction} onRecheck={onRecheck} />
        </div>
      )}
      {connection.status === 'unavailable' && (
        <p className="pb-3 pl-[26px] text-xs text-muted-foreground">{connection.reason}</p>
      )}
    </div>
  );
};

/**
 * The always-visible draft panel. One panel serves both CREATE and EDIT:
 * pass an `environment` to edit it — fields prefill and the CTA becomes
 * Save changes. The name is LOCKED in edit mode (the store is keyed by
 * name), and so is the provider (switching providers is a re-creation,
 * not a patch). `local` is never a choice — exactly one local environment
 * exists, built-in and already set up.
 *
 * Model keys: existing references never reach the client (the routes
 * reduce them to `keyedProviders`), so an edit shows the keyed providers
 * as read-only chips — but NEW keys can be added in either mode. In edit
 * they ride the PUT-only additive `addCredentials`, which the server
 * merges into the stored map (fix: env-edit-keys-and-table-nits — an
 * environment created without keys must be able to gain them later).
 */
// Exported for direct panel tests (mirrors WorkerDraftPanel).
export const EnvironmentDraftPanel: React.FC<{
  environment?: EnvironmentView;
  providers: SandboxProviderView[];
  onCreate: (input: CreateEnvironmentInput) => Promise<{ ok: boolean; error?: string }>;
  onUpdate: (
    name: string,
    patch: Omit<CreateEnvironmentInput, 'name'>,
  ) => Promise<{ ok: boolean; error?: string }>;
  // Leave edit mode — the page clears its editing selection. Called after a
  // successful save; the page's New environment header button is the manual
  // way out (the footer has no Cancel).
  onExitEdit: () => void;
  // Delete the edited environment — the destructive action lives HERE, not
  // on the table row (fix: env-edit-keys-and-table-nits task 2).
  onDelete: (name: string) => void;
}> = ({ environment, providers, onCreate, onUpdate, onExitEdit, onDelete }) => {
  const editing = environment !== undefined;
  const firstAvailable = providers.find((p) => p.available)?.id ?? '';
  const [name, setName] = useState(environment?.name ?? '');
  const [provider, setProvider] = useState(environment?.provider ?? firstAvailable);
  const [account, setAccount] = useState(environment?.account ?? '');
  const [keys, setKeys] = useState<{ provider: string; reference: string }[]>([]);
  const [pickProvider, setPickProvider] = useState('');
  const [pickReference, setPickReference] = useState('');
  const [idleTimeout, setIdleTimeout] = useState(
    String(environment?.policy?.idleTimeoutMinutes ?? 30),
  );
  const [isolation, setIsolation] = useState<'isolated' | 'private'>(
    environment?.policy?.networkIsolation ?? 'isolated',
  );
  const [preWarm, setPreWarm] = useState(environment?.policy?.preWarm ?? false);
  const [confirmingDelete, setConfirmingDelete] = useState(false);
  // Keyed providers staged for removal this edit — persisted on Save (task 12).
  const [removals, setRemovals] = useState<string[]>([]);
  const [error, setError] = useState<string | null>(null);
  // The model the Test button runs the smoke-run against (env-smoke-test task 2).
  const [testModel, setTestModel] = useState('');
  const smoke = useEnvironmentSmokeTest();

  // Re-seed when the edited environment changes — the natural way to drive
  // edit from the table is to swap this prop (select A, then B, then back
  // to create). useState initializers run only on mount, so without this
  // the panel would keep A's fields and PUT against A. React's supported
  // "reset on prop change" pattern: key on the identity held in state and
  // reset in-render when it changes.
  const identity = environment?.name;
  const [seededFor, setSeededFor] = useState(identity);
  if (identity !== seededFor) {
    setSeededFor(identity);
    setName(environment?.name ?? '');
    setProvider(environment?.provider ?? firstAvailable);
    setAccount(environment?.account ?? '');
    setKeys([]);
    setPickProvider('');
    setPickReference('');
    setIdleTimeout(String(environment?.policy?.idleTimeoutMinutes ?? 30));
    setIsolation(environment?.policy?.networkIsolation ?? 'isolated');
    setPreWarm(environment?.policy?.preWarm ?? false);
    setConfirmingDelete(false);
    setRemovals([]);
    setError(null);
    setTestModel('');
  }

  // One resolution for everything provider-shaped: the select value, the
  // slot list, the policy gating, and the saved field. `provider` seeds
  // from '' when the panel mounts before the catalog fetch resolves, so raw
  // reads of it would disagree with what the select shows.
  const effectiveProvider = provider || firstAvailable;
  const selectedProvider = providers.find((p) => p.id === effectiveProvider);
  const slots = selectedProvider?.credentialProviders ?? [];
  const slotFor = (id: string) => slots.find((s) => s.id === id);
  // Models the Test button can smoke-run: those unlocked by a PERSISTED key on
  // this environment (a just-added, unsaved key can't be tested yet). Keyed
  // providers × the models their slot unlocks.
  const testableModels = slots
    .filter((s) => (environment?.keyedProviders ?? []).includes(s.id))
    .flatMap((s) => s.models);
  const effectiveTestModel = testableModels.includes(testModel)
    ? testModel
    : (testableModels[0] ?? '');
  // Collapse the streamed started→settled pairs to one row per phase (its
  // latest status). A Map keeps each phase at its first-seen position while
  // later events overwrite the value — so values() is one row per phase in
  // fire order, with no hardcoded phase list to drift from core's union.
  const smokeRows = [...new Map(smoke.phases.map((p) => [p.phase, p])).values()];
  // The chips still shown = existing keys minus staged removals; a slot is
  // takeable unless a key is staged for it or a KEPT chip still holds it —
  // staging a removal frees its slot for re-adding (a replace).
  const keptKeyed = (environment?.keyedProviders ?? []).filter((k) => !removals.includes(k));
  const unadded = slots.filter(
    (s) => !keys.some((k) => k.provider === s.id) && !keptKeyed.includes(s.id),
  );
  // Keep the picker on a real, unadded slot as keys come and go.
  const effectivePick = unadded.some((s) => s.id === pickProvider)
    ? pickProvider
    : (unadded[0]?.id ?? '');

  const addKey = () => {
    if (!effectivePick || pickReference.trim().length === 0) return;
    setKeys([...keys, { provider: effectivePick, reference: pickReference.trim() }]);
    setPickReference('');
  };

  const policy =
    effectiveProvider === 'railway'
      ? {
          policy: {
            idleTimeoutMinutes: Number.parseInt(idleTimeout, 10) || 30,
            networkIsolation: isolation,
            preWarm,
          },
        }
      : {};

  const save = async () => {
    if (environment !== undefined) {
      // Edit keys on the existing name (the route). The account is sent
      // even when blank so a pinned account can be CLEARED — the probe
      // treats an absent/empty pin as "any session". Newly staged keys ride
      // the additive addCredentials; existing references stay server-side
      // untouched (see the panel doc block).
      const addCredentials: Record<string, string> = {};
      for (const key of keys) addCredentials[key.provider] = key.reference;
      const result = await onUpdate(environment.name, {
        provider: environment.provider,
        account: account.trim(),
        ...(keys.length > 0 ? { addCredentials } : {}),
        ...(removals.length > 0 ? { removeCredentials: removals } : {}),
        ...policy,
      });
      if (result.ok) {
        setError(null);
        onExitEdit();
      } else {
        setError(result.error ?? 'Failed to save environment');
      }
      return;
    }
    const credentials: Record<string, string> = {};
    for (const key of keys) credentials[key.provider] = key.reference;
    const input: CreateEnvironmentInput = {
      name: name.trim(),
      provider: effectiveProvider,
      ...(account.trim() ? { account: account.trim() } : {}),
      ...(Object.keys(credentials).length > 0 ? { credentials } : {}),
      ...policy,
    };
    const result = await onCreate(input);
    if (result.ok) {
      // Create clears its fields for the next environment.
      setError(null);
      setName('');
      setAccount('');
      setKeys([]);
      setPickReference('');
      setIdleTimeout('30');
      setIsolation('isolated');
      setPreWarm(false);
    } else {
      setError(result.error ?? 'Failed to save environment');
    }
  };

  const field = 'w-full rounded-md border border-[var(--ds-border)] bg-transparent px-2 py-1.5 text-sm';

  return (
    <aside
      aria-label={editing ? 'Edit environment' : 'New environment'}
      className="panel h-fit rounded-2xl p-5"
    >
      <h2 className="text-sm font-semibold">
        {editing ? 'Edit environment' : 'New environment'}
      </h2>
      <div className="mt-3 grid gap-3">
        {/* Mandatory only where the user can actually type it — the locked
            edit-mode name must not wear a contradictory asterisk. Defaulted
            selects (Provider) are intentionally unmarked: they always hold a
            valid value the user cannot empty. */}
        <FieldLabel label="Name" required={!editing} subtitle="How you'll refer to this environment when attaching workers.">
          <input
            className={`${field} ${editing ? 'cursor-not-allowed text-muted-foreground opacity-70' : ''}`}
            value={name}
            onChange={(e) => setName(e.target.value)}
            // Locked while editing — the name is the store key.
            disabled={editing}
          />
        </FieldLabel>
        <label className="text-xs">
          <span className="text-muted-foreground">Provider</span>
          <select
            className={`${field} ${editing ? 'cursor-not-allowed text-muted-foreground opacity-70' : ''}`}
            value={effectiveProvider}
            // Locked while editing — a provider switch is a re-creation.
            // No keys reset on change in create mode: railway is the only
            // selectable provider today, so a switch can't happen through
            // the UI. Re-introduce (with a test) when a second provider
            // unlocks.
            disabled={editing}
            onChange={(e) => setProvider(e.target.value)}
          >
            {providers.map((p) => (
              <option key={p.id} value={p.id} disabled={!p.available}>
                {p.available ? p.label : `${p.label} — soon`}
              </option>
            ))}
            {/* An edited environment may sit on a provider the catalog no
                longer offers — keep its stored value renderable. */}
            {editing && !providers.some((p) => p.id === effectiveProvider) && (
              <option value={effectiveProvider}>{effectiveProvider}</option>
            )}
          </select>
        </label>
        <FieldLabel label="Account" subtitle="Optional — pin the provider session to this account.">
          <input
            className={field}
            value={account}
            placeholder="you@example.com"
            onChange={(e) => setAccount(e.target.value)}
          />
        </FieldLabel>
        <div className="mt-1">
          <p className="text-xs font-semibold">Model credentials</p>
          {editing ? (
            <p className="mt-1 text-xs text-muted-foreground">
              Existing key references never leave the server, so they can't be viewed or
              edited here — but you can add a key for any provider that doesn't have one yet.
            </p>
          ) : (
            <>
              <p className="mt-1 text-xs text-muted-foreground">
                Each key unlocks that provider's models for workers in this environment: if you
                have an Anthropic API key, add it to {selectedProvider?.label ?? 'the provider'}{' '}
                and enter the <span className="font-semibold">name</span> of that variable here
                (not the actual key!). Same for an OpenAI API key. A full provider
                reference pastes through untouched.
              </p>
              <p className="mt-1.5 text-xs text-muted-foreground">
                The worker resolves the reference inside the sandbox at run time — your actual
                key is never seen by tiny-brain.
              </p>
            </>
          )}
        </div>
        {/* Chips for the keys the environment still holds (edit mode only) —
            references stay server-side, but each chip can STAGE its removal
            (task 12); the freed slot returns to the picker so remove+re-add
            is a replace. Staged edits persist on Save. */}
        {editing && keptKeyed.length > 0 && (
          <div className="flex flex-wrap gap-1.5 text-xs">
            {keptKeyed.map((keyed) => (
              <span
                key={keyed}
                className="inline-flex items-center gap-1 rounded-md bg-[color-mix(in_oklab,var(--ds-fg)_6%,transparent)] px-1.5 py-0.5 font-mono"
              >
                <ProviderGlyph provider={keyed} />
                {keyed}
                <button
                  type="button"
                  aria-label={`Remove ${keyed} key`}
                  className="ml-0.5 rounded text-muted-foreground transition-colors hover:text-red-500 focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-red-500"
                  onClick={() => setRemovals([...removals, keyed])}
                >
                  <Trash2 className="h-3 w-3" />
                </button>
              </span>
            ))}
          </div>
        )}
        <>
            {keys.length === 0 && keptKeyed.length === 0 && (
              <p className="text-xs text-muted-foreground">
                {removals.length > 0
                  ? 'All keys staged for removal — they drop when you save.'
                  : 'No keys yet — models stay locked.'}
              </p>
            )}
            {keys.map((key) => {
              const slot = slotFor(key.provider);
              return (
                <div
                  key={key.provider}
                  className="rounded-xl border border-[var(--ds-border)] p-3 text-xs"
                >
                  <div className="flex items-center gap-2">
                    <ProviderGlyph provider={key.provider} className="h-3.5 w-3.5 shrink-0 text-muted-foreground" />
                    <span className="font-semibold">{slot?.label ?? key.provider}</span>
                    <code className="flex-1 truncate font-mono text-muted-foreground">
                      {key.reference}
                    </code>
                    <Button
                      variant="ghost"
                      size="sm"
                      aria-label={`Remove ${slot?.label ?? key.provider} key`}
                      onClick={() => setKeys(keys.filter((k) => k.provider !== key.provider))}
                    >
                      <Trash2 className="h-3.5 w-3.5" />
                    </Button>
                  </div>
                  {slot !== undefined && slot.models.length > 0 && (
                    <p className="mt-1.5 text-muted-foreground">
                      Unlocks {slot.models.join(', ')}
                    </p>
                  )}
                </div>
              );
            })}
            {unadded.length > 0 && (
              <div className="rounded-xl border border-dashed border-[var(--ds-border)] p-3">
                <div className="grid gap-2">
                  <label className="text-xs">
                    <span className="text-muted-foreground">Add a provider key</span>
                    <select
                      className={field}
                      value={effectivePick}
                      onChange={(e) => setPickProvider(e.target.value)}
                    >
                      {unadded.map((slot) => (
                        <option key={slot.id} value={slot.id}>
                          {slot.label}
                        </option>
                      ))}
                    </select>
                  </label>
                  <FieldLabel
                    label="Key name"
                    required
                    subtitle="Not the actual key contents — the variable's name at your provider."
                  >
                    <input
                      className={field}
                      value={pickReference}
                      placeholder={`${effectivePick.toUpperCase()}_API_KEY`}
                      onChange={(e) => setPickReference(e.target.value)}
                    />
                  </FieldLabel>
                  {pickReference.trim().length > 0 && (
                    <p className="font-mono text-[10px] leading-snug text-muted-foreground">
                      {(() => {
                        const preview = sharedReferencePreview(effectiveProvider, pickReference);
                        return preview !== null ? `Stored as ${preview}` : 'Stored as-is';
                      })()}
                    </p>
                  )}
                  <div>
                    <Button
                      variant="outline"
                      size="sm"
                      onClick={addKey}
                      disabled={pickReference.trim().length === 0}
                    >
                      <Plus className="mr-1.5 h-3.5 w-3.5" />
                      Add key
                    </Button>
                  </div>
                </div>
              </div>
            )}
        </>
        {effectiveProvider === 'railway' && (
          <>
            <label className="text-xs">
              <span className="text-muted-foreground">Idle timeout (minutes, 1–120)</span>
              <input
                className={field}
                type="number"
                value={idleTimeout}
                onChange={(e) => setIdleTimeout(e.target.value)}
              />
            </label>
            <label className="text-xs">
              <span className="text-muted-foreground">Network</span>
              <select
                className={field}
                value={isolation}
                onChange={(e) => setIsolation(e.target.value as 'isolated' | 'private')}
              >
                <option value="isolated">Isolated</option>
                <option value="private">Private</option>
              </select>
            </label>
            <label className="flex items-start gap-2 text-xs">
              <input
                type="checkbox"
                className="mt-0.5"
                checked={preWarm}
                onChange={(e) => setPreWarm(e.target.checked)}
              />
              <span className="flex flex-col gap-0.5">
                <span className="font-medium">Pre-warm</span>
                <span className="text-muted-foreground">
                  Create repo templates ahead of the first run.
                </span>
              </span>
            </label>
          </>
        )}
        {/* Test environment (env-smoke-test task 2): the cheapest end-to-end
            proof. Provisions a sandbox, runs one real (tiny) model call on the
            key to echo the model's identity, then tears down — streaming each
            phase. Only offered in edit mode, and only for models a PERSISTED
            key unlocks (a run has a real key to resolve). */}
        {editing && testableModels.length > 0 && (
          <div className="mt-1 rounded-xl border border-[var(--ds-border)] p-3">
            <p className="text-xs font-semibold">Test environment</p>
            <p className="mt-1 text-xs text-muted-foreground">
              Provisions a sandbox, makes one real (tiny) model call on your key to echo
              the model's identity, then tears it down. It spends a trivial amount on your
              key.
            </p>
            <div className="mt-2 flex items-center gap-2">
              <select
                aria-label="Test model"
                className={field}
                value={effectiveTestModel}
                onChange={(e) => setTestModel(e.target.value)}
              >
                {testableModels.map((model) => (
                  <option key={model} value={model}>
                    {model}
                  </option>
                ))}
              </select>
              <Button
                variant="outline"
                size="sm"
                className="shrink-0"
                onClick={() => void smoke.run(environment.name, effectiveTestModel)}
                disabled={smoke.running || effectiveTestModel === ''}
              >
                {smoke.running ? 'Testing…' : 'Test'}
              </Button>
            </div>
            {smoke.error && <p className="mt-2 text-xs text-red-500">{smoke.error}</p>}
            {smokeRows.length > 0 && (
              <ul className="mt-2 grid gap-1 text-xs">
                {smokeRows.map((row) => (
                  <li key={row.phase} className="flex items-center gap-2 font-mono">
                    <span className="min-w-[6.5rem] text-muted-foreground">{row.phase}</span>
                    <span
                      className={
                        row.status === 'failed'
                          ? 'text-red-500'
                          : row.status === 'succeeded'
                            ? 'text-[var(--ds-done)]'
                            : 'text-muted-foreground'
                      }
                    >
                      {row.status}
                    </span>
                  </li>
                ))}
              </ul>
            )}
            {smoke.result?.outcome === 'success' && (
              <div className="mt-2 rounded-md bg-[color-mix(in_oklab,var(--ds-done)_12%,transparent)] p-2 text-xs">
                <span className="font-semibold text-[var(--ds-done)]">Model responded: </span>
                <code className="font-mono break-all">{smoke.result.echo}</code>
              </div>
            )}
            {smoke.result?.outcome === 'failure' && (
              <div className="mt-2 rounded-md bg-[color-mix(in_oklab,var(--ds-warn,orange)_12%,transparent)] p-2 text-xs">
                <span className="font-semibold text-[var(--ds-warn,orange)]">
                  Failed at {smoke.result.failedPhase}:
                </span>{' '}
                <span className="text-muted-foreground break-all">{smoke.result.reason}</span>
              </div>
            )}
          </div>
        )}
      </div>
      {error && <p className="mt-2 text-xs text-red-500">{error}</p>}
      <div className="mt-4 flex items-center gap-2">
        {editing && (
          <Button
            variant="ghost"
            size="sm"
            className="shrink-0 text-red-500 hover:bg-red-500/10 hover:text-red-500"
            aria-label={`Delete ${environment.name}`}
            onClick={() => setConfirmingDelete(true)}
          >
            <Trash2 className="mr-1.5 h-3.5 w-3.5" />
            Delete
          </Button>
        )}
        <Button
          size="sm"
          className={editing ? 'ml-auto shrink-0' : 'min-w-0 flex-1'}
          onClick={() => void save()}
          // No provider = the catalog fetch failed or nothing is available
          // — a POST with provider '' would just 400. Name only gates
          // create; in edit mode the name is fixed to the environment's.
          disabled={!editing && (name.trim().length === 0 || effectiveProvider === '')}
        >
          {editing ? 'Save changes' : 'Save environment'}
        </Button>
      </div>
      {/* Confirmation gate — one stray click destroys nothing (task 4);
          the trigger lives left-aligned in the footer row (task 7). */}
      {editing && (
        <>
          <AlertDialog
            open={confirmingDelete}
            onOpenChange={(open) => {
              if (!open) setConfirmingDelete(false);
            }}
          >
            <AlertDialogContent>
              <AlertDialogHeader>
                <AlertDialogTitle>Delete environment</AlertDialogTitle>
                <AlertDialogDescription>
                  Delete &quot;{environment.name}&quot;? Workers pointing at it lose their
                  environment; the key variables at your provider are untouched.
                </AlertDialogDescription>
              </AlertDialogHeader>
              <AlertDialogFooter>
                <AlertDialogCancel>Cancel</AlertDialogCancel>
                <AlertDialogAction
                  onClick={() => {
                    setConfirmingDelete(false);
                    onDelete(environment.name);
                  }}
                >
                  Delete
                </AlertDialogAction>
              </AlertDialogFooter>
            </AlertDialogContent>
          </AlertDialog>
        </>
      )}
    </aside>
  );
};

const EnvironmentsPage: React.FC = () => {
  const { environments, providers, loading, error, refresh, create, update, remove } =
    useEnvironments();
  // The clicked row drives the shared draft panel into edit mode;
  // undefined = the panel's default create mode.
  const [editing, setEditing] = useState<EnvironmentView | undefined>(undefined);

  return (
    <div className="w-full p-4 md:p-6 lg:p-8">
      {/* Page identity lives in the top rail (task 11); the page starts at
          its subtitle and the actions portal into the rail's slot. */}
      <HeaderActions>
        <Button size="sm" onClick={() => setEditing(undefined)}>
          <Plus className="mr-1.5 h-3.5 w-3.5" />
          New environment
        </Button>
      </HeaderActions>
      <p className="text-sm text-muted-foreground">
        Where workers run. Configure a provider once — connect the account, reference the
        key — then attach it to any worker. Environments know nothing about repos or work
        items; a run is what binds them, and nothing is provisioned until a worker runs
        here. Key references are provider variables (e.g. Railway project variables),
        never raw secrets — click an environment to edit its keys and policy.
      </p>

      {error && <p className="mt-4 text-sm text-red-500">{error}</p>}
      {loading && <p className="mt-4 text-sm text-muted-foreground">Loading environments…</p>}

      {/* Panel stacks below the table until xl — same breakpoint story as
          the Workers page: the list keeps full width on laptop widths. */}
      <div className="mt-6 grid gap-4 xl:grid-cols-[minmax(0,1fr)_360px]">
        <div className="panel h-fit min-w-0 rounded-2xl p-4">
          <div className={`${rowGrid} pb-2 eyebrow text-[10px] text-muted-foreground`}>
            <span>Environment</span>
            <span>Provider</span>
            <span>Account</span>
            <span>Model keys</span>
            <span />
          </div>
          {environments.map((environment) => (
            <EnvironmentRow
              key={environment.name}
              environment={environment}
              onRecheck={() => void refresh()}
              onEdit={setEditing}
            />
          ))}
        </div>
        {/* One shared panel: a clicked-row environment drives edit mode,
            else it creates. It re-seeds in-render when this prop changes,
            so switching rows resets the form without a remount. */}
        <EnvironmentDraftPanel
          environment={editing}
          providers={providers}
          onCreate={create}
          onUpdate={update}
          onExitEdit={() => setEditing(undefined)}
          onDelete={(name) => {
            // Deleting the environment being edited must not leave the panel
            // patching a ghost — drop back to create mode.
            setEditing(undefined);
            void remove(name);
          }}
        />
      </div>
    </div>
  );
};

export default EnvironmentsPage;
