import { useCallback, useEffect, useRef } from 'react';

/**
 * A trailing-debounce wrapper around a refetch callback. Every call to the
 * returned `schedule` resets a single timer, so a burst of triggers coalesces
 * into ONE `refetch` after `delayMs` of quiet — a dispatch → commit → status
 * SSE burst on one entity becomes a single re-read. The pending timer is cleared
 * on unmount (and whenever `refetch`'s identity changes, e.g. a repoId switch),
 * so a debounce armed for a stale closure can never fire.
 *
 * Extracted from the board's run-change refetch wiring (useBoard.ts) so the runs
 * surface (useRepoRuns.ts) shares one implementation rather than a second copy.
 */
export function useDebouncedRefetch(refetch: () => void, delayMs: number): () => void {
  const debounceRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  const schedule = useCallback(() => {
    if (debounceRef.current !== null) clearTimeout(debounceRef.current);
    debounceRef.current = setTimeout(() => {
      debounceRef.current = null;
      refetch();
    }, delayMs);
  }, [refetch, delayMs]);

  useEffect(
    () => () => {
      if (debounceRef.current !== null) {
        clearTimeout(debounceRef.current);
        debounceRef.current = null;
      }
    },
    [refetch],
  );

  return schedule;
}
