import type { CSSProperties } from 'react';
import { Check, Lock, TriangleAlert, X } from 'lucide-react';
import { cn } from '@/lib/utils';
import type { ValidationChip, ValidationLane } from '../utils/validation-panel-state';

/**
 * The shared validation lane primitives (validation-pipeline-visibility) — the
 * chip strip and the lane row, extracted from the F4 ValidationPanel so the F6
 * PRD rollup renders per-feature lanes in the same visual family (the feature's
 * `ValidationChipStrip` / `ValidationLaneRow`). The chip vocabulary + states
 * live in `validation-panel-state.ts`; this module is pure presentation.
 */

/**
 * Screen-reader word for a chip's state — the strip's whole payload (which step
 * passed, failed, runs, or is unknown) is otherwise carried by icon shape +
 * colour alone, invisible to assistive tech (adversarial review of 6224a68ef).
 */
const CHIP_STATE_WORD: Record<ValidationChip['state'], string> = {
  passed: 'passed',
  failed: 'failed',
  running: 'running',
  // The reconcile-lane rebase chip on a `conflict` terminal — halted, needs a
  // hand, but not a hard failure (the verify stage never ran).
  warn: 'needs a hand',
  pending: 'pending',
  indeterminate: 'unknown',
};

/**
 * The `--phase` colour token that tints each chip's border + background, reusing
 * the shared `.chip` (CommitPipeline / PipelineChip) pill. `passed` glows in the
 * done colour, `running` in the review colour (the live phase), `failed` in red;
 * `pending` / `indeterminate` carry no phase so the `.chip.pending` dashed-dim
 * default stands.
 */
const CHIP_PHASE_VAR: Record<ValidationChip['state'], string | undefined> = {
  passed: 'var(--color-done)',
  failed: 'var(--color-phase-red)',
  running: 'var(--color-phase-review)',
  warn: 'var(--color-warn)',
  pending: undefined,
  indeterminate: undefined,
};

/**
 * One step chip in the CommitPipeline visual family — the shared `.chip` bordered
 * pill (validation-strip-tdd-pill-styling): a green tick when done, a red x when
 * failed, a pulsing `.cdot` for the running step (the `.chip.current` ring +
 * pulse), a dim dot for pending, and a dashed dot for an indeterminate step (a
 * live run we cannot see the frame of — honestly "unknown", never a fabricated
 * tick). `running` maps to the `current` modifier, `pending`/`indeterminate` to
 * the dashed `pending` modifier — same pill lifecycle the task-row strip renders.
 */
function StepChip({ chip }: { chip: ValidationChip }) {
  const phase = CHIP_PHASE_VAR[chip.state];
  return (
    <li>
      <span
        data-testid="validation-chip"
        data-state={chip.state}
        className={cn(
          'chip',
          chip.state === 'running' && 'current',
          (chip.state === 'pending' || chip.state === 'indeterminate') && 'pending',
        )}
        style={phase ? ({ '--phase': phase } as CSSProperties) : undefined}
      >
        <span className="grid h-3.5 w-3.5 place-items-center">
          {chip.state === 'passed' ? (
            <Check className="h-3 w-3 text-[var(--color-done)]" aria-hidden="true" />
          ) : chip.state === 'failed' ? (
            <X className="h-3 w-3 text-[var(--color-phase-red)]" aria-hidden="true" />
          ) : chip.state === 'warn' ? (
            <TriangleAlert className="h-3 w-3 text-[var(--color-warn)]" aria-hidden="true" />
          ) : chip.state === 'running' ? (
            // The .chip.current .cdot rule owns the pulse — no hand-rolled animate.
            <span className="cdot" aria-hidden="true" />
          ) : chip.state === 'indeterminate' ? (
            <span className="h-1.5 w-1.5 rounded-full border border-dashed border-current" aria-hidden="true" />
          ) : (
            <span className="cdot" aria-hidden="true" />
          )}
        </span>
        <span aria-hidden="true">{chip.emoji}</span>
        <span>{chip.label}</span>
        <span className="sr-only"> — {CHIP_STATE_WORD[chip.state]}</span>
      </span>
    </li>
  );
}

/** The chip strip — one {@link StepChip} per step, in order. Internal to this
 *  module until a consumer needs it standalone (the lane row is the shared unit
 *  every surface renders today). */
function ValidationChipStrip({ chips, label }: { chips: readonly ValidationChip[]; label: string }) {
  return (
    // The strip fills the row and right-aligns its pills (label-left / strip-right,
    // the task-row pipeline idiom) — validation-strip-tdd-pill-styling.
    <ol
      className="flex flex-1 flex-wrap items-center justify-end gap-1.5"
      aria-label={`${label} pipeline`}
    >
      {chips.map((chip) => (
        <StepChip key={chip.type} chip={chip} />
      ))}
    </ol>
  );
}

/**
 * One validation lane: its label + scope sub-line and the chip strip. A lane
 * marked `receipt` (a landed work-item lane, or a passed feature in the F6
 * rollup) is dimmed and collapsed to a one-line receipt — reading the ACTUAL
 * chip states, never asserting "all passed" blind (the exact lie the panel
 * exists to prevent, one lane over).
 */
// The scope sub-line reads as a plain-English sentence (user call 2026-08-10)
// rather than the bare `<value> scope` token.
const SCOPE_LABEL: Record<'changed' | 'full', string> = {
  changed: 'Run on changed files only',
  full: 'Run on all files',
};

export function ValidationLaneRow({ lane, flush = false }: { lane: ValidationLane; flush?: boolean }) {
  const passed = lane.chips.filter((c) => c.state === 'passed').length;
  const allPassed = passed === lane.chips.length && lane.chips.length > 0;
  return (
    <div
      data-testid="validation-lane"
      className={cn(
        'flex flex-col gap-1.5 sm:flex-row sm:items-center sm:gap-3',
        // `flush`: the step-timeline (validation-panel-step-timeline F6) owns the
        // row padding on its `.vstep`, so the lane row drops its own to avoid a
        // double indent. The PRD rollup keeps the default `px-3 py-2`.
        !flush && 'px-3 py-2',
        // A gated reconcile lane (work-item not passed) is dimmed like a receipt —
        // it is a not-yet-reached stage, not a live one.
        (lane.receipt === true || lane.gated === true) && 'opacity-60',
      )}
    >
      <div className="min-w-[9rem]">
        <div className="text-xs font-medium text-foreground">{lane.title}</div>
        <div className="text-[10px] text-subtle">
          {/* A bespoke subtitle (the reconcile lane's "Rebase onto main, then
              verify") overrides the changed/full scope sentence; the reconcile
              lane carries no scope at all, so guard the lookup. */}
          <span data-testid="validation-scope">
            {lane.subtitle ?? (lane.scope !== undefined ? SCOPE_LABEL[lane.scope] : null)}
          </span>
        </div>
      </div>
      {lane.faulted !== undefined ? (
        // The latest completion faulted on a wrong-tree scope (fix validation-
        // strip-silent-on-laundered-scoping-fault) — laundered out of the genuine
        // grouping, so it never pins a red. Name it + prompt a re-run in place of
        // the misleading all-pending chip strip; the reason rides the hover title
        // and the screen-reader text.
        <div className="flex flex-1 items-center justify-end">
          <span
            data-testid="validation-faulted"
            title={lane.faulted.reason}
            className="chip"
            style={{ '--phase': 'var(--color-warn)' } as CSSProperties}
          >
            <TriangleAlert className="h-3 w-3 text-[var(--color-warn)]" aria-hidden="true" />
            Validation couldn&apos;t run — scoping fault · re-run
            <span className="sr-only"> — {lane.faulted.reason}</span>
          </span>
        </div>
      ) : lane.gated === true ? (
        // The reconcile stage is not started — work-item validation must pass
        // first. A locked pill in the pending `.chip` skin, not an activity strip.
        <div className="flex flex-1 items-center justify-end">
          <span data-testid="validation-reconcile-gated" className="chip pending">
            <Lock className="h-3 w-3" aria-hidden="true" />
            not started — validation must pass first
          </span>
        </div>
      ) : lane.receipt === true ? (
        <div
          data-testid="validation-receipt"
          className={cn(
            'inline-flex items-center gap-1.5 text-[11px]',
            allPassed ? 'text-[var(--color-done)]' : 'text-subtle',
          )}
        >
          {allPassed ? (
            <Check className="h-3 w-3" aria-hidden="true" />
          ) : (
            <span className="h-1.5 w-1.5 rounded-full bg-current opacity-60" aria-hidden="true" />
          )}
          <span aria-hidden="true">{lane.chips.map((c) => c.emoji).join('')}</span>
          {allPassed ? `${lane.chips.length} steps · all passed` : `${passed}/${lane.chips.length} steps passed`}
        </div>
      ) : (
        <ValidationChipStrip chips={lane.chips} label={lane.title} />
      )}
    </div>
  );
}
