import { cn } from '@/lib/utils';

export interface GradientProgressProps {
  /**
   * Completion percentage; clamped to the 0–100 range. Optional so the bar can
   * render an {@link indeterminate} state (work happening, extent unknown) with
   * no value — omit `value` and set `indeterminate` for that mode.
   */
  value?: number;
  /**
   * Render an indeterminate bar — a sweeping partial fill and NO `aria-valuenow`
   * (the ARIA convention for an in-progress task of unknown extent). Ignores
   * `value`. Retained as a deliberate shared-primitive affordance: the runs card
   * moved to the board-parity determinate bar (runs-card-uplift task 2), so no
   * current consumer sets this — it stays as a standard progress-bar mode a
   * future surface with genuinely unknown-extent work can opt into.
   */
  indeterminate?: boolean;
  /**
   * Accessible name for the progressbar (both modes). A bare progressbar is
   * unnamed to assistive tech; a caller on a surface with sibling bars (e.g. the
   * run card's phase bar) passes a label so screen readers announce what the bar
   * measures. Omitted ⇒ no `aria-label` (the default board-card convention).
   */
  ariaLabel?: string;
  /** Extra classes for the track (e.g. `mt-3`, `flex-1`). */
  className?: string;
}

/**
 * The gradient progress bar from the UI Refresh design system: a recessed track
 * with a pink→blue gradient fill. Exposes the standard `progressbar` ARIA role
 * so the completion value is conveyed to assistive tech. In {@link indeterminate}
 * mode the fill sweeps and no `aria-valuenow` is emitted (unknown extent).
 */
export function GradientProgress({ value, indeterminate = false, ariaLabel, className }: GradientProgressProps) {
  const trackClassName = cn('progress-track h-1.5 w-full overflow-hidden rounded-full', className);
  const fillGradient = 'rounded-full bg-gradient-to-r from-pink to-blue';
  if (indeterminate) {
    // No aria-valuenow: an indeterminate progressbar (work happening, extent
    // unknown). A partial fill sweeps across the clipped track; reduced-motion
    // users get a static half-width fill instead of the animation.
    return (
      <div role="progressbar" aria-label={ariaLabel} aria-valuemin={0} aria-valuemax={100} className={trackClassName}>
        <div
          data-testid="gradient-progress-fill"
          className={cn(
            fillGradient,
            'h-full w-2/5 animate-shimmer motion-reduce:w-1/2 motion-reduce:animate-none',
          )}
        />
      </div>
    );
  }
  // Guard non-finite input (e.g. a `done / total` division with total 0) so we
  // never emit `aria-valuenow="NaN"` / `width: NaN%`. `typeof` narrows the
  // optional value with no assertion.
  const safe = typeof value === 'number' && Number.isFinite(value) ? value : 0;
  const pct = Math.min(100, Math.max(0, safe));
  return (
    <div
      role="progressbar"
      aria-label={ariaLabel}
      aria-valuenow={Math.round(pct)}
      aria-valuemin={0}
      aria-valuemax={100}
      className={trackClassName}
    >
      <div
        data-testid="gradient-progress-fill"
        className={cn('h-full', fillGradient)}
        style={{ width: `${pct}%` }}
      />
    </div>
  );
}

export default GradientProgress;
