import { useEffect, useState } from 'react';
import { FileText } from 'lucide-react';
import { cn } from '@/lib/utils';
import {
  Sheet,
  SheetContent,
  SheetHeader,
  SheetTitle,
  SheetDescription,
} from '@/components/ui/sheet';
import { fetchPlanContent } from '../services/api';
import { useLazySourceContent, SourceSheetBody } from './source-sheet-content';

export interface PlanSourceSheetProps {
  repoId: string;
  /** The PRD directory slug the content endpoints resolve documents by. */
  planId: string;
  /** The plan's features, for the document picker (PRD + one per feature). */
  features: readonly { id: string; title?: string }[];
  isOpen: boolean;
  onClose: () => void;
}

/**
 * Frontmatter split for the header strip (approved mockup: frontmatter lives
 * in the sheet header, the prose pane renders the body only). Top-level
 * `key: value` lines are extracted; nested/indented lines and bare `key:`
 * lines are skipped — this is a display strip, not a YAML parser.
 */
function splitFrontmatter(md: string): { fields: Map<string, string>; body: string } {
  const match = md.match(/^---\n([\s\S]*?)\n---\n?/);
  if (!match) return { fields: new Map(), body: md };
  const fields = new Map<string, string>();
  for (const line of match[1].split('\n')) {
    const pair = line.match(/^(\w[\w-]*):\s*(.+)$/);
    if (pair) fields.set(pair[1], pair[2]);
  }
  return { fields, body: md.slice(match[0].length) };
}

/**
 * The frontmatter keys the header strip shows, in order — the approved mockup
 * shows exactly these three, NOT every key a real prd.md carries (a real one
 * also has title/version/created/updated/author, which would swamp the strip
 * with timestamps).
 */
const HEADER_KEYS = ['id', 'status', 'uuid'] as const;

/**
 * Right-side slide-over showing a PRD's raw markdown source — the PRD parallel
 * to FixSourceSheet (fix: prd-source-not-viewable). A document picker switches
 * between the PRD body (`prd.md`) and each feature's markdown, fetched lazily
 * per selection via the plan content endpoints; the content pane matches the
 * fix source view's prose card.
 */
export const PlanSourceSheet: React.FC<PlanSourceSheetProps> = ({
  repoId,
  planId,
  features,
  isOpen,
  onClose,
}) => {
  // null selects the PRD document; a feature id selects that feature's doc.
  const [selected, setSelected] = useState<string | null>(null);

  // A different plan's sheet must not open on a stale feature selection.
  useEffect(() => setSelected(null), [planId]);

  const { content, loading, error } = useLazySourceContent(
    isOpen,
    () => fetchPlanContent(repoId, planId, selected ?? undefined),
    [repoId, planId, selected],
  );

  const docPath =
    selected === null
      ? `docs/prd/${planId}/prd.md`
      : `docs/prd/${planId}/features/${selected}.md`;
  const { fields, body } =
    content !== null ? splitFrontmatter(content) : { fields: new Map<string, string>(), body: null };
  const headerFields = HEADER_KEYS.flatMap((key) => {
    const value = fields.get(key);
    return value === undefined ? [] : [[key, value] as const];
  });

  const docButtonClass = (active: boolean) =>
    cn(
      'flex w-full items-center gap-2 rounded-lg px-2.5 py-2 text-left text-xs transition-colors',
      active
        ? 'bg-accent font-medium text-foreground'
        : 'text-muted-foreground hover:bg-accent hover:text-foreground',
    );

  return (
    <Sheet open={isOpen} onOpenChange={(open) => !open && onClose()}>
      <SheetContent side="right" className="flex w-[860px] flex-col sm:max-w-[860px]">
        <SheetHeader>
          <SheetTitle className="display">Plan source</SheetTitle>
          <SheetDescription className="mono truncate text-xs">{docPath}</SheetDescription>
          {headerFields.length > 0 && (
            <div
              data-testid="plan-source-frontmatter"
              className="mono flex flex-wrap items-baseline gap-x-4 gap-y-1 pt-1 text-[11px]"
            >
              {headerFields.map(([key, value]) => (
                <span key={key} className="inline-flex items-baseline gap-1.5">
                  <span className="text-muted-foreground">{key}</span>
                  {key === 'status' ? (
                    <span className="rounded bg-accent px-1.5 py-0.5 text-[10px] font-semibold uppercase tracking-wide">
                      {value}
                    </span>
                  ) : (
                    <span>{value}</span>
                  )}
                </span>
              ))}
            </div>
          )}
        </SheetHeader>
        <div className="flex min-h-0 flex-1">
          <nav
            aria-label="Documents"
            className="w-52 flex-none space-y-0.5 overflow-y-auto border-r border-border px-3 pb-4"
          >
            <button
              type="button"
              aria-pressed={selected === null}
              onClick={() => setSelected(null)}
              className={docButtonClass(selected === null)}
            >
              <FileText className="h-3.5 w-3.5 flex-none" />
              <span className="truncate">PRD</span>
            </button>
            {features.map((feature) => (
              <button
                key={feature.id}
                type="button"
                aria-pressed={selected === feature.id}
                onClick={() => setSelected(feature.id)}
                className={docButtonClass(selected === feature.id)}
              >
                <FileText className="h-3.5 w-3.5 flex-none" />
                <span className="truncate">{feature.title ?? feature.id}</span>
              </button>
            ))}
          </nav>
          <div className="min-h-0 flex-1 overflow-auto px-4 pb-4">
            <SourceSheetBody
              noun="plan source"
              testId="plan-source"
              loading={loading}
              error={error}
              markdown={body}
            />
          </div>
        </div>
      </SheetContent>
    </Sheet>
  );
};

export default PlanSourceSheet;
