import { useEffect, useRef, useState } from 'react';
import type { RunEvent, RunResources } from '@magic-ingredients/tiny-brain-core';
import { subscribeRunStream } from './run-stream-core';

/**
 * Fold a batch of streamed run events into a resource footprint — the client
 * mirror of core's read-side `foldResourceSamples`
 * (`packages/tiny-brain-core/src/services/runs/fold-resource-samples.ts`), which
 * is not exported from the core barrel, and the client value-imports no core
 * functions — so the contract is duplicated here deliberately. Keep the two in
 * lock-step: any change to core's fold must be mirrored in this one. `peakRssBytes`
 * is the highest RSS sample seen; `lastCpuPercent` / `sampledAt` come from the
 * LAST-APPENDED `resource` event (a sequential ticker emits in order, so the last
 * is the most recent — not a timestamp-max). Non-resource events are ignored; a
 * batch with no `resource` events folds to `undefined`, never a fabricated zero
 * (honesty rule).
 */
export function foldLiveRunResources(events: readonly RunEvent[]): RunResources | undefined {
  let peakRssBytes = 0;
  let last: { cpuPercent: number; ts: string } | undefined;
  for (const event of events) {
    if (event.type !== 'resource') continue;
    if (event.rssBytes > peakRssBytes) peakRssBytes = event.rssBytes;
    last = { cpuPercent: event.cpuPercent, ts: event.ts };
  }
  if (last === undefined) return undefined;
  return { peakRssBytes, lastCpuPercent: last.cpuPercent, sampledAt: last.ts };
}

/** Merge a freshly-folded batch onto the prior footprint: peak RSS is the running
 *  max; the newer batch's CPU% / instant win (batches arrive in stream order). */
function mergeFootprint(prior: RunResources | undefined, batch: RunResources): RunResources {
  if (prior === undefined) return batch;
  return {
    peakRssBytes: Math.max(prior.peakRssBytes, batch.peakRssBytes),
    lastCpuPercent: batch.lastCpuPercent,
    sampledAt: batch.sampledAt,
  };
}

/**
 * task 9 — live OS-resource footprints for the running cards. A running run's
 * record carries no `resources` until its terminal fold (fix
 * `card-select-slow-resource-sampler-churns-run-record` stopped the per-tick
 * record churn), so this hook rides the per-run `resource` EVENT stream instead:
 * it multiplexes one {@link subscribeRunStream} watch per running run (mirroring
 * the board's multiplexed land watcher), folds each fresh batch of `resource`
 * events {@link foldLiveRunResources}, and exposes the accumulated footprint per
 * run. A watch is torn down when its run leaves the set (ended) or the view
 * unmounts. It never touches the run record / `run-change` path, so it cannot
 * reintroduce the churn the earlier fix removed.
 */
export function useLiveRunResources(
  repoId: string,
  runIds: readonly string[],
): ReadonlyMap<string, RunResources> {
  const [resources, setResources] = useState<ReadonlyMap<string, RunResources>>(new Map());
  // Live subscriptions, keyed runId → cancel. A ref so the reconcile effect can
  // diff the desired id set against the open watches without re-subscribing all.
  const subs = useRef<Map<string, () => void>>(new Map());
  // The repo the open watches point at. The reconcile diffs the desired set by
  // runId alone, so without this a repo switch that kept the SAME run ids would
  // leave every watch pointed at the OLD repo's stream (they'd be `has()`-skipped).
  const watchedRepo = useRef<string>('');

  // Stable string key so the reconcile effect only re-runs when the SET of
  // running ids changes — not on every array identity (the caller derives the
  // list fresh each render).
  const key = runIds.join(',');

  useEffect(() => {
    if (!repoId) return;
    // Repo changed: every open watch is on the old repo's stream. Tear them all
    // down and clear their footprints so the loop below re-subscribes each run
    // under the new repo, rather than skipping it as already-watched.
    if (watchedRepo.current !== repoId) {
      for (const cancel of subs.current.values()) cancel();
      subs.current.clear();
      watchedRepo.current = repoId;
      setResources((prev) => (prev.size === 0 ? prev : new Map()));
    }
    const desired = new Set(runIds);

    // Start a watch for each newly-running run.
    for (const runId of desired) {
      if (subs.current.has(runId)) continue;
      const cancel = subscribeRunStream(repoId, runId, {
        onEvents: (fresh) => {
          const batch = foldLiveRunResources(fresh);
          if (batch === undefined) return;
          setResources((prev) => new Map(prev).set(runId, mergeFootprint(prev.get(runId), batch)));
        },
      });
      subs.current.set(runId, cancel);
    }

    // Cancel + forget any run that left the set, and drop its footprint so a
    // stale live value can't linger on a card the run no longer backs. The run's
    // record carries the terminal fold once its refetch lands (RepoDetailPage
    // falls back to `run.resources` when there is no live entry), so a momentary
    // blank in the handoff is honest — preferred over showing a frozen live value.
    for (const [runId, cancel] of subs.current) {
      if (desired.has(runId)) continue;
      cancel();
      subs.current.delete(runId);
      setResources((prev) => {
        if (!prev.has(runId)) return prev;
        const next = new Map(prev);
        next.delete(runId);
        return next;
      });
    }
    // `key` is the SET identity the reconcile depends on; runIds is read through it.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [repoId, key]);

  // Abort every live watch on unmount.
  useEffect(() => {
    const live = subs.current;
    return () => {
      for (const cancel of live.values()) cancel();
      live.clear();
    };
  }, []);

  return resources;
}
