import type { Plan, Fix, TaskRowTask } from '../types';

export interface TaskLocation {
  readonly task: TaskRowTask;
  /** 1-based ordinal of the task within its container. */
  readonly taskNumber: number;
  /** The containing feature id (plan task) or fix id (fix task). */
  readonly container: string;
}

/**
 * Locate a task within the loaded plan or fix and report its 1-based ordinal
 * and container id — the pieces the task-detail header meta line needs. Plan
 * features are searched before the fix; returns null when the id matches
 * neither (the header then falls back to the raw id).
 */
export function resolveTaskLocation(
  plan: Plan | null | undefined,
  fix: Fix | null | undefined,
  taskId: string,
): TaskLocation | null {
  for (const feature of plan?.features ?? []) {
    const tasks = feature.tasks ?? [];
    const index = tasks.findIndex((t) => t.id === taskId);
    if (index !== -1) {
      return { task: tasks[index], taskNumber: index + 1, container: feature.id };
    }
  }
  if (fix) {
    const tasks = fix.tasks ?? [];
    const index = tasks.findIndex((t) => t.id === taskId);
    if (index !== -1) {
      return { task: tasks[index], taskNumber: index + 1, container: fix.id };
    }
  }
  return null;
}
