import { useEffect, useRef, useState } from 'react';
import type { RunEvent, RunStatus } from '@magic-ingredients/tiny-brain-core';
import { subscribeRunStream } from './run-stream-core';
import type { RunListRow } from './useRepoRuns';

/**
 * A running run's live activity, folded from its event stream (runs-card-uplift):
 * the latest streamed-activity instant (advancing the `no output for {N}m` stall
 * clock) and — once the stream reaches a terminal `exit` — the settled fact that
 * lets the card stop ticking "Running for {N}". The runs list is a one-shot read
 * (`useRepoRuns`) that never re-fetches, so `settled` is what tells the card a run
 * has ENDED; without it a since-ended run reads live forever.
 */
export interface LiveRunActivity {
  /** Latest streamed-activity instant — text / tool_use / tool_result / usage. */
  readonly lastActivityAt?: string;
  /** Set once the stream emits a terminal `exit`: settle the card (live=false,
   *  elapsed frozen at `endedAt`). */
  readonly settled?: { readonly status: RunStatus; readonly endedAt: string };
}

/** The streamed event types that count as run ACTIVITY for the stall clock — the
 *  same set the server stamps `lastActivityAt` from (a tool-heavy stretch is
 *  activity, not silence). `pipeline` / `resource` are excluded so a resource
 *  ticker on a dead process can't masquerade as agent output. */
const ACTIVITY_EVENT_TYPES: ReadonlySet<RunEvent['type']> = new Set([
  'text',
  'tool_use',
  'tool_result',
  'usage',
]);

/** The non-terminal run statuses — a run still executing. An `exit` frame only
 *  SETTLES the card when its status is terminal; the fold asserts this locally
 *  rather than trusting the upstream convention that every `exit` is terminal, so
 *  a future non-terminal exit frame can never freeze a still-live card. */
const NON_TERMINAL_STATUSES: ReadonlySet<RunStatus> = new Set<RunStatus>(['running', 'cancelling']);


/**
 * Fold a batch of streamed events onto the prior activity state: advance
 * `lastActivityAt` to the newest activity-event instant, and record `settled`
 * once an `exit` event arrives. Returns `undefined` for a batch (and no prior)
 * that carried neither — never a fabricated entry (honesty rule).
 */
export function foldLiveRunActivity(
  events: readonly RunEvent[],
  prior?: LiveRunActivity,
): LiveRunActivity | undefined {
  let lastActivityAt = prior?.lastActivityAt;
  let settled = prior?.settled;
  for (const event of events) {
    if (ACTIVITY_EVENT_TYPES.has(event.type)) {
      // ISO-8601 instants sort lexically, so a string `>` picks the newest tick.
      if (lastActivityAt === undefined || event.ts > lastActivityAt) lastActivityAt = event.ts;
    } else if (event.type === 'exit' && !NON_TERMINAL_STATUSES.has(event.status)) {
      settled = { status: event.status, endedAt: event.ts };
    }
  }
  if (lastActivityAt === undefined && settled === undefined) return undefined;
  return {
    ...(lastActivityAt !== undefined ? { lastActivityAt } : {}),
    ...(settled !== undefined ? { settled } : {}),
  };
}

/**
 * Overlay a run's live activity onto its runs-lens row (runs-card-uplift task 1):
 * advance `lastActivityAt` to the newer of the row's and the live value (so the
 * stall clock reflects real output), and — when the run has `settled` — flip
 * `live` off and stamp the terminal `status` / `endedAt` so the card stops ticking
 * "Running for {N}". No activity ⇒ the row is returned by identity (a stable
 * reference the caller's memo can skip).
 */
export function overlayLiveRunActivity(run: RunListRow, activity?: LiveRunActivity): RunListRow {
  if (activity === undefined) return run;
  let next: RunListRow = run;
  if (
    activity.lastActivityAt !== undefined &&
    (run.lastActivityAt === undefined || activity.lastActivityAt > run.lastActivityAt)
  ) {
    next = { ...next, lastActivityAt: activity.lastActivityAt };
  }
  if (activity.settled !== undefined) {
    next = { ...next, live: false, status: activity.settled.status, endedAt: activity.settled.endedAt };
  }
  return next;
}

/**
 * Multiplex one run-stream watch per running run and expose each run's live
 * activity (runs-card-uplift task 1). Mirrors {@link useLiveRunResources}: one
 * {@link subscribeRunStream} watch per id, folded per fresh batch. UNLIKE the
 * resources hook, a `settled` entry is STICKY — retained after the run leaves the
 * running set — because the one-shot runs list never re-fetches to learn the run
 * ended, so the card would otherwise revert to a live, ticking row.
 */
export function useLiveRunActivity(
  repoId: string,
  runIds: readonly string[],
): ReadonlyMap<string, LiveRunActivity> {
  const [activity, setActivity] = useState<ReadonlyMap<string, LiveRunActivity>>(new Map());
  const subs = useRef<Map<string, () => void>>(new Map());
  const watchedRepo = useRef<string>('');
  const key = runIds.join(',');

  useEffect(() => {
    if (!repoId) return;
    // Repo changed: every open watch is on the old repo's stream. Tear them all
    // down and clear state so the loop below re-subscribes under the new repo.
    if (watchedRepo.current !== repoId) {
      for (const cancel of subs.current.values()) cancel();
      subs.current.clear();
      watchedRepo.current = repoId;
      setActivity((prev) => (prev.size === 0 ? prev : new Map()));
    }
    const desired = new Set(runIds);

    for (const runId of desired) {
      if (subs.current.has(runId)) continue;
      const cancel = subscribeRunStream(repoId, runId, {
        onEvents: (fresh) => {
          setActivity((prev) => {
            const folded = foldLiveRunActivity(fresh, prev.get(runId));
            if (folded === undefined) return prev;
            return new Map(prev).set(runId, folded);
          });
        },
      });
      subs.current.set(runId, cancel);
    }

    // Cancel + forget any run that left the set. A run that has SETTLED keeps its
    // entry (sticky) — the one-shot runs list never re-fetches to learn it ended,
    // so dropping the settle would revert the card to a live, ticking row. A
    // run that left WITHOUT settling drops its live-only entry (nothing to keep).
    for (const [runId, cancel] of subs.current) {
      if (desired.has(runId)) continue;
      cancel();
      subs.current.delete(runId);
      setActivity((prev) => {
        const entry = prev.get(runId);
        if (entry === undefined || entry.settled !== undefined) return prev;
        const next = new Map(prev);
        next.delete(runId);
        return next;
      });
    }
    // `key` is the SET identity the reconcile depends on; runIds is read through it.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [repoId, key]);

  useEffect(() => {
    const live = subs.current;
    return () => {
      for (const cancel of live.values()) cancel();
      live.clear();
    };
  }, []);

  return activity;
}
