import { useState } from 'react';
import { Diff, Hunk, getChangeKey, type FileData } from 'react-diff-view';
import { ChevronDown, ChevronRight } from 'lucide-react';

function summarize(file: FileData): {
  additions: number;
  deletions: number;
  changeKeys: Set<string>;
} {
  let additions = 0;
  let deletions = 0;
  const changeKeys = new Set<string>();
  for (const hunk of file.hunks) {
    for (const change of hunk.changes) {
      changeKeys.add(getChangeKey(change));
      if (change.type === 'insert') additions += 1;
      else if (change.type === 'delete') deletions += 1;
    }
  }
  return { additions, deletions, changeKeys };
}

interface DiffFileViewProps {
  file: FileData;
  /** react-diff-view change keys to highlight (rail → diff anchor). */
  selectedChanges?: string[];
}

/**
 * One file in a diff pane: a header that toggles the body's collapse (chevron +
 * path + `+N −M` change counts) above the unified `<Diff>`.
 *
 * Files start collapsed, so a diff opens as a scannable list of file headers
 * rather than a wall of code. A file opens when the user clicks its header, or
 * when the rail anchors a selected change that lives in this file — so selecting
 * a test reveals its file and the highlighted line scrolls into view. Shared by
 * the task-detail Red/Green tabs (and the forthcoming Review/Commits tabs).
 */
export default function DiffFileView({ file, selectedChanges }: DiffFileViewProps) {
  const path = file.newPath ?? file.oldPath ?? '';
  const { additions, deletions, changeKeys } = summarize(file);
  const [open, setOpen] = useState(false);
  // Auto-open when a selected (anchored) change belongs to this file, so the
  // rail can reveal a collapsed file's highlighted line.
  const containsSelected = !!selectedChanges?.some((key) => changeKeys.has(key));
  const expanded = open || containsSelected;

  return (
    <div>
      <button
        type="button"
        aria-expanded={expanded}
        onClick={() => setOpen((o) => !o)}
        className="file-hd mono flex w-full items-center justify-between gap-3 border-b border-border px-4 py-2 text-left text-[12px] hover:bg-muted/40"
      >
        <span className="inline-flex min-w-0 items-center gap-2">
          {expanded ? (
            <ChevronDown className="h-3.5 w-3.5 flex-none text-muted-foreground" />
          ) : (
            <ChevronRight className="h-3.5 w-3.5 flex-none text-muted-foreground" />
          )}
          <span className="truncate">{path}</span>
        </span>
        <span className="mono flex-none text-[11px]">
          <span style={{ color: 'var(--color-phase-green)' }}>+{additions}</span>{' '}
          <span style={{ color: 'var(--color-phase-red)' }}>−{deletions}</span>
        </span>
      </button>
      {expanded && (
        <Diff
          viewType="unified"
          diffType={file.type}
          hunks={file.hunks}
          selectedChanges={selectedChanges}
        >
          {(hunks) => hunks.map((hunk) => <Hunk key={hunk.content} hunk={hunk} />)}
        </Diff>
      )}
    </div>
  );
}
