import React, { useEffect, useRef, useState } from 'react';
import { useSearchParams } from 'react-router';
import ReactMarkdown from 'react-markdown';
import remarkGfm from 'remark-gfm';
import { Circle, Play, CheckCircle2, FastForward } from 'lucide-react';
import type { TaskRowTask, TddPhase } from '@/types';
import type { PipelineStep } from '@magic-ingredients/tiny-brain-core/phase-derivation';
import { deriveTddPhase } from '@/utils/tdd-phases';
import { phaseToTab } from '@/utils/task-detail-link';
import CommitPipeline from '@/components/CommitPipeline';
import MiniStatusRail from '@/components/MiniStatusRail';
import type { WorktreeBranchRef } from '@/components/worktree-branches';
import { applyDerivedState } from '@/utils/apply-derived-state';
import { applyWorktreePhaseShas } from '@/utils/worktree-aware-shas';
import { deriveEffectiveStatus } from '@/utils/effective-task-status';

interface ManualCompleteContext {
  readonly planId: string;
  readonly featureId: string;
  readonly taskNumber: number;
}

interface TaskRowProps {
  task: TaskRowTask;
  repoId: string;
  reviewPipeline?: PipelineStep[];
  manualCompleteContext?: ManualCompleteContext;
  /**
   * Human slug path for the task (`<prd>/<feature>/task-N` etc.), rendered
   * inline at the start of the status line as `slug · status`
   * (stable-uuid-identity F6-T5). The opaque UUID is never shown — slug paths
   * are the only external identifier.
   */
  slugPath?: string;
  /**
   * The worktree the parent feature's work lives on (when uniform). When a task's
   * effective status comes from THIS same worktree, the per-task pill is
   * suppressed — the feature header already shows it. The pill renders only when
   * a task overrides to a different worktree.
   */
  featureWorktreeRef?: string;
}

const phaseLabels: Record<Exclude<TddPhase, 'complete'>, string> = {
  red: 'Writing failing tests (TDD red phase)..',
  green: 'Writing an implementation (TDD green phase)..',
  adversarial: "Reviewing what's been done..",
  'adversarial-refactor': 'Making things better (TDD refactor phase)..',
  mutation: 'Spawning mutants..',
  'mutation-refactor': 'Making things better post mutation (TDD refactor phase)..',
};

const statusConfig: Record<
  TaskRowTask['status'],
  { icon: React.FC<{ className?: string }>; title: string; iconClass: string }
> = {
  not_started: { icon: Circle, title: 'Not started', iconClass: 'text-muted-foreground' },
  in_progress: { icon: Play, title: 'In progress', iconClass: 'text-blue-500' },
  completed: { icon: CheckCircle2, title: 'Completed', iconClass: 'text-green-500' },
  superseded: { icon: CheckCircle2, title: 'Superseded', iconClass: 'text-orange-500' },
};

// The mock's completed subtitle (`completed 19 Jul`) — day + short month, no
// year: the row is a glance line, the full timestamp lives on the detail page.
// Pinned to UTC so the shown day matches the stored timestamp's date on every
// machine — a near-midnight completion must not drift a day with the viewer's
// timezone.
const formatCompleted = (iso: string): string =>
  `completed ${new Date(iso).toLocaleDateString('en-GB', { day: 'numeric', month: 'short', timeZone: 'UTC' })}`;

const TaskRow: React.FC<TaskRowProps> = ({ task, repoId, reviewPipeline, manualCompleteContext, slugPath, featureWorktreeRef }) => {
  const [, setSearchParams] = useSearchParams();

  // Overlay telemetry-derived state up front so the row's navigation target and
  // the pipeline strip agree. Commit SHAs often arrive via telemetry
  // (`derivedState`) rather than the raw progress.json snapshot.
  //
  // Then fill any phase SHA still missing on the launch ref from the per-ref
  // lattice (worktree/branch commits), so a task whose work lives only on a
  // worktree reads its real phase — the strip and the navigation tab stay
  // consistent because both read this single overlayed task (ADR-0007 /
  // multi-ref-projection T5).
  const overlayed = applyWorktreePhaseShas(applyDerivedState(task, task.derivedState));

  // The row's status reflects the most-advanced ref: the launch-ref status,
  // unless a live worktree is strictly ahead (work completed/superseded there but
  // not on the launch ref). `effectiveTask` drives every status-keyed render —
  // icon, superseded marker, second-row text — so worktree work isn't shown as
  // not_started. `worktreeRef` tags where the status came from.
  const effective = deriveEffectiveStatus(overlayed);
  const effectiveTask = effective.status === overlayed.status ? overlayed : { ...overlayed, status: effective.status };

  // The LHS icon reflects work-in-flight: once a phase has STARTED (an event
  // stamp) OR the first phase commit has LANDED (testCommitSha — the 'skipped'
  // sentinel counts, so red-skipped green tasks qualify), the task reads In
  // progress even while its stored status is still not_started — matching the RHS
  // pipeline strip, which renders on the same signals. testCommitSha must count
  // even when the redStartedAt stamp is absent (a green that landed without
  // `task start`, a fresh clone) so the icon doesn't read "Not started" over work
  // the strip shows done. A raw commitSha with NO testCommitSha is an anomalous
  // stray commit (green with no preceding red), not real progress, so it does not
  // flip the icon. Display only — events still never write the persisted status.
  const hasStartedPhase = !!(
    overlayed.redStartedAt ||
    overlayed.greenStartedAt ||
    overlayed.testCommitSha
  );
  const displayStatus: TaskRowTask['status'] =
    effective.status === 'not_started' && hasStartedPhase ? 'in_progress' : effective.status;
  const { icon: Icon, title, iconClass } = statusConfig[displayStatus] ?? statusConfig.not_started;
  const iconTitle = effective.worktreeRef ? `${title} on ${effective.worktreeRef}` : title;
  // Show the per-task worktree pill only when the task's status comes from a
  // worktree the feature header isn't already showing (an override). When the
  // whole feature shares one worktree, the header carries it and the rows stay
  // clean.
  const showWorktreePill = !!effective.worktreeRef && effective.worktreeRef !== featureWorktreeRef;
  // The branch is the identity (where the status came from). When the task's
  // worktree assignment names the same branch, surface its dir name too — branch
  // and worktree are different axes, so the rail tooltip distinguishes them.
  const worktreeBranch = effective.worktreeRef;
  const worktreeName =
    task.worktree && task.worktree.branch === worktreeBranch ? task.worktree.name : undefined;
  // One branch-ref for the shared rail: the compact worktree chip renders the
  // branch glyph and carries the branch (and diverging worktree dir name) in its
  // tooltip — the same structure every other surface uses.
  const worktreeBranches: readonly WorktreeBranchRef[] = worktreeBranch
    ? [{ branch: worktreeBranch, hasWorktree: !!worktreeName, worktreeName }]
    : [];
  // Clicking the chip opens the worktree-merge island (?island=<branch>) — the
  // same content-replacing delivery surface the fix/prd/spike headers open. The
  // indicator was glance-only before task 4.
  const openMerge = () => {
    if (!worktreeBranch) return;
    setSearchParams((prev) => {
      const next = new URLSearchParams(prev);
      next.set('island', worktreeBranch);
      return next;
    });
  };

  // Plain list rows separated by the parent's hairline dividers — completion /
  // not-started carry no fill. The in-progress (current) row is the exception:
  // a subtle wash plus a left accent stripe (inset shadow, so it doesn't shift
  // the icon out of line with the header chevron). Clickable rows get a hover.
  const inProgressAccent =
    displayStatus === 'in_progress'
      ? 'bg-[color-mix(in_oklab,var(--color-blue)_8%,transparent)] shadow-[inset_3px_0_0_var(--color-blue)]'
      : '';
  // Manual tasks have no TDD pipeline (no red/green/review/commits), so there's
  // no detail page to open — their row carries only the Mark-complete control
  // and is not a navigating button (which also avoids a <button> nested inside a
  // button). Every other row navigates and reads as clickable.
  const isManual = effectiveTask.pipelineType === 'manual';
  const hoverClass = isManual ? '' : 'cursor-pointer hover:bg-muted/40';

  // The task's live TDD phase, derived once: it drives both the status-line
  // text and which tab the row opens the detail view on.
  const derivedPhase = deriveTddPhase(effectiveTask, reviewPipeline);
  // Opening a task is an in-place view swap on the current route — set
  // `?task=<id>&tab=<phase>` (preserving other params) rather than navigating,
  // so the workspace stays mounted and its data warm.
  const openTaskPage = () => {
    setSearchParams((prev) => {
      const next = new URLSearchParams(prev);
      next.set('task', task.id);
      next.set('tab', phaseToTab(derivedPhase));
      return next;
    });
  };

  // The status-line text (beneath the title): superseded note, manual-task
  // vocabulary, the live TDD phase label, or the completed/not-started fallback.
  // Computed as a plain string so it can sit inline with the slug.
  const statusText = ((): string => {
    if (effectiveTask.status === 'superseded') return effectiveTask.note ?? 'Superseded';
    if (effectiveTask.pipelineType === 'manual') {
      // `completionNote` is currently always absent — the note rides the
      // terminal commit's `CompletionNote:` trailer and nothing parses that
      // trailer back onto the projected task yet (fix
      // completion-note-trailer-has-no-reader). The field is kept, not
      // deleted: it is where that reader will land.
      return effectiveTask.status === 'completed'
        ? effectiveTask.completionNote ?? 'Completed'
        : 'Awaiting manual completion';
    }
    // A recorded completion time is authoritative: show it even if the SHA-based
    // gate walk still reports an active review/refactor phase (e.g. a completed
    // task whose review records weren't captured, or one completed via another
    // path). Without a completedAt, an in-flight derived phase still shows its
    // live label below — that window is the green-landed/review-pending state on a
    // task whose status has already flipped to completed.
    if (effectiveTask.status === 'completed' && effectiveTask.completedAt) {
      return formatCompleted(effectiveTask.completedAt);
    }
    const derived = derivedPhase;
    if (derived !== 'complete' && derived !== 'red') {
      if (derived.startsWith('review:')) {
        const type = derived.slice(7);
        const step = reviewPipeline?.find((s) => s.type === type);
        return step ? `${step.label} review in progress..` : `${type} review in progress..`;
      }
      if (derived.startsWith('refactor:')) {
        const type = derived.slice(9);
        const step = reviewPipeline?.find((s) => s.type === type);
        return step ? `Refactoring after ${step.label} review..` : `Refactoring after ${type} review..`;
      }
      const label = phaseLabels[derived as keyof typeof phaseLabels];
      if (label) return label;
    }
    if (derived === 'red' && effectiveTask.redStartedAt) return phaseLabels.red;
    if (effectiveTask.status === 'completed') {
      return effectiveTask.completedAt ? formatCompleted(effectiveTask.completedAt) : 'Completed';
    }
    return 'Not started';
  })();
  // The mock's subtitle slug is the compact TN form (`T1 · completed 19 Jul`)
  // — display-only; slug paths stay `task-N` everywhere else (copy-id, commit
  // headers, routes), so only the bare task-component form compacts.
  const displaySlug = slugPath?.replace(/^task-(\d+)$/, 'T$1');
  const subtitle = displaySlug ? `${displaySlug} · ${statusText}` : statusText;

  return (
    <div
      className={`flex items-center gap-3 px-4 py-3 ${inProgressAccent} ${hoverClass}`}
      {...(isManual
        ? {}
        : {
            role: 'button',
            tabIndex: 0,
            onClick: openTaskPage,
            onKeyDown: (e: React.KeyboardEvent) => {
              if (e.key === 'Enter' || e.key === ' ') {
                e.preventDefault();
                openTaskPage();
              }
            },
          })}
    >
      {/* Status icon — vertically centered against the row (the slug now rides
          in the status line, not a column). */}
      <div className="flex-shrink-0" title={iconTitle}>
        <Icon className={`h-5 w-5 ${iconClass}`} />
      </div>

      {/* Content: the title spans the full width on its own row; the status
          text (left) and the commit-pipeline pills (right) share the row
          beneath it. */}
      <div className="flex-1 min-w-0">
        {/* Top row: the title (left) and the worktree indicator (right), so the
            indicator is right-aligned on the task's first row and the pipeline
            rail sits on the status line below. */}
        <div data-testid="task-title-row" className="flex items-start justify-between gap-2">
          <div className={`min-w-0 flex-1 text-sm font-normal leading-snug ${effectiveTask.status === 'superseded' ? 'line-through text-muted-foreground' : ''}`}>
            <ReactMarkdown remarkPlugins={[remarkGfm]} components={{ p: ({ children }) => <span>{children}</span> }}>
              {task.description}
            </ReactMarkdown>
          </div>

          {/* Worktree override indicator — shown only when this task's status
              comes from a worktree the feature header isn't already showing
              (ADR-0007 / multi-ref-projection). The shared MiniStatusRail in
              compact card mode renders the clickable branch chip alone (no
              worker/env glyphs — the row carries no per-task run identity), so
              the task row stays structurally consistent with every other
              surface instead of hand-matching a bespoke span. */}
          {showWorktreePill && (
            <MiniStatusRail
              mode="card"
              worktreeMode="compact"
              branches={worktreeBranches}
              onMerge={openMerge}
              isWorkerRun={false}
              where="local"
              className="flex-shrink-0"
            />
          )}
        </div>

        <div data-testid="task-statusline" className="mt-1 flex items-center justify-between gap-3">
          {/* Reads effectiveTask so worktree-completed / -superseded work shows
              its real status text, not "Not started". */}
          <p data-testid="task-subtitle" className="mono text-[11px] text-subtle truncate">
            {subtitle}
          </p>

          <div className="flex shrink-0 items-center gap-2">
            {/* Pipeline pills / fast-forward / manual affordance. */}
            {renderRightCell({
              task: effectiveTask,
              repoId,
              reviewPipeline,
              manualCompleteContext,
            })}
          </div>
        </div>
      </div>
    </div>
  );
};

/**
 * Decides what (if anything) renders in the right-hand cell of a TaskRow.
 * Manual tasks get the markdown-edit affordance (suppressing the TDD
 * timeline entirely); everything else falls back to the standard pipeline
 * timeline, which itself only renders once the task has activity.
 */
interface RenderRightCellArgs {
  task: TaskRowTask;
  repoId: string;
  reviewPipeline?: PipelineStep[];
  manualCompleteContext?: ManualCompleteContext;
}

function renderRightCell({
  task,
  repoId,
  reviewPipeline,
  manualCompleteContext,
}: RenderRightCellArgs): React.ReactNode {
  if (task.status === 'superseded') {
    // Superseded tasks skipped the pipeline. The orange tick on the left
    // marks the terminal state; this fast-forward marker echoes that the
    // task was fast-forwarded past, sitting where the pipeline strip would.
    return (
      <div className="flex-shrink-0 flex justify-center" title="Superseded — skipped">
        <FastForward className="h-5 w-5 text-orange-500" />
      </div>
    );
  }

  if (task.pipelineType === 'manual') {
    // No manualCompleteContext means the parent hasn't plumbed the
    // identifiers through yet — render nothing rather than a half-broken
    // UI. Add the context at the call site to enable the affordance.
    if (!manualCompleteContext) return null;
    return (
      <div className="flex-shrink-0" onClick={(e) => e.stopPropagation()}>
        <ManualCompleteAffordance
          task={task}
          repoId={repoId}
          context={manualCompleteContext}
        />
      </div>
    );
  }

  // `task` is already telemetry-overlayed by the caller (TaskRow), so the
  // strip reads the same derived fields the row navigates on. The overlay
  // makes derived fields win where present and falls back to the raw task
  // fields where derivedState is empty (legacy tasks, fresh clones,
  // missing-hooks scenarios). See fix: dashboard-pipeline-not-derived-from-telemetry.
  // Include greenStartedAt: a skip-RED task (spikes, --phase green) signals
  // in-flight work via the green phase, not red — without it a green-started
  // task with no commit yet would render no pipeline at all.
  const hasTddActivity = !!(task.redStartedAt || task.greenStartedAt || task.testCommitSha);
  if (task.status === 'not_started' && !hasTddActivity) return null;

  // The chips are display-only — no onPhaseClick. A click on the strip falls
  // through to the row, which navigates to the full task detail page; the
  // detail lives there now, not in a popover.
  return (
    <div className="flex-shrink-0">
      <CommitPipeline task={task} reviewPipeline={reviewPipeline} />
    </div>
  );
}

/**
 * Inline button → expanded note form for manual-pipelineType tasks.
 * Closed state shows "Mark complete"; open state shows a textarea + Submit,
 * which POSTs to the manual-complete endpoint. That endpoint emits the
 * `manual:` terminal commit; the resulting ref move is what the dashboard's
 * git-ref watcher picks up to re-project this row (fix
 * manual-complete-writes-markdown-nothing-reads — it used to write a markdown
 * line the projector ignored, so the row never moved).
 *
 * The note is optional. Trivial gates ("verify staging works") submit fine
 * with empty input; the server omits the `CompletionNote:` commit trailer
 * entirely when there's nothing to record.
 */
interface ManualCompleteAffordanceProps {
  task: TaskRowTask;
  repoId: string;
  context: ManualCompleteContext;
}

const ManualCompleteAffordance: React.FC<ManualCompleteAffordanceProps> = ({ task, repoId, context }) => {
  const [open, setOpen] = useState(false);
  const [note, setNote] = useState('');
  const [submitting, setSubmitting] = useState(false);
  const [error, setError] = useState<string | null>(null);

  // On success the file-watcher refreshes this task to status: completed,
  // which causes the right-hand cell to swap and this component to unmount
  // mid-`fetch`. Guard the post-await state writes so React doesn't warn
  // (and so error/submitting flags don't get re-set on the dead instance).
  const mounted = useRef(true);
  useEffect(() => {
    mounted.current = true;
    return () => { mounted.current = false; };
  }, []);

  if (task.status === 'completed') return null;

  const trimmed = note.trim();
  // The note is optional — trivial gates like "verify staging works"
  // don't need an audit blurb. Only `submitting` disables the button.
  const canSubmit = !submitting;

  const submit = async () => {
    if (!canSubmit) return;
    setSubmitting(true);
    setError(null);
    try {
      const res = await fetch(
        `/api/repos/${encodeURIComponent(repoId)}/plans/${encodeURIComponent(context.planId)}/features/${encodeURIComponent(context.featureId)}/tasks/${context.taskNumber}/manual-complete`,
        {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          // `task.id` is the projected task's UUID (the projector keys it off
          // the markdown `id:` stamp). Sending it makes the server resolve by
          // identity rather than by the positional taskNumber in the path,
          // which is this row's array index and only coincides with the
          // `### n.` heading number when the doc's numbering is gapless.
          // Getting that wrong now completes the wrong task permanently.
          body: JSON.stringify({ completionNote: trimmed, taskUuid: task.id }),
        },
      );
      if (!mounted.current) return;
      if (!res.ok) {
        const body = await res.json().catch(() => ({}));
        if (!mounted.current) return;
        setError(typeof body.error === 'string' ? body.error : `Failed (${res.status})`);
        return;
      }
      setOpen(false);
      setNote('');
    } catch (err) {
      if (!mounted.current) return;
      setError(err instanceof Error ? err.message : 'Network error');
    } finally {
      if (mounted.current) setSubmitting(false);
    }
  };

  if (!open) {
    return (
      <button
        type="button"
        onClick={() => setOpen(true)}
        className="px-2 py-1 text-xs rounded border border-blue-300 text-blue-700 hover:bg-blue-50 dark:border-blue-700 dark:text-blue-300 dark:hover:bg-blue-950/30"
      >
        Mark complete
      </button>
    );
  }

  return (
    <div className="flex flex-col gap-1 min-w-[220px]">
      <label className="text-xs text-muted-foreground" htmlFor={`manual-note-${task.id}`}>
        Completion note
      </label>
      <textarea
        id={`manual-note-${task.id}`}
        value={note}
        onChange={(e) => setNote(e.target.value)}
        rows={2}
        className="text-xs rounded border border-muted-foreground/30 px-2 py-1 bg-background"
        placeholder="What was verified / done?"
      />
      <div className="flex items-center gap-2">
        <button
          type="button"
          onClick={submit}
          disabled={!canSubmit}
          className="px-2 py-1 text-xs rounded bg-blue-600 text-white disabled:opacity-40 disabled:cursor-not-allowed hover:bg-blue-700"
        >
          Submit
        </button>
        <button
          type="button"
          onClick={() => { setOpen(false); setError(null); }}
          className="px-2 py-1 text-xs rounded border border-muted-foreground/30 hover:bg-muted/50"
        >
          Cancel
        </button>
        {error && <span role="alert" className="text-xs text-red-600">{error}</span>}
      </div>
    </div>
  );
};

export default TaskRow;
