import type { LandAvailability, RunEvent } from '@magic-ingredients/tiny-brain-core';
// Value import via the browser-safe subpath — the core barrel pulls node
// builtins, which Vite externalises and crashes at runtime. The running /
// terminal PARTITION is core's (beside the vocabulary, so the two cannot
// drift); this module adds only presentation — the labels — keyed as `Record`s
// over the partition types, so a new core phase fails to COMPILE here instead
// of silently misclassifying at runtime. That presentation split is also why
// the fold lives in dashboard utils rather than core beside `deriveEndcapState`:
// the machine's states carry UI copy, which is the client's altitude.
import {
  isReconcileStreamPhase,
  isReconcileTerminalPhase,
  type ReconcileRunningPhase,
  type ReconcileTerminalPhase,
} from '@magic-ingredients/tiny-brain-core/reconcile-stream';

export type { ReconcileRunningPhase };
/** The typed end states a reconcile run settles into (F7 task 1 terminals). */
export type ReconcileTerminal = ReconcileTerminalPhase;

/** Honest per-rung labels — the label follows the RUNNING rung, never a stale one. */
const RUNNING_LABELS: Record<ReconcileRunningPhase, string> = {
  queued: 'Queued…',
  replaying: 'Rebasing onto main…',
  agent: 'Agent resolving…',
  verifying: 'Verifying…',
};

const TERMINAL_LABELS: Record<ReconcileTerminal, string> = {
  'ready-to-land': 'Ready to land',
  conflict: 'Conflicts with main',
  'verify-failed': 'Verification failed',
  failed: 'Reconcile failed',
};

/** The landing strip's render state — exactly one of idle / running / terminal. */
export type ReconcileStripState =
  | { kind: 'idle' }
  | {
      kind: 'running';
      phase: ReconcileRunningPhase;
      label: string;
      /**
       * When the CURRENT phase was entered (its frame's `ts`) — the surface's
       * elapsed-time anchor, so a 12-minute verify visibly ticks instead of
       * reading as a hang (reconcile-verify-progress-invisible). Absent on the
       * pre-frame `queued` fallback: nothing has been entered yet, and a
       * fabricated timestamp would show a made-up count.
       */
      since?: string;
    }
  | {
      kind: 'terminal';
      terminal: ReconcileTerminal;
      label: string;
      /**
       * Where the terminal came from: a typed frame the live run itself emitted
       * (`stream`), or the reconstruction from the persisted on-disk verdict
       * (`disk`). Consumers deciding OWNERSHIP — e.g. whether the strip's
       * terminal replaces a run's raw error channel — must key on `stream`: a
       * disk reconstruction describes the branch's standing verdict, not what
       * the just-finished run concluded (fix merge-click-bypasses-reconcile-
       * strip task 3 refactor, adversarial MEDIUM: a fault under a stale
       * conflicts verdict must not be swallowed).
       */
      source: 'stream' | 'disk';
      /**
       * The persisted failure reason, rendered in the strip so a refreshed
       * page says "Verification failed: <reason>" instead of going idle (fix
       * verify-outcomes-invisible-in-ui task 1). Set on disk-reconstructed
       * failure terminals; a live stream's failure detail rides `output`.
       */
      reason?: string;
    };

/**
 * The branch's persisted latest verdict with its reason — the model's
 * `lastReconcile` axis, the reconstruction source for the FAILURE family
 * (verify-failed / failed), which `landAvailability` deliberately maps to
 * `unknown` for the Merge gate.
 */
export interface LastReconcileFeed {
  verdict: 'ready-to-land' | 'conflicts' | 'verify-failed' | 'failed';
  exitReason?: string;
  /**
   * The verdict run's id. Not read by the strip machine itself — it is the
   * declared seam for THIS FIX's task 2 (CLI-initiated reconciles surface on
   * the strip), whose foreign-run subscription keys `useRunStream` off it.
   * Carried on the axis from day one so the wire shape doesn't churn between
   * the two tasks (the primitive-ahead-of-consumer house pattern).
   */
  runId?: string;
}

/**
 * The landing strip as a PURE state machine over the reconcile run's streamed
 * phase events (work-item-provenance F7 task 2), with the on-disk reconcile
 * result — the F6 model's `landAvailability` axis — as the refresh/reconnect
 * reconstruction source. The fold, in precedence order:
 *
 * 1. A streamed TYPED TERMINAL frame wins outright — over liveness (the exit
 *    may still be in flight) and over a stale on-disk verdict (the fresh run
 *    is truer).
 * 2. While the stream is live, the LATEST recognised phase renders with its
 *    honest label (`queued` before any frame arrives); foreign pipeline
 *    phases on the shared channel (worker TDD rungs, land phases) are
 *    filtered by the core guard and never move the machine.
 * 3. A dead stream NEVER reads as running — the stuck-spinner this feature
 *    kills. With no terminal frame it reconstructs from the on-disk result
 *    (`landable` → ready-to-land, `conflicts` → conflict); `already-landed` /
 *    `unknown` / absent mean nothing to show — idle.
 */
export function deriveReconcileStrip(input: {
  events: readonly RunEvent[];
  /** Whether the reconcile run's stream is live (subscribed, no exit, not broken). */
  streaming: boolean;
  /** The persisted reconcile verdict (the F6 model's availability axis), when known. */
  onDisk?: LandAvailability;
  /** The persisted latest verdict + reason — the failure family's reconstruction source. */
  lastReconcile?: LastReconcileFeed;
}): ReconcileStripState {
  // One frame object, not parallel phase/ts locals: `ts` is required on the
  // pipeline variant, so a frame either exists whole or not at all — a split
  // pair would force a statically-dead second guard on the `since` spread.
  let latestFrame: { phase: ReconcileRunningPhase | ReconcileTerminalPhase; ts: string } | undefined;
  for (const event of input.events) {
    if (event.type === 'pipeline' && isReconcileStreamPhase(event.phase)) {
      latestFrame = { phase: event.phase, ts: event.ts };
    }
  }
  const latest = latestFrame?.phase;

  if (latest !== undefined && isReconcileTerminalPhase(latest)) {
    return { kind: 'terminal', terminal: latest, label: TERMINAL_LABELS[latest], source: 'stream' };
  }
  if (input.streaming) {
    // The terminal partition returned above, so a defined `latest` here is a
    // running phase; the explicit re-narrow keeps the label lookup compiling
    // against the Record<ReconcileRunningPhase, …> map.
    const phase: ReconcileRunningPhase =
      latest !== undefined && !isReconcileTerminalPhase(latest) ? latest : 'queued';
    // `since` is the CURRENT phase frame's timestamp — the elapsed-time anchor
    // (reconcile-verify-progress-invisible); the pre-frame fallback has none.
    return {
      kind: 'running',
      phase,
      label: RUNNING_LABELS[phase],
      ...(latestFrame !== undefined ? { since: latestFrame.ts } : {}),
    };
  }
  if (input.onDisk === 'landable') {
    return { kind: 'terminal', terminal: 'ready-to-land', label: TERMINAL_LABELS['ready-to-land'], source: 'disk' };
  }
  if (input.onDisk === 'conflicts') {
    return { kind: 'terminal', terminal: 'conflict', label: TERMINAL_LABELS.conflict, source: 'disk' };
  }
  // A landed branch has nothing left to reconcile — a stale failure verdict
  // from before the land must not resurrect as "Verification failed" on a
  // merged item (adversarial review of 9e8ebf882, LOW).
  if (input.onDisk === 'already-landed') {
    return { kind: 'idle' };
  }
  // The failure family reconstructs from the persisted verdict + reason (fix
  // verify-outcomes-invisible-in-ui task 1) — availability reads these as
  // `unknown` for the Merge gate, but the strip must SAY what happened.
  // Landable/conflicts stay the availability axis's to reconstruct above
  // (both describe the same latest run, so they cannot disagree).
  if (input.lastReconcile?.verdict === 'verify-failed' || input.lastReconcile?.verdict === 'failed') {
    const terminal = input.lastReconcile.verdict;
    return {
      kind: 'terminal',
      terminal,
      label: TERMINAL_LABELS[terminal],
      source: 'disk',
      ...(input.lastReconcile.exitReason !== undefined ? { reason: input.lastReconcile.exitReason } : {}),
    };
  }
  return { kind: 'idle' };
}
