import { useState } from 'react';
import { ArrowLeft, Archive } from 'lucide-react';
import type { PipelineStep } from '@magic-ingredients/tiny-brain-core/phase-derivation';
import { cn } from '@/lib/utils';
import { ResizablePanel, ResizablePanelGroup, ResizableHandle } from '@/components/ui/resizable';
import PlanList from '@/components/PlanList';
import PlanDetails from '@/components/PlanDetails';
import FixList from '@/components/FixList';
import FixDetail from '@/components/FixDetail';
import type { Plan, Fix } from '@/types';

/**
 * board-first-chrome T3 — the Archive view. The board is active work only, so
 * archived plans + fixes are dropped from the board projection and reached here
 * instead (opened from the top-rail Archive control). A master-detail over the
 * archived items, reusing the same list + detail components the workspace lists
 * used; a kind filter (All / Plans / Fixes) scopes the list, and the detail's
 * Unarchive action returns an item to the active board.
 *
 * Dumb surface: the archived sets and the unarchive handlers are owned by the
 * page (which holds repoPlans/repoFixes and the archive/unarchive API calls).
 */
export interface ArchiveViewProps {
  /** All plans; archived (`type === 'archived'`) and superseded ones are surfaced here. */
  plans: Plan[];
  /** All fixes; archived (`archived === true`) and superseded ones are surfaced here. */
  fixes: Fix[];
  repoId: string;
  reviewPipeline?: PipelineStep[];
  viewMode: 'summary' | 'details' | 'json';
  onUnarchivePlan: (planId: string) => void;
  onUnarchiveFix: (fixId: string) => void;
  /** Return to the board. */
  onClose: () => void;
}

type ArchiveKind = 'all' | 'prd' | 'fix';

// Selection keys are kind-prefixed so one piece of state serves both lists.
const PLAN_KEY = 'prd:';
const FIX_KEY = 'fix:';

export function ArchiveView({
  plans,
  fixes,
  repoId,
  reviewPipeline,
  viewMode,
  onUnarchivePlan,
  onUnarchiveFix,
  onClose,
}: ArchiveViewProps) {
  // Archived (a location) and superseded (a terminal "no longer relevant"
  // status) both leave the board and land here, so neither kind of dropped work
  // vanishes.
  const archivedPlans = plans.filter((p) => p.type === 'archived' || p.status === 'superseded');
  const archivedFixes = fixes.filter((f) => f.archived || f.status === 'superseded');
  const [selected, setSelected] = useState<string | null>(null);
  const [kind, setKind] = useState<ArchiveKind>('all');

  // The kind pill scopes BOTH the list and the detail: when it hides a kind, a
  // still-selected item of that kind must not keep rendering in the detail pane
  // (the selection is preserved and reappears when the kind is shown again).
  const kindShowsPlans = kind === 'all' || kind === 'prd';
  const kindShowsFixes = kind === 'all' || kind === 'fix';
  const selectedPlan =
    kindShowsPlans && selected?.startsWith(PLAN_KEY)
      ? archivedPlans.find((p) => p.id === selected.slice(PLAN_KEY.length)) ?? null
      : null;
  const selectedFix =
    kindShowsFixes && selected?.startsWith(FIX_KEY)
      ? archivedFixes.find((f) => f.id === selected.slice(FIX_KEY.length)) ?? null
      : null;

  const empty = archivedPlans.length === 0 && archivedFixes.length === 0;
  const showPlans = kindShowsPlans && archivedPlans.length > 0;
  const showFixes = kindShowsFixes && archivedFixes.length > 0;

  const pills: { value: ArchiveKind; label: string; count: number }[] = [
    { value: 'all', label: 'All', count: archivedPlans.length + archivedFixes.length },
    { value: 'prd', label: 'Plans', count: archivedPlans.length },
    { value: 'fix', label: 'Fixes', count: archivedFixes.length },
  ];

  return (
    <div className="flex h-full flex-col overflow-hidden" data-testid="archive-view">
      <div className="flex flex-shrink-0 items-center gap-3 px-4 py-3">
        <button
          type="button"
          onClick={onClose}
          aria-label="Back to the board"
          className="inline-flex items-center gap-1.5 rounded-lg px-2 py-1 text-sm text-muted-foreground transition-colors hover:text-foreground"
        >
          <ArrowLeft className="h-4 w-4" aria-hidden="true" />
          Board
        </button>
        <h1 className="display inline-flex items-center gap-2 text-lg font-bold">
          <Archive className="h-4 w-4" aria-hidden="true" />
          Archive
        </h1>
        <span className="mono text-[11px] text-muted-foreground">
          {archivedPlans.length} plans · {archivedFixes.length} fixes
        </span>
      </div>

      {empty ? (
        <div className="flex flex-1 items-center justify-center px-6 text-center text-sm text-muted-foreground">
          Nothing archived. Archived plans and fixes appear here, off the board.
        </div>
      ) : (
        <div className="flex-1 overflow-hidden">
          <ResizablePanelGroup direction="horizontal">
            <ResizablePanel defaultSize={30} minSize={20} maxSize={40}>
              <div className="flex h-full flex-col overflow-hidden">
                <div className="flex flex-shrink-0 flex-wrap gap-1.5 px-3 pb-2 pt-3" role="group" aria-label="Filter archive by kind">
                  {pills.map((pill) => (
                    <button
                      key={pill.value}
                      type="button"
                      data-testid={`archive-kind-${pill.value}`}
                      aria-pressed={kind === pill.value}
                      onClick={() => setKind(pill.value)}
                      className={cn(
                        'inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-xs transition-colors',
                        kind === pill.value
                          ? 'border-transparent bg-foreground text-background'
                          : 'border-border text-muted-foreground hover:text-foreground',
                      )}
                    >
                      {pill.label}
                      <span className="mono">{pill.count}</span>
                    </button>
                  ))}
                </div>
                <div className="flex-1 overflow-auto">
                  {showPlans && (
                    <PlanList
                      plans={archivedPlans}
                      selectedPlanId={selectedPlan?.id ?? null}
                      onSelectPlan={(id) => setSelected(`${PLAN_KEY}${id}`)}
                    />
                  )}
                  {showFixes && (
                    <FixList
                      fixes={archivedFixes}
                      selectedFixId={selectedFix?.id ?? null}
                      onSelectFix={(id) => setSelected(`${FIX_KEY}${id}`)}
                      reviewPipeline={reviewPipeline}
                      repoId={repoId}
                    />
                  )}
                </div>
              </div>
            </ResizablePanel>
            <ResizableHandle withHandle />
            <ResizablePanel defaultSize={70}>
              <div className="flex h-full flex-col">
                {selectedPlan ? (
                  <div className="panel mx-3 mb-3 flex min-h-0 flex-1 flex-col overflow-hidden rounded-2xl">
                    <PlanDetails
                      plan={selectedPlan}
                      viewMode={viewMode}
                      repoId={repoId}
                      onUnarchive={() => onUnarchivePlan(selectedPlan.id)}
                    />
                  </div>
                ) : selectedFix ? (
                  <div className="panel mx-3 mb-3 flex min-h-0 flex-1 flex-col overflow-hidden rounded-2xl">
                    <FixDetail
                      fix={selectedFix}
                      repoId={repoId}
                      onUnarchive={() => onUnarchiveFix(selectedFix.id)}
                    />
                  </div>
                ) : (
                  <div className="flex h-full items-center justify-center text-sm text-muted-foreground">
                    Select an archived item to see its detail and unarchive it.
                  </div>
                )}
              </div>
            </ResizablePanel>
          </ResizablePanelGroup>
        </div>
      )}
    </div>
  );
}

export default ArchiveView;
