import type { FC } from 'react';
import { ShieldCheck, Compass, Minus, RotateCcw, AlertTriangle, CircleDashed, type LucideIcon } from 'lucide-react';
import { cn } from '@/lib/utils';
import type { PlanningGateStatus, PlanningGateState } from '@magic-ingredients/tiny-brain-core';

export interface PlanningChecksRowProps {
  /** The item's folded planning-gate states, as served on the payload
   *  (`plan.planning`). Absent / empty ⇒ the component renders nothing. */
  checks: readonly PlanningGateStatus[] | undefined;
  /**
   * Where the row is rendered — `card` is the compact chip row on a Backlog
   * board card; `header` is the detail-header pill row. Presentation only; the
   * state→tone map is identical.
   */
  variant?: 'card' | 'header';
}

/** A chip's visual weight, exposed as `data-tone` so a surface (and a test) can
 *  read the quiet-good / attention / neutral split without knowing the gate. */
type Tone = 'quiet' | 'attention' | 'neutral';

interface KnownGate {
  readonly label: string;
  readonly Icon: LucideIcon;
}

/**
 * The gates this row knows how to label and tone. A gate NOT in this map renders
 * neutrally with its literal name — so a third planning check added to the
 * config needs no change here (plan-readiness-indicators F3 acceptance
 * criterion). `architecture-alignment` reads as the shorter "architecture".
 */
const KNOWN_GATES: Record<string, KnownGate> = {
  deliverability: { label: 'deliverability', Icon: ShieldCheck },
  'architecture-alignment': { label: 'architecture', Icon: Compass },
};

/** One planning state's full presentation, keyed exhaustively by
 *  `PlanningGateState` so a new state is a compile error here rather than a
 *  silent fall-through. Quiet-good stays quiet (passed / outstanding); attention
 *  fills and colours up (stale / needs-rework, amber / red) with a re-run /
 *  rework affordance. `Icon: null` ⇒ use the gate's own glyph (passed). */
interface StateStyle {
  readonly tone: Tone;
  readonly Icon: LucideIcon | null;
  readonly chipClass: string;
  readonly iconClass: string;
  /** The re-run / rework affordance appended to the label (attention states). */
  readonly suffix?: string;
  /** Screen-reader phrasing (the visible chip shows the gate name + suffix). */
  readonly aria: string;
}

const STATE_STYLE: Record<PlanningGateState, StateStyle> = {
  passed: { tone: 'quiet', Icon: null, chipClass: 'text-subtle', iconClass: 'text-done', aria: 'passed' },
  outstanding: {
    tone: 'quiet',
    Icon: Minus,
    chipClass: 'text-subtle border border-dashed border-border',
    iconClass: 'text-subtle',
    aria: 'not assessed',
  },
  stale: {
    tone: 'attention',
    Icon: RotateCcw,
    chipClass: 'text-warn bg-warn/10 border border-warn/30 font-semibold',
    iconClass: '',
    suffix: 're-run',
    aria: 'stale, re-run',
  },
  'needs-rework': {
    tone: 'attention',
    Icon: AlertTriangle,
    chipClass: 'text-destructive bg-destructive/10 border border-destructive/30 font-semibold',
    iconClass: '',
    suffix: 'rework',
    aria: 'needs rework',
  },
};

interface CheckView {
  readonly tone: Tone;
  readonly Icon: LucideIcon;
  readonly text: string;
  readonly aria: string;
  readonly chipClass: string;
  readonly iconClass: string;
}

/** Map one served `{gate, state}` to its chip's tone, glyph, label and classes.
 *  A known gate takes the exhaustive `STATE_STYLE` table (its own glyph for the
 *  passed state); an unknown gate renders neutral with its literal name. */
function describeCheck(check: PlanningGateStatus): CheckView {
  const known = KNOWN_GATES[check.gate];
  if (known === undefined) {
    return {
      tone: 'neutral',
      Icon: CircleDashed,
      text: check.gate,
      aria: `${check.gate}: ${check.state}`,
      chipClass: 'text-muted-foreground bg-foreground/[0.06]',
      iconClass: 'text-muted-foreground',
    };
  }
  const style = STATE_STYLE[check.state];
  return {
    tone: style.tone,
    Icon: style.Icon ?? known.Icon,
    text: style.suffix !== undefined ? `${known.label} · ${style.suffix}` : known.label,
    aria: `${known.label}: ${style.aria}`,
    chipClass: style.chipClass,
    iconClass: style.iconClass,
  };
}

/**
 * The planning-checks row (readiness-rail-ui F3) — renders the served
 * `{gate, state}` list as chips. Quiet-good states (passed / outstanding) sit
 * low-contrast; attention states (stale / needs-rework) fill and colour up with
 * a re-run / rework affordance; an unknown gate renders neutrally with its
 * literal name so a third check needs no code change. Dumb: it maps served state
 * to tone and derives nothing. Renders nothing for an absent / empty list.
 */
export const PlanningChecksRow: FC<PlanningChecksRowProps> = ({ checks, variant = 'card' }) => {
  if (checks === undefined || checks.length === 0) return null;
  return (
    <div
      data-testid="planning-checks-row"
      role="list"
      aria-label="Planning checks"
      className={cn('flex flex-wrap items-center', variant === 'header' ? 'gap-1.5' : 'gap-1')}
    >
      {checks.map((check) => {
        const v = describeCheck(check);
        return (
          <span
            key={check.gate}
            role="listitem"
            data-testid={`planning-check-${check.gate}`}
            data-state={check.state}
            data-tone={v.tone}
            aria-label={v.aria}
            className={cn(
              'mono inline-flex items-center gap-1 whitespace-nowrap rounded-md border border-transparent px-1.5 py-0.5 leading-tight',
              variant === 'header' ? 'text-[11px]' : 'text-[10.5px]',
              v.chipClass,
            )}
          >
            <v.Icon aria-hidden="true" className={cn('h-3 w-3 shrink-0', v.iconClass)} />
            {v.text}
          </span>
        );
      })}
    </div>
  );
};

export default PlanningChecksRow;
