import { useCallback, useEffect, useState } from 'react';

/**
 * Client view of a worker as the global /api/workers routes return it —
 * the named (agent · model · effort · environment) profile work is
 * dispatched to.
 */
export interface WorkerView {
  /**
   * Stable UUIDv7 identity (ADR-0027) — the key CRUD addresses. `name` is
   * a mutable label the row displays; the uuid is what edit/delete/probe
   * send, so a rename never strands a reference.
   */
  uuid: string;
  name: string;
  adapter: string;
  environment: string;
  model: string;
  effort: 'low' | 'medium' | 'high';
  timeoutMs?: number;
  /**
   * True when a committed worker references an environment that doesn't
   * resolve against the global registry (repo-scoped surface only). The
   * row badges it rather than hiding it — the same exclusion the launch
   * menu applies.
   */
  danglingEnvironment?: boolean;
}

/** One manual probe outcome, as POST /api/workers/:id/probe returns it. */
export interface WorkerProbeView {
  worker: string;
  ok: boolean;
  probedAt: string;
  reason?: string;
}

// Create sends the authored fields only — the server mints the uuid, and
// `danglingEnvironment` is a server-computed row badge, never client input.
export type CreateWorkerInput = Omit<WorkerView, 'timeoutMs' | 'uuid' | 'danglingEnvironment'>;

/** One provider's models as offered to an agent, as the server gates them. */
export interface AgentModelGroupView {
  provider: string;
  providerLabel: string;
  /** False = drivable but keyless in the environment — render locked. */
  enabled: boolean;
  models: string[];
}

export interface AgentOptionsView {
  agent: string;
  agentLabel: string;
  groups: AgentModelGroupView[];
}

/**
 * The Environment → Agent → Model options for the draft form, resolved
 * SERVER-side (env keys ∩ each agent's drivable providers) and refetched
 * whenever the chosen environment changes. A failed fetch degrades to no
 * options — the form disables create rather than guessing.
 */
export function useWorkerFormOptions(environment: string) {
  const [agents, setAgents] = useState<AgentOptionsView[]>([]);

  useEffect(() => {
    if (environment === '') {
      setAgents([]);
      return;
    }
    let cancelled = false;
    void (async () => {
      try {
        const res = await fetch(
          `/api/workers/form-options?environment=${encodeURIComponent(environment)}`,
        );
        if (!res.ok) {
          if (!cancelled) setAgents([]);
          return;
        }
        const data = (await res.json()) as { agents: AgentOptionsView[] };
        if (!cancelled) setAgents(data.agents ?? []);
      } catch {
        if (!cancelled) setAgents([]);
      }
    })();
    return () => {
      cancelled = true;
    };
  }, [environment]);

  return { agents };
}

/**
 * The Workers surface's data feed: list on mount, dumb create/remove that
 * POST/DELETE raw fields for the server to validate, and MANUAL probes —
 * `probe`/`reload` run only when the user asks (per-row Re-check /
 * top-bar Reload); nothing probes on mount and nothing polls.
 *
 * `basePath` selects the surface: the global `/api/workers` (default,
 * user-scope) or a repo-scoped `/api/repos/:repoId/workers`. Every CRUD /
 * probe request is rooted at it, so the same hook drives both the global
 * /workers page and the repo Settings section.
 */
export function useWorkers(basePath: string = '/api/workers') {
  const [workers, setWorkers] = useState<WorkerView[]>([]);
  const [probes, setProbes] = useState<Record<string, WorkerProbeView>>({});
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const refresh = useCallback(async (): Promise<WorkerView[]> => {
    try {
      const res = await fetch(basePath);
      if (!res.ok) {
        setError(`Failed to load workers (HTTP ${res.status})`);
        return [];
      }
      const data = (await res.json()) as { workers: WorkerView[] };
      const list = data.workers ?? [];
      setWorkers(list);
      // Prune probe results for uuids no longer listed — a deleted worker
      // must not leave its status behind. Keyed by uuid (ADR-0027) so a
      // rename keeps the row's probe status.
      setProbes((prev) =>
        Object.fromEntries(
          Object.entries(prev).filter(([uuid]) => list.some((w) => w.uuid === uuid)),
        ),
      );
      setError(null);
      return list;
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to load workers');
      return [];
    } finally {
      setLoading(false);
    }
  }, [basePath]);

  useEffect(() => {
    void refresh();
  }, [refresh]);

  // Shared submit for create (POST /api/workers) and update
  // (PUT /api/workers/:name): the body is sent raw for the server to run
  // its triple validation (environment × agent × model); the hook stays
  // dumb, reporting the server's { ok, error } and refreshing on success.
  const submitWorker = useCallback(
    async (
      method: 'POST' | 'PUT',
      url: string,
      body: unknown,
    ): Promise<{ ok: boolean; error?: string }> => {
      try {
        const res = await fetch(url, {
          method,
          headers: { 'content-type': 'application/json' },
          body: JSON.stringify(body),
        });
        if (!res.ok) {
          const errBody = (await res.json().catch(() => ({}))) as { error?: string };
          return { ok: false, error: errBody.error ?? `HTTP ${res.status}` };
        }
      } catch (err) {
        return {
          ok: false,
          error: err instanceof Error ? err.message : 'Failed to save worker',
        };
      }
      await refresh();
      return { ok: true };
    },
    [refresh],
  );

  const create = useCallback(
    (input: CreateWorkerInput) => submitWorker('POST', basePath, input),
    [submitWorker, basePath],
  );

  // Edit keys on the worker's uuid (the route); `name` is an ordinary body
  // field, so a rename rides in the same patch (ADR-0027). The body is sent
  // raw for the server to run its triple validation — the hook stays dumb.
  const update = useCallback(
    (uuid: string, input: Partial<CreateWorkerInput>) =>
      submitWorker('PUT', `${basePath}/${encodeURIComponent(uuid)}`, input),
    [submitWorker, basePath],
  );

  // Delete addresses the worker by its uuid (ADR-0027), so a pending rename
  // never mis-targets it.
  const remove = useCallback(
    async (uuid: string): Promise<void> => {
      try {
        const res = await fetch(`${basePath}/${encodeURIComponent(uuid)}`, {
          method: 'DELETE',
        });
        if (!res.ok) {
          const body = (await res.json().catch(() => ({}))) as { error?: string };
          setError(body.error ?? `Failed to delete worker (HTTP ${res.status})`);
          return;
        }
        setError(null);
      } catch (err) {
        setError(err instanceof Error ? err.message : 'Failed to delete worker');
        return;
      }
      await refresh();
    },
    [refresh, basePath],
  );

  // Probe addresses the uuid and stores the result under it — a rename keeps
  // the row's status (the response still names the worker for display).
  const probe = useCallback(
    async (uuid: string): Promise<void> => {
      try {
        const res = await fetch(`${basePath}/${encodeURIComponent(uuid)}/probe`, {
          method: 'POST',
        });
        if (!res.ok) return; // the row simply stays on its last known status
        const result = (await res.json()) as WorkerProbeView;
        setProbes((prev) => ({ ...prev, [uuid]: result }));
      } catch {
        // Transport failure leaves the row unprobed — Re-check again.
      }
    },
    [basePath],
  );

  /** Top-bar Reload: refetch the list, then probe what it returned. */
  const reload = useCallback(async (): Promise<void> => {
    const list = await refresh();
    await Promise.all(list.map((worker) => probe(worker.uuid)));
  }, [refresh, probe]);

  return { workers, probes, loading, error, refresh, create, update, remove, probe, reload };
}
