import React from 'react';
import {
  Bot,
  Check,
  ChevronRight,
  Circle,
  CircleCheckBig,
  CircleDot,
  Cloud,
  Copy,
  ExternalLink,
  Folder,
  FolderOpen,
  GitBranch,
  GitMerge,
  GitPullRequest,
  HardDrive,
  Layers,
  PlaneLanding,
  RefreshCw,
  RotateCcw,
  Terminal,
  Trash2,
  TriangleAlert,
  X,
} from 'lucide-react';
import { cn } from '@/lib/utils';
import { Island } from './Island';
import type {
  PrdTeardownModel,
  PrdTeardownAggregate,
  TeardownCounts,
  TeardownFeatureSection,
  TeardownRunNode,
  RunMergeState,
} from '@magic-ingredients/tiny-brain-core';

/** A vitals-chip status dot (green = ok, amber = watch, red = risk). */
type VitalDot = 'd-ok' | 'd-watch' | 'd-risk';
/** A vitals-chip value tone (good = done-green, bad = risk-red); default is neutral. */
type VitalTone = 't-good' | 't-bad';

/**
 * One vitals chip — an icon OR a status dot, a label, and its value. Mirrors the
 * single-fix island's `Vital` and the teardown mockup's `.vital.seg` markup.
 */
function Vital({
  icon: Icon,
  dot,
  label,
  value,
  tone,
}: {
  icon?: React.ComponentType<{ className?: string }>;
  dot?: VitalDot;
  label: string;
  value: string;
  tone?: VitalTone;
}) {
  return (
    <span className="vital seg">
      {Icon ? (
        <Icon className="h-3.5 w-3.5 text-muted-foreground" />
      ) : dot ? (
        <span className={cn('dot', dot)} aria-hidden="true" />
      ) : null}
      <span className="text-xs text-muted-foreground">{label}</span>
      <span className={cn('mono text-xs font-semibold', tone ?? 'text-foreground')}>{value}</span>
    </span>
  );
}

/**
 * The header's human summary line: how many runs merged, plus the PR-open and
 * conflict clauses that still need attention. Joined the mockup's way — clauses
 * with ", " and the last with " and ".
 */
export function teardownStatusSentence(a: PrdTeardownAggregate): string {
  if (a.runs === 0) return 'No worker runs on this PRD yet.';
  const head = `${a.merged} of ${a.runs} run${a.runs === 1 ? '' : 's'} merged`;
  const clauses: string[] = [];
  if (a.prOpen > 0) clauses.push(`${a.prOpen} pull request${a.prOpen === 1 ? '' : 's'} still open`);
  if (a.conflict > 0) clauses.push(`${a.conflict} worktree${a.conflict === 1 ? '' : 's'} blocked on a merge conflict`);
  if (clauses.length === 0) return `${head}.`;
  const tail =
    clauses.length === 1 ? clauses[0] : `${clauses.slice(0, -1).join(', ')} and ${clauses[clauses.length - 1]}`;
  return `${head}, ${tail}.`;
}

/**
 * The PRD teardown island (workers / worktree-teardown-surface tasks 4-8).
 *
 * Where the single-fix `WorktreeMergeIsland` lands ONE run on ONE branch, this
 * renders the PRD case: many features, each delivered by one or more worker
 * runs, every run on its own branch, landed / remediated independently. The
 * body is the multi-chip header (task 4), the collapsible per-feature sections
 * (task 5), the nested per-run nodes (task 6), and per-run remediation (task 7).
 *
 * Dumb + projection-driven: it renders the server-derived {@link PrdTeardownModel}
 * and POSTs ids for actions — never a client-computed payload. There is
 * deliberately NO "land the PRD" control: a PRD is not a landable ref.
 */
/**
 * Per-run remediation handlers — dumb-UI seam: each POSTs an id (branch or
 * runId) and the server does the work. Omitted handlers render inert controls.
 */
export interface RunActions {
  /** Open the PR-open run's pull request (branch → the server knows its PR). */
  onReviewPr?: (branch: string) => void;
  /** Open the conflicted branch's worktree on disk. */
  onOpenWorktree?: (branch: string) => void;
  /** Re-check the branch's mergeability after a manual rebase. */
  onRecheck?: (branch: string) => void;
  /** Discard the run — throw the work away (keyed by runId, not branch). */
  onDiscard?: (runId: string) => void;
  /** Land a done-but-not-merged feature via the CLI land pipeline (F5 task 1). */
  onLandFeature?: (featureId: string) => void;
  /**
   * Clear down a merged, reclaimable worktree (F5 task 2) — reap its worktree /
   * branch / run record. Keyed by branch (the reclaimable unit); the run id
   * rides along so the run record reaps too.
   */
  onClearDown?: (branch: string, runId?: string) => void;
}

export interface PrdTeardownIslandProps extends RunActions {
  open: boolean;
  onClose: () => void;
  model: PrdTeardownModel;
  /**
   * The last action's non-success outcome, as an operator-readable sentence
   * (F5 task 1) — a conflicts/pending/failed land must not vanish silently.
   * Null/absent when the last action succeeded (or none ran).
   */
  actionNotice?: string | null;
}

/** The feature's status glyph — its delivery-status icon + tone, keyed by status. */
const STATUS_GLYPH: Record<TeardownFeatureSection['status'], { icon: React.ComponentType<{ className?: string }>; tone: string }> = {
  completed: { icon: CircleCheckBig, tone: 'text-done' },
  superseded: { icon: CircleCheckBig, tone: 'text-subtle' },
  in_progress: { icon: CircleDot, tone: 'text-blue' },
  not_started: { icon: Circle, tone: 'text-subtle' },
};

/**
 * The per-feature summary pill — labelled by the WORST run state so the pill
 * leads with what still needs attention: conflict ≻ PR-open ≻ mergeable
 * (ready-to-land but NOT yet landed) ≻ merged. The else-branch is reached only
 * when every run merged (runs = merged + prOpen + conflict + mergeable), so a
 * mergeable-only feature is never mislabelled "merged".
 */
function featureSummary(r: TeardownCounts): { label: string; pill: string; icon: React.ComponentType<{ className?: string }> } {
  const runs = `${r.runs} ${r.runs === 1 ? 'run' : 'runs'}`;
  if (r.conflict > 0) return { label: `${r.conflict} conflict · ${runs}`, pill: 'pill-red', icon: GitMerge };
  if (r.prOpen > 0) return { label: `PR open · ${runs}`, pill: 'pill-warn', icon: GitPullRequest };
  if (r.mergeable > 0) return { label: `${r.mergeable} ready · ${runs}`, pill: 'pill-blue', icon: GitBranch };
  return { label: `merged · ${runs}`, pill: 'pill-done', icon: Check };
}

/** Human worktree size — B / KB / MB / GB, whole numbers where exact. */
export function formatBytes(n: number): string {
  if (n < 1024) return `${n} B`;
  const units = ['KB', 'MB', 'GB', 'TB'];
  let value = n / 1024;
  let unit = 0;
  while (value >= 1024 && unit < units.length - 1) {
    value /= 1024;
    unit += 1;
  }
  return `${value % 1 === 0 ? value : value.toFixed(1)} ${units[unit]}`;
}

/** The env chip — local (disk) vs cloud, matching the mockup's blue/violet pills. */
function envChip(where: TeardownRunNode['where']): { label: string; pill: string; icon: React.ComponentType<{ className?: string }> } {
  return where === 'cloud'
    ? { label: 'cloud', pill: 'pill-violet', icon: Cloud }
    : { label: 'local', pill: 'pill-blue', icon: HardDrive };
}

/** The per-run merge-state pill label + tint. */
const RUN_STATE_PILL: Record<RunMergeState, { label: string; pill: string }> = {
  merged: { label: 'merged', pill: 'pill-done' },
  'pr-open': { label: 'PR open', pill: 'pill-warn' },
  conflict: { label: 'conflict', pill: 'pill-red' },
  mergeable: { label: 'ready', pill: 'pill-blue' },
};

/** The graph-node dot colour: an attention state (conflict/PR) overrides the env hue. */
export function nodeColorClass(node: TeardownRunNode): string {
  if (node.state === 'conflict') return 'n-red';
  if (node.state === 'pr-open') return 'n-warn';
  return node.where === 'cloud' ? 'n-violet' : 'n-blue';
}

/** A subtle inline control (the mockup's `seg` button skin). */
const segButton = 'inline-flex items-center gap-1.5 rounded-lg seg px-2.5 py-1.5 text-xs text-muted-foreground transition-colors hover:text-foreground';

/**
 * Per-run remediation. A PR-open run offers a link to merge its PR; a conflict
 * run names the conflict file, gives a copyable rebase command for its worktree,
 * and offers Open-worktree / Re-check / Discard. Merged / mergeable / ready runs
 * need no remediation and render nothing.
 */
function RunRemediation({ node, actions }: { node: TeardownRunNode; actions: RunActions }) {
  if (node.state === 'pr-open' && node.prNumber !== undefined) {
    return (
      <div data-testid="run-remediation" className="mt-3 flex flex-wrap items-center gap-2 border-t border-border pt-3">
        <p className="flex items-center gap-1.5 text-xs text-muted-foreground">
          <GitPullRequest className="h-3.5 w-3.5" />
          Move it forward by merging the PR:
        </p>
        <button type="button" className={cn(segButton, 'text-blue')} onClick={() => actions.onReviewPr?.(node.branch)}>
          Review PR #{node.prNumber}
          <ExternalLink className="h-3.5 w-3.5" />
        </button>
      </div>
    );
  }

  if (node.state === 'conflict') {
    const rebase = node.worktreePath !== undefined ? `cd ${node.worktreePath} && git rebase main` : undefined;
    return (
      <div data-testid="run-remediation" className="mt-3 border-t border-border pt-3">
        {node.conflictedFiles?.[0] !== undefined && (
          <p className="flex items-center gap-1.5 text-xs text-phase-red">
            <TriangleAlert className="h-3.5 w-3.5" />
            Conflict in <span className="mono">{node.conflictedFiles[0]}</span> — resolve it in the worktree to land.
          </p>
        )}
        {rebase !== undefined && (
          <div className="mt-2 flex items-center gap-2 rounded-lg border border-border bg-background p-2 pl-3">
            <Terminal className="h-3.5 w-3.5 shrink-0 text-subtle" aria-hidden="true" />
            <code className="mono min-w-0 flex-1 truncate text-xs text-foreground">{rebase}</code>
            <button
              type="button"
              data-testid="copy-rebase"
              aria-label="Copy rebase command"
              className={cn(segButton, 'shrink-0 px-2 py-1 text-[11px]')}
              onClick={() => void navigator.clipboard?.writeText(rebase)}
            >
              <Copy className="h-3 w-3" />
              Copy
            </button>
          </div>
        )}
        <div className="mt-2 flex flex-wrap items-center gap-2">
          <button type="button" className={segButton} onClick={() => actions.onOpenWorktree?.(node.branch)}>
            <FolderOpen className="h-3.5 w-3.5" />
            Open worktree
          </button>
          <button type="button" className={segButton} onClick={() => actions.onRecheck?.(node.branch)}>
            <RefreshCw className="h-3.5 w-3.5" />
            Re-check merge
          </button>
          <button
            type="button"
            className={cn(segButton, 'font-semibold text-phase-red')}
            onClick={() => { const id = node.runId; if (id !== undefined) actions.onDiscard?.(id); }}
          >
            <RotateCcw className="h-3.5 w-3.5" />
            Discard run
          </button>
        </div>
      </div>
    );
  }

  // A merged run whose worktree is still on disk is RECLAIMABLE (F5 task 2):
  // offer the reap `tiny-brain land` runs automatically — worktree + branch +
  // run record — which a raw-landed worktree never got. A merged run with no
  // worktree left has nothing to reclaim and renders nothing, as before.
  if (node.state === 'merged' && node.worktreePath !== undefined) {
    return (
      <div data-testid="run-remediation" className="mt-3 flex flex-wrap items-center gap-2 border-t border-border pt-3">
        <p className="flex items-center gap-1.5 text-xs text-muted-foreground">
          <HardDrive className="h-3.5 w-3.5" />
          Merged — the worktree is reclaimable:
        </p>
        <button
          type="button"
          data-testid="clear-down"
          className={cn(segButton, 'text-blue')}
          onClick={() => actions.onClearDown?.(node.branch, node.runId)}
        >
          <Trash2 className="h-3.5 w-3.5" />
          Clear down
        </button>
      </div>
    );
  }

  return null;
}

/**
 * One run node — a landable branch. Keyed by branch, it shows the env pill, run
 * id, worker · task-count, the merge-state pill, and (second line) the branch
 * ref, merge route, and worktree size (omitted when the branch has no worktree).
 */
function RunNode({ node, actions }: { node: TeardownRunNode; actions: RunActions }) {
  const env = envChip(node.where);
  const EnvIcon = env.icon;
  const state = RUN_STATE_PILL[node.state];

  return (
    <div className={cn('gnode panel-flat rounded-xl p-3.5', nodeColorClass(node))} data-testid="teardown-run" data-branch={node.branch}>
      <div className="flex flex-wrap items-center justify-between gap-2">
        <div className="flex min-w-0 items-center gap-2">
          <span data-testid="run-env" className={cn('pill', env.pill)}>
            <EnvIcon className="h-3 w-3" />
            {env.label}
          </span>
          <span className="mono text-sm font-semibold">{node.runId ?? 'Interactive'}</span>
          <span className="text-xs text-subtle">
            {node.worker !== undefined ? `${node.worker} · ${node.taskCount} tasks` : `${node.taskCount} tasks`}
          </span>
        </div>
        <span data-testid="run-state" className={cn('pill shrink-0', state.pill)}>
          {state.label}
        </span>
      </div>
      <div className="mt-2 flex flex-wrap items-center gap-x-3 gap-y-1 text-xs text-subtle">
        <span className="mono">{node.branch}</span>
        <span className="text-border-strong" aria-hidden="true">·</span>
        <span className="mono">{node.route}</span>
        {node.sizeBytes !== undefined && (
          <>
            <span className="text-border-strong" aria-hidden="true">·</span>
            <span data-testid="run-size" className="pill pill-warn">
              <Folder className="h-3 w-3" />
              {`worktree ${formatBytes(node.sizeBytes)}`}
            </span>
          </>
        )}
      </div>
      <RunRemediation node={node} actions={actions} />
    </div>
  );
}

/** The feature's graph-spine hue — its worst run state (red > warn > done). */
export function graphColor(r: TeardownCounts): string {
  if (r.conflict > 0) return 'var(--color-phase-red)';
  if (r.prOpen > 0) return 'var(--color-warn)';
  return 'var(--color-done)';
}

/**
 * A collapsible per-feature section. Lifecycle-driven default: a fully-merged
 * feature (nothing left to do but reclaim) collapses; a feature with any
 * unmerged run (conflict / PR-open / mergeable) expands, so attention-needing
 * work is open by default.
 */
function FeatureSection({ feature, actions }: { feature: TeardownFeatureSection; actions: RunActions }) {
  const glyph = STATUS_GLYPH[feature.status];
  const GlyphIcon = glyph.icon;
  const summary = featureSummary(feature.rollup);
  const SummaryIcon = summary.icon;
  const allMerged = feature.rollup.runs > 0 && feature.rollup.merged === feature.rollup.runs;

  return (
    <details
      className="feat"
      data-testid="teardown-feature"
      data-feature-id={feature.id}
      {...(allMerged ? {} : { open: true })}
    >
      <summary className="flex cursor-pointer items-center justify-between gap-2 px-5 py-3">
        <div className="flex min-w-0 items-center gap-2">
          <ChevronRight className="chev h-4 w-4 shrink-0 text-subtle" />
          <span data-testid="feature-glyph" data-status={feature.status} aria-label={feature.status}>
            <GlyphIcon className={cn('h-4 w-4 shrink-0', glyph.tone)} />
          </span>
          <h3 className="display truncate text-base font-semibold">{feature.title}</h3>
          <span className="mono hidden text-[11px] text-subtle md:inline">{feature.id}</span>
          <span className="pill pill-muted shrink-0">{feature.taskCount} tasks</span>
        </div>
        <div className="flex shrink-0 items-center gap-2">
          {/* Per-feature Land (work-item-provenance F5 task 1): a COMPLETED
              feature with a ready (mergeable) run lands on its own — the CLI
              pipeline runs server-side — without the whole PRD being ready.
              preventDefault keeps the <summary> from toggling on the click. */}
          {feature.status === 'completed' && feature.rollup.mergeable > 0 && (
            <button
              type="button"
              data-testid="land-feature"
              className={cn(segButton, 'font-semibold text-blue')}
              onClick={(e) => {
                e.preventDefault();
                actions.onLandFeature?.(feature.id);
              }}
            >
              <PlaneLanding className="h-3.5 w-3.5" />
              Land
            </button>
          )}
          <span data-testid="feature-summary" className={cn('pill', summary.pill)}>
            <SummaryIcon className="h-3 w-3" />
            {summary.label}
          </span>
        </div>
      </summary>
      <div className="px-5 pb-5 pt-4">
        <div
          data-testid="feature-graph"
          className="graph space-y-3"
          style={{ '--g': graphColor(feature.rollup) } as React.CSSProperties}
        >
          {feature.runs.map((node) => (
            <RunNode key={node.branch} node={node} actions={actions} />
          ))}
        </div>
      </div>
    </details>
  );
}

export function PrdTeardownIsland({ open, onClose, model, actionNotice = null, ...actions }: PrdTeardownIslandProps) {
  const { title, aggregate } = model;
  return (
    <Island open={open} onClose={onClose} ariaLabel="PRD teardown">
      <div data-testid="prd-teardown" className="flex flex-col overflow-hidden">
        <header className="shrink-0 border-b border-border px-6 py-5">
          <button
            type="button"
            onClick={onClose}
            aria-label="Close"
            className="absolute right-4 top-4 inline-flex items-center rounded-lg p-1.5 text-subtle transition-colors hover:bg-accent/50 hover:text-foreground"
          >
            <X className="h-4 w-4" />
          </button>
          <h2 className="display text-xl font-bold leading-snug">{title}</h2>
          <p className="mt-2 max-w-2xl text-sm text-muted-foreground">{teardownStatusSentence(aggregate)}</p>
          {actionNotice !== null && actionNotice.length > 0 && (
            <p data-testid="teardown-notice" className="mt-2 flex items-center gap-1.5 text-xs text-phase-red">
              <TriangleAlert className="h-3.5 w-3.5 shrink-0" aria-hidden="true" />
              {actionNotice}
            </p>
          )}
          <div aria-label="Teardown vitals" className="mt-5 flex flex-wrap gap-2">
            <Vital icon={Layers} label="Features" value={String(aggregate.features)} />
            <Vital icon={Bot} label="Runs" value={String(aggregate.runs)} />
            <Vital dot="d-ok" label="Merged" value={`${aggregate.merged} / ${aggregate.runs}`} tone="t-good" />
            <Vital dot="d-watch" label="PR open" value={String(aggregate.prOpen)} />
            <Vital
              dot="d-risk"
              label="Conflict"
              value={String(aggregate.conflict)}
              tone={aggregate.conflict > 0 ? 't-bad' : undefined}
            />
            <Vital
              icon={HardDrive}
              label="Reclaimable"
              value={String(aggregate.reclaimable)}
              tone={aggregate.reclaimable > 0 ? 't-good' : undefined}
            />
          </div>
        </header>
        <div className="flex-1 min-h-0 space-y-3 overflow-y-auto px-6 py-5">
          {model.features.map((feature) => (
            <FeatureSection key={feature.id} feature={feature} actions={actions} />
          ))}
        </div>
      </div>
    </Island>
  );
}

export default PrdTeardownIsland;
