import { useEffect, useState } from 'react';
import { cn } from '@/lib/utils';
import type { SpikeStatus } from '@magic-ingredients/tiny-brain-core';
import { SPIKE_TERMINAL_STATUSES } from './spike-status';

export interface TimeboxCountdownProps {
  readonly created: string;
  readonly timebox: string;
  readonly status: SpikeStatus;
}

const TERMINAL: ReadonlySet<SpikeStatus> = SPIKE_TERMINAL_STATUSES;

const TIMEBOX_PATTERN = /^\s*(\d+(?:\.\d+)?)\s*([smhdw])\s*$/i;
type TimeboxUnit = 's' | 'm' | 'h' | 'd' | 'w';
const UNIT_MS: Record<TimeboxUnit, number> = {
  s: 1_000,
  m: 60_000,
  h: 3_600_000,
  d: 86_400_000,
  w: 604_800_000,
};

/**
 * Parse a compact timebox string ("4h", "2d", "1w", "30m") into ms.
 * Returns null for anything the schema didn't ratify — the caller
 * degrades to "no countdown" rather than rendering bogus times.
 */
function parseTimeboxMs(raw: string): number | null {
  const match = TIMEBOX_PATTERN.exec(raw);
  if (!match) return null;
  const value = Number(match[1]);
  const unit = match[2].toLowerCase() as TimeboxUnit;
  return value * UNIT_MS[unit];
}

/**
 * Format the remaining ms as a coarse string. Spikes are minutes-to-days,
 * so "1d 4h" / "2h 15m" / "12m" is the right granularity — seconds-level
 * precision would flicker without adding signal.
 */
function formatRemaining(ms: number): string {
  if (ms <= 0) return '0m';
  const days = Math.floor(ms / UNIT_MS.d);
  const hours = Math.floor((ms % UNIT_MS.d) / UNIT_MS.h);
  const minutes = Math.floor((ms % UNIT_MS.h) / UNIT_MS.m);
  if (days > 0) return hours > 0 ? `${days}d ${hours}h` : `${days}d`;
  if (hours > 0) return minutes > 0 ? `${hours}h ${minutes}m` : `${hours}h`;
  return `${minutes}m`;
}

export const TICK_INTERVAL_MS = 30_000;

export function TimeboxCountdown({ created, timebox, status }: TimeboxCountdownProps) {
  const isTerminal = TERMINAL.has(status);
  // `not_started` spikes are treated like terminals for countdown
  // purposes — work hasn't begun, so showing remaining/expired
  // against `created` would surface a deadline that isn't real yet.
  const showsCountdown = !isTerminal && status !== 'not_started';

  // `tick` exists purely to force a re-render on the interval so the
  // remaining/expired derivation re-runs against the current wall
  // clock. Cheap; the alternative (storing the derived values in
  // state) would duplicate the source of truth.
  const [, setTick] = useState(0);

  useEffect(() => {
    if (!showsCountdown) return;
    const id = setInterval(() => setTick((t) => t + 1), TICK_INTERVAL_MS);
    return () => clearInterval(id);
  }, [showsCountdown]);

  const timeboxMs = parseTimeboxMs(timebox);
  const createdMs = new Date(created).getTime();
  const expiryMs = timeboxMs !== null && Number.isFinite(createdMs)
    ? createdMs + timeboxMs
    : null;

  // Compute against the *current* clock at render time so a spike that
  // was already expired when the user opened the page shows that state
  // immediately rather than only after the first tick.
  const now = Date.now();
  const remainingMs = expiryMs !== null ? expiryMs - now : null;
  // expired only applies when a countdown would render; terminal /
  // not_started spikes don't surface a deadline, so the attribute
  // reflects "no active countdown" rather than wall-clock truth.
  const expired = showsCountdown && remainingMs !== null && remainingMs <= 0;

  const suffix = (() => {
    if (!showsCountdown || remainingMs === null) return null;
    if (expired) return 'expired';
    return `${formatRemaining(remainingMs)} remaining`;
  })();

  return (
    <span
      data-testid="timebox-countdown"
      data-expired={expired ? 'true' : 'false'}
      className="text-xs text-muted-foreground"
    >
      Timebox: {timebox}
      {suffix && (
        <span
          className={cn(
            'ml-1.5 px-1.5 py-0.5 rounded text-[10px] uppercase tracking-wide font-medium',
            expired
              ? 'bg-amber-100 text-amber-800 dark:bg-amber-900/40 dark:text-amber-200'
              : 'bg-gray-100 text-gray-700 dark:bg-gray-800 dark:text-gray-300',
          )}
        >
          {suffix}
        </span>
      )}
    </span>
  );
}
