import { useEffect, useState } from 'react';
import type { WorkItemProvenance, ProvenanceWorkKind } from '@magic-ingredients/tiny-brain-core';
import { fetchWorkItemProvenance } from '../services/api';

/**
 * The work-item provenance feed (work-item-provenance F4) — a work item's
 * per-feature delivered where/who/landed via
 * `GET /api/repos/:repoId/provenance/:kind/:id`, loaded on mount and whenever
 * the (repoId, kind, id) key changes, with honest loading / error states.
 * Read-only: provenance is git-derived, so there is no mutate surface here.
 *
 * `refreshKey` re-runs the fetch on identity change. Callers pass the live
 * item payload (the plan/fix object) so the provenance snapshot re-syncs
 * whenever the item re-projects — without it the two feeds drift mid-session
 * and contradict (e.g. a feature that just completed on main splitting as
 * "Done" off a stale unlanded delivery).
 */
export function useWorkItemProvenance(
  repoId: string | undefined,
  kind: ProvenanceWorkKind,
  id: string | undefined,
  refreshKey?: unknown,
) {
  const [provenance, setProvenance] = useState<WorkItemProvenance | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    if (!repoId || !id) {
      // Nothing to resolve — settle to an empty, non-loading state rather than
      // spinning forever (both ids are `string | undefined`).
      setProvenance(null);
      setLoading(false);
      return;
    }
    let cancelled = false;
    setLoading(true);
    setError(null);
    fetchWorkItemProvenance(repoId, kind, id)
      .then((data) => {
        if (!cancelled) setProvenance(data);
      })
      .catch((err: unknown) => {
        if (cancelled) return;
        setError(err instanceof Error ? err.message : 'Failed to load provenance');
        setProvenance(null);
      })
      .finally(() => {
        if (!cancelled) setLoading(false);
      });
    return () => {
      cancelled = true;
    };
    // refreshKey is a pure re-run trigger — referenced only as a dependency.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [repoId, kind, id, refreshKey]);

  return { provenance, loading, error };
}
