import { GitMerge, GitPullRequest, TriangleAlert, Ban, CircleCheckBig } from 'lucide-react';
import type { LucideIcon } from 'lucide-react';
import { cn } from '@/lib/utils';
import type { WorktreeListStatus } from '@/utils/worktree-list-status';

export interface WorktreeStatusMeta {
  /** The pill label shown on the card and the header filter pills. */
  readonly label: string;
  /** Status text colour — always applied (card pill + filter pill, active or not). */
  readonly text: string;
  /** Status background tint — applied to the card pill, and to a filter pill only when active. */
  readonly fill: string;
  /** The pill's leading glyph, or `null` when the pill leads with a pulse dot. */
  readonly Icon: LucideIcon | null;
  /** Render a pulsing live dot instead of an icon — the in-progress convention. */
  readonly pulse?: boolean;
}

/**
 * The single display source for every worktree status bucket — pill label, tint
 * and glyph. Co-located with the bucket vocabulary's consumer so the card and the
 * header filter pills render from one map. Colour is split into `text` (always on)
 * and `fill` (the background tint) so a filter pill can show tinted text when
 * inactive and add the fill only when active, mirroring ListStatusFilter.
 * In-progress leads with a pulsing dot (the live convention shared with
 * {@link StatusPill}); the rest lead with an icon.
 */
export const WORKTREE_STATUS_META: Record<WorktreeListStatus, WorktreeStatusMeta> = {
  'in-progress': { label: 'in progress', text: 'text-blue-500', fill: 'bg-blue-500/15', Icon: null, pulse: true },
  'ready-to-merge': { label: 'ready to merge', text: 'text-emerald-500', fill: 'bg-emerald-500/15', Icon: GitMerge },
  'pr-open': { label: 'PR open', text: 'text-purple-500', fill: 'bg-purple-500/15', Icon: GitPullRequest },
  conflict: { label: 'conflict', text: 'text-red-500', fill: 'bg-red-500/15', Icon: TriangleAlert },
  rejected: { label: 'rejected', text: 'text-red-500', fill: 'bg-red-500/15', Icon: Ban },
  'ready-to-clean': { label: 'ready to clean', text: 'text-gray-500', fill: 'bg-gray-500/15', Icon: CircleCheckBig },
};

/**
 * The shared worktree status pill — the single rendering of a {@link WorktreeListStatus}
 * bucket as a tinted pill (pulsing dot for the live in-progress convention, else the
 * bucket glyph, then the label). The sidebar card and the merge-detail header both
 * render it from the SAME meta, so a worktree reads identically on both surfaces.
 */
export function WorktreeStatusPill({ status, className }: { status: WorktreeListStatus; className?: string }) {
  const meta = WORKTREE_STATUS_META[status];
  const Icon = meta.Icon;
  // Match the StatusPill geometry (rounded-full · text-[11px] · sans · same
  // padding + dot size) so a worktree's bucket pill reads as the same family as
  // the plan/fix/spike cards' status pill — only the bucket label, tint, and
  // leading glyph differ.
  return (
    <span
      data-testid="status-pill"
      className={cn(
        'inline-flex items-center gap-1.5 whitespace-nowrap rounded-lg px-2 py-0.5 text-[11px] font-medium',
        meta.fill,
        meta.text,
        className,
      )}
    >
      {meta.pulse ? (
        <span data-testid="status-pulse-dot" className="h-1.5 w-1.5 flex-shrink-0 rounded-full bg-current animate-pulse" aria-hidden="true" />
      ) : (
        Icon && <Icon className="h-3 w-3 flex-shrink-0" />
      )}
      {meta.label}
    </span>
  );
}
