import React from 'react';

export interface FixControlStripProps {
  /**
   * The LHS attribution content — the idle "Click to launch →" hint, the live
   * MiniStatusRail, or a settled deliverer (glyph+text who + branch chip). This
   * is the "who / where the work ran" section; it leads the strip and is never
   * pushed around by the landed chip (fix endcap-resumes-pipeline-runs task 9 —
   * the worker section stays put on the left).
   */
  attribution: React.ReactNode;
  /**
   * The delivery landed chip (`merged → main` / `via fix <slug>`), RIGHT-aligned
   * against the end cap rather than crowding the LHS attribution (task 9). Omit
   * for non-delivered states.
   */
  landedChip?: React.ReactNode;
  /** The read-only provenance-island entry cap (started, island-addressable). */
  showDetails?: React.ReactNode;
  /** The full-height one-action end cap closing the row. */
  endcap: React.ReactNode;
}

/**
 * The whole-fix control strip (mock §§03–05), extracted from FixDetail's inline
 * JSX (fix endcap-resumes-pipeline-runs task 6) so every state is storyable.
 * ONE row: the LHS attribution, the delivery landed chip pushed to the RIGHT
 * (`ml-auto`) so it reads against the end cap, then the optional Show-details
 * cap and the full-height end cap. The cap rounds its own right edge, so no
 * overflow-hidden. Purely presentational — the host derives which attribution
 * and caps to pass.
 */
export function FixControlStrip({ attribution, landedChip, showDetails, endcap }: FixControlStripProps) {
  return (
    <section data-testid="fix-control-strip" className="panel-flat flex items-stretch rounded-2xl">
      <div className="flex min-h-14 min-w-0 flex-1 flex-wrap items-center gap-2.5 px-4 py-3.5">
        {attribution}
        {landedChip !== undefined && landedChip !== null && (
          <span data-testid="fix-strip-landed" className="ml-auto shrink-0">
            {landedChip}
          </span>
        )}
      </div>
      {showDetails}
      {endcap}
    </section>
  );
}

export default FixControlStrip;
