/**
 * The Measured section's trend invariant. Every analyser metric in the
 * "signals" rethink is framed as a quantity to keep low (risk-complement), so a
 * single rule colours every trend: a falling line is an improvement (good), a
 * rising line is a regression (bad). The only exceptions are *scale* metrics —
 * test count, type-error count — which carry no risk direction and are never
 * coloured by movement.
 */

export type TrendColour = 'good' | 'bad' | 'neutral';
export type TrendDirection = 'up' | 'down' | 'flat';

/** Whether a metric is a risk to keep low (trend-coloured) or a neutral scale. */
export type MetricSemantics = 'lower-better' | 'neutral';

export interface MetricTrend {
  readonly direction: TrendDirection;
  readonly colour: TrendColour;
  /** current − previous (0 when there is no history). */
  readonly delta: number;
}

export const METRIC_SEMANTICS: Record<string, MetricSemantics> = {
  uncovered: 'lower-better',
  lint: 'lower-better',
  'survived-mutants': 'lower-better',
  'dependency-vulns': 'lower-better',
  // Scale, not a risk direction — a bigger test suite or a 0/non-0 type-error
  // count says nothing on a keep-it-low axis, so it is never trend-coloured.
  'type-errors': 'neutral',
  'test-suite': 'neutral',
};

export function semanticsFor(metricKey: string): MetricSemantics {
  return METRIC_SEMANTICS[metricKey] ?? 'lower-better';
}

export function metricTrend(
  current: number,
  previous: number | undefined,
  semantics: MetricSemantics,
): MetricTrend {
  if (previous === undefined) {
    return { direction: 'flat', colour: 'neutral', delta: 0 };
  }

  const delta = current - previous;
  const direction: TrendDirection = delta > 0 ? 'up' : delta < 0 ? 'down' : 'flat';

  let colour: TrendColour;
  if (semantics === 'neutral' || direction === 'flat') {
    colour = 'neutral';
  } else {
    colour = direction === 'down' ? 'good' : 'bad';
  }

  return { direction, colour, delta };
}
