import type { DeliveryWorktreeRow } from '@/services/api';
import { WorktreeMergeContent } from '@/components/WorktreeMergeContent';
import ReconcileStrip from '@/components/ReconcileStrip';
import { useLiveReconcileStrip } from '@/hooks/useLiveReconcileStrip';
import { deliveryWorktreeStatus } from '@/utils/worktree-list-status';

export interface WorktreeMergeDetailProps {
  /** The repo the worktree belongs to — kept on the interface so both mounts keep their wiring (the read-only island posts nothing). */
  repoId: string;
  /** The selected worktree — its fields (incl. the ONE delivery model) drive the surface. */
  worktree: DeliveryWorktreeRow;
  /**
   * Fired once when the branch's WATCHED live machinery run ends (exit or
   * broken stream) — the refetch seam that lets the availability chip and
   * `liveReconcileRunId` catch up with the run's verdict
   * (reconcile-verify-progress-invisible). No user action originates here;
   * the surface stays read-only.
   */
  onActionComplete?: () => void;
  /** Optional close affordance — the overlay passes it (header ✕); the inline detail pane omits it. */
  onClose?: () => void;
}

/**
 * The worktree provenance surface as a worktree-in component: given a
 * {@link DeliveryWorktreeRow}, it derives the header + provenance sections
 * ({@link WorktreeMergeContent}) from the row — including the row's ONE derived
 * delivery model (work-item-provenance F6 task 2), which every delivery pixel
 * renders from. READ-ONLY: the delivery actions live on the F9 end-caps, so
 * this surface owns no POST wiring. Container-agnostic — the overlay mounts it
 * inside `Island`, the two-pane Worktrees view mounts it directly in the detail
 * pane.
 */
export function WorktreeMergeDetail({ repoId, worktree, onActionComplete, onClose }: WorktreeMergeDetailProps) {
  // The branch's LIVE machinery run (a reconcile/land whoever started it — a
  // CLI `tiny-brain reconcile-branch` included): subscribe and render its
  // honest phase with elapsed time, so a 12-minute verify never reads as idle
  // on this surface (reconcile-verify-progress-invisible). Status-only — the
  // surface stays read-only. With no disk feeds wired, the machine yields only
  // running states and STREAM-sourced terminals (this run's own conclusion);
  // idle renders nothing inside the strip. The run's terminal fires
  // `onActionComplete` once, so the persisted facts (availability chip,
  // `liveReconcileRunId`) refetch instead of sitting stale under the verdict.
  const reconcile = useLiveReconcileStrip(repoId, worktree.model.liveReconcileRunId, onActionComplete);

  return (
    <div className="space-y-2">
      <ReconcileStrip state={reconcile} branch={worktree.branch} />
      <WorktreeMergeContent
        title={worktree.branch}
        contents={worktree.contents}
        acceptanceState={worktree.acceptanceState}
        mergeState={deliveryWorktreeStatus(worktree.status, worktree.acceptanceState)}
        isWorkerRun={worktree.isWorkerRun}
        model={worktree.model}
        provenance={worktree.provenance}
        runs={worktree.runs}
        deliveredTasks={worktree.tasksDelivered}
        {...(worktree.unlandedCommits ? { unlandedCommits: worktree.unlandedCommits } : {})}
        {...(onClose ? { onClose } : {})}
      />
    </div>
  );
}

export default WorktreeMergeDetail;
