/**
 * SSE-driven refetch trigger for run-lifecycle changes (fix
 * run-dispatch-stale-dashboard).
 *
 * A worker dispatch creates a run record, a status transition rewrites
 * it, a prune deletes it; the file watcher broadcasts each as
 * `run-change` → client `runChange`. This hook bridges a matching
 * repo's event into a refetch callback, mirroring `usePrdDocLive` /
 * `useFixDocLive` in useDocLive.ts. The refetch is unconditional across
 * changeTypes — every lifecycle move re-reads the server projection.
 * Consumers: the in-flight lanes (`inFlight.refresh()`) and the plans
 * list (`fetchRepoPlans()` — the feature rail's `activeRun` swaps Launch
 * for the Running pill).
 */

import { useEffect } from 'react';
import { sseManager, sseEventMatchesRepo, type SSEEvent } from '../services/SSEManager';

/** Invoke onChange when a run record changes in this repo. */
export function useRunLive(repoId: string | null, onChange: () => void): void {
  useEffect(() => {
    if (!repoId) return;

    const handle = (event: SSEEvent): void => {
      if (event.type !== 'runChange') return;
      if (!sseEventMatchesRepo(event, repoId)) return;
      onChange();
    };

    return sseManager.on('runChange', handle);
  }, [repoId, onChange]);
}
