import { useCallback, useEffect, useRef, useState } from 'react';
import type { WorkRef, BoardLane, Liveness, AttentionReason, LifecyclePhase, PlanningGateStatus } from '@magic-ingredients/tiny-brain-core';
import type { Fix } from '../types';
import { sseManager, type SSEEvent } from '../services/SSEManager';
import { sseEventMatchesRepo } from '../services/sseRepoMatch';
import { useRunLive } from './useRunLive';
import type { ValidationStepView } from '../utils/validation-panel-state';

/**
 * Trailing-debounce window for SSE-driven board refetches. A commit landing
 * emits a burst (a statusChange per re-projected entity plus a run-change on
 * the ref move); one window folds the burst into a single `/board` re-derive.
 * Short on purpose — it only needs to swallow a same-commit burst, and the
 * doc-change stream is already burst-windowed server-side (750ms).
 */
const SSE_REFRESH_DEBOUNCE_MS = 250;

/**
 * The board wire contract, mirroring the server's `BoardRow` / `BoardLanes` in
 * `server/routes/board.projection.ts`. The row shape is re-declared client-side
 * (like {@link InFlightRow} in `useInFlight`): the client tsconfig excludes
 * `server/`, so the two are kept in sync by hand — but the leaf enums (`BoardLane`,
 * `Liveness`) and `WorkRef` come from the core package both sides depend on, so
 * those cannot drift. Each row carries a lean `BoardCardSummary` (the fields the
 * card renders) instead of the full record — the full fix/plan/spike is fetched
 * on selection (`useBoardItemDetail`), so the list stays cheap.
 */
export type { BoardLane, Liveness, AttentionReason };

/**
 * The lean per-card fields the board renders, mirroring the server's
 * `BoardCardSummary` in `server/routes/board.summary.ts` (kept in sync by hand,
 * like the row shape). The full record never rides the list.
 */
export interface BoardCardSummary {
  // Shape mirrors the server's `BoardCardSummary` field-for-field (readonly,
  // same optionality) so the hand-sync can't drift silently on a re-read.
  readonly kind: 'fix' | 'prd' | 'spike';
  readonly title: string;
  /** Task-completion percentage; `null` for spikes (timeboxed, no bar). */
  readonly progress: number | null;
  readonly tasksDone: number;
  readonly tasksTotal: number;
  readonly severity?: Fix['severity'];
  readonly featureCount?: number;
  readonly timebox?: string;
  /** Spike-only — fixes/PRDs have no worktree in core, so their meta shows time. */
  readonly branch?: string;
  readonly timestamp?: string;
  /** The item's FILED instant — `reported` (fix) / `created` (plan, spike);
   *  distinct from the display `timestamp`. The lane's filed-age sort key. */
  readonly filed?: string;
  /** Fix / PRD — the item's latest task worktree attribution; the card renders
   *  it as the worktree glyph before the User glyph (task 35). */
  readonly worktree?: { readonly name: string; readonly branch: string };
}

// The chip-strip step view now lives in the util layer (validation-panel-state)
// so pure utils — the shared validation-visibility receipt — can bind to it
// without a util→hook dependency. Imported above for local use in this module's
// interfaces; re-exported here for board consumers (a bare `export … from` gives
// no local binding, so the type annotations below could not see it).
export type { ValidationStepView };

/** The server-assembled per-step validation summary — mirrors the server
 *  `BoardRowValidation`. The card's journey bar and the detail panel render
 *  THIS, reading no config and folding no events themselves. */
export interface BoardRowValidation {
  /** The run this reflects — ABSENT when the strip stands on configuration alone
   *  with no genuine run to anchor (an all-pending preview: an interactive land,
   *  or a laundered scoping-fault / rejected run) — fix validation-strip-always-
   *  shown-when-pipeline-configured. */
  readonly runId?: string;
  readonly kind: 'completion' | 'main-validation';
  readonly steps: readonly ValidationStepView[];
  readonly scope: 'changed' | 'full';
  /** When the reflected run started — ABSENT alongside {@link runId} when no
   *  genuine run anchors the strip. */
  readonly startedAt?: string;
  /** The item has landed — the journey bar's main-boundary diamond is filled
   *  (validation-pipeline-visibility F5). */
  readonly landed: boolean;
  /** The post-merge (main-validation) lane's segments, present only when the
   *  repo configures a post-land step (F5) — the journey bar's right half. */
  readonly postLand?: { readonly steps: readonly ValidationStepView[] };
  /** The pre-merge reconcile stage (reconcile-segment task 2) — the journey
   *  bar's segment left of the merge diamond + the diamond's colour code. Present
   *  only on in-review rows whose work lives on a live branch. */
  readonly reconcile?: BoardReconcileSummary;
}

/** The board card's reconcile axis (reconcile-segment task 2) — mirrors the
 *  server `BoardReconcileSummary`. `segment` tints the reconcile rail (absent ⇒
 *  a hollow "not entered" rail); `merge` colour-codes the boundary diamond. */
export interface BoardReconcileSummary {
  readonly segment?: 'verifying' | 'ready' | 'conflict';
  // No `merged`: the journey bar is in-review-only, so a merged boundary never
  // reaches a card (mirrors the server BoardReconcileSummary).
  readonly merge: 'pending' | 'ready' | 'blocked';
  /**
   * The main SHA the latest settled reconcile/land rebased onto (surface-reconciled-
   * main-sha F1) — mirrors the server `BoardReconcileSummary`. The card's ready cue
   * reads "ready to land · main@<sha7>" from it (provisional-ready-badge-and-footer
   * F2). Absent while verifying / not entered, and on old runs. Absent-safe.
   */
  readonly reconciledAgainst?: string;
}

/**
 * The launch provisioning stage on a row (worktree-readiness-commands F8) —
 * mirrors the server `BoardProvisioning`. `setting-up` while the worktree is
 * being made ready; `failed-at-step` when a setup command failed (the failed
 * step + a bounded output tail), which the card styles as an environment fault.
 * A `ready` result surfaces nothing, so this field is simply absent then.
 */
export type BoardProvisioning =
  | { readonly status: 'setting-up' }
  | { readonly status: 'failed-at-step'; readonly failedStep: string; readonly outputTail?: string };

export interface BoardRow {
  workRef: WorkRef;
  lane: BoardLane;
  /**
   * The item's landed bit, carried from the server row (fix board-detail-
   * provenance-not-seeded-from-summary). Paired with `producingRun`, it is the
   * who/landed the detail pane seeds its provenance view from on selection, so
   * the who glyph and delivery state stop flashing in behind the per-item fetch.
   */
  landed?: boolean;
  /** In-progress: all arms. Backlog: `live` (launched) or `failed` (dead
   *  dispatch) only — mirrors the server BoardRow contract. */
  liveness?: Liveness;
  /**
   * The row's "needs a decision" attention reasons (attention-filter F5); empty
   * when fine. Required + readonly to match the server contract — the projection
   * always sets it — so consumers need no `?? []` guard.
   */
  attention: readonly AttentionReason[];
  /**
   * The provenance of the run that PRODUCED the work (task 30) — worker + where —
   * mirroring the server's `ProducingRun`. Absent when worked interactively (no
   * run on record), which the card reads as an operator on local disk.
   */
  producingRun?: { worker: string; model?: string; where: 'local' | 'remote' };
  /**
   * The id of the item's LIVE run (fix: prd-feature-live-run-stream-unreachable
   * task 1) — the card's Running pill opens the run stream with it. Present
   * exactly while a live worker run exists.
   */
  activeRunId?: string;
  /**
   * A REAL pipeline run is in flight for this item — its completion suite or
   * the post-merge regression suite covering its land, still awaiting a
   * verdict (fix validating-derived-from-review-gates-not-pipeline-runs —
   * never derived from task review gates). Mirrors the server BoardRow
   * contract; stamped on In-review rows ONLY (the 2026-08-09 lane ruling),
   * so the validating pill can never appear on any other lane.
   */
  validating?: true;
  /**
   * True when a worker run for this item failed and was not superseded by a
   * resume — surfaced independently of `liveness` (which the failed run's own
   * recent activity can mask to `live`) so the card can flag the failure
   * (fix: failed-run-not-surfaced-on-card-and-header).
   */
  hasFailedRun?: boolean;
  /**
   * Done-lane only (done-lane-cleanup task 1): delivery proven, but a typed
   * worktree branch for the item is still live on disk — cleanup debt. Mirrors
   * the server row field; never set on any other lane.
   */
  cleanup?: true;
  /**
   * The live typed branches that tripped `cleanup` (raw names) — set exactly
   * when `cleanup` is; mirrors the server row field (fix
   * prd-cleanup-pill-not-attributed-to-features task 1).
   */
  cleanupBranches?: readonly string[];
  /**
   * This row is the land main's current regression was attributed to
   * (split-land-from-validation F6) — the card wears the `regression` pill.
   * Mirrors the server row field: set on exactly one row while main is red and
   * attribution is confident, and on NO row when it is ambiguous.
   */
  regression?: true;
  /**
   * The server-assembled per-step validation summary
   * (validation-pipeline-visibility F3) — the completion pipeline the card's
   * journey bar renders. Present on in-review rows held by a completion run.
   * Mirrors the server row field.
   */
  validation?: BoardRowValidation;
  /**
   * The item's SERVER-computed lifecycle phase (work-item-detail-service-rewrite /
   * board-parity-retire) — the same `LifecyclePhase` core `getValidation` returns
   * and the fix/prd detail endpoint carries. The card renders its delivery pill AND
   * its failure-pill remediation from THIS, so board and detail read one producer.
   * The legacy `deliveryPill` mirror field was retired here (fix
   * retire-legacy-deliverypill-from-board-card task 2). Optional so client row
   * fixtures need no sweep — the server always sets it.
   */
  lifecycle?: LifecyclePhase;
  /**
   * The launch provisioning stage (worktree-readiness-commands F8) — mirrors the
   * server row field. Present while the item's launch worktree is being set up,
   * or when a setup command failed; absent otherwise.
   */
  provisioning?: BoardProvisioning;
  /**
   * The item's folded planning-review states (plan-readiness-indicators F3) —
   * one per configured `planningPipeline` gate. Mirrors the server row field;
   * the card renders the Backlog-only planning-checks row from it, and the row
   * is dropped once the item leaves Backlog (the detail header keeps the pills).
   */
  planning?: readonly PlanningGateStatus[];
  summary: BoardCardSummary;
}

/**
 * Attribution flattened for display, mirroring the server's
 * `BoardAttributionSummary` in `server/routes/board.projection.ts`. The client
 * never value-imports core, so the culprit / suspects arrive already reduced to
 * display strings.
 */
export type BoardAttributionSummary =
  | { readonly kind: 'attributed'; readonly culprit: string }
  | { readonly kind: 'ambiguous'; readonly suspects: readonly string[] };

/** An in-flight main-validation run — mirrors the server's shape. */
export interface BoardValidatingSummary {
  readonly runId: string;
  readonly startedAt: string;
}

/**
 * Main's validation health (split-land-from-validation F6), mirroring the
 * server's `BoardHealthSummary`. Lives here with the rest of the wire contract
 * rather than in the component that renders it — the hook owns the shape, the
 * component consumes it.
 */
export type BoardHealthSummary =
  | { readonly mainRed: false; readonly validating?: BoardValidatingSummary }
  | {
      readonly mainRed: true;
      readonly tipSha: string;
      readonly baselineSha: string;
      readonly attribution: BoardAttributionSummary;
      /**
       * Every land in the flagged range, in landed order — the overlay's triage
       * table (F6 Task 3). Each carries its own SHA, because reverting acts on
       * a LAND and attribution only ever names a card.
       */
      readonly lands: readonly BoardSuspectLand[];
      /** The failing tests, as the runner reported them — the overlay's evidence. */
      readonly failingTests?: readonly string[];
      /**
       * A fresh validation running right now — the banner switches its whole
       * rail to the revalidating state while this is set
       * (revalidate-click-rail-not-instant), elapsed minutes from `startedAt`.
       */
      readonly validating?: BoardValidatingSummary;
    };

/** One land inside the flagged range, flattened for display. */
export interface BoardSuspectLand {
  readonly sha: string;
  /** The owning work item, as its work-ref slug. */
  readonly item: string;
  readonly files: readonly string[];
}

export interface BoardLanes {
  backlog: BoardRow[];
  inProgress: BoardRow[];
  inReview: BoardRow[];
  done: BoardRow[];
  canceled: BoardRow[];
}

export interface UseBoardResult {
  lanes: BoardLanes;
  /** Total rows needing a decision across all lanes — feeds the header chip. */
  attentionCount: number;
  /**
   * Main's validation health (split-land-from-validation F6) — feeds the
   * always-on red-main banner. Server-derived and already flattened to display
   * strings, so the client renders it without value-importing core.
   */
  health: BoardHealthSummary;
  /**
   * The Done lane's size (board-surface task 23/24). The list payload carries
   * Done as a count only — `lanes.done` is empty until {@link loadDone} fetches
   * the rows on expand — so the collapsed Done strip reads this.
   */
  doneCount: number;
  /**
   * The Done lane's cleanup-debt total (done-lane-cleanup task 1) — flagged
   * done items whose worktree/branch/run were never reaped. Served beside
   * `doneCount` on the list payload, so the collapsed Done strip can show it
   * without loading rows.
   */
  cleanupCount: number;
  /**
   * Fetch the Done lane's full rows on demand (the fetch-on-expand source) and
   * populate `lanes.done`. Idempotent to call; a no-op without a repo.
   */
  loadDone: () => Promise<void>;
  /** True while {@link loadDone} is in flight — lets the Done lane show a loading
   * affordance rather than an empty state indistinguishable from a real empty. */
  doneLoading: boolean;
  loading: boolean;
  error: string | null;
  refresh: () => void;
}

const EMPTY: BoardLanes = { backlog: [], inProgress: [], inReview: [], done: [], canceled: [] };

/** A row's stable identity across refetches — its work ref (kind + slug). */
const rowIdentityKey = (row: BoardRow): string => `${row.workRef.kind}:${row.workRef.id}`;

/**
 * Preserve a row's OBJECT identity across a `/board` refetch when its content is
 * unchanged (delivery-surface-refetch-storm task 2). The server sends a fresh row
 * object on every re-derive, so a reconcile's per-step refetch would otherwise hand
 * the memoised card a new identity each step — resetting/blanking it in lockstep
 * with the validation control. Keyed by work ref; a byte-for-byte match reuses the
 * PRIOR object (referentially stable), while any genuine change still yields the
 * fresh one. A key-order drift only ever falls back to the fresh object (today's
 * behaviour), never freezes a real change — the two rows are same-shaped JSON from
 * one server serializer, so in practice the compare is exact.
 */
function reconcileRows(prev: readonly BoardRow[], next: readonly BoardRow[]): BoardRow[] {
  const prevByKey = new Map(prev.map((row) => [rowIdentityKey(row), row]));
  return next.map((row) => {
    const prior = prevByKey.get(rowIdentityKey(row));
    return prior && JSON.stringify(prior) === JSON.stringify(row) ? prior : row;
  });
}

/**
 * Load the repo's work board — the five lanes from `GET /api/repos/:repoId/board`
 * — and re-fetch on the repo's SSE signals: `run-change` (a run starting/exiting),
 * `status-change` (a task landing re-projects the entity), and the fix/plan
 * doc-change events (a new or edited markdown doc), coalesced through one
 * trailing debounce so a commit's event burst re-derives the board once.
 * Mirrors {@link useInFlight}: a direct fetch with an `isActive` cancel guard;
 * the invalidation is wired here (via {@link useRunLive} + a `statusChange`
 * subscription) so a consumer just calls `useBoard(repoId)`.
 */
export function useBoard(repoId: string | null): UseBoardResult {
  const [lanes, setLanes] = useState<BoardLanes>(EMPTY);
  const [attentionCount, setAttentionCount] = useState(0);
  // Main's validation health for the red-main banner (split-land-from-validation
  // F6). Server-derived and already flattened to display strings.
  const [health, setHealth] = useState<BoardHealthSummary>({ mainRed: false });
  const [doneCount, setDoneCount] = useState(0);
  const [cleanupCount, setCleanupCount] = useState(0);
  const [doneLoading, setDoneLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [loading, setLoading] = useState(true);
  // Whether Done's rows have been fetched for the CURRENT repo. Drives two things:
  // an SSE `/board` refresh preserves + re-fetches Done only when it was showing
  // (never blanks an expanded lane), and a repoId change resets it.
  const doneLoadedRef = useRef(false);

  // Guards every setState against an after-unmount resolve. Set true on (re)mount
  // so a StrictMode remount re-arms it. The refresh / SSE-driven refetches default
  // to this guard; the initial-load effect ANDs it with a per-run `cancelled` so a
  // stale in-flight response from a prior repoId is also dropped.
  const mountedRef = useRef(true);
  useEffect(() => {
    mountedRef.current = true;
    return () => {
      mountedRef.current = false;
    };
  }, []);

  // Fetch the Done lane's rows on demand (task 24). The list payload omits them
  // (count only); this fills `lanes.done` when the user expands or focuses Done,
  // and is re-run by `load` on a refresh to keep an expanded lane fresh. A failed
  // fetch keeps whatever rows are already shown (never blanks) — the working
  // lanes are unaffected. Marks `doneLoadedRef` so `load` knows to preserve +
  // re-fetch Done rather than reset it to the payload's empty array.
  const loadDone = useCallback(async () => {
    if (!repoId) return;
    setDoneLoading(true);
    try {
      const res = await fetch(`/api/repos/${encodeURIComponent(repoId)}/board/done`);
      if (!res.ok) return;
      const data = (await res.json()) as { done?: BoardRow[] };
      if (mountedRef.current) {
        // Same identity reconcile as the working lanes — an expanded Done row
        // survives a reconcile-driven refetch without resetting (task 2).
        setLanes((prev) => ({ ...prev, done: reconcileRows(prev.done, data.done ?? []) }));
        doneLoadedRef.current = true;
      }
    } catch {
      // Keep any already-shown Done rows on a fetch error.
    } finally {
      if (mountedRef.current) setDoneLoading(false);
    }
  }, [repoId]);

  const load = useCallback(
    async (isActive: () => boolean = () => mountedRef.current) => {
      if (!repoId) {
        if (isActive()) {
          setLanes(EMPTY);
          setAttentionCount(0);
          setDoneCount(0);
          doneLoadedRef.current = false;
          setError(null);
          setLoading(false);
        }
        return;
      }
      try {
        const res = await fetch(`/api/repos/${encodeURIComponent(repoId)}/board`);
        if (!res.ok) {
          if (isActive()) {
            setError(`Failed to load board (HTTP ${res.status})`);
            setLanes(EMPTY);
            setAttentionCount(0);
            setDoneCount(0);
            setCleanupCount(0);
            doneLoadedRef.current = false;
          }
          return;
        }
        const data = (await res.json()) as Partial<BoardLanes> & {
          health?: BoardHealthSummary;
          attentionCount?: number;
          doneCount?: number;
          cleanupCount?: number;
        };
        if (isActive()) {
          setLanes((prev) => ({
            // Reconcile each lane against the prior rows so an unchanged row keeps
            // its object identity across the refetch (delivery-surface-refetch-
            // storm task 2) — a reconcile's per-step /board re-derive no longer
            // resets/blanks a card whose content did not move.
            backlog: reconcileRows(prev.backlog, data.backlog ?? []),
            inProgress: reconcileRows(prev.inProgress, data.inProgress ?? []),
            inReview: reconcileRows(prev.inReview, data.inReview ?? []),
            // Done is loaded separately (task 24) — the /board payload carries it
            // count-only, so PRESERVE any rows loadDone already fetched instead of
            // clearing the expanded lane on every SSE refresh. A repoId change
            // resets `done` (and doneLoadedRef) in the effect below.
            done: prev.done,
            canceled: reconcileRows(prev.canceled, data.canceled ?? []),
          }));
          setAttentionCount(data.attentionCount ?? 0);
          setHealth(data.health ?? { mainRed: false });
          setDoneCount(data.doneCount ?? 0);
          setCleanupCount(data.cleanupCount ?? 0);
          setError(null);
          // Keep an already-loaded Done lane fresh: re-fetch its rows so a newly
          // completed item appears without a manual collapse/re-expand.
          if (doneLoadedRef.current) void loadDone();
        }
      } catch (err) {
        if (isActive()) {
          setError(err instanceof Error ? err.message : 'Failed to load board');
          setLanes(EMPTY);
          setAttentionCount(0);
          setDoneCount(0);
          setCleanupCount(0);
          doneLoadedRef.current = false;
        }
      } finally {
        if (isActive()) setLoading(false);
      }
    },
    [repoId, loadDone],
  );

  useEffect(() => {
    // A repoId change (load identity changes with it) starts a fresh board — clear
    // ALL lanes at once so the previous repo's cards never linger through the new
    // repo's ~20s load (repo-switch-shows-stale-board task 1); the board reads as
    // loading until the new `/board` resolves. Also drop the Done loaded flag so
    // `load` doesn't preserve stale Done rows. An SSE refresh calls `load` directly
    // (not this effect), so it keeps the expanded Done rows.
    doneLoadedRef.current = false;
    setLanes(EMPTY);
    // Reset the collapsed-Done count too, else the strip reads the previous repo's
    // "Done N" through the whole load (review finding) — a half-cleared board.
    setDoneCount(0);
    setCleanupCount(0);
    let cancelled = false;
    setLoading(true);
    void load(() => !cancelled && mountedRef.current);
    return () => {
      cancelled = true;
    };
  }, [load]);

  const refresh = useCallback(() => {
    void load();
  }, [load]);

  // Every SSE trigger funnels through ONE trailing debounce into `load`
  // (board-lanes-refresh-only-on-run-change): a commit's event burst becomes a
  // single `/board` re-derive. Lane membership is a server-side derivation, so
  // a client-side entity patch can't substitute for the refetch.
  const debounceRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const scheduleRefresh = useCallback(() => {
    if (debounceRef.current !== null) clearTimeout(debounceRef.current);
    debounceRef.current = setTimeout(() => {
      debounceRef.current = null;
      void load();
    }, SSE_REFRESH_DEBOUNCE_MS);
  }, [load]);

  // A repoId change swaps `load`'s identity — drop any pending timer so a
  // debounce armed for the OLD repo can't fire its stale closure over the new
  // repo's freshly cleared lanes. Also covers unmount.
  useEffect(
    () => () => {
      if (debounceRef.current !== null) {
        clearTimeout(debounceRef.current);
        debounceRef.current = null;
      }
    },
    [load],
  );

  // A run dispatch/exit rewrites a run record → `run-change` → re-derive the
  // board so the affected row moves lanes without a manual refresh.
  useRunLive(repoId, scheduleRefresh);

  // The board's non-run refresh signals, all through the shared debounce:
  // - `statusChange` — a git-ref move or status-affecting telemetry re-projects
  //   the entity; the signal that advances a card's progress and moves it
  //   across lanes while working interactively, when no run ever dispatches.
  // - `fixDocChange` / `prdDocChange` / `spikeDocChange` — a markdown write
  //   (`tb work add`, an edit); the ONLY signal a newly created item can ride
  //   onto the board, covering all three card kinds the board renders.
  //   Deliberately independent of the Archive's `archiveOpen`-gated consumer.
  // Matching is by canonical repoId OR the clone-scoped event's `repoIds` alias
  // set (worktree registrations); doc events carry no alias set, so for them
  // the matcher degrades to canonical equality.
  useEffect(() => {
    if (!repoId) return;

    // Each subscription is type-scoped by `sseManager.on`, so one handler
    // serves them all. Every subscribed type carries a required `repoId`; the
    // `in` check exists to NARROW the SSEEvent union for the matcher (members
    // like PersonaChangeEvent have no repo fields), not as a runtime filter.
    const handle = (event: SSEEvent): void => {
      if (!('repoId' in event)) return;
      if (!sseEventMatchesRepo(event, repoId)) return;
      scheduleRefresh();
    };

    // `pipelineChange` (a .tiny-brain/config.json edit) refetches too: the board
    // ships the repo-constant validation pipeline defs, so a pipeline-config edit
    // must re-pull them (props-in-ui). It carries only the repo, so the shared
    // repo matcher and debounce handle it like every other refetch trigger.
    const offs = (['statusChange', 'fixDocChange', 'prdDocChange', 'spikeDocChange', 'pipelineChange'] as const).map(
      (type) => sseManager.on(type, handle),
    );
    // Reconnect resync (sse-client-gives-up-and-never-resyncs task 3): the
    // manager fires `reconnected` on every reopen after a drop — events emitted
    // while the tab was deaf are gone, so the board may be arbitrarily stale.
    // No repo filter (the synthetic event carries none); the shared debounce
    // folds it with whatever else the recovery moment brings.
    offs.push(sseManager.on('reconnected', scheduleRefresh));
    return () => {
      for (const off of offs) off();
    };
  }, [repoId, scheduleRefresh]);

  return { lanes, attentionCount, health, doneCount, cleanupCount, loadDone, doneLoading, loading, error, refresh };
}
