import React, { useMemo, useState } from 'react';
import { useSkillInvocation } from '../hooks/useSkillInvocation';
import type {
  QualityRunDetail,
  ParsedQualityData,
  ParsedPlanData,
  QualityIssue,
  StepScoreResponse,
} from '../types';
import { calculateCategoryScores } from '../utils/qualityScoring';

interface QualityDetailProps {
  selectedRun: QualityRunDetail | null;
  stepCards?: ReadonlyArray<StepScoreResponse>;
  selectedStepType?: string | null;
  agentIssues?: QualityIssue[] | null;
  agentIssuesLoading?: boolean;
  agentIssuesError?: string | null;
  onGenerateQip?: (stepType: string) => void;
  onViewQip?: (stepType: string) => void;
  qipGenerating?: boolean;
  hasQip?: boolean;
  /** Repo whose skill runs the issue rows trigger. Optional: this component is
   *  not wired into production today (QualityTab is the live consumer); the
   *  prop keeps the run-spine contract intact if it is ever mounted. */
  repoId?: string;
}

/**
 * Non-overlapping mapping: each category assigned to exactly ONE primary step.
 * This prevents double-counting when multiple steps share a category domain.
 */
const CATEGORY_TO_STEP: Record<string, string> = {
  Security: 'security',
  Performance: 'performance',
  Testing: 'testing',
  Maintainability: 'code-quality',
  Architecture: 'code-quality',
  Documentation: 'code-quality',
  Operations: 'code-quality',
  Reliability: 'code-quality',
};

/** Group issues by pipeline step using agentId when available, falling back to category mapping */
function groupIssuesByStep(
  issues: ReadonlyArray<QualityIssue>,
  steps: ReadonlyArray<StepScoreResponse>,
): Map<string, QualityIssue[]> {
  const groups = new Map<string, QualityIssue[]>();
  const stepTypes = new Set<string>();

  for (const step of steps) {
    groups.set(step.type, []);
    stepTypes.add(step.type);
  }

  for (const issue of issues) {
    // npm-audit issues → dependency-audit step
    if (issue.source === 'npm-audit') {
      if (groups.has('dependency-audit')) {
        groups.get('dependency-audit')!.push(issue);
      }
      continue;
    }
    if (issue.source !== 'llm') continue;

    // Route by agentId: strip -reviewer suffix to get step type
    if (issue.agentId) {
      const stepType = issue.agentId.replace(/-reviewer$/, '');
      if (groups.has(stepType)) {
        groups.get(stepType)!.push(issue);
        continue;
      }
    }

    // Fallback: route by category mapping
    const stepType = CATEGORY_TO_STEP[issue.category];
    if (stepType && groups.has(stepType)) {
      groups.get(stepType)!.push(issue);
    }
  }

  return groups;
}

export function parseQualityData(rawContent: string): ParsedQualityData | null {
  try {
    const jsonMatch = rawContent.match(/```json\n([\s\S]*?)\n```/);
    if (jsonMatch) {
      const parsed: ParsedQualityData = JSON.parse(jsonMatch[1]);

      if (!parsed.categoryScores) {
        parsed.categoryScores = calculateCategoryScores(parsed.issues);
      }

      return parsed;
    }
  } catch (e) {
    console.error('Failed to parse quality data:', e);
  }
  return null;
}

export function parsePlanData(planContent: string): ParsedPlanData | null {
  try {
    const jsonMatch = planContent.match(/```json\n([\s\S]*?)\n```/);
    if (jsonMatch) {
      return JSON.parse(jsonMatch[1]) as ParsedPlanData;
    }
  } catch (e) {
    console.error('Failed to parse plan data:', e);
  }
  return null;
}

const SEVERITY_ORDER: Record<string, number> = { critical: 0, major: 1, minor: 2, info: 3 };

const SEVERITY_COLORS: Record<string, string> = {
  critical: 'bg-red-100 text-red-800 dark:bg-red-900/30 dark:text-red-400',
  major: 'bg-orange-100 text-orange-800 dark:bg-orange-900/30 dark:text-orange-400',
  minor: 'bg-yellow-100 text-yellow-800 dark:bg-yellow-900/30 dark:text-yellow-400',
  info: 'bg-blue-100 text-blue-800 dark:bg-blue-900/30 dark:text-blue-400',
};

const IssueRow: React.FC<{ issue: QualityIssue; repoId?: string }> = ({ issue, repoId }) => {
  const [expanded, setExpanded] = useState(false);
  const { invoke } = useSkillInvocation(repoId ?? '');

  return (
    <div className="border-b border-border last:border-b-0">
      <button
        onClick={() => setExpanded(!expanded)}
        className="w-full flex items-start gap-3 px-3 py-2 text-left hover:bg-muted transition-colors"
      >
        <span className={`px-1.5 py-0.5 rounded text-xs font-medium whitespace-nowrap mt-0.5 ${SEVERITY_COLORS[issue.severity] ?? SEVERITY_COLORS.info}`}>
          {issue.severity}
        </span>
        <div className="flex-1 min-w-0">
          <p className="text-sm text-foreground line-clamp-2">{issue.message}</p>
          <p className="text-xs text-muted-foreground mt-0.5">
            {issue.file}{issue.line ? `:${issue.line}` : ''}
          </p>
        </div>
      </button>
      {expanded && (
        <div className="px-3 pb-3 ml-8 space-y-2">
          {issue.evidence && (
            <pre className="text-xs bg-muted p-2 rounded overflow-x-auto">
              <code>{issue.evidence}</code>
            </pre>
          )}
          {issue.suggestion && (
            <div className="flex items-start justify-between gap-2">
              <p className="text-xs text-muted-foreground">{issue.suggestion}</p>
              <button
                onClick={(e) => {
                  e.stopPropagation();
                  invoke('fix', `Create a fix for: ${issue.message} in ${issue.file}`, {});
                }}
                className="shrink-0 text-xs text-blue hover:underline"
              >
                Create Fix
              </button>
            </div>
          )}
          <div className="flex gap-3 text-xs text-muted-foreground">
            {issue.effort && <span>Effort: {issue.effort}</span>}
            {issue.impact && <span>Impact: {issue.impact}</span>}
            {issue.theme && <span>Theme: {issue.theme}</span>}
            {issue.scoreImpact && <span>+{issue.scoreImpact} pts if fixed</span>}
          </div>
        </div>
      )}
    </div>
  );
};

const QualityDetail: React.FC<QualityDetailProps> = ({ selectedRun, stepCards = [], selectedStepType = null, agentIssues = null, agentIssuesLoading = false, agentIssuesError = null, onGenerateQip, onViewQip, qipGenerating = false, hasQip = false, repoId }) => {
  const parsedData = useMemo(() => {
    if (!selectedRun?.rawContent) return null;
    return parseQualityData(selectedRun.rawContent);
  }, [selectedRun?.rawContent]);

  // Group issues by pipeline step
  const issuesByStep = useMemo(() => {
    if (!parsedData?.issues || stepCards.length === 0) return new Map<string, QualityIssue[]>();
    return groupIssuesByStep(parsedData.issues, stepCards);
  }, [parsedData?.issues, stepCards]);

  // Split issues: hygiene (eslint/ts), npm-audit → dependency-audit, llm → agent steps
  const { hygieneIssues } = useMemo(() => {
    if (!parsedData?.issues) return { hygieneIssues: [] as QualityIssue[] };
    const hygiene = parsedData.issues.filter(i => i.source !== 'llm' && i.source !== 'npm-audit');
    return { hygieneIssues: hygiene };
  }, [parsedData?.issues]);


  if (!selectedRun) {
    return null;
  }

  // When a step is selected, show only that step's issues as a flat list
  if (selectedStepType) {
    const stepType = selectedStepType;
    const step = stepType === 'hygiene'
      ? { label: 'Static Analysis', emoji: '🔬' }
      : stepCards.find(s => s.type === stepType);

    // Use directly-fetched agent issues when available, fall back to grouped issues
    const issues = stepType === 'hygiene'
      ? hygieneIssues
      : agentIssues ?? issuesByStep.get(stepType) ?? [];

    const sorted = [...issues].sort((a, b) =>
      (SEVERITY_ORDER[a.severity] ?? 9) - (SEVERITY_ORDER[b.severity] ?? 9)
    );
    const capped = sorted.slice(0, 100);
    const hasMore = sorted.length > 100;

    return (
      <div className="space-y-3">
        {/* Header */}
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-2">
            {step?.emoji && <span className="text-lg">{step.emoji}</span>}
            <h4 className="text-sm font-semibold text-foreground">
              {step?.label ?? stepType}
            </h4>
          </div>
          <div className="flex items-center gap-2">
            <span className={`text-sm font-medium ${issues.length === 0 ? 'text-green-600 dark:text-green-400' : 'text-muted-foreground'}`}>
              {issues.length} {issues.length === 1 ? 'issue' : 'issues'}
            </span>
            {stepType !== 'hygiene' && issues.length > 0 && (
              hasQip && onViewQip ? (
                <button
                  onClick={() => onViewQip(stepType)}
                  className="px-3 py-1 text-xs font-medium rounded-md bg-blue/10 text-blue hover:bg-blue/20 transition-colors"
                >
                  View QIP
                </button>
              ) : onGenerateQip ? (
                <button
                  onClick={() => onGenerateQip(stepType)}
                  disabled={qipGenerating}
                  className="px-3 py-1 text-xs font-medium rounded-md bg-blue text-white hover:opacity-90 disabled:opacity-50 disabled:cursor-not-allowed transition-colors"
                >
                  {qipGenerating ? 'Generating...' : 'Fix these issues'}
                </button>
              ) : null
            )}
          </div>
        </div>

        {agentIssuesLoading ? (
          <div className="flex items-center justify-center py-12 text-sm text-muted-foreground">
            Loading issues...
          </div>
        ) : agentIssuesError ? (
          <div className="flex items-center justify-center py-12 text-sm text-amber-600 dark:text-amber-400">
            {agentIssuesError}
          </div>
        ) : issues.length === 0 ? (
          <div className="flex items-center justify-center py-12 text-sm text-green-600 dark:text-green-400">
            No issues found.
          </div>
        ) : (
          <div className="rounded-lg border overflow-hidden" style={{ borderColor: 'var(--border, rgba(255,255,255,0.15))' }}>
            {capped.map((issue, idx) => (
              <IssueRow key={`${issue.file}-${issue.line}-${idx}`} issue={issue} repoId={repoId} />
            ))}
            {hasMore && (
              <div className="p-3 text-sm text-muted-foreground bg-muted">
                Showing 100 of {sorted.length} issues.
              </div>
            )}
          </div>
        )}
      </div>
    );
  }

  // No step selected — show empty state prompt
  return (
    <div className="flex items-center justify-center py-16 text-sm text-muted-foreground">
      Select a card to see the issues it found.
    </div>
  );
};

export default QualityDetail;
