import { GitBranch } from 'lucide-react';
import { cn } from '@/lib/utils';

export interface MsrPillProps {
  /** The branch the work lives on — shown by NAME, inline (the mock's `.msr`
   *  always states the branch; an icon-only chip made the reader hover). */
  branch?: string;
  /** The worktree dir when a task names one — carried on the pill's title so
   *  the branch/worktree axes stay distinguishable without a tooltip stack. */
  worktreeName?: string;
  /** Collapse to the icon-only worktree glyph, moving the branch name (and dir)
   *  onto the title (fix feature-card-live-glyph-and-run-watch-surface task 6).
   *  For a COMPLETED feature, where the full branch name is noise once done. */
  iconOnly?: boolean;
  className?: string;
}

/**
 * The mock's MiniStatusRail branch pill (detail-provenance-mock `.msr`): ONE
 * borderless rounded-full mono pill naming the WHERE — the branch the quiet
 * work lives on. The deliverer (`who`) no longer rides inside it: the strip
 * names WHO as a glyph + plain-text label beside this chip (fix
 * endcap-resumes-pipeline-runs task 5, {@link DeliveredProvenance}), so the
 * settled body matches the live MiniStatusRail's glyph+text shape instead of a
 * tinted who-bubble. There is no environment axis here on purpose: this pill
 * renders only quiet (no-run) states, whose work sits on the local disk, and
 * local is the unmarked default everywhere (MSR rule 5). Run-backed states go
 * through MiniStatusRail, which shows the Cloud exactly when the run was remote.
 */
export function MsrPill({ branch, worktreeName, iconOnly, className }: MsrPillProps) {
  // No branch to name — renders nothing (fix control-strip-mute-during-live-run
  // task 3). A pill with no segments is a stray empty bubble: a not-started fix
  // carries no worktree branch, so the strip must make NO claim.
  if (branch === undefined) return null;
  // Icon-only: the branch name moves to the title so the glyph carries no inline
  // text; the worktree dir joins it there (task 6). Otherwise only the dir rides
  // the title and the branch shows inline.
  const title = iconOnly
    ? `branch: ${branch}${worktreeName !== undefined ? ` · worktree: ${worktreeName}` : ''}`
    : worktreeName !== undefined
      ? `worktree: ${worktreeName}`
      : undefined;
  return (
    <span
      data-testid="msr-pill"
      title={title}
      // Icon-only: the glyph is aria-hidden and there is no text child, so name
      // the pill for assistive tech — otherwise the branch drops out of the
      // accessibility tree (adversarial review of 6dfae8321). The inline-text
      // variant names itself through its visible branch text.
      aria-label={iconOnly ? `worktree branch ${branch}${worktreeName !== undefined ? ` (${worktreeName})` : ''}` : undefined}
      className={cn(
        // BORDERLESS soft fill (user call, 2026-07-26): the attribution pill
        // sits beside bordered STATUS chips on the fix/feature command rows and
        // must read as a different class of information — metadata, not state.
        'inline-flex items-center gap-1.5 rounded-full py-0.5 mono text-[10px]',
        iconOnly ? 'px-1.5' : 'px-2.5',
        'bg-foreground/[0.06] text-muted-foreground',
        className,
      )}
    >
      <span className="inline-flex min-w-0 items-center gap-1">
        <GitBranch className="h-3 w-3 shrink-0" aria-hidden="true" />
        {!iconOnly && <span className="truncate">{branch}</span>}
      </span>
    </span>
  );
}

export default MsrPill;
