import type { PipelineStep } from '@magic-ingredients/tiny-brain-core/phase-derivation';
import type { Plan, Feature } from '../types';
import { taskPhaseProgress } from './task-progress';
import { toEffectiveTask, derivePlanEffectiveStatus } from './effective-task';

/**
 * The ONE phase-weighted completion percentage (0–100) for a PRD — the plan
 * analogue of {@link deriveFixProgress}. Flattens every feature's tasks, applies
 * the worktree-effective rollup ({@link toEffectiveTask}), and takes the mean of
 * each task's per-task phase progress over the TOTAL task count.
 *
 * This mirrors the server board summary's `weightedProgressPct` (the
 * phase-weighted mean, which also flattens across features) so the PRD's sidebar
 * card, detail header, and board card all read the same metric — fixes and PRDs
 * finally share the SAME progress family. Unlike a completed-task count, an
 * in-flight task contributes its per-step fraction, so the bar advances on every
 * RED / GREEN / review-written, not only when a whole task completes.
 *
 * Scope note: like `deriveFixProgress`, this is ONLY the mean — it does NOT
 * apply the server `summarisePlan` short-circuit that reads a completed /
 * superseded PLAN as 100 regardless of per-task shape. In a consistent
 * projection every terminal task already contributes 1, so the two agree; the
 * settled-plan override lives outside this function (see the test that pins this
 * boundary). Pure.
 */
export function derivePlanProgress(plan: Pick<Plan, 'features'>, reviewPipeline?: PipelineStep[]): number {
  const tasks = (plan.features ?? []).flatMap((feature) => feature.tasks ?? []);
  const total = tasks.length;
  if (total === 0) return 0;
  const weight = tasks.map(toEffectiveTask).reduce((sum, task) => sum + taskPhaseProgress(task, reviewPipeline), 0);
  return Math.round((weight / total) * 100);
}

/**
 * The completion percentage a PRD's card / detail should DISPLAY: the pure
 * phase-weighted {@link derivePlanProgress} PLUS the settled short-circuit — a
 * worktree-effective terminal plan reads 100 regardless of per-task shape.
 *
 * Keyed on {@link derivePlanEffectiveStatus} (the promote-only rollup the plan
 * surfaces already use for their status pill), so it agrees with the server
 * `summarisePlan` (`isDone ? 100 : weightedProgressPct`) for a declared-terminal
 * plan AND additionally reads 100 for a worktree-ahead plan whose launch-ref
 * status lags — the same worktree-awareness FixCard has. Every client PRD
 * progress surface routes through this so they can't drift. Pure.
 */
export function derivePlanDisplayProgress(
  plan: Pick<Plan, 'status' | 'features'>,
  reviewPipeline?: PipelineStep[],
): number {
  // A worktree-effective terminal plan reads 100 (matching deriveFixDisplayProgress
  // and the server closed card); otherwise the phase-weighted mean.
  // derivePlanEffectiveStatus is promote-only and never downgrades a terminal
  // plan (completed OR superseded → 'completed'), so a single effective-status
  // check suffices — same shape as deriveFixDisplayProgress.
  const status = derivePlanEffectiveStatus(plan);
  if (status === 'completed' || status === 'superseded') return 100;
  return derivePlanProgress(plan, reviewPipeline);
}

export interface DashboardMetrics {
  totalFeatures: number;
  completedFeatures: number;
  totalTasks: number;
  completedTasks: number;
  overallProgress: number;
  daysSinceCreated: number;
  lastUpdated: string;
  createdDate: string;
}

export interface RecentActivity {
  type: 'task' | 'feature';
  title: string;
  featureTitle?: string;
  status: string;
  priority?: 'high' | 'medium' | 'low';
}

export interface NextAction {
  type: 'task' | 'feature';
  title: string;
  featureTitle?: string;
  description?: string;
  priority?: 'high' | 'medium' | 'low';
}

// Terminal statuses count as "done" for progress calculation
const isTaskDone = (status: string) => status === 'completed' || status === 'superseded';
const isFeatureDone = (status: string) => status === 'completed' || status === 'superseded';

/**
 * Extract dashboard metrics from plan data
 */
export function extractMetrics(plan: Plan): DashboardMetrics {
  const features = plan.features || [];
  const totalFeatures = features.length;
  const completedFeatures = features.filter(p => isFeatureDone(p.status)).length;

  let totalTasks = 0;
  let completedTasks = 0;

  features.forEach(feature => {
    totalTasks += feature.tasks?.length || 0;
    const featureProgress = feature.tasks?.reduce((sum, task) => sum + taskPhaseProgress(task), 0) ?? 0;
    completedTasks += Math.round(featureProgress);
  });

  // Overall progress is always feature-based
  const overallProgress = totalFeatures > 0 ? Math.round((completedFeatures / totalFeatures) * 100) : 0;

  // Calculate days since created (estimate from plan structure)
  const createdDate = plan.updatedAt || plan.lastUpdated || new Date().toISOString();
  const daysSinceCreated = Math.floor(
    (new Date().getTime() - new Date(createdDate).getTime()) / (1000 * 60 * 60 * 24)
  );

  return {
    totalFeatures,
    completedFeatures,
    totalTasks,
    completedTasks,
    overallProgress,
    daysSinceCreated,
    lastUpdated: plan.lastUpdated || plan.updatedAt || 'Unknown',
    createdDate
  };
}

/**
 * Get recent completed items (tasks and features)
 */
export function getRecentActivity(plan: Plan): RecentActivity[] {
  const activities: RecentActivity[] = [];
  const features = plan.features || [];

  // Add completed/superseded features
  features
    .filter(feature => isFeatureDone(feature.status))
    .forEach(feature => {
      activities.push({
        type: 'feature',
        title: feature.title,
        status: feature.status
      });
    });

  // Add completed/superseded tasks
  features.forEach(feature => {
    feature.tasks?.forEach(task => {
      if (isTaskDone(task.status)) {
        activities.push({
          type: 'task',
          title: task.description,
          featureTitle: feature.title,
          status: task.status
        });
      }
    });
  });

  // Return last 3 activities (most recent first)
  return activities.slice(-3).reverse();
}

/**
 * Get next actions (pending tasks and features)
 */
export function getNextActions(plan: Plan): NextAction[] {
  const actions: NextAction[] = [];
  const features = plan.features || [];

  // Add next action from plan state if available
  if (plan.currentState?.nextAction && actions.length < 3) {
    actions.push({
      type: 'task',
      title: 'Priority Task',
      description: plan.currentState.nextAction.description,
      priority: plan.currentState.nextAction.priority as 'high' | 'medium' | 'low' || 'medium'
    });
  }

  // Find current in-progress feature and add its incomplete tasks
  const currentFeature = features.find(p => p.status === 'in_progress');
  if (currentFeature && actions.length < 3) {
    const nextTasks = currentFeature.tasks?.filter(task => !isTaskDone(task.status)) || [];
    nextTasks.slice(0, 3 - actions.length).forEach(task => {
      actions.push({
        type: 'task',
        title: task.description,
        featureTitle: currentFeature.title,
        priority: 'medium'
      });
    });
  }

  // Add pending features until we have 3 actions
  const pendingFeatures = features.filter(p => p.status === 'not_started');
  for (const feature of pendingFeatures) {
    if (actions.length >= 3) break;

    // First add the feature itself if no tasks
    if (!feature.tasks || feature.tasks.length === 0) {
      actions.push({
        type: 'feature',
        title: feature.title,
        description: feature.description,
        priority: actions.length === 0 ? 'high' : 'medium'
      });
    } else {
      // Add incomplete tasks from this pending feature (exclude done tasks)
      const incompleteTasks = feature.tasks.filter(task => !isTaskDone(task.status));
      for (const task of incompleteTasks) {
        if (actions.length >= 3) break;
        actions.push({
          type: 'task',
          title: task.description,
          featureTitle: feature.title,
          priority: actions.length === 0 ? 'high' : 'medium'
        });
      }
    }
  }

  // If still not enough actions, add the remaining in-progress or pending features
  if (actions.length < 3) {
    const remainingFeatures = features.filter(p =>
      (p.status === 'in_progress' || p.status === 'not_started') &&
      !actions.some(a => a.type === 'feature' && a.title === p.title)
    );

    for (const feature of remainingFeatures) {
      if (actions.length >= 3) break;
      actions.push({
        type: 'feature',
        title: feature.title,
        description: feature.description,
        priority: 'low'
      });
    }
  }

  return actions.slice(0, 3); // Return exactly 3 actions (or less if not enough data)
}

/**
 * Calculate feature-specific metrics
 */
export function getFeatureMetrics(features: Feature[]): Array<{
  featureNumber: number;
  title: string;
  progress: number;
  totalTasks: number;
  completedTasks: number;
  status: string;
}> {
  return features.map(feature => {
    const totalTasks = feature.tasks?.length || 0;
    const completedTasksRaw = feature.tasks?.reduce((sum, task) => sum + taskPhaseProgress(task), 0) ?? 0;
    const completedTasks = Math.round(completedTasksRaw);
    // Terminal feature statuses show as 100% complete
    // Use raw fractional sum for progress percentage (more accurate), round for display count
    const progress = isFeatureDone(feature.status) ? 100 :
                     totalTasks > 0 ? Math.round((completedTasksRaw / totalTasks) * 100) : 0;

    return {
      featureNumber: feature.number,
      title: feature.title,
      progress,
      totalTasks,
      completedTasks,
      status: feature.status
    };
  });
}

/**
 * Get plan lifecycle information
 */
export function getPlanLifecycle(plan: Plan) {
  return {
    createdAt: plan.updatedAt || plan.lastUpdated || 'Unknown',
    lastUpdated: plan.lastUpdated || plan.updatedAt || 'Unknown',
    status: plan.status,
    isTheCurrentPlan: plan.isTheCurrentPlan || false,
    featureCount: plan.featureCount || plan.features?.length || 0
  };
}