import type { BoardHealthSummary } from '@/hooks/useBoard';
import { checkWindowLabel, shortSha } from './short-sha';

/**
 * split-land-from-validation F6 Task 3 — the "main is broken" overlay.
 *
 * A port of case C in
 * `docs/prd/split-land-from-validation/assets/land-validation-lifecycle.html`:
 * the honest surface for an AMBIGUOUS verdict. No card wears a pill in that
 * case, because naming one of several suspects would be a guess — so the whole
 * suspect range is laid out with each land's SHA and a human picks.
 *
 * Fix-forward is the default posture of the whole PRD; revert is the explicit
 * escape, and it belongs to F5. This renders a revert control only when the
 * host wires one, so having the SHAs on hand never becomes a dead button.
 */
export interface MainBrokenOverlayProps {
  health: Extract<BoardHealthSummary, { mainRed: true }>;
  onClose: () => void;
  /** Revert one land by SHA (F5). Omitted ⇒ no revert controls render. */
  onRevert?: (sha: string) => void;
}

/**
 * The lede, in the USER's language (red-banner-copy-speaks-jargon): each shape
 * gets the sentence that is true of it, and the internal vocabulary — lands,
 * attribution, ranges — never reaches the surface.
 */
function ledeFor(health: Extract<BoardHealthSummary, { mainRed: true }>): string {
  if (health.attribution.kind === 'attributed') {
    return `The failing check was introduced by ${health.attribution.culprit} — its commit is marked below.`;
  }
  if (health.lands.length === 1) {
    return 'It could be the following commit — the only recent change in the failing window:';
  }
  return `It could be any of the following ${health.lands.length} commits:`;
}

/** Is this land's item the one attribution named? Only an attributed verdict marks a row. */
function isCulprit(
  health: Extract<BoardHealthSummary, { mainRed: true }>,
  item: string,
): boolean {
  return health.attribution.kind === 'attributed' && health.attribution.culprit === item;
}

export function MainBrokenOverlay({ health, onClose, onRevert }: MainBrokenOverlayProps) {
  const { lands, baselineSha, tipSha, failingTests } = health;

  return (
    <div className="tb-broken" role="dialog" aria-label="Main is broken">
      <div className="tb-broken__head">
        <h4 className="tb-broken__title">Main is broken</h4>
        <span className="tb-broken__range">{checkWindowLabel(baselineSha, tipSha)}</span>
        <button type="button" className="tb-broken__close" onClick={onClose} aria-label="Close">
          ✕
        </button>
      </div>

      {lands.length === 0 ? (
        /* No commits could be listed for the failing window (reachable until
           every record carries a resolved baseline). The USER-dictated sentence
           carries the one thing that matters — what is failing and what to do —
           and the build-failed line covers a check that died before any test. */
        <p className="tb-broken__empty">
          {failingTests !== undefined && failingTests.length > 0
            ? failingTests.length === 1
              ? 'There is 1 failing test. This needs to be fixed before a full regression can run successfully. The commit responsible is not identified.'
              : `There are ${failingTests.length} failing tests. These need to be fixed before a full regression can run successfully. The commit responsible is not identified.`
            : 'The build failed before tests ran — open the check run for the log.'}
        </p>
      ) : (
        <>
          <p className="tb-broken__lede">{ledeFor(health)}</p>
          <ul className="tb-broken__lands">
            {lands.map((land) => (
              <li
                key={land.sha}
                className={
                  isCulprit(health, land.item)
                    ? 'tb-broken__land tb-broken__land--culprit'
                    : 'tb-broken__land'
                }
              >
                <div className="tb-broken__land-main">
                  <p className="tb-broken__land-item">
                    {land.item}
                    {isCulprit(health, land.item) && (
                      <span className="tb-broken__land-tag">cause</span>
                    )}
                  </p>
                  <p className="tb-broken__land-meta">
                    <span className="tb-broken__land-sha">{shortSha(land.sha)}</span>
                    {land.files.length > 0 && <> · {land.files.join(', ')}</>}
                  </p>
                </div>
                {onRevert !== undefined && (
                  <button
                    type="button"
                    className="tb-broken__revert"
                    onClick={() => onRevert(land.sha)}
                  >
                    Revert
                  </button>
                )}
              </li>
            ))}
          </ul>
        </>
      )}

      {failingTests !== undefined && failingTests.length > 0 && (
        <div className="tb-broken__evidence">
          <p className="tb-broken__evidence-head">Failing tests ({failingTests.length})</p>
          {failingTests.map((test) => (
            <p key={test} className="tb-broken__evidence-row">
              ✗ {test}
            </p>
          ))}
        </div>
      )}
    </div>
  );
}
